window.QUIZ_LOCAL = (window.QUIZ_LOCAL||[]).concat([{"q":"○○○의 창건과 중수 과정 등 ○○○의 내력을 전해 주는 기록으로, ○○○ 1책과 목판 11매로 구성되어 있다. ○○○는 세 부분으로 구성되어 있는데, 1733년(영조 9)에 신유한(申維翰, 1681~?)이 작성한 본문과 산인(山人) 명학(明學)이 이듬해에 쓴 발문, 사찰 내 각 전각과 부속 암자에 보관된 경전과 기물의 목록 등이 나열된 부록이 그것이다. ○○○에는 신라시대에 ○○○를 건립하게 된 유래와 연혁 등이 자세하게 적혀 있을 뿐만 아닐, 절의 중수(重修)와 그 공사를 맡은 주지의 이름, 공사에 들어간 비용 등까지 적혀 있어 ○○○의 역사를 이해하는 데 중요한…","a":"창녕 관룡사 사적기","c":"시도유형문화유산","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641793.jpg"},{"q":"19세기 말 20세기 초의 보살상으로 토제의 소형 보살상임에도 불구하고 부드러움과 자연스러움이 잘 표현되어 있고 전통적인 소조 기법으로 제작되어 희소성과 예배대상물로서의 빼어난 조형미를 지니고 있는 등 자료로서 가치가 크다.","a":"김해 관음정사 소조보살좌상","c":"문화유산자료","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666686.jpg"},{"q":"고려 인종(재위 1122∼1146) 때 어의(御醫)이면서 명신인 장경공 최사전을 중심으로 그의 후손 4명(손암 최윤덕, 금남 최부, 문절공 유희춘, 충열공 나덕헌)을 모시고 있는 서원이다. 최사전은 의술로써 벼슬에 나갔는데 왕의 총애를 받아 높은 벼슬에 오른 사람이다. ○○○○은 1927년에 탐진 최씨 문중이 전국 유림의 호응을 얻어서 세운 서원이다. 서원의 이름은 광주의 옛 지명에서 따 왔다고 하는데, 강당인 이택당을 중심으로 왼편과 오른편에 합의문과 합인문이 있다. 합의문을 지나면 오른편에 동재인 성지재가 있고 왼편에는 서재인 낙호재가 있다. 또한 높은 땅 위에…","a":"무양서원","c":"문화유산자료","r":"전남광주통합특별시","s":"광산구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659595.jpg"},{"q":"조선시대 무신인 하경복(1377∼1438) 선생의 위패를 모신 사당이다. 하경복은 태종 2년(1402) 무과에 급제하고 여러 관직을 거쳐 병마사, 병마절제사가 되어 국방을 수비하였다. 15년 동안 국경지대에서 여진족과 대치하며 경비에 철저했으며 특히 세종 15년(1433) 정흠지, 황보인 등과 함께 『계축진설』을 펴내 군사 교육의 교재로 삼았다. 성품이 너그럽고 활을 잘 쏘았으며 개국 초기 철저히 국방을 지켜 국가의 기틀을 마련하는데 큰 공을 세웠다. 정현사는 정조 10년(1784) 유림들이 세웠으며 이곳에는 하경복을 대신해 노모를 모신 하경리, 그를 이어 북방에서…","a":"하동 경현사","c":"문화유산자료","r":"경상남도","s":"하동군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664244.jpg"},{"q":"패총은 ‘조개무덤’이라고도 하며, 해안이나 강가에 살던 선사시대인이 버린 조개 껍질이 쌓여 무덤처럼 된 유적이다. 조개껍질이 지닌 석회질로 그 안의 토기, 석기 및 짐승의 뼈 등이 잘 보존되어 있어 고고학적으로 귀중한 연구 자료가 된다. ○○○○○은 2000년 지표조사에서 확인된 유적으로 외황강과 바닷물이 만나, 강물과 바닷물이 섞이는 곳에 분포한다. 유적의 남동쪽에는 ○○○○○과 동일한 시기에 해당하는 울산 세죽유적이 위치하며, 북동쪽에는 조선시대의 수군만호진성(水軍萬戶鎭城)인 개운포성지가 있다. 유적은 조수간만의 차이로 인해 해안가에서 밀려들어온 실트성의 고운 흙…","a":"성암동패총","c":"시도기념물","r":"울산광역시","s":"남구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645896.jpg"},{"q":"매향의식을 치른 후 그 내용을 바위에 새겨놓은 것이다. 매향의식이란 향나무를 땅에 묻는 민간 불교의식을 이르는 것으로, 향나무를 통해 소원을 비는 자와 미륵불이 연결되기를 바라는 미륵신앙의 한 형태이다. 매향비는 보통 바닷물과 계곡물이 만나는 지점을 그 적격지로 하여 세워두며, 14∼15세기에 주로 세웠다. 이 시기는 왜구의 침략이 잦았던 때로, 이러한 의식을 통하여 해안지역의 불안한 민심을 달래고자 했던 것으로 보인다. 대개는 의식을 행한 후 비를 세워두는 것이 보통이나 이렇듯 바위에 새겨두기도 한다. 향토산 중턱의 처녀바위라 불리우는 곳에 새겨 놓은 이 기록은 조…","a":"삼천포매향암각","c":"시도유형문화유산","r":"경상남도","s":"사천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642161.jpg"},{"q":"○○○란 임금이나 고관 등의 평생업적을 기록하여 그의 무덤 가까이에 세우는 비로, 이 비는 조선 중기의 문신인 충강공 ○○○ 선생을 기리고 있다. ○○○은 선조 39년(1606) 문과에 급제한 후 형조좌랑, 평안도도사를 역임하였다. 그 후 벼슬을 버리고 학문연구와 후진교육에 힘썼으며, 인조반정 후 다시 단천군수 ·연안부사 등을 역임하고 병조참지가 되어 군비확장에 힘을 기울였다. 인조 14년(1636) 병자호란이 일어나자 남한산성에 왕을 모셨으며, 강화도로 가던 중 적병에게 피살되었다. 그 후에 이조판서의 벼슬로 추증되었고, 순조 때 ‘충강공’의 시호를 받았다.","a":"충주 이상급 신도비","c":"시도유형문화유산","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638479.jpg"},{"q":"조선 중기의 문신이며 인조의 장인인 한준겸(韓浚謙, 1557∼1627) 선생과 후손들의 가족 묘역이다. 묘역은 한준겸 묘를 중심으로 좌측에 아들 한회일(韓會一) 묘역과 우측에 손자 한이성(韓以成) 묘역, 그리고 앞쪽에 증손 한두상(韓斗相) 묘역이 4대에 걸쳐 조성되어 있다. 한준겸 묘역은 부인 황씨(黃氏)와 합장한 단분(單墳 ; 하나의 봉분)의 형태이다. 17세기 전반기의 묘제를 잘 보여주는 곳으로 묘표에서부터 동자석인과 장명등까지 골고루 갖춘 표준이 되는 묘역이다. 묘표는 1628년(인조 5)에 제작한 것으로 대리석 재질의 정갈한 비석이다. 동자석인 머리는 쌍계형(…","a":"청주한씨문익공파묘역","c":"시도기념물","r":"경기도","s":"시흥시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2018103113231300.jpg"},{"q":"수열평 마을에 자리하고 있는 비로, 조선시대 중기의 오씨 부인이라는 여인의 절개를 기리고 있다. 선조 30년(1597) 정유재란이 일어났을 때 장수지방에 침입하였던 왜적들이 집집마다 약탈을 하며 불을 지르기도 하면서 부녀자들을 겁탈하는 일이 잦았다. 화평 마을에 살고 있는 양사무의 부인 오씨부인은 아침에 들이닥친 왜적들에게 가슴을 잡히는 등 모욕을 당하게 되자, 자신의 가슴을 칼로 베어 그들의 얼굴에 뿌리면서 “짐승만도 못한 오랑캐들아! 젖이 욕심나거든 이것을 들고 네 나라로 돌아가라”며 크게 외쳤다. 부인의 위엄에 눌린 왜적들은 곧 달아나고, 피를 많이 흘린 부인은…","a":"수열비","c":"문화유산자료","r":"전북특별자치도","s":"장수군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661659.jpg"},{"q":"돈대란 적의 움직임을 살피거나 공격에 대비하기 위하여 영토 내 접경지역 또는 해안지역의 감시가 쉬운 곳에 마련해 두는 초소이다. 보통 높은 평지에 쌓아 두는데, 밖은 성곽으로 높게 하고 안은 낮게 하여 포를 설치해 둔다. 특히 ○○도에 있는 돈대들은 조선 인조 14년(1636) 병자호란이 일어나 ○○도가 함락되자, 이에 놀란 조정에서 해안 경비를 튼튼히 하기 곳곳에 쌓아두도록 한 것이다. 창후리 선착장에서 북쪽으로 난 비포장길을 따라 100m 정도 떨어진 곳에 자리하고 있는 이 돈대는 해안을 따라 직사각형으로 길게 쌓았다. ○○유수를 지내던 윤이제가 해안 방어를 튼튼…","a":"강화 무태돈대","c":"문화유산자료","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/0000000001659581.jpg"},{"q":"○○○○○에 대한 고마움을 잊지 않기 위해 주민들이 세운 ○○○로 파손되어 매몰되어 있는 것을 1855년에 후손들이 다시 세운 것 입니다. 전국적으로 아전에 대한 ○○○는 매우 희귀한 사례임.","a":"고성 이방 박영장 불망비","c":"시도유형문화유산","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018110716563200.jpg"},{"q":"○○○은 전주 이씨의 시조 이한(李翰)의 묘역이다. 태조 이성계는 조선 왕조를 세운 뒤 건지산에 있는 이 묘역을 각별히 지키게 했으며, 그 후 역대 왕들도 이의 보호에 정성을 다하였다. 특히 고종 황제는 광무 3년(1899)에 이곳에 단을 쌓고 비를 세워, 관리를 배치하고 매년 한 차례씩 제사를 지내도록 했다. 비석에 새긴 ｢대한 ○○○｣이란 글씨와 그 비문은 고종 황제가 직접 쓴 것이다. ○○○은 경기전, 조경묘와 함께, 전주가 조선왕조의 발원지임을 상징하는 곳이다.","a":"조경단","c":"시도기념물","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653285.jpg"},{"q":"조선 후기 성리학자인 유중교(1821∼1893)가 후진을 양성했던 곳으로 고종 26년(1889)에 창주정사로 세웠는데 1906년 유림에서 ○○○○으로 새롭게 세웠다. 고종 32년(1895)에는 의병장 유인석(1842∼1915)이 팔도 유림들을 모아 비밀회의를 하던 곳이기도 하다. 유중교는 이항로와 김평묵의 제자였으며 그들의 영향을 받아 위정척사론을 주장한 인물이다. 유인석 역시 이항로의 문하에 있었으며 위청척사론자이자 의병장으로 적극적인 항일 운동을 전개시켰다. 이곳에는 주자·송시열·이화서·유중교·유인석·이직신의 영정을 모시고 있으며 해마다 봄·가을에 제사를 지낸다.…","a":"제천 자양영당","c":"시도기념물","r":"충청북도","s":"제천시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1649668.jpg"},{"q":"○○○○은 1917년에 초창된 교육시설로서 세부적인 구조수법과 의장, 평면구성에서 근대한옥의 특징을 보여주고 있어 건축사적으로 보존할 가치가 높다. 특히 영남지역 기호학맥의 본거지로서 상징성과 역사성을 가지고 있으며, 전통한학과 예법교육 장소로 활용가치가 있는 건축물이다.","a":"김해 월봉서당","c":"문화유산자료","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666522.jpg"},{"q":"○○○○에 서 있는 탑으로, 지금 자리에서 서쪽으로 40m 지점에 무너져 있던 것을 옮겨 세운 것이다. 이 탑으로 인하여 ‘○○’이라는 마을 이름이 생겨났다. 형태로 보아 2층 기단(基壇) 위에 5층의 탑신(塔身)을 올렸을 듯 하나, 지금은 기단부가 거의 없어지고 탑신부는 1층의 몸돌과 1, 2, 3, 5층의 지붕돌만이 남아 있다. 5층 몸돌과 꼭대기의 머리장식은 탑을 복원할 때에 보충한 것이다. 일부만 남은 기단은 윗면에 탑신의 1층 몸돌을 받치기 위한 두꺼운 괴임조각을 두었다. 탑신의 1층 몸돌은 모서리마다 기둥모양의 조각을 두고, 4면에 불상을 새겼는데 동쪽은…","a":"청주 탑동 오층석탑","c":"시도유형문화유산","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638434.jpg"},{"q":"충숙공 문극겸(1122∼1189)을 기리기 위해 세운 서원이다. 문극겸은 고려시대 무신들이 집권한 시기의 문신으로, 재상이 되었을 때에도 상장군을 겸하고 무신들의 자문에 응하는 등 문무를 겸비한 독특한 인물이었다. ○○○○은 정조 1년(1777) 대병면 역평리에 세웠다. 그 뒤 고종 7년(1871) 흥선대원군의 서원철폐령으로 철거되었다가 1957년에 사우 등을 복원하였다. 지금 있는 건물은 ○○댐 건설로 1985년에 옮겨 복원한 것이다.","a":"합천 송호서원","c":"문화유산자료","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664051.jpg"},{"q":"문적의 내용은, 노소재 문집 본초을중 일책으로 체제는, 세로 24cm 가로 14.2cm의 한지 장본, 심침장법 총 45정행초서로 평균 매면 8행, 1행 16자이다. 내용은, 소재선생이 을사 사화로 순천, 진도 등지로 유배되던 1548년부터 수년 간 유배지에서 쓴 시부를 수록하였는데, 무신 정월 난고 21수를 비롯하여 이월난고 40수와 옥주 2천언 등이다. 이는, 소재 문집 본초 전 7권 중 유일하게 남은 을중본이다. 소재 노수신 선생의 자는 과회요 호는 소재며 벼슬은 영의정, 시호는 문간공이다. 선생의 학문은, 탄수. 환훤당.점필재에 연원을 둔 유학자로서 진도 유배…","a":"노소재문적","c":"시도유형문화유산","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640725.jpg"},{"q":"○○○는 월악산 기슭에 있는 절로 신라 진평왕 4년(582) 아도가 지었다고 하나 연대가 확실하지 않다. 그 뒤 신라 문무왕(재위 661∼681) 때 원효가 고쳤다고 하며, 조선 선조(재위 1567∼1608) 때 사명대사가 다시 지어 오늘에 이르고 있다. ○○○○○은 아미타불을 모시는 건물이다. 앞면 3칸·옆면 3칸이며, 지붕 옆면이 사람 인(人)자 모양인 맞배지붕집이다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 기둥 위와 기둥 사이에도 있는 다포계 양식의 건물이다. 건물의 바깥쪽 벽에는 여래상을 그려 장엄하게 하였으며, 내부에는 천장 좌우에 문수보살과 보현보살…","a":"제천 신륵사 극락전","c":"시도유형문화유산","r":"충청북도","s":"제천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638597.jpg"},{"q":"배를 타고 들어오는 외적의 침입을 막기 위해 제주도에서는 해안선을 따라가며 성을 쌓았는데 이를 ○○○○이라 한다. 현재 성벽이 남아있는 곳으로는 온평리, 행원리, 한동리. 동복리, 북촌리, 애월리, 고내리 등 14곳이 있다. 김상헌이 지은 『남사록』에는 ○○○○을 일러 ‘탐라의 만리장성’이라 부르고 있다. 현재 남아 있는 한동 ○○○○ 성벽의 길이는 약 290m이다.","a":"한동환해장성","c":"시도기념물","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657921.jpg"},{"q":"○○○ 수안골에 있는 ○○○○○으로 19세기 말에 지은 것이다. ○○○○○은 지붕의 용마루 끝에 구멍을 내어 집안에서 생기는 연기를 빼내고 빛을 받아들이는 가옥이다. 앞면 3칸·옆면 2칸 규모에 외양간이 1칸 덧붙었다. 방은 모두 심을 넣은 흙벽이고, 봉당과 부엌·외양간은 널벽으로 지었다. 앞면 가운데 칸에 두짝의 널대문을 달고 앞칸에 흙바닥 출입구인 봉당을, 뒷칸에 마루를 갖춘 경북지방 ○○○○○의 골격을 갖추었다. 여기에 마루 뒷쪽을 막아서 좁은 도장방을 설치한 형식은 강원특별자치도 남부지방 ○○○○○의 요소가 섞인 것이다. 경북지역의 가장 위쪽에 위치한 지리적…","a":"분천리까치구멍집","c":"시도민속문화유산","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658828.jpg"},{"q":"이 재사는 우곡(愚谷)선생의 높은 덕을 기리기 위하여 증손 송영(宋穎)이 숙종대에 건립한 건물로 추정된다. 17세기 후기의 건물로서는 가운데 설주, 연귀마춤 등의 치목수법(治木手法)이 건립 연대와 부합되는 수작으로 평가된다. 우곡(愚谷) 송량(宋亮, 1534～1618)선생은 유교를 실천 궁행한 대표적 선비 중의 한 분이다. 스스로 효행을 다한 선비로, 그가 사는 마을 소곡(所谷)을 효곡(孝谷)이라 부르게 된 것은 선조 17년 이후부터라 한다. 임진 왜란 때는 창의하여 전공을 세웠으며, 아들 이회(以誨)와 이필(以弼)이 양친을 구하려다가 죽고, 딸 노경건(盧景健)의 처…","a":"효곡재사","c":"시도유형문화유산","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640802.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○를 세운 시기는 정확하게 알 수 없지만 태조 1년(1392)에 세웠다고 전한다. 건물 배치는 앞쪽에 배우는 공간으로 강당인 명륜당과 학생들의 기숙사인 동재·서재가 있고, 뒤쪽에 제사지내는 공간으로 대성전과 동무·서무가 있는 전학후묘의 형태를 따르고 있다. 대성전 안쪽에는 공자를 비롯한 중국과 우리나라 선현들의 위패를 모시고 있다. 대성전 좌우에 있는 동무와 서무는 규모와 형식이 같은 건물인데 앞면 3칸·옆면 1칸 규모이다. 지붕은 옆면에서 볼 때 사람 인(人)자…","a":"면천향교","c":"시도기념물","r":"충청남도","s":"당진시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653029.jpg"},{"q":"○○○존불입상(보물)과 함께 ‘일명사’라는 옛 절터에 있던 탑으로, 군청 뒤편에 옮겼다가 1961년 지금의 장소로 옮겨 세웠다. 형태는 1층 기단(基壇) 위에 3층의 탑신(塔身)을 올린 모습이다. 기단은 간결하게 짜여 있고, 탑신은 각 층 몸돌과 지붕돌을 각각 한 돌로 만들어 쌓아 올렸다. 탑신의 1층 몸돌 앞면에는 문짝모양을 본 떠 새겼다. 꼭대기에는 노반(露盤:머리장식받침), 앙화(仰花:활짝 핀 연꽃모양 장식) 등이 남아 머리장식을 하고 있다. 고려시대에 제작된 것으로 보인다.","a":"청양삼층석탑","c":"문화유산자료","r":"충청남도","s":"청양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661138.jpg"},{"q":"은진 송씨 문중의 송종만이 조선 고종 3년(1866)에 지은 가옥이다. 처음에는 유전리에 있던 것을 1986년에 지금 있는 자리로 옮겨 지었다. 본채는 앞면 5칸·옆면 2칸의 규모이며, 건넌방·마루·큰방·부엌 순으로 배치하였다. 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다. 사랑채는 앞면 4칸·옆면 2칸 규모의 맞배지붕 건물로 모방·작은방·큰방·마루·부엌 순으로 배치하였으며, 마루에는 조각한 난간을 설치하였다.","a":"합천 역평리 송씨종가","c":"문화유산자료","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664063.jpg"},{"q":"조선 중기의 무신인 최호(?∼1597) 장군의 위패를 모신 사당이다. 장군은 선조 9년(1576) 무과에 장원급제하여 관직에 나아간 후 여러 관직을 거쳐 선조 27년(1594) 함경도 병마절도사가 되었으며, 선조 29년(1596)에는 충청도 수군절도사로 이몽학의 난을 평정하였다. 선조 30년(1597)에 정유재란이 일어나자 칠천량해전에서 원균 등과 함께 싸우다 전사하였다. 선조 37년(1604)에 이몽학의 난을 평정한 공으로 청난공신 2등에 봉해졌다. 이 사당은 최호의 후손 최호선이 영조 5년(1729)에 세운 것으로 1906년에 보수하여 오늘에 이르고 있다. 건물은…","a":"최호장군유지","c":"시도기념물","r":"전북특별자치도","s":"군산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653408.jpg"},{"q":"현재 敬天廟에 모셔져 있는 이 ○○의 인물은 임금이 쓰는 어관(冕旒冠)을 쓰고 있으면서 한편으로는 신하의 예를 갖추는 笏을 양손에 쥔 형태로 묘사되어 있어 인물의 着衣에 관해서는 추후 再考가 필요할 것이다. 그러나 신라의 마지막 임금으로서 고려에 遜國했던 까닭에 신라 임금의 모습과 고려에 대한 신하의 예를 동시에 갖추고 있는 모습으로 동시에 묘사된 것으로 추정된다. 그리고 제작시기에 관해서는 세밀한 필치와 음영이 표현된 채색 등의 묘사방식과 화풍으로 보아 1677년 이후의 개모기록은 남아 전하고 있지 않지만 1677년 이후 다시 한 번 개모되었으며 개모된 ○○은 소실…","a":"하동 경천묘 경순왕 어진","c":"시도유형문화유산","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643089.jpg"},{"q":"○○○는 통일신라 흥덕왕 7년(832)에 무량국사가 세운 절로 ○○○은 1979년에 새로 지은 건물이다. 앞면 3칸·옆면 2칸 규모이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 안쪽에는 수기삼존불좌상을 모시고 있으며, 지장탱화·신중탱화 등도 함께 모시고 있다.","a":"함안 장춘사 대웅전","c":"문화유산자료","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663813.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다 원래는 군서쪽 8리에 있던 것을 중종 37년(1542)에 주세붕이 이곳으로 옮겨 지은 후 숙종 18년(1692)에 다시 옛터로 되옮겼다가 영조 11년(1735)에 현재의 위치로 옮겼다. 남아있는 건물로는 공부하는 곳인 명륜당, 향교를 관리하던 교직사, 사당 출입문인 내삼문, 사당인 ○○○과 동·서무 등이 있다. 특히 ○○○과 동·서무의 벽과 창호가 특이해 고풍스럽다. 조선시대에는 국가로부터 토지와 전적·노비 등을 받아 학생들을 가르쳤으나, 갑오개혁(1894) 이후 제사만 지내…","a":"풍기향교<대성전동.서무>","c":"시도유형문화유산","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640709.jpg"},{"q":"○○○○는 우리나라를 비롯하여 일본, 대만, 중국 등의 따뜻한 지방에 분포하고 있다. 가지가 사방으로 퍼져 자라서 둥근 형태로 보이며, 꽃은 5월에 피고 열매는 원반모양으로 10월에 익는다. 줄기가 굵고 수명이 길어서 쉼터역할을 하는 정자나무로 이용되거나 마을을 보호하고 지켜주는 당산나무로 보호를 받아왔다. ○○○○○의 ○○○○는 2그루로, 나이가 약 400년 정도로 추정된다. 큰 나무는 높이 12∼13m, 둘레 230∼235㎝이다. 또 한 그루는 높이 12m, 둘레 185∼190㎝이다. 이곳 ○○○○는 당산목으로 신묘 양측에 위치한다. 1914년 행정구역 개편 전…","a":"고흥 대강리 느티나무","c":"시도기념물","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654367.jpg"},{"q":"일반적으로 임진왜란 이전의 ○○○는 자료의 희소성으로 국가유산적 가치를 인정받고 있다. ‘○○○○○’ 9점은 여타 ○○○와는 달리 형식은 단조롭지만 시기적으로 모두 임진왜란 이전의 것이라는 점에서 국가유산적 가치가 있다. 특히 이러한 사가 소장의 ○○○들은 시간이 지남에 따라 산일(散逸)되는 경우가 많다는 점에서 유형문화유산으로 지정되었다.","a":"김언신 관련 고문서","c":"시도유형문화유산","r":"경상북도","s":"포항시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641129.jpg"},{"q":"○○ 도천리 ○○○는 철종 6년(1855) 4월 하문도·하락도 형제가 ○○○를 짓고 같은 해 ○○○판 호정집(浩亭集)을 다시 간행한 곳이다. 철종 12년(1861년) 이후부터 최근까지 후학을 양성하는 기관인 위양서원으로 이용하다가 학생이 줄어 문을 닫았다. 문충공 하륜의 사당인 문충사, 위양서원, 선장각, 동·서재 등은 없어졌지만 2009년 11월 경상남도 문화유산으로 지정되어 ○○○를 해체·보수한 상태로 관리되고 있다. 1976년에 문충공(文忠公) 하륜(河崙)의 제19세손 종손 하경식(河景植)이 ○○○ 기와를 보수한 이력이 있다. 재실은 정면 4칸 측면 2칸의 규모…","a":"함양 경충재","c":"문화유산자료","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2642989.jpg"},{"q":"이 책은 조선과 러시아 간에 체결한 조약문서이다. 그 내용은 조선과 러시아가 자유롭게 영원히 통상하자는 것이다. 당시 조선이 수입한 것은 농기, 주류 등 39종, 호박 등 32종, 약품 등 4종이며, 수출은 금은 등 5종, 홍삼 등 다수이다. 조선에서는 고종 21년(1884) 5월 15일에 특간전권대신 김병시가 서명을 하였고 같은해 6월 25일에 러시아 전권대신이 서명을 하였다. 또한 고종 22년(1885) 8월 16일에 고종이 경복궁에서 직접 서명한 것이다. 이것은 러시아와의 외교사를 연구하는데 중요한 자료이다.","a":"조아통상조약(한문, 아문)","c":"시도유형문화유산","r":"서울특별시","s":"서초구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2587935.jpg"},{"q":"옛 나주군청에 서 있는 비로, 원래는 과원동 사매기 (‘사마교’의 음이 잘못 전하여 생긴 말인듯함)의 한 민가 담 옆에 있던 것을 1968년 이곳으로 옮겨 놓았다. 고려 현종 2년(1011) 거란이 쳐들어오자 왕은 수도 개경을 떠나 남쪽으로 피신하게 되었고, 이곳 나주에서도 10여일 동안 머무르는 일이 있었다. 왕이 네 마리의 말이 이끄는 수레를 타고 다리를 지나갔는데, 그 때부터 이 다리를 ‘사마교’라 불렀으며, 조선시대에 와서 고을 현감이 이 다리를 수리한 후 그 기념으로 비를 세워 놓았다. 비는 낮은 사각 받침돌 위로 비몸을 세우고 머릿돌을 올린 모습이다. 받침…","a":"사마비","c":"문화유산자료","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662025.jpg"},{"q":"적려란 귀양 또는 유배되어 갔던 곳을 이르며, ○○○는 한 인물의 옛 자취를 밝히어 후세에 알리고자 세워두는 비를 말하는 것으로, 이 비는 조선 중종 때 이곳에 유배당한 ○○○ 선생의 옛 자취를 기록해 두고 있다. ○○○ 선생의 호는 정암으로, 중종 10년(1515) 문과에 급제하여 성균관전적, 사헌부감찰, 예조좌랑 등을 역임하였다. 중종 14년(1519)에는 대사헌에 이르렀으나 기묘사화를 당해 이곳 능주 지방으로 유배되었으며, 그해 12월 20일에 사약을 받았다. 그는 기성세력을 축출하고 새로운 정치질서를 이루려다 뜻을 이루지 못하였으며 그가 죽은 후 선조 대에 와…","a":"화순정암조광조선생적려유허비","c":"시도기념물","r":"전남광주통합특별시","s":"화순군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654082.jpg"},{"q":"신도비란 왕이나 고관 등의 평생업적을 기록하여 후세에 전하고자 그의 묘 남동쪽에 세워두는 것으로, 이 비는 조선 선조 때의 문신인 김용(1557∼1620) 선생의 행적을 기리고 있다. 선생의 호는 운천으로, 34세에 문과에 급제하여 벼슬길에 올랐다. 예문관 검열·병조참의 등의 관직을 거쳤으며, 임진왜란이 일어났을 때에는 안동수성장이 되어 많은 공을 세웠다. 그 후 편수관이 되어『선조실록』의 편집과 편찬에 참여하기도 하였다. 비각안에 있는 비는 낮은 사각받침돌 위로 비몸을 세우고, 반달모양의 머릿돌을 올린 모습이다. 조선 고종 29년(1892)에 세운 것으로, 권연하가…","a":"운천신도비","c":"문화유산자료","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662463.jpg"},{"q":"보신각은 일명 종각이라고도 하며 고종 32년(1895) 보신각이란 사액을 내린데서 이름이 지어졌다. 태조 4년(1395)에 처음 지어진 후 4번이나 불타 없어지고, 8번에 걸쳐 다시 지어졌다. 현재의 건물은 1979년 8월에 서울시에서 지은 것으로, 동서 5칸·남북 5칸의 2층 누각으로 되어있다. 보물 \"옛 보신각 동종\"은 조선 세조 14년(1468)에 만들어져 원각사에 있다가, 절이 폐사된 후 광해군 11년(1619)에 현재의 보신각 자리에 옮겨졌다. 보신각종은 오전 4시에 33번, 오후 7시에 28번을 울려 도성의 문을 여닫고 하루의 시각을 알리는 역할을 해왔다.…","a":"보신각터","c":"시도기념물","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2018102309271400.jpg"},{"q":"병자호란 때 강화도에서 순절한 윤전(1575∼1636)의 제사를 모시는 곳이다. 윤전은 조선 중기 문신으로 광해군 2년(1610)에 문과에 급제하였으나 1613년 이이첨과 이위경으로 인해 파면되었다 다시 기용되어 1615년 호조좌랑에 이르렀으나 이위경 등에게 몰려 파면되었다. 인조반정으로 경기도도사로 복직되었고 이듬해 이괄의 난 때는 공주에 피신한 인조를 호위하였다. 인조 14년(1636) 병자호란이 일어나자 빈궁을 모시고 강화도로 들어가 적과 싸우다 전사하였다. 그 뒤 이조판서로 임명되었으며 충헌(忠憲)이라는 시호를 받았다. 이 건물은 월래 노산군 노성면 병사리에…","a":"충헌공윤전사우","c":"문화유산자료","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661340.jpg"},{"q":"합덕 평야에 농업용수를 조달하던 저수지로, 연꽃이 만발해 연지(蓮池)라고도 불리웠다. 지금은 저수지가 논으로 변하여, 제방만이 남아 있다. 제방은 평지로부터 높이 7∼8m, 전체길이 1,771m에 이르는 큰 방죽으로, 흙을 쌓아 만들었으나 후에 돌을 이용하여 보수한 부분도 보인다. 제방의 서쪽 끝에는 보수할 때의 기록을 적어둔 중수비가 5기 남아있다. 제방이 만들어진 정확한 연대는 알 수 없으나, 통일신라 후기 후백제를 세운 견훤이 축조한 것으로 전하고 있다. 김제 벽골제의 제방이 일직선인데 비해, 이곳의 제방은 곡선으로 이루어져 있어 특이하다.","a":"당진 합덕제","c":"시도기념물","r":"충청남도","s":"당진시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652801.jpg"},{"q":"돈대는 해안가나 접경 지역에 쌓은 소규모 관측·방어시설이다. 병사들이 돈대 안에서 경계근무를 서며 외적의 척후 활동을 비롯한 각종 수상한 정황을 살피고 대처한다. 적이 침략할 때는 돈대 안에 비치된 무기로 방어전을 펼친다. 1679년(숙종 5) 5월에 완성된 48돈대에 이후 5개 돈대가 추가로 지어졌다. 48돈대는 황해도·강원도·함경도 승군 8,900명과 어영청 소속 어영군 4,262명이 80일 정도 걸려서 쌓았다. 돈대 축조를 기획하고 감독한 이는 병조판서 김석주였고 실무 총괄은 ○○유수 윤이제였다. ○○○○는 1679년(숙종 5)에 쌓은 48돈대 가운데 하나로 오…","a":"강화 화도돈대","c":"문화유산자료","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/0000000001659580.jpg"},{"q":"지방 양반들이 행정업무를 도우면서 향촌의 사회·정치적 지위를 유지하기 위하여 모였던 건물이다. 서울과 지방의 연결고리 구실을 하기도 했다. 1500년대 말에 현감 벼슬을 지내던 한순이 처음 세웠으나 임진왜란 때 없어졌고, 광해군 2년(1610)에 손자인 한진이 다시 세웠다고 한다. 그 뒤 여러 차례 고쳐 지었고 일제시대에는 일본군이 업무를 처리하던 곳으로 이용하였다. 1995년까지 상주시에서 업무를 처리하는 곳으로 사용하였다. 앞면 5칸·옆면 2칸 규모인데 건물 자체는 많이 훼손되었다. 지방 양반들이 이곳에서 향촌사회의 발전을 위해 자발적으로 참여했다는 점과 향청이…","a":"상주향청","c":"문화유산자료","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663163.jpg"},{"q":"경상남도 사천시 정동면에 있는 이 산성은 일명 ‘고읍성’이라고도 한다. 옛 사천고을의 중심이 되는 읍의 소재지가 산성과 가까운 정동면 고읍리에 있었기 때문에 붙여진 이름이다. 성은 정상의 산봉우리를 둘러싼 테뫼식 산성으로, 현재는 둘레 약 1109m, 높이 3.5m의 흙으로 쌓은 성벽이 남아 있다. 그러나 남쪽 가파른 언덕에 길이 4m, 높이 3m 가량의 돌로 쌓은 벽이 남아 있어, 원래는 흙과 돌을 혼합하여 쌓은 산성으로 보인다. 기록에 의하면 돌로 쌓은 벽의 둘레는 1,941척이라 하였으며, 성 안에는 샘, 무기고, 서낭신을 모시는 성황단, 통신수단인 봉수대가 있…","a":"사천성황당산성","c":"시도기념물","r":"경상남도","s":"사천시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655694.jpg"},{"q":"암행어사로 많은 일화를 남긴 박문수(1691∼1756)의 제사를 모신 곳이다. 박문수는 조선 후기 문신으로 경종 3년(1723) 문과에 급제하여 병조정랑에까지 올랐다가 1724년 노론이 집권할 때 파면되었다. 1727년 소론이 집권하면서 다시 기용되어 영남암행어사, 충청도암행어사 등을 거치며 부정한 관리들을 적발하였다. 그 뒤 호조참판을 거쳐 병조판서와 영의정에까지 벼슬이 올랐다. 이 건물은 1932년에 세웠으며 안채는 ㄱ자형으로 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다. 사랑채는 5칸 규모이며 一자형 평면을 갖춘 집이다. 재실 안에는 박문수 공…","a":"고령박씨종중재실","c":"문화유산자료","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661356.jpg"},{"q":"송파 박전과 그의 부인 신안 주씨의 유덕을 추모하기 위하여 후손들이 세웠다. 박전(1514∼1558)은 조선 명종 1년(1546)에 문과에 급제하여 호조정랑, 북평사를 역임하였고 명종 13년(1558)에 죽었다. 그 뒤 부인 주씨는 3년상을 치른 후 어린 아들과 함께 친정인 울진으로 갔다. 그리고 순흥 땅 화천리로 이사하여 아들 박선장을 남삼송에게 가르침을 받게 해 문과에 급제하여 크게 이루니, 후세 사람들이 주씨 부인의 행적을 추모하여 정자를 세웠다. ‘○○○’이라는 이름은 박전이 돌아가신 후 그의 부인이 꿈에서 계시를 받아 꽃 ‘화(花)’자가 든 화천리를 택하여…","a":"몽화각","c":"문화유산자료","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662708.jpg"},{"q":"○○○○○은 1929년 성당 2대 주임신부였던 라크루가 ○○○○의 ○○○으로 건축하였다. ○○○은 르네상스식과 로마네스크 양식이 절충된 최신의 서양식 건축물이었다. 규모는 지상 3층이고 공사비는 15,000원이 소요되었다.현재 초기의 건축물 형태를 전체적으로 유지하고 있으며 외관이 아름답다.","a":"전동성당사제관","c":"문화유산자료","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661858.jpg"},{"q":"대은(大隱) ○○○은 원(元)나라 출신 무장(武將)으로 본관이 황주(黃州)이며, 1351년에 공민왕(恭愍王)을 따라 고려로 왔다. 공민왕은 ○○○에게 판추밀부사 원개(元顗)의 딸과 혼인을 주선하고, 본관을 원주(原州)로 바꾸게 하였는데, 이 일을 계기로 ○○○은 원주변씨의 시조가 되었다. ‘○○○ 묘’는 양주(楊州) 주엽산(注葉山)에 있었는데 인근에 조선 세조(世祖) 광릉(光陵)이 조영되면서 현재 위치인 풍양(豊壤) 오리동(吾利洞)으로 옮겼다. 이후 ○○○ 묘소가 실전되었다가 다시 찾은 뒤에 1571년 묘표(墓表)를 건립했다. ○○○ 묘표는 운수방부(雲首方趺; 구름이…","a":"대은변안렬묘역","c":"문화유산자료","r":"경기도","s":"남양주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660242.jpg"},{"q":"○○는 승려의 무덤을 상징하여 그 유골이나 사리를 모시는 곳으로, 이 ○○는 백련사 일주문 옆 ○○밭에 자리하고 있다. 둥근 바닥돌 위에 종모양의 탑신(塔身)을 올려 놓은 간단한 형태를 하고 있다. 바닥돌과 탑신의 맨 윗부분은 연꽃을 둘러 조각하였고, 꼭대기에도 연꽃을 새긴 머리장식을 올렸다. 전체적으로 연꽃 장식 외에는 별다른 꾸밈이 없는 단순하고 소박한 모습이다.","a":"매월당 부도","c":"시도유형문화유산","r":"전북특별자치도","s":"무주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639431.jpg"},{"q":"전라남도 도청 앞뜰에 놓여 있는 8각 석등으로, 불을 밝혀두는 화사석(火舍石)을 중심으로 아래에는 3단의 받침을 두고, 위에는 지붕돌과 머리장식을 올렸다. 받침부분은 길쭉한 가운데기둥을 사이에 두고, 아래 ·위 받침돌에 연꽃무늬를 대칭적으로 새겼다. 화사석은 4곳에 창을 두었으며, 그 위에 얹어진 지붕돌은 규모가 작아서인지 다른 부재들과 균형을 이루지 못하고 있다. 전체적으로 통일신라의 일반적인 석등양식을 하고 있으나, 당시에 비해 조각기법이 조잡하고 섬세하지 못하다. 석등의 가운데 기둥에는 ‘무진(戊辰)’이라는 기록이 있는데, 조각양식과 관련지어 볼 때 고려 전기…","a":"광주재명석등","c":"시도유형문화유산","r":"전남광주통합특별시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637140.jpg"},{"q":"○○○는 청동기 시대의 대표적인 무덤으로 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 거대한 덮개돌[上石]이 지상에 드러나 있고 그 밑에 고임돌[支石], 묘역시설(墓域施設), 무덤방 등이 있는 구조를 가지고 있다. 하지만 지역과 시기에 따라 그 형태는 매우 다양하다. 일반적으로는 무덤방이 지상에 위치한 탁자식(卓子式)과 지하에 위치한 기반식(碁盤式) 또는 바둑판식으로 분류하고 있다. ‘○○○○○’는 경안천 주변의 완만한 구릉에 위치하는 탁자식 ○○○이다. 2기의 ○○○가 동서 방향으로 5m 간격을 두고 분포하는데, 이 가운데 1호 ○○○는 비…","a":"용인 왕산리 지석묘","c":"시도기념물","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645968.jpg"},{"q":"이 불상은 50여 년 전부터 ○○○에 보존되어 있었던 석가여래상으로, 근래 새로 금칠하여 이곳에 봉안하고 있다. 고개를 앞으로 숙인 채 책상다리를 하고 앉아 있는 모습인데, 단정한 신체와 안정된 자세 등 조선후기 불상의 특징을 보여준다. 얼굴은 사각형에 가까우면서도 온화한 인상이다. 이목구비 역시 단아한데, 가늘고 길게 뜬 눈, 아담한 코, 단정하게 다문 입, 짧은 턱 등이 돋보인다. 옷차림새는 두 어깨를 모두 가린 형식을 취하고 있다. 이 불상은 양식적 특징으로 보아 17세기경의 작품으로 보인다.","a":"극락암목조여래좌상","c":"문화유산자료","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661805.jpg"},{"q":"18세기 불화의 전통을 계승하고 있는 탱화로 19세기 중후반 전라도와 경상도에서 활발한 활동과 함께 많은 작품을 남기고 있는 작품세계를 살펴볼 수 있다. 1981년 화재로 대웅전이 전소되면서 삼존불과 후불탱, 괘불탱 등 많은 성보가 소실된 후 각 전당이나 요사 내에 남아 있는 성보자료 등을 지금의 임시 수장고에 보관하고 있다. 보관된 성보 중 주존지장탱과 10위의 시왕탱 중 7위 만 양호한 상태로 보존되어 있다.","a":"남해 화방사 지장시왕탱","c":"시도유형문화유산","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2020041114233500.jpg"},{"q":"부도란 승려의 무덤을 상징하여 그 유골이나 사리를 모셔둔다. 이 부도는 군산의 보천사에 있던 것을 이 곳 혜봉원으로 옮겨놓은 것으로, ‘연화당부도’라 부르기도 한다. 전체적인 모습은 낮은 사각바닥돌 위로, 3단을 이루는 8각 기단(基壇)을 쌓고, 공모양의 탑몸돌을 올린 후 8각 지붕돌을 얹은 구조이다. 기단 중에서 아래받침돌은 두 겹의 연꽃잎을 둘러 새겼으며, 그 위로는 가운데받침돌을 괴기 위한 높직한 받침을 하나 더 두었다. 이 받침은 이 부도에서만 볼 수 있는 특이한 모습으로, 위는 좁고 아래는 넓어서 각면이 사다리꼴을 이루며, 위아래에 연꽃무늬 등을 새겨 장식하…","a":"모현동부도","c":"문화유산자료","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661627.jpg"},{"q":"○○○는 통일신라 애장왕 5년(804)에 세운 절로 법당과 부속건물 및 여러 암자를 갖추고 있는 절이다. ○○○은 조선 광해군 12년(1620)에 지었다는 기록이 있으나 정확하지 않다. 숙종 21년(1695)에 고쳐 지은 후, 여러 차례 보수를 거쳐 오늘에 이르고 있다. 앞면 6칸·옆면 6칸 규모의 건물로 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다. 간결한 조선 후기의 건축 양식을 보이는 좋은 예로서 소박한 옛 건축의 아름다움을 느끼게 한다.","a":"파계사적묵당","c":"문화유산자료","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659464.jpg"},{"q":"풍양 조씨 3인(석곡 조박·성강 조견소·퇴수재 조성복)을 기리고 있는 서원이다. 조박(1577∼1650)은 선조 39년(1606)에 과거에 급제하여 벼슬길에 올랐다. 국정을 수행하는 최고의 관료집단인 당상관 중에 통정대부를 지냈다. 조견소(1611∼1677)는 조선 후기의 문신으로, 관직이 금구현령에 이르렀으나 사직하고 학문과 후학을 가르치는데 전념했다. 조성복(1681∼1723)은 벼슬이 대사간에 이르렀으나 정치적으로 반대하는 이들에 의해 유배되어 그곳에서 죽음을 맞았다. 이 서원은 영조 33년(1757) 세도면 동사리에 처음 지었는데, 처음에는 조성복의 위패만을…","a":"퇴수서원","c":"문화유산자료","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661036.jpg"},{"q":"○○○는 통일신라 애장왕 5년(804)에 세운 절로 법당과 부속건물 및 여러 암자를 갖추고 있는 절이다. ○○○을 지은 시기는 알 수 없으나 1976년에 고쳐 세우고 1979년 보수를 거쳐 오늘에 이르고 있다. 앞면 1칸·옆면 1칸 규모이며, 지붕은 옆면에서 볼 때 사람 인(人)자 모양을 한 맞배지붕이다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 기둥 윗부분에 새 날개 모양으로 짜올렸다. 건물 안팎으로는 단청을 하여 화려함을 더하고 옆면 외벽에도 그림을 그려 넣었다. 전통 민간신앙이 불교에 습합(習合)되어 나타난 전각 중 하나로 화려한 꾸밈을 엿볼 수 있다.","a":"파계사산령각","c":"문화유산자료","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659462.jpg"},{"q":"전남 해남군 북평군 이진리 해안에 돌로 쌓은 성이다. 선조 21년(1588)에 군대의 진을 세우고 인조 5년(1627)에 만호진으로 승격되었는데 이 당시에 쌓은 것으로 보인다. 『여지도서』의 기록에 보면 군 남쪽 120리에 있고 성은 돌로 쌓은 석성으로, 둘레는 1,470척, 높이 8자이며 샘이 2개있다고 전한다. 『문화유적총람』에는 둘레 2.5㎞의 성지로 인조 26년(1648)에 만호(각 진에 배치한 종4품의 무관직)를 두어 성을 세웠고, 성 주위로 바다 호수를 만들어 왜군이 침입하지 못하게 하였다고 한다. 또 이진은 제주도 출입 통제소이기도 하였으며, 제주도의 말…","a":"이진성지","c":"시도기념물","r":"전남광주통합특별시","s":"해남군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2019052020401600.JPG"},{"q":"조선 전기 문신인 ○○○ 선생은 본관이 재령(載寧)으로 『동국통감(東國通鑑)』을 편수하는 데 참여했으며, 청백리에 녹선되었다. ○○○○○ 묘는 부인 파평윤씨(坡平尹氏)와 쌍분(雙墳)으로 조성되어 있다. 각 봉분 앞에는 묘표와 석상, 향로석 등이 놓여 있다. 두 봉분 사이에는 우의정(右議政) 허침(許琛, 1444~1505)이 지은 비문을 1956년에 후손들이 그대로 옮겨 세운 건립한 묘비가 있다. 각 봉분 앞의 묘표는 하엽수(荷葉首; 연잎 형태의 비석 머리)로 건립되었다. 봉분 좌우에는 문인석 1쌍이 건립되어 있다. 묘표와 문인석은 15세기 작품이며, 다른 석물들은 현…","a":"이맹현선생묘","c":"시도기념물","r":"경기도","s":"남양주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646484.jpg"},{"q":"○○○이 이몽학의 난을 평정한 후, 그 사실을 후세에 전하고자 세워놓은 비이다. 임진왜란이 일어난 후 계속되는 흉년으로 민심이 동요된 틈을 타서 왕의 종친이면서도 서자인 이몽학이 조선 선조 30년(1597)에 반란을 일으켜 홍주성을 쳐들어 왔다. 당시 ○○○은 홍주목사로 있으면서 난을 평정하였고, 그 공으로 청난공신(淸難功臣) 1등에 봉해졌다. 비는 인조 19년(1641)에 세웠는데, 오랫동안 돌보지 못하여 파손된 것을 1973년 홍성군수가 보수하여 오늘에 이르고 있다.","a":"홍가신청난비","c":"문화유산자료","r":"충청남도","s":"홍성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661162.jpg"},{"q":"이중환의 택리지에 ‘조선인재반재영남(朝鮮人材半在嶺南)’이라는 대목이 나온다. ‘조선 인재의 반이 영남에서 태어났다’는 뜻이다. 특히 진주는 강․하․정씨가 본관을 두고 있을 정도로 많은 인물들이 탄생하였으니, 진주지역에도 인명록 출판이 성행하였다. 곧, 연계안(蓮桂案)이나 향안(鄕案)이 그것들이다. 연계안은 진주출신으로서 과거에 급제한 인물들의 이름을 적은 명부이고, 향안은 진주에서 학식과 덕행을 두루 갖춘 선비의 이름을 적은 인명록이다. 조선시대 향안과 연계안에 이름이 기록된 조상을 둔 후손들은 진주시 옥봉동에 연계재(蓮桂齋)를 지어서 인명록을 소중하게 보관하면서 큰…","a":"계적안 하(1892년)","c":"시도유형문화유산","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001642560.jpg"},{"q":"○○○의 서북쪽 구릉일대에 분포한 대형 돌방무덤들이다. 사벌국에 의해 만들어진 것으로 추정되며, ○○지역에서 형성범위나 규모가 가장 큰 무덤이다. 무덤이 있는 ○○○의 정상부에는 흙과 돌을 섞어 쌓은 ○○○성이 축조되어 있어, 무덤을 만든 세력의 힘을 짐작할 수 있게 해준다. 아마도 그 세력은 사벌국의 중심세력이나 삼국시대 ○○지역의 지방 유지세력에 의해 만들어졌을 가능성이 크다. ○○○ 무덤들은 원삼국시대의 사벌국의 실체와 그 후에 나타난 세력의 실체를 파악하는데 중요한 단서를 제공해주는 곳이다.","a":"상주 병풍산 고분군","c":"시도기념물","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654614.jpg"},{"q":"이 교지는 장백손이 무관의 관직을 거쳐 오는 동안 받은 것으로 1490년(조선 성종 21) 선략장군행충무위우도부사직(宣略將軍行忠武衛右都副司直)에 임명되었을 때 받은 고신으로부터 시작해서 1523년(조선 중종 18)에 마지막 관직인 어모장군행오위도총부경력(禦侮將軍行五衛都摠府經歷)에 임명될 때까지 그의 관력을 상세히 알 수 있는 것으로 총 31점이다. 교지의 평면형태는 모두 장방형으로 재질은 한지로 만들었으며, 이렇게 많은 분량으로 보존상태가 양호하게 남아있는 경우는 우리나라에서 희귀하며, 특히 임진왜란 이전의 것이라는 점, 무반의 경력을 일목요연하게 보여주는 것이라는…","a":"장백손교지","c":"시도유형문화유산","r":"경상북도","s":"울진군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641178.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. ○○○ 고인돌은 기원전 1세기 경에 축조된 것으로 전형적인 바둑판식에, 지석을 여러 매 괴거나 상석이 아치 모양을 이루는 제주 형태를 취하고 있다. 특히 이 고인돌은 덮개돌의 주변으로 크고 작은 현무암 자연석을 이용하여 타원형의 적석부분이…","a":"신례리지석묘1호","c":"시도기념물","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657694.jpg"},{"q":"고려시대 문신인 성사달(?∼1380)을 비롯하여 성부·성여원·성무조 등 창녕 성씨들의 위패를 모시고 있는 사당이다. 성사달은 충혜왕 2년(1341) 문과에 급제하고 한림사성이 되었다. 공민왕 1년(1352) 억울하게 옥살이를 하였으나 곧 복직되었다. 1362년 홍건적이 침입했을 때 왕을 호위하였으며 김용의 난을 평정하여 1등공신이 되었다. 그 뒤 1364년 교주도병마사로 여진의 침입을 막아 대제학에 올랐으며 창산 부원군에 봉해졌다. 문장과 글씨에도 뛰어났으며 죽은 뒤 문효란 시호를 받았다. 사당 건물은 앞면 3칸·옆면 2칸으로 지붕은 옆에서 보면 사람 인(人)자 모양…","a":"송양사","c":"문화유산자료","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661827.jpg"},{"q":"○○○○○는 인천 최초로의 상수도 시설이자 도시계획 시설로 1905년 중도(中島)박사에 의해 경인수도 설계가 완성됨에 따라 1906년 11월 착공하여 1908년 준공되었다. 또한 1910년 10월 노량진 수원지 정수시설이 준공되어 동년 12월 급수를 하기 시작하였다. ○○○○○는 표고 56.8m에 위치하고 있으며 규모는 부지면적 36,780㎡, 5,000㎡로 저수조 3개를 갖추고 있다. 현존하는 ○○○ 건물로는 ○○○○과 23단의 화강석으로 된 장대석 계단과 철제 정문이 있고 정문은 화강석 초반 위에 콘크리트 기둥을 심고 4각 모양과 둥근 화강석의 주두로 이루어져 있…","a":"송현 배수지 제수변실","c":"문화유산자료","r":"인천광역시","s":"제물포구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/0000000001659586.jpg"},{"q":"\"○○○○은 조선조 선조 초년의 명신인 미암 유희춘(1513～1577)의 사당이다. 유희춘은 조선 중기의 문신으로 자는 안중, 호는 미암 또는 인재(寅齋)하고 한다. 본관은 선산이며 순천에서 해남으로 이거한 유계린(柳桂麟)의 차남으로 출생하였다. 금남 최부(錦南 崔溥, 1454～1504)의 외손이다. 1537년(중종 6)에 생원시에 합격하고 다음해에 문과에 급제하여 성균관 학유, 예문관 검열, 홍문관 수찬, 무장현감 등을 지내다가 을사사화때 파직되었다. 1547년(명종 2) ‘양재역벽서사건’으로 제주로 유배되었다가 함경도 종성으로 이배되어 19년의 유배생활을 보내게…","a":"담양미암사당","c":"시도민속문화유산","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658405.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려 놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 경상북도 청도군 화양읍 ○○○에 있는 바둑판식 고인돌로 받침돌이 없는 개석식 고인돌이 무리를 이루고 있다. 이곳의 고인돌은 ○○○ 청도천 주변에 50m 정도의 간격을 두고 동쪽에 22기, 서쪽에 12기가 밀집 분포하고 있다. 이는 청동기시…","a":"청도범곡리지석묘군","c":"시도기념물","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654563.jpg"},{"q":"○○○은 별내면 청학리 수락산의 미륵봉 서쪽에 위치하고 있으며 별내면 청학리에 있는 봉선사의 말사이다. 이 곳 전각에 봉안한 불화들은 대개 해방 이후에 제작, 봉안된 것이나 괘불만은 19세기 경기·경상도에서 활발하게 활동하던 화사들의 작품으로 19세기 경기지방, 특히 ○○○권 불화의 지역성과 19세기 불화의 양식적인 면을 살필 수 있는 새로운 자료라고 할 수 있으며, 2004년 유형문화유산 197호로 지정되었다. ○○○의 괘불은 1885년에 조성된 것으로, 구도는 대담하고 간략하며 크게 마름모꼴을 이루는 특이한 인물 배치를 보이고 있다. 즉, 전법륜인을 한 석가모니불…","a":"남양주내원암괘불도","c":"시도유형문화유산","r":"경기도","s":"남양주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637762.jpg"},{"q":"임실 ○○○○○은 2016년 <임실군 불교유적 학술연구 용역사업>을 통해서 ○○○○○이 어깨를 덮는 통견 형태의 법의 목 부분이 'V'자 형태의 옷깃이 있는 두루마기를 입은 형상이고, 석불입상의 가슴 중앙과 등 쪽에 있는 수식(垂飾)은 조선시대 문인석에 장식된 수식의 영향을 받은 것으로 밝혀졌다. 석불에 글씨는 없었으며 미륵을 받치고 있는 받침대는 연화문이 새겨져 있는 연화대이다. 조사결과 연구진은 이 석불에 대해서 15세기 불상 조각의 전통이 남아있는 16세기 석조불상으로 추정하였다. ○○○○○을 봉안해 놓은 보호각은 1996년에 1칸짜리 전각으로 세워졌다. 높이…","a":"임실이도리미륵불상","c":"시도유형문화유산","r":"전북특별자치도","s":"임실군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639612.jpg"},{"q":"마을입구의 마련된 보호각 안에 서 있는 2구의 장승으로, 할아버지와 할머니의 모습을 하고 있다. 마을사람들은 장승이라기보다 비석이라고 부르며 있으며, 이 거리를 ＇비석거리라 칭하고 한다. 할아버지 비석은 얼굴이 전체의 절반을 차지하고 있다. 원유관을 쓴 머리, 움푹 패인 눈, 넓은 코, 두꺼운 입술, 역삼각형의 수염 등이 표현되었고, 관리가 임금을 뵐 때 손에 쥐는 홀을 들고있다. 할머니 비석은 머리가 위로 치켜올라간 듯 둥그런 얼굴을 하고 있으며, 눈은 패였고 코와 입은 닳아서 흔적만 남아있다. 지극히 희화적인 이 ○○○은 조선 헌종 4년(1838) 담양부사 홍기섭…","a":"천변리석인상","c":"문화유산자료","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661934.jpg"},{"q":"○○○ 봉명산 기슭에 있는 서봉사의 옛 절터로 주춧돌과 축대가 여기저기 흩어져 있으며, 현재는 차밭으로 개간되었다. 『영봉산용암사』, 『서봉사 사적』 등의 기록에 따르면, 신라 눌지왕(417∼457)때 세웠다고 전하며 그 당시에는 봉암사라 했으나 조선시대 때 서봉사로 바뀐 듯하다. 조선 광해군 6년(1614)에 의현 스님이 다시 지었으며, 절의 규모가 대단히 컸다고 한다. 서봉사에서 인쇄된 불경을 서울대 도서관에서 소장하고 있다.","a":"사천용산리사지","c":"시도기념물","r":"경상남도","s":"사천시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656215.jpg"},{"q":"마산 ○○○ 대웅전 향우측 불단에 봉안되어 있는 이 신중탱은 2副 1鋪의 비단으로 이루어진 액자 형태이며, 화면에는 童眞菩薩을 주존으로 하여 神衆 6位가 묘사되어 있는 탱화이다. 오랜 세월로 인해 원채색이 다소 퇴색된 것과 약간의 剝落 및 화면 곳곳에 촛농이 많이 튀어져 있는 점 이외에는 보존상태가 대체로 양호한 편이다","a":"창원 법성사 신중도","c":"문화유산자료","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666410.jpg"},{"q":"계초심학입문(誡初心學入文), 묘법연화경 권제1(妙法蓮華經 卷第一) 등 10책 모두 370년이 넘은 고전적(古典籍)이며, 불교사의 희귀 자료이다. 2004년 성주사 안심료(安心寮)에 임시 봉안된 불상을 지장전 건립과 함께 이전하여 개금(改金) 및 개채(改彩)하면서 지장보살불의 복장유물을 확인한 결과 지장보살과 시왕을 비롯한 권속일체가 1681년 신조된 사실과 조성한 화원 및 시주자 명단이 열거되어 있으며, 당시 성주사의 명칭이 웅신사(熊神寺, 곰절) 임을 알 수 있다.","a":"모자이혹론 미성책","c":"시도유형문화유산","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018102913445600.JPG"},{"q":"부도는 이름난 스님들의 유골을 모시기 위해 세운 돌탑을 말한다. 이 두 기(基)의 부도는 ○○○의 터에 있던 것이며, 현재는 시적사 경내에 위치하고 있다. 부도는 종을 닮아서 석종형(石鐘形)이라는 명칭으로 부르고, 모두 조선시대에 만들어진 것이다. 석종형 부도는 고려 말 이후부터 조선시대에 걸쳐 주로 조성되었다. 이 부도들은 지대석이 없으며, 탑신(塔身)에는 별다른 문양이 조각되어 있지 않다. 인당초 무늬의 받침돌 위에 연꽃무늬가 새겨진 좌대를 받치고 탑신을 얹었다. 크기는 각각 152㎝, 160㎝이다. ○○○○는 2001년 학술발굴조사가 이루어졌으며, 그 결과 건물…","a":"운흥사지부도","c":"시도유형문화유산","r":"울산광역시","s":"울주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637252.jpg"},{"q":"◦ ○○○○는 조선시대 1723년(경종3)에 현유(賢儒)의 위패를 봉안․배향하고 지방민의 중등교육과 교화를 위하여 창건되었음. ◦ 1868년, 1964년, 1967년에 각각 중수(重修)되었으며, 현존하는 건축물로는 정면 5칸 측면 3칸의 맞배지붕으로 된 대성전을 비롯하여 부속건물이 있으며, 전학후묘(前學後廟)의 일반적 향교 배치 양식을 따르고 있음. ◦ 동재 서재는 기숙사이며, 명륜당은 강의실임. 대성전에는 공자를 위시한 중국 5성(五聖)과 4현(四賢), 우리나라 18현(賢)의 위패가 봉안되어있음. ◦ 조선시대에는 국가로부터 토지와 노비를 지급받아 보령현감의 통제 하…","a":"보령향교","c":"시도기념물","r":"충청남도","s":"보령시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652886.jpg"},{"q":"개태사는 고려 태조 왕건이 후백제 세력을 완전히 물리친 후, 태조 23년(940)에 지은 절이다. 당시 절 안에는 태조의 초상화가 있어서 나라에 전쟁의 기미가 있으면 그 앞에 기원문을 올려 나라가 태평하기를 빌었다고 한다. 그 후 이 절은 고려 후기에 이르러 왜구의 빈번한 약탈에 의해 차츰 기울어진 것으로 보인다. 현재의 위치는 세종 10년(1428)에 옮겨진 것으로, 개태사 안에는 ○○○○삼존불상(보물 제219호)이 있고, 이외에도 석탑과 쇠솥이 있다. 전성기에 장국을 끓였다고 전해지는 이 쇠솥은 지름 3m, 높이 1m, 둘레 9.4m에 이를 정도여서 수백명의 승려…","a":"개태사지","c":"시도기념물","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652745.jpg"},{"q":"이 불상은 사명대사의 원불(願佛)이라 전하는 높이 9.5㎝의 소형 ○○○○○이다. 연화대좌 위에 편단우견의 대의를 입고 결가부좌하였으며, 왼손은 선정인, 오른손은 무릎 아래로 내려 촉지인을 결하고 있다. 대좌는 앙련과 복련이 연접한 2중의 연화좌인데 이는 고려시대 말에 유입된 라마교의 불상양식으로 이를 통해 제작연대를 추정해 볼 수 있다. 소규모의 불상이지만 안정적인 비례감을 지니고 있고, 손톱과 발가락, 연화좌 등 세부표현도 매우 치밀하게 이루어져 있다. 원만상일 뿐만 아니라 완형이며 보존상태도 양호하다.","a":"포항 대성사 소장 금동여래좌상","c":"시도유형문화유산","r":"경상북도","s":"포항시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641210.jpg"},{"q":"화면 하단 중앙 가장자리 밖에에 화기란을 마련한 후 적색 바탕에 화기를 묵서하고 있는데 화기 아래 부분이 그을림으로 인해 몇몇 자가 판독하기 어렵다. 화기에 의하면 光緖 庚寅 4월에 표충사에서 제작하여 玄堂에 봉안하였다고 하며 이탱화를 제작한 金魚로는 奉?와 妙英이었다고 한다. 畵記에서 확인되는 바와 같이 1890년 表忠寺에서 제작된 탱화로 19세기말 신충탱의 양식을 살펴볼 수 있는 자료이다.","a":"밀양운주암신중탱","c":"문화유산자료","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666422.jpg"},{"q":"○○○는 횃불과 연기를 이용하여 급한 소식을 전하던 옛날의 통신수단을 말한다. 높은 산에 올라가서 불을 피워 낮에는 연기로 밤에는 불빛으로 신호를 보냈다. ○○○에 있는 이 ○○○○는 조선시대 봉수체제가 확립되었던 세종 24년(1438)에 ○○○ 동·서에 만든 ○○○ 가운데 동쪽 ○○○○이다. 평안북도 강계에서 시작하여 황해도, 경기도 내륙, 고양 해포나루, 무악동봉, 남산 훈도방으로 연결되는 봉수를 남산에 최종적으로 연락하는 곳이다. 터만 남아있던 것을 서울정도 600년 기념사업의 하나로 1994년에 복원하였다.","a":"무악산동봉수대터","c":"시도기념물","r":"서울특별시","s":"서대문구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1644788.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다. 조선 명종 15년(1560)에 세워진 ○○○○는 고종 7년(1870)과 24년(1887)에 고쳤고, 후에 여러 번의 수리를 거쳐 오늘에 이르고 있다. 현재 남아있는 건물은 대성전·동재·서재·명륜당 등이 있다. 건물은 내삼문을 경계로 앞쪽에는 학생들이 공부하던 명륜당을 중심으로 배움의 공간을 두고 있다. 뒤쪽에는 공자를 비롯하여 여러 성현들의 제사를 지내는 대성전이 있어, 향교의 일반적 배치형태인 전학후묘를 따르고 있다. 특히 동재·서재가 다른 곳과는 달리 명륜당의 뒤쪽에 있…","a":"음성향교","c":"시도유형문화유산","r":"충청북도","s":"음성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638550.jpg"},{"q":"보(洑)라는 것은 논에 물을 대기 위하여 둑을 쌓고 냇물을 가두어 두는 곳을 말한다. 원래 정읍천과 태인천 상류에 농민들이 설치한 보가 있었으나, 고종 30년(1893) 고부군수 조병갑이 농민들을 강제로 동원하여 두 하천이 합류하는 하류지점에 새로 만석보를 축조하였다. 만석보가 완공된 후 가을에 새 보에 대한 수세라는 명목으로 많은 양의 쌀을 착취하자 농민들이 분개하여 1894년 전봉준을 중심으로 민란을 일으켜 동학농민운동의 발단이 되었다. 만석보는 농민들에 의하여 파괴되어 지금은 둑을 쌓았던 흔적만이 남아있다. 1973년 동학농민운동의 근원지인 이곳을 기념하기 위해…","a":"만석보지","c":"시도기념물","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653411.jpg"},{"q":"『유암총서(柳菴叢書)』,『○○○○』는 이강회(李綱會; 1789~?)가 ○○○○○에 칩거하면서 자신의 글과 스승인 정약전, 정약용 형제의 글을 한데 묶어 놓은 문집의 초고본에 해당한다. 다른 곳에서는 발견할 수 없는 정약전의 저서 「표해시말(漂海始末)」(유암총서 수록)․「송정사의(松政私議)」(○○○○ 일권에 수록)가 담겨져 있으며, 정약용의 속담 한역(俗談漢譯) 저술인 「백언시(百諺詩)」는 『여유당전서(與猶堂全書)』에 수록된 「이담속찬(耳談續纂)」의 초고본으로서 높은 가치를 지닌다. 『표해시말』에는 ○○○ 어부 문순득 일행이 유구를 비롯하여 당시 스페인이 지배하던 필리…","a":"신안 우이도 유암총서와 운곡잡저","c":"문화유산자료","r":"전남광주통합특별시","s":"신안군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662335.jpg"},{"q":"선소마을 선착장의 오른쪽 해변에 자리하고 있는 비로, 중국 명나라 장수인 ○○○이 동쪽을 정벌하고 바위에 글을 새겼다 하여 ‘○○○○○’라 이름붙인 것이다. 비의 형태는 커다란 자연석의 윗면을 직사각형으로 평평하게 갈아 글을 새겼다. 직사각형의 테 주변에는 덩굴무늬를 아름답고 정교하게 조각하였다. 비문은 이여송과 진린이 원군으로 조선의 ○○에 와서 왜군을 무찔렀다는 내용으로, 명나라 군인의 우월성을 나타내는 전승기념비적 성격을 띠고 있다. 역사적 자료에는 선소마을에서 명의 수군과 왜군이 싸웠다는 기록이 없어 비문의 내용이 의심스럽지만, 노량해전 직후나 그 이듬해인 선…","a":"남해 장량상 동정마애비","c":"시도유형문화유산","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641381.jpg"},{"q":"1630년을 전후한 시기에 조선시대 종4품 관청인 수문관청(守門將廳)에 소속된 ○○○들의 계회를 그린 ○○○이다. 전서체의 제목과 그림, 좌목 세 부분으로 구성된 전형적인 계축의 형식이다. 좌목에는 품직, 이름, 자, 생년, 무과 합격년도, 본관, 거주지 등과 부친의 품직과 이름이 기록되어 있다. 좌목 서두에 “守門將廳”이라 쓰여 있어 ○○○의 제작 주체가 ○○○들이며 총 19명의 ○○○들이 모였었음을 알 수 있다. 19명의 ○○○은 강옥(姜沃, 1588~), 김충립(金忠立, 좌목에 생년 기록 없음), 안수익(安受益, 1577~?), 박준민(朴俊敏, 1586~?),…","a":"수문장계회도","c":"시도유형문화유산","r":"서울특별시","s":"노원구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636532.jpg"},{"q":"조선중기 헌마공신(獻馬功臣) ○○○ 분묘는 비교적 정확한 축조시기를 알 수 있어, 17세기 제주분묘의 산담과 봉분의 축조양식 및 구조를 파악할 수 있는 자료이다. 묘역 내에는 동일시기로 추정되는 봉분 1기, 혼유석(魂遊石) 1기, 비석 1기, 문인석 2기 등이 있으며, 문인석은 돌하르방과 같은 형태의 제주형으로 제주 고유의 석물문화를 밝히는데 중요자료가 된다. 헌마공신 ○○○은 1592년부터 인조대(1623~1649)에 걸쳐 계속된 전쟁당시에 자신의 제주마를 수차 국가에 헌납하여 ‘헌마공신’이란 칭호를 받았다. 지위는 종2품 가선대부(嘉善大夫) 오위도총부도총관(五衛都…","a":"의귀리 김만일묘역","c":"시도기념물","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1658019.jpg"},{"q":"○○군 하일면 ○○○ 927번지내 ○○○○○는 약 330년전 하일면 학동마을에 정착하면서 축조한 건축물로 토담과 납작한 돌로 축담을 층층이 쌓은 후, 그 위에 건축물을 축조한 형태는 다른 지역에서는 볼 수 없는 특이하고 독특한 양식으로 안채와 사랑채, 고방채, 토담으로 잘 쌓은 창고, 집안의 텃밭, 마을의 특색인 돌축대, 축대위로 토담과 넓은 돌덮개 지붕으로 된 닭장, 안채뒤 장독대는 계단식 돈대로 그 면적이 상당히 넓고 고풍스러움을 풍긴다","a":"고성 학림리 최씨종가","c":"시도민속문화유산","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659073.jpg"},{"q":"이 석탑은 기단(基壇)이 제대로 갖추어지지 않은 채, 평평한 돌 위로 5층의 탑신(塔身)이 올려져 있다. 탑신의 1층 몸돌은 2개의 돌로 이루어졌고, 나머지 몸돌과 지붕돌은 각각 하나의 돌로 만들어졌다. 1층 몸돌은 큰편이고, 2층 몸돌에서 급격히 낮아지다가 5층까지는 비슷한 크기를 유지한다. 각 층 지붕돌은 두꺼운 편이며, 밑면에는 5단씩의 받침을 두었다. 전체적으로 비례가 좋지 않고, 지붕돌이 두꺼워진 점 등으로 보아 고려시대 작품으로 짐작된다. 일제시대에 쓰러졌던 것을 1967년 마을 주민들이 다시 세워놓은 것이다.","a":"괴산 봉학사지 오층석탑","c":"시도유형문화유산","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638445.jpg"},{"q":"○○○○○은 \"기미(1919년) 3·1운동\"보다 5개월 먼저 일어난 제주도내의 최초 최대의 ○○○○이자 1910년대 종교계가 일으킨 전국 최대 규모의 무장○○○○이다. 1918년 10월 7일(월) 서귀포시 도순동 산1번지에 있는 ○○○에서 평소 일본제국의 통치를 반대하던 불교계의 김연일(金連日) · 방동화(房東華) 등 승려들이 중심이 되어 ○○○ 신도와 ·선도교도 · 민간인 등 700여명이 집단으로 무장하여 2일 동안 조직적으로 일본에 항거한 ○○○○으로서, 1919년대의 3·1운동을 비롯하여 민족항일의식을 전국적으로 확산시켜나가는 선구적인 역할을 하였다. ○○○○○…","a":"무오법정사항일운동발상지","c":"시도기념물","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1658004.jpg"},{"q":"이 곳은 신라시대의 지극한 효자인 손순(孫順)의 유허지이다. 이 곳에 조선말기 학자인 허전(許傳)이 찬술한 비문을 새긴 유허비(遺墟碑)가 있었다고 전한다. 신라 흥덕왕(興德王) 때의 사람인 손순의 효행은 『삼국유사, 三國遺事』에 기록되어 있다. 이 책의 손순매아(孫順埋兒)편에 따르면, “모량리(牟梁里)의 손순과 그 아내는 자신의 어머니를 봉양하기 위하여 음식을 빼앗아 먹는 아들을 땅에 묻기로 하고, 취산(醉山)으로 들어가 땅을 파다가 이상한 석종(石鐘)을 하나 얻었다 이에 하늘의 뜻이라 하고 아이를 묻지 않고 집으로 돌아와 석종을 매달아 두들겼더니 그 소리가 왕궁에까…","a":"경주손순유허","c":"시도기념물","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654595.jpg"},{"q":"선운사 참당암 대웅전 안에 있는 입 지름 50㎝의 조선시대 범종이다. 종을 매다는 용뉴는 용이 네발을 종에 대고 웅크리고 있는 형상이다. 어깨부위에는 둥근 원으로 띠를 두르고, 원안에 범자를 양각하였다. 몸통 위쪽으로는 직사각형으로 외곽을 두른 보살입상을 4면에 주조하였고, 그 사이에는 사각형 모양의 유곽을 배치하였다. 유곽의 테두리는 빗살무늬로 장식하였고, 내부에는 꽃모양을 한 4개의 유두가 있다. 보살상 아래쪽으로는 간격을 두고 굵게 두 줄의 테가 돌려져 있고, 그 사이에 명문판이 불규칙하게 주조되어 있다. 입구 부분에는 빗살무늬를 새겼다.","a":"참당암동종","c":"시도유형문화유산","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639596.jpg"},{"q":"이곳의 ○○○○○ 화석은 약 1억년 전의 전기 백악기 시대에 살았던 공룡들의 것으로 보인다. 당시의 공룡들은 아열대 기후 아래 우기와 건기가 반복되고 열대 무역풍이 영향을 미치는, 사바나 지역의 하천평야 일대에서 살았던 것으로 알려져 있다. 대곡천에는 여러 장소에서 ○○○○○이 확인되지만, 이곳의 ○○○○○ 화석은 보존상태가 가장 양호한 것이다. 이곳의 ○○○○○은 약 100㎥ 넓이의 바위에 새겨져 있는데, 용각류 팔용과에 속하는 것(60톤급)과 조각류 이구아나과에 속하는것(고성룡족인) 등 24여 개다. 일정한 방향으로 걸어가는 모습으로 남아있는 것으로 보아 공룡들은…","a":"대곡리공룡발자국화석","c":"문화유산자료","r":"울산광역시","s":"울주군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659796.jpg"},{"q":"영안부원군(永安府院君) ○○○과 청양부부인(靑陽府夫人) 심씨(沈氏, 1766~1828)의 묘역이다. ○○○은 본관이 안동(安東)이다. 정조(正祖)가 그의 딸을 간택해 훗날 순조(純祖) 정비(正妃)인 순원왕후(純元王后)가 되게 한다. 순원왕후가 중전(中殿)에 책봉되자 ○○○은 영안부원군에 봉해졌다. ‘○○○ 묘’는 합장된 봉분 앞에 혼유석(魂遊石), 상석(床石), 향로석(香爐石), 장명등(長明燈)이 차례로 놓여 있으며 묘역 좌우에 망주석도 설치되어 있다. 묘표(墓表)는 혼유석 동쪽편에 건립되어 있으며, 개석방부(蓋石方趺; 지붕돌과 네모난 비석 받침) 형태로 비신(碑身)…","a":"풍고김조순묘역","c":"시도기념물","r":"경기도","s":"이천시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2019051613435200.jpg"},{"q":"조선 선조 6년(1573)에 월곡면 도곡동에 여강서원이라는 이름으로 지었다. 처음에는 퇴계의 위패를 모시고 제사 지내다가 광해군 12년(1620)에 학봉 김성일, 서애 유성룡 2분의 위패를 함께 모시게 되었다. 숙종 2년(1676)에 임금으로부터 ‘호계’라는 이름과 토지·노비 등을 하사받았다. 흥선대원군의 서원철폐령 때 없어졌다가 7년 뒤에 강당만 새로 지어 오늘에 이르고 있다. 안동댐 건설로 인하여 1973년 이곳으로 옮겨 다시 지었다. 앞면 5칸·옆면 3칸 규모이며, 지붕 옆면이 사람 인(人)자 모양인 맞배지붕집이다. 평면상으로는 一자집인데, 지붕의 양쪽 끝이 정…","a":"호계서원","c":"시도유형문화유산","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640292.jpg"},{"q":"‘○○○○○’은 원삼국 시대 늦은 시기의 집단 무덤으로 임진강 유역에서 처음 발굴 조사된 ○○○○○이라는 점에서 의미가 있다. 이 무덤은 고구려 적석총과 다르게 분구 위의 돌층이 두텁지 않기 때문에 즙석묘, 즙석총, 즙석식적석묘 등 다양한 명칭이 사용되었지만, 최근 학계에서는 적석분구묘로 부르기도 한다. 무덤은 임진강이 남쪽으로 흐르다가 다시 북쪽으로 곡류하는 지점의 북쪽 모래 언덕 위에 위치한다. 모래 언덕은 동서 방향으로 길게 형성되어 있는데, 전체 ○○○ 모습은 타원형에 가깝다. 이 무덤은 강가에 있는 자연의 모래 언덕을 평탄하게 정지하고 그 위에 강돌로 무덤방…","a":"연천삼곶리돌무지무덤","c":"시도기념물","r":"경기도","s":"연천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646777.jpg"},{"q":"고려 때 절의를 지킨 포은 정몽주·목은 이색·야은 길재 등 삼은(三隱)의 위패를 모신 건물이다. 정몽주는 고려의 문신이자 학자로서 1360년 문과에 장원하여 1362년 예문관에 들어갔으며 이성계와 함께 여진토벌에 참여하기도 했다. 이색은 고려말의 문신이자 학자로서 충목왕 4년(1348)에 원나라에 가서 국자감 생원이 되었으며 성리학을 연구하였다. 그는 원·명 교체기 때 천명(天命)이 명나라로 돌아갔다고 보고 친명정책을 지지하였으며 유교의 입장에서 불교를 이해하고자 하였다. 길재는 고려말∼조선초의 학자로 공민왕 23년(1374)에 국자감에 들어가 생원시에 합격하였고 우…","a":"삼은각","c":"문화유산자료","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660967.jpg"},{"q":"현재 ○○○ 대웅전 석가불상의 후불도로 봉안된 ○○○○○로서, 화기에 의하면 1899년(광무 3년)에 조성하여 삼각산 청룡암 칠성각에 봉안하였으며, 화사로는 윤감(允鑑), 재겸(在謙) 등이 참여하였다. 이 불화는 ○○○○상을 중심으로 좌·우 3열 층단식 구도를 이루며 시왕 및 권속들이 배치되어 있다. 가로로 긴 화폭 중앙에 ○○○○상과 도명존자·무독귀왕이 삼각형 구도를 이루고 있으며, 다시 2열 횡대를 이루며 시왕상들이 그려져 있다. 상단에는 두루마리를 든 사자와 동녀, 장군과 옥졸, 판관과 팔부신중 등의 인물상들이 배치되어 있다. 본존인 ○○○○상은 스님 머리에 투…","a":"지장암 지장보살도","c":"시도유형문화유산","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636488.jpg"},{"q":"고려의 개국공신인 ○○○을 기리는 유적이다. ○○○은 평산 신씨의 시조로서, 918년 배현경, 홍유, 복지겸 등과 함께 궁예를 몰아내고 왕건을 추대하여, 고려의 건국에 이바지한 인물이다. 고려 태조 10년(927) 대구 공산에서 후백제 견훤의 군대와 싸우다가 태조가 적군에게 포위되어 위급해지자, 태조의 옷을 입고 변장하여 맞서다가 전사하였다. 태조는 그의 죽음을 애통히 여겨 그의 시신을 거두어 광해주(지금의 춘천)에 묻고 순절단, 지묘사, 미리사를 세워 명복을 빌었다. 조선 선조 40년(1607)에 경상도관찰사 유영순이 지묘사의 자리에 표충사를 지어 ○○○을 모셨으며…","a":"신숭겸장군유적","c":"시도기념물","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645328.jpg"},{"q":"조선 중기의 유학자 신독재(愼獨齋) 김집(1574∼1656)의 묘이다. 18세에 진사에 합격하고 광해군 2년(1610)에 참봉이 되었으나 광해군의 문란한 정치로 은퇴하였다가 인조반정 후 다시 벼슬길에 올랐지만 곧 사직하였다. 효종이 즉위한 후 대사헌을 거쳐 이조판서가 되어 북벌을 계획하기도 하였고 판중추부사의 자리에까지 올랐다. 죽은 후 고종 20년(1883)에 영의정으로 벼슬이 높여졌다. 그는 초야에 묻혀 아버지의 학문을 이어받고자 노력하였으며 이이의 학문을 계승하여 송시열에게 그 학문을 전해주어 기호학파 형성에 크게 공헌하였다. 그의 묘는 충남 논산시 벌곡면의 고…","a":"김집선생묘","c":"문화유산자료","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661364.jpg"},{"q":"鐵製의 칼로 검신[劍身]과 슴베[莖]가 여러 차례의 담금질로 鍛造되었고 칼집[鞘]과 손잡이[把柄]은 오동나무이다. 劍身의 단면은 이등변삼각형으로 한 면은 평면이고 반대쪽 면은 山形이다. 칼날 끝[鋒]에서 손잡이 쪽으로 7.7cm 지점의 山형면에 V자형 갈고리가 부착되었다고 하나 현재 부식과 연마 시 부주의로 멸실되었다. 다만 그 잔흔은 있어 융기된 부분이 남아 있다. 수장자의 전언에 따르면 6.25 한국전쟁 시 땅속에 묻어두어 물에 잠기어 劒身과 슴베에 부식이 있었다는데 대체로 일치된다. 칼의 한 면이 평면이고 그 반대편이 삼각형인 점과 갈고리를 부착된 점 및 칼자루…","a":"합천 마씨종택 철검","c":"문화유산자료","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666412.jpg"},{"q":"2층 규모의 붉은 벽돌 치장쌓기한 건물로, 일제가 1911년 8월 ‘조선교육령’을 발표한 뒤 대전에 처음 생긴 ○○○○이다. 경부선 철도 부설공사로 인해 일본인의 이주가 많아 일본인 아동을 교육하는 소학교의 필요성에 의해 건립되었다. 당시 유리를 많이 사용하던 추세에 맞춰 전·후면을 비롯한 양 측면에 유리창을 많이 넣었고, 현관은 충남도청처럼 귀빈 승용차가 현관 입구에 차를 세울 수 있도록 하였다. 입면에는 원형창을 설치, 내부 채광을 도입함과 동시에 주변의 직사각형 수직창과 대조를 이루게함으로써 미적인 측면을 배려한 것으로 보인다.","a":"삼성초등학교구교사","c":"문화유산자료","r":"대전광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659764.jpg"},{"q":"영사재는 반남박씨 집성촌인 논산시 상월면 대우리에 위치하고 있으며 예빈시 참봉으로 임명되고 후에 호조참판으로 추증된 박동민과 사헌부 집의를 지낸 아들 휘, 손자 박세기를 배향하는 재실로서 신도비, 묘표석, 처인 정경부인 전주이씨의 정려각 등 연계유적이 근처에 소재하고 있다. 인조 10년(1632) 창건된 후, 조선 숙종 20년(1694)과 그 후 몇 차례의 중수를 거치며, 원형을 보존하고 있으며 건물 전면에 영사재의 현판이 있고 내부에 중수기 등이 현액되어 있다. 또한, 목재를 다듬은 수법과 결구 기법이 우수하고 전형적인 재실건축 양식이 잘 나타나며 보존관리 상태가…","a":"논산영사재","c":"문화유산자료","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661560.jpg"},{"q":"충청북도 ○○시 가금면에 있으며 자연 암벽 위에 얕은 선으로 새겨진 마애불로 연꽃무늬가 새겨진 대좌 위에 서 있다. 크고 길게 찢어진 눈꼬리, 큼직한 코와 귀 등에서 근엄한 인상을 풍긴다. 양 어깨에 걸친 옷에는 3가닥의 선으로 새긴 것과 더불어 구불구불한 선으로 새긴 특이한 형태의 옷주름이 표현되어 있다. 토속적인 분위기와 세련되지 못한 세부 표현, 하체 조각이 생략된 기법, 구불구불한 선 모양 등 이 지방에서 많이 보이는 독특한 지방양식을 보여주는 작품이라고 할 수 있다.","a":"충주 창동리 마애여래상","c":"시도유형문화유산","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638503.jpg"},{"q":"현곡 유영선(1893∼1961)의 우국정신과 덕행을 기리고 영정을 모시기 위해 후학들이 세운 사당이다. 앞면 3칸 ·옆면 2칸 규모로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕집이다. 정사 근처에 있는 장서각에 현곡이 저술한 책과 가문에서 보존하고 있는 많은 장서와 유품이 있다.","a":"현곡정사","c":"시도유형문화유산","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639454.jpg"},{"q":"이희맹·김제민·최안·김지수를 비롯하여 김제안·김흔·김섬·김습 등을 기리고 있는 서원이다. 이희맹은 조선 전기 문신이며 김종직의 제자로 성균관 재학시절부터 문장과 인품으로 인정을 받았다. 성종 23년(1492)에 장원 급제하여 등용되었으며 이후 여러 벼슬자리를 거쳤다. 김제민(1527∼1599)은 이항의 제자로 과거에 급제하여 벼슬길에 올랐으며 임진왜란 때에는 의병을 모아 왜군과 싸워 공을 세웠다. 이 서원은 현종 14년(1673)에 이희맹, 김제민과 더불어 조선 중기 의병장 최안과 조선 중기 문신 김지수를 모시기 위해 세웠다. 그 뒤 숙종 23년(1697)에 김제안을…","a":"도계서원","c":"문화유산자료","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661695.jpg"},{"q":"○○○는 백제 성왕 7년(529) 아도화상이 비로암을 지은 것에서 유래하였다는 설과 통일신라 경문왕 1년(861) 도선국사가 세워 ○○○라 이름지었다는 두 가지 설이 있다. 고려 선종 5년(1088)에 의천이 새롭게 고쳐 세웠으나 조선 선조 30년(1597) 정유재란 때 대부분의 건물이 불에 타버렸다. 그 뒤 여러 스님이 건물들을 세우고 고쳐 오늘에 이르고 있다. ○○○○○은 조선 현종 1년(1660)에 경준, 경잠, 문정대사가 처음 지었고, 숙종 24년(1698) 호암대사가 고쳐지었다. 지금 있는 건물은 순조 24년(1824)에 다시 고친 건물이다. 규모는 앞면 3…","a":"선암사원통전","c":"시도유형문화유산","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640101.jpg"},{"q":"○○○은 중종 28년(1533)에 ○○○ 송순(1493∼1582)선생이 관직을 떠나 선비들을 가르치며 여생을 보내던 정자로, 퇴계 이황을 비롯한 유명인사들과 학문에 대해 토론하던 곳이다. 조선 중기 문신인 송순 선생은 과거에 급제한 후 여러 벼슬을 거쳤으며, 말년에는 학문에 전념하면서 많은 책을 저술하였다. 처음 있던 정자는 선조 30년(1597) 임진왜란으로 파괴되어, 효종 5년(1654)에 후손들이 다시 지었다. 정자는 앞면 3칸·옆면 2칸 규모이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. ○○○은 간소한 양식의 건물이기는 하지만, 역사적 가…","a":"면앙정","c":"시도기념물","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653944.jpg"},{"q":"○○○는 신라 문무왕 17년(677)에 의상대사가 지었으며 그 뒤 무학대사가 보수하였다고 전한다. 경내에는 극락전을 비롯하여 같은 건물로 연결된 심검당, 무량수각 등의 건물이 있으며, 극락전 앞에 안양루가 서해를 향하고 있다. 극락전은 앞면 3칸·옆면 3칸의 규모로, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 기둥 위에만 있는 주심포 양식으로 꾸몄다. 고려시대의 건축 양식을 보이고 있는 건축물이다.","a":"부석사","c":"문화유산자료","r":"충청남도","s":"서산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018072515350100.jpg"},{"q":"조선 후기의 실학자이며 과학사상가인 담헌(湛軒) ○○○ 선생의 묘소이다. 청나라에 사신으로 가는 작은 아버지 홍억을 수행하여 여러 학자들과 친교를 맺었으며, 서양 선교사들을 찾아가 서양문물을 보고 접했다. 이덕무·박지원·박제가 등과 어울려 북학파를 형성하였는데, 북학파의 선구자로 특히 천문학에 관심을 기울여 지전설을 주장했으며, 저서로는『담헌서』가 있다. 묘소는 천안시 수신면 장산리에서 속창리로 통하는 도로변에 위치하고 있는데, 묘의 앞에는 상석·망주석·비석이 서 있다. 비석의 앞면에는 ‘담헌홍공대용지묘 숙인한산이씨부좌(湛軒洪公大容之墓 淑人韓山李氏咐左)’라고 적혀 있…","a":"홍대용선생묘","c":"시도기념물","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652860.jpg"},{"q":"이 유적은 임진왜란 때 의병장으로 활약하다가 순국한 송암(松菴) 김면(1541～1593) 장군의 묘소, 신도비(神道碑), 도암사(道巖祠), 도암재(道巖齋), 도암서당(道巖書堂)을 일괄하여 지정한 사적지이다. ○○○○은 조선 선조 25년(1592) 임진왜란이 일어나자 고령, 거창 등지에서 의병을 규합, 수십 여 차례에 걸친 전투에서 승리하면서 의병장으로 추대되었다. 1593년 경상우도병마절도사(慶尙右道兵馬節度使)가 되었으나, 선산대전을 앞두고 충청․전라도 의병과 함께 금산, 개령에 주둔하고 있을 당시에 병을 얻었다. 장군은 ‘오로지 나라만이 있는 줄 알았고, 내 몸이…","a":"김면장군유적","c":"시도기념물","r":"경상북도","s":"고령군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654523.jpg"},{"q":"규장각 대제학을 지낸 민승세가 1820년경 고향으로 돌아와 지은 집이다. 이 가옥은 안채, 사랑채, 행랑채가 ㄱ자 형태로 되어 있다. 안채 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다. 6대째 살아온 이 집 주인인 민익현은 민승세 공의 5대손이다.","a":"민익현가옥","c":"문화유산자료","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661357.jpg"},{"q":"금성면 하신리에 있는 어필각 근처에 세웠던 절이다. 일제시대 때 지금 있는 자리에서 약 100m 떨어진 곳으로 옮겼다가 1982년 다시 지금 있는 자리로 옮겨 지었다고 한다. 앞면 3칸·옆면 2칸 규모이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 기둥 위와 기둥 사이에도 있는 다포 양식으로 꾸몄다. 안쪽은 하나의 칸으로 되어 있으며 바닥에는 우물마루를 깔았고, 뒤쪽 중앙에 불단을 만들고 비로자나불을 모시고 있다. 이 불상은 신음산 국사봉 아래에 있는 신안사에서 옮긴 것이라고 전한다.","a":"금산 대원정사","c":"문화유산자료","r":"충청남도","s":"금산군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661483.jpg"},{"q":"○○○○○는 고려 시대 청자와 백자를 만들던 곳이다. 요지는 안양천 지류인 삼성천 상류에서 무너미고개로 올라가다가 초입 우측 사면에 위치한다. 반경 40~50m 범위에서 음각이나 양각한 백자, 청자, 흑유자기 등이 다양하게 출토되어 고려 시대 관악산 일대 도자기 제작양상을 살펴볼 수 있다. 출토된 청자는 대접, 접시와 같이 일상에서 많이 쓰이는 기종이 많고 각접시, 항아리, 뚜껑 등도 조금씩 보인다. 음각이나 양각 혹은 상감문양을 가진 것도 있다. 백자는 연질(軟質)과 경질(硬質)의 두 종류가 있고, 대접, 접시, 합뚜껑, 호 등의 기종에 드물게는 상감과 음각으로 시…","a":"안양시비산동도요지","c":"시도기념물","r":"경기도","s":"안양시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646593.jpg"},{"q":"고려시대 후기에서부터 조선시대에 사용된 읍성과 ○○○이다. 전형적인 평산성(평지성과 산성의 쌓는 법을 아울러 벌판과 산을 이어 쌓은 성)으로 주변은 수암봉에서 서쪽으로 내려 온 소금절골과 작은골 사이의 능선이 읍성을 감싸며 남쪽에 ○○○가 위치하였다. 안산관아는 처음에 목내동 일대에 있다가 세종 23년(1441)에 수암동으로 옮겨졌고 현종 10년(1669)에 당시 자리에서 동남쪽으로 약 50m 떨어진 현재의 위치로 이전하였다. 당시 해안으로 침입하던 왜구에 대비하기 위해 만들었으며, 평시에는 행정적 기능을 담당하였다. 성의 형태는 모서리가 둥근 장방형을 띤다. 주요…","a":"안산읍성및관아지","c":"시도기념물","r":"경기도","s":"안산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646614.jpg"},{"q":"총 높이 80㎝, 몸체 길이 60㎝, 입 지름 50㎝로, 소형이나 명문이 확실한 조선 후기 범종의 특징이 잘 나타나 있다. 입 주변에는 한개의 덩굴무늬 띠를 둘렀으며, 어깨 부위에는 덩굴무늬 띠와 물결무늬 띠가 잇대어 배열되어 있다. 어깨 아래로는 2줄로 만든 작은 원 안에 범자를 도들새김 하였으며, 24개의 원을 배열하여 문양을 만들었다. 몸체 중앙에는 정사각형의 유곽을 4개 두고 안에는 9개의 유두를 도드라지게 새겼다. 유곽을 만든 띠는 덩굴무늬로 채웠다. 유곽과 유곽 사이에는 보살상을 양각하였다. 몸체의 맨 윗부분에는 꽃을 세워 장식한 듯한 문양이 있다. 이 동…","a":"내장사조선동종","c":"시도유형문화유산","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639439.jpg"},{"q":"이 곳은 임진왜란(壬辰倭亂) 때 금산전투에서 전사한 의병장 고경명(高敬明)의 옛 집터이다. 현재의 가옥은 1917년 고원희의 증조부인 고종석(高琮錫)이 지은 것이다. 지금은 사랑채, 안채, 곳간채, 사당이 남아있는데 예전에는 더 많은 건물들이 있었다고 한다. 사당에는 고경명과 아들 종후(從厚), 인후(因厚)의 위패를 모신 부조묘(不祖廟)가 있다.","a":"고원희가옥","c":"문화유산자료","r":"전남광주통합특별시","s":"남구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659601.jpg"},{"q":"종은 절에서 쓰이는 도구 중 하나로서 시간이나 의례를 알리거나, 복음을 전달하는데 사용한다. ○○○은 내원사 계곡에 있었다고 전하는 89암자 중의 하나로서, 내원사 창건 당시 암자가 폐쇄되었던 것을 조선 인조 24년(1646)에 영훈대사가 중건한 것으로 비교적 잘 보존되어 있다. 이 종은 어깨부분에 ‘범’자를 원안에 새겼으며, 몸통 위쪽 주위에는 돌출된 9개의 유두가 있었으나 2개는 파손되었다.","a":"양산 안적암 동종","c":"문화유산자료","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664241.jpg"},{"q":"강릉 시내에 있던 집을 150년 전에 지금의 위치로 옮겨지은 것으로, 처음 지은 연대는 알지 못한다. 전형적인 ㅁ자형 집이며, 안채를 중심으로 왼쪽에 작은 사랑채·오른쪽에 곳간채·앞쪽에 큰 사랑채로 구성되어 있다. 앞면 5칸·옆면 2칸 규모의 안채는 지붕 옆면이 여덟 팔(八)자 모양인 화려한 팔작지붕집이며, 3개의 방과 마루·부엌이 있다. 원래 안채는 겹집의 형태였지만 지금은 각 방이 길게 연결되어 있으며, 기단을 사랑채보다 높게 하여 채광과 환기에 대한 배려를 하였다. 안채 왼쪽으로는 작은 사랑채가 있고 작은 대문을 사이에 두고 큰 사랑채와 연결되었는데, 사랑채는…","a":"강릉조수환가옥","c":"시도유형문화유산","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638100.jpg"},{"q":"○○○는 선사시대 사람들이 바위나 동굴벽에 기호나 물건, 동물 등의 그림을 새겨놓은 것을 말하는데, 주로 농사의 풍요와 생산을 기원하던 주술행위의 결과물로 보인다. 이 ○○○는 거북이 모양으로 생긴 바위 한 쪽 옆면에 7개의 그림을 새겨 놓았다. 그림을 새긴 면의 넓이는 최대 길이 337㎝, 최대 폭 130㎝이다. 포항 칠전리와 고령 양전동, 영주 가흥리에 있는 ○○○와 비슷한 것으로 보아 같은 문화유형으로 추정되나, 각 그림의 세부형식이 조금씩 달라, 서로 시대가 달랐거나 혹은 지역이 다르기 때문인 것으로 보인다. 연대를 정확하게 규명하기는 어렵지만 청동기 후기나…","a":"영천보성리암각화","c":"시도유형문화유산","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640891.jpg"},{"q":"고려 후기 왜구토벌에 공을 세운 조선 개국공신 필암(筆菴) ○○○의 ○○이다. 고려 공민왕 때 문과에 급제하였으며, 진주수령·상주목사·계림부윤·화령부윤 등을 역임하였다. 우왕 2년(1376) 진주도원수가 되어 왜구를 대파하였으며, 우왕 4년(1378) 경상도원수로서 욕지도에서 왜구를 대파하였다. 고려 우왕 14년(1388) 요동출병 때 이성계 휘하에 참여하여 위화도 회군을 도와주었다. 이후에 여러 관직을 역임하였으며, 정도전·조준 등과 함께 공양왕을 폐하고 이성계를 조선 태조로 즉위시켜서 그 공으로 1등개국공신이 되었고 조선 최초의 영의정이 되었다. 묘의 형태는 직사…","a":"증평 배극렴 묘소","c":"시도기념물","r":"충청북도","s":"증평군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650361.jpg"},{"q":"이 건물은 임진왜란 때 경주지역에서 의병을 일으켜 공을 세운 동호東湖 이방린李芳隣, 1574～1624과 동생 유린有隣, 광린光隣 삼형제를 추모하기 위해 조선 순조純祖 15년1815에 세운 정자이다. 이방린은 임진왜란 때 경주판관慶州判官 박의장朴毅長, 의병장 권응수權應銖등과 함께 영천성永川城전투에 참가하였고, 비격진천뢰飛擊震天雷를 사용해 경주성 회복의 공을 세웠다. 그리고 경주의 계연鷄淵전투에도 공을 세워 안동대도호부판관 겸부사安東大都護府判官 兼 府使를 지냈다. 가운데에 3칸 마루를 깔고 양 옆에 온돌방을 두었으며, 가운데칸 뒤쪽 필경재必敬齋는 이방린을, 왼쪽의 화수당…","a":"삼괴정","c":"시도유형문화유산","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640831.jpg"},{"q":"태조 이성계의 첫째 아들인 진안대군 이방우와 대군의 첫째 아들인 봉령후의 위패를 모신 사당이다. 이방우(？∼1393)는 부친이 혁명의 뜻이 있음을 알고 해주에 은거하다 죽고, 사후에 진안대군에 봉해졌다. 순조 31년(1831)에 세운 이 건물의 ‘청덕(淸德)’이라는 이름은 대군이 청빈하고 덕이 있다고 하여 붙인 것으로 ‘○○○’라고 쓴 현판을 솟을삼문에 걸었다. 솟을삼문 둘레로는 담장을 두르고 외삼문 안에는 연못을 조성하였다. 건물 구조는 앞면 3칸·옆면 1칸 반 규모로, 지붕은 옆면에서 볼 때 사람(人)자 모양인 맞배지붕이다.","a":"괴산 청덕사","c":"문화유산자료","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660727.jpg"},{"q":"독립운동가인 ○○○ 선생의 ○○로, 선생은 충청북도 ○○ 출신이며 호는 보재이다. 선생은 이시영, 이규형 등과 신학문을 공부하였다. 을사보호조약이 체결된 후, 통분을 금치못해 길거리에서 연설한 후 집 밖에 나오지 않았다. 1907년 네덜란드 헤이그에서 열린 만국평화회의에 조선이 독립국임을 주장하는 고종의 밀서를 가지고 갔으나 뜻을 이루지 못했다. 조국의 국권회복을 위하여 노력하다가 1917년 연해주에서 생애를 마쳤다. 가옥은 앞면 3칸·옆면 1칸 규모로 흙벽돌로 쌓고 진흙으로 마감한 초가이다. 40여년 전에 무너졌던 것을 최근에 복원·수리하였다.","a":"진천 이상설 생가","c":"시도기념물","r":"충청북도","s":"진천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650054.jpg"},{"q":"월계 마을 북서쪽에 있는 초포산에서 남쪽으로 흘러내린 산줄기의 해발 20m 내외의 구릉 능선상에 있는 2기의 고분이다. 1호분의 평면은 네모난 모양과 둥근 형태를 모두 가지고 있는 장고분이고 2호분은 평면형태가 둥근 원형이다. 1호분은 북서쪽에서 남동쪽으로 완만하게 내려오는 구릉의 능선상에 있는데 구릉 위쪽에 네모난 부분을 두고 있다. 둥근 부분의 남동쪽은 민묘 등으로 인하여 약간 변형되었고 네모난 부분의 북서쪽은 길이 생기면서 훼손되었다. 2호분은 둥근 형태를 하고 있는 원분으로 1호분의 남동쪽 아래에 자리하고 있다. 1호분은 오랜 세월 동안 그 형태가 다소 변형되…","a":"영광월산리월계고분군","c":"시도기념물","r":"전남광주통합특별시","s":"영광군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654346.jpg"},{"q":"이 불상은 발목 부분이 흙에 묻혀 있어 전체 높이는 정확히 알 수 없으나, 드러난 불신(佛身)의 높이가 1.95m에 이르는 대형 불상이다. 석불은 전체적으로 마모가 심한 상태이지만, 조각선이 깊어 대략적인 형상은 파악할 수 있다. 먼저, 머리에는 크게 표현된 육계(肉髻, 상투 모양의 머리)가 있으며, 얼굴은 전체적으로 풍만한 형태를 띠고 있다. 옷차림은 양 어깨를 덮는 통견(通肩)으로, 가슴 아래로 넓은 U자형의 옷주름이 흘러내리다가 다리 부분에서 두 가닥으로 갈라진다. 수인(手印)은 시무외인(施無畏印, 왼손)과 여원인(與願印, 오른손)을 취했던 것으로 보이나, 팔꿈…","a":"논산덕평리석조여래입상","c":"시도유형문화유산","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639096.jpg"},{"q":"소주 가씨인 가유약·가상·가침 등 삼대를 기리기 위한 사당이다. 가유약은 중국의 이름높은 장군으로, 소주 가씨의 중시조(쇠퇴한 가문을 일으킨 조상)이다. 그는 임진왜란(1592)이 일어나자 이여송과 함께 조선에 와서 왜군을 무찌르는데 큰 공을 세우고 돌아갔다. 얼마 후 선조 30년(1597) 정유재란이 일어나자 아들과 손자인 가상장군, 가침을 데리고 다시 조선에 오게 되었다. 가유약은 가침을 두고 가상과 부산에서 왜군과 싸우다 함께 전사하였다. 가침은 원수를 갚으러 전장으로 가려 했으나 주위의 만류로 시체를 거두어 장사하고 묘를 모셨다. 그 뒤 가침의 아들 4형제가…","a":"숭의사","c":"문화유산자료","r":"충청남도","s":"태안군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661370.jpg"},{"q":"승려 처영에게 하사한 구리로 만든 도장이다. 처영은 조선 선조 25년(1592) 임진왜란이 일어나자 ○○○○의 승병장이 되어 성을 크게 수축하고 전란에 대비하였다. 이에 조정에서 산성별장(山城別將)임을 증명하는 의미로 이 도장을 새겨 하사하였다. 도장은 산성내의 선국사 주지에게 대대로 전해내려 오다, 동학혁명군 김개남이 ○○○○을 본거지로 활동할 때 잃어버렸던 것을 1960년 당시의 주지였던 보월 스님이 발견하여 지금에 이르고 있다. 가로 6.3㎝, 세로 7.8㎝, 두께 1.5㎝의 크기로, ‘○○○○○인(蛟龍山城僧將印)’이라는 7글자를 세로로 2줄 새겨 놓았다. 직사…","a":"교룡산성승장동인","c":"시도민속문화유산","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658318.jpg"},{"q":"원래 경상북도 봉화군 성화곡 절터에서 발견된 것을 ○○○로 옮겨서 보관하고 있으며, 두 손을 새로 만든 것 이외에는 거의 완전한 형태이다. 민머리 위에 있는 상투 모양의 둥글고 큼직한 머리묶음, 토실토실한 얼굴에 아담한 이목구비 등은 통일신라 후기의 불상양식을 잘 반영하고 있다. 둥근 어깨, 잘록한 허리, 통통한 다리 등에서 부드러움과 균형잡힌 부피감을 엿볼 수 있다. 이러한 신라적인 특징은 옷입는 법에서도 나타나는데, 양 어깨를 감싸고 입은 옷은 간결한 몇 가닥의 계단식 주름으로 처리하고 있다. 옷깃은 목둘레를 따라 3줄의 선으로 한번 뒤집은 것이지만 양 어깨를 완…","a":"천성사석조여래입상","c":"시도유형문화유산","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640521.jpg"},{"q":"○○○ 내의 원각국사비(보물 제534호) 뒤쪽에 자리하고 있는 사리탑으로, 사리의 주인공이 누구인지는 알수가 없다. 탑의 기단부(基壇部)는 네모난 바닥돌 위로 8각의 아래받침돌을 세우고, 역시 8각의 윗받침돌을 올려놓은 구조이다. 아래받침돌은 각 면마다 안상(眼象)을 얕게 새겼고, 위가 반듯한 윗받침돌은 밑으로 한겹씩의 연꽃무늬를 둘렀다. 탑신(塔身)의 몸돌은 둥근 공모양이며, 지붕돌은 8각으로 여러 조각들이 생략되어 밋밋하고 투박하다. 지붕돌 위로는 꽃봉오리모양을 한 머리장식을 올려 놓았다. 각 부분의 조각들이 생략되거나 간략화되고, 연꽃잎이 한겹으로 되어 있어 고…","a":"영동 영국사 구형승탑","c":"시도유형문화유산","r":"충청북도","s":"영동군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638684.jpg"},{"q":"○○○에 있는 산성으로, 능선의 병풍처럼 생긴 자연 암반을 북벽으로 하고, 서남쪽의 계곡을 성안에 품어 산꼭대기를 둘러쌓았다. 성의 둘레는 1,500m이고, 높이는 3m, 폭은 4.5m 정도이다. 남쪽의 좁은 계곡을 성문으로 삼고, 좌우의 낮은 지역에는 자연석으로 성벽을 쌓았으며, 높은 암벽을 최대한 활용하면서 능선을 따라 쌓아서 정면에서 보면 마치 이등변삼각형처럼 보인다. 북쪽과 동쪽은 비교적 완전한 편이나, 서쪽은 자연적인 풍화로 붕괴되어 있다. 이 지역은 옛 신라와 가야의 국경지역으로, 전쟁이 자주 일어나자 신라의 침입을 막으려고 가야에서 성을 쌓았던 것으로 추…","a":"창녕 영축산성","c":"문화유산자료","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664015.jpg"},{"q":"○○○○○ 종 목: 경기도 유형문화유산 시 대 : 1500년(조선 연산군 5년) ○○○○○는 불경에 나오는 숫자가 들어 있는 용어를 가려 뽑아서 숫자의 차례대로 배열하여 쉽게 찾아볼 숭 있도록 엮어놓은 일종의 불교용어사전이다. 본래 이 책은 당나라 승려 현수(賢首)가 부조의 설법을 숫자로서 표시하여 일목요연하게 이해할 수 있도록 편찬했는데, 후대 오면서 점차 희귀해지자 명나라 행심(行深)이 불교입문의 지침이 될 만한 체재로 재편하였다. 이 목판본은 합천 봉서사(鳳栖寺)에서 간행한 것으로 11권 1책이며, 서문과 발문에서 편찬 취지와 간행 동기를 명확하게 밝히고 있어…","a":"현수제승법수","c":"시도유형문화유산","r":"경기도","s":"남양주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2019052009570400.jpg"},{"q":"○○○는 석가모니의 제자들인 십육나한 중 첫 번째 존자인 독성존자(獨聖尊者)를 단독으로 그린 그림이다. 독성존자는 세속인들에게 신통력을 드러냈다가 부처의 꾸중을 듣고, 열반에 드는 것이 허락되지 않아 부처가 열반한 후 모든 중생들을 제도하고자 하는 존재가 되었다. 사찰의 독성각(獨聖閣)에 단독으로 모셔지거나, 삼성각(三聖閣) 내에 산신도(山神圖), 칠성도(七星圖)와 함께 봉안된다. ○○○○○는 19세기 후반의 작품으로 독성각에 단독으로 모셔져 있다.","a":"수원 청련암 독성도","c":"문화유산자료","r":"경기도","s":"수원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660286.jpg"},{"q":"○○○○○은 조선 광해군 5년(1613)에 세워진 건물로 조선시대 말기인 헌종 8년(1842)에 고쳤다. ○○○은 대적광전이라고도 하며 원래는 비로자나불을 모시는 법당이지만 이곳에서는 최근에 나한을 모시고 있다 해서 영산전이라 부르고 있다. 앞면 3칸·옆면 2칸으로 옆면이 사람 인(人)자 모양인 맞배집이다. 기둥 위에서 지붕 처마를 받치는 공포가 기둥 위와 기둥 사이에도 있는 다포계 양식이다. 가운데 칸은 공포를 2개씩, 양쪽 칸은 1개의 공포를 배치하였다. ○○○○○은 전체적으로 조선 후기 건축양식의 특징을 갖추고 있어 경내의 조선 중기 건축인 대웅전과 좋은 대비를…","a":"청주 안심사 비로전","c":"시도유형문화유산","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638571.jpg"},{"q":"조선 전기 학자 고은 이지활(1434∼?)을 기리기 위해 경상도 유림에서 세운 서원이다. 이지활은 단종이 수양대군에게 왕위를 빼앗기고 영월로 유배당하자 벼슬을 버리고 남은 여생을 산속에서 은거하다 세상을 떠난 분이다. 죽은 뒤인 고종 28년(1891) 나라에서 이조판서의 벼슬을 내렸다. 순조 30년(1830)에 세운 이 서원은 흥선대원군의 서원철폐령으로 고종 6년(1869)에 해체되었으나 1947년 다시 복원하였다. 후일 세종대왕의 아들로 이곳 ○○에서 돌아가신 이어(李瘀)와 이지활의 손자인 송계 이지번을 추가로 모셔 현재 이곳에는 3분의 위패를 모시고 있다. 경내에…","a":"함양 송호서원","c":"문화유산자료","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664342.jpg"},{"q":"율곡 이이가 쓰던 벼루와 토지 양여서이다. 벼루는 가운데가 타원형으로 오목하게 패여 있고, 위쪽과 아래쪽에 나뭇가지와 잎사귀를 양각하였다. 벼루의 뒷면에는 글씨가 새겨 있는데, 정조 12년(1788)에 정조가 율곡 이이의 유품이 강릉에 있다는 말을 듣고 직접 보시고, 쓰신 것을 그대로 새긴 것이다. 보신 후 율곡의 유품을 소중히 보존하기 위해 어제각이라는 건물을 지어 보관하도록 하였다. 토지 양여서는 율곡이 그의 소유의 토지를 이종 권처균(權處均)에게 양여 한다는 증서로, 계약서나 각서와 같은 성질의 문서이다. 이 문서는 선조 12년(1579)에 율곡이 친필로 작성한…","a":"율곡유품(벼루,토지양여서)","c":"시도유형문화유산","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637865.jpg"},{"q":"이 책은 조선 후기 ○○○ 적멸보궁의 중창사실과 이를 재정적으로 후원한 일반 시주자 및 인근 사찰의 시주스님을 기록한 책으로, ○○○ 적멸보궁(중대)에서 보관용으로 기록한 것이다. 각 장 8행(行)에 글자 수는 16∼25자로 불규칙하며, 모두 20장으로 이루어져 있다. 책에는 재물을 출연하여 시주하는 공덕을 찬양하는 내용의 발문, 일반 대시주자의 이름과 소원문이 보이며, 이어서 본사 비구를 비롯하여 인근의 사찰 및 경상도 은해사 스님들의 시주명이 차례로 기재되어 있으며, 권말에는 이를 증명하는 각 사찰명이 지역별로 기재되어 있다. 이 책이 만들어진 시기는 책 끝부분에…","a":"오대산중대불량문","c":"문화유산자료","r":"강원특별자치도","s":"평창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660630.jpg"},{"q":"충청북도 ○○시 상당구 ○○○에 있는 바위면에 새긴 마애불이다. 머리에는 마치 모자를 쓴 듯하며, 머리 뒤에는 동그란 머리광배가 표현되어 있다. 신체는 균형이 잘 잡혀 있으며, 자연스럽게 흐르는 얇은 선의 옷주름 표현이 돋보인다. 왼손 검지 손가락을 오른손으로 잡을 듯한 모습을 하고 있다. 이런 특징적인 손모양은 동화사 비로암석조비로자나불좌상(보물)이나 도피안사 철조비로자나불좌상(국보)과 비교된다. 불신의 각 부분을 정교하지 않고 간략하게 처리하고 있는 조형감이나 정제되지 않고 거친 조각수법을 고려할 때, ○○○○○은 고려시대에 제작되었을 것으로 여겨진다.","a":"청주 정하동 마애비로자나불좌상","c":"시도유형문화유산","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638572.jpg"},{"q":"탑동 마을 어귀에 있는 밭 가운데에 자리하고 있는 탑으로, 뒤로는 종산(鍾山)이 펼쳐져 배경을 이룬다. 원래 이곳은 옛 부터 ○○○라는 절이 있었다 하나, 지금은 없어지고 이 탑만 남아있다. 탑은 전체의 무게를 지탱하는 기단(基壇)을 2층으로 두고, 3층의 탑신(塔身)을 올려놓은 모습인데, 일부가 떨어져 나가 시멘트로 발라놓는 등 보존상태가 좋지 않다. 기단은 네 모서리마다 별도의 돌을 다듬어 기둥처럼 세워 이 탑의 가장 큰 특징이 되고 있다. 탑신부는 2매의 돌로 이루어진 1층 몸돌을 제외하고는 각 층의 몸돌과 지붕돌이 각각 하나의 돌로 되어 있다. 각 몸돌은 모서…","a":"한산사지삼층석탑","c":"문화유산자료","r":"전남광주통합특별시","s":"화순군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661997.jpg"},{"q":"고려 말 조선 초의 문신인 ○○○의 영정(影幀)이다. ○○○은 본관이 청주이고, 호는 신재(信齋)이다. 1392년(공양왕 4)에 이성계(李成桂)를 추대하는 모의에 참여한 공으로 익대개국공신(翊戴開國功臣) 3등에 책록되었다. ‘○○○ 영정’에는 조선 초기의 초상화 양식을 잘 반영되어 있다. 관모의 양각이 아래로 내려온 모양, 흉배가 없는 담홍색 단령, 등받이가 없는 접이식 의자인 승상(繩牀) 등이 그러한 단서이다. 이 초상은 여러 가지 단서로 볼 때 17세기 베껴 그린 이모본(移模本)이지만, 표현상의 요소는 15세기를 대표할 단서를 갖고 있다. 화폭의 왼편 상단에는 표…","a":"신재한상경영정","c":"시도유형문화유산","r":"경기도","s":"남양주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637698.jpg"},{"q":"무등산 서쪽 기슭에 있는 ○○○는 9세기 중엽에 철감선사가 지었다. 고려 선종 10년(1094)에 혜조국사가 수리하였으며, 조선 세종 25년(1443)에 김방이 다시 지었다. 그 뒤 임진왜란(1592) 때 불타 없어진 것을 광해군 1년(1609)에 짓고, 여러 차례의 수리를 거쳐 오늘에 이르고 있다. ○○○은 대웅전의 뒤편에 세워진 법당으로, 현재 무등산에 남아 있는 절 건물 중 가장 오래된 것이다. 오백나한과 10대 제자상을 모시고 있으며 이 고장 사람들의 평안을 기원하기 위해 지은 것이다. 앞면 3칸·옆면 3칸 규모이며, 지붕 옆면이 사람 인(人)자 모양인 맞배지…","a":"증심사오백전","c":"시도유형문화유산","r":"전남광주통합특별시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637149.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다. ○○○○는 세종 9년(1427)에 동문 밖에 세웠으며, 중종 29년(1534)에 남일리 자고개로 옮겨 인종 1년(1545)에 수리하였다. 정유재란 때 불타 없어진 것을 선조 33년(1600)에 성균관과 남평 현민들이 협조하여 지금의 위치에 다시 지었다. 그 뒤 여러 차례의 수리를 거쳐 오늘에 이르고 있다. 현재 남아있는 건물은 대성전·명륜당·외삼문·내삼문 등이 있다. 경사지에 위치한 ○○○○의 외삼문을 들어서면 배움의 공간인 명륜당과 동재·서재가 있고, 뒤쪽의 내삼문을 들어…","a":"남평향교","c":"시도유형문화유산","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639991.jpg"},{"q":"○○○는 통일신라 진성여왕 6년(892)에 범일조사가 처음 지은 절로, 이때에는 운망사라 하였다. 조선 선조 18년(1585)에 사명대사가 지금의 자리로 다시 옮겨지으면서 ○○○라고 이름을 바꾸었다. 그 뒤 산불로 절이 모두 불탄 것을 순조 5년(1805)에 다시 지었다고 전한다. ○○○ 대웅전은 앞면 3칸·옆면 3칸의 규모이며, 옆에서 보았을 때 지붕선이 사람 인(人)자 모양인 단순한 맞배지붕집이다. 지붕을 받치면서 장식을 겸하는 공포는 기둥 위와 기둥 사이에도 있는 다포양식이다. 다포식 건물은 보통 팔작지붕이나 우진각지붕집인데 비해, 이 건물은 맞배지붕으로 특이하…","a":"삼척영은사대웅보전","c":"시도유형문화유산","r":"강원특별자치도","s":"삼척시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638047.jpg"},{"q":"○○○○○는 1868년 지장시왕도, 칠성도와 함께 조성, 극락전에 봉안되었던 불화로서 현재는 ○○○ 대웅전 향좌측 측벽에 봉안되어 있다. 칠성도를 그린 응륜(應崙)과 승의(勝宜)및 가사탱(袈裟幀)을 그린 명응윤감(明應允鑑)이 함께 조성하였는데, 현왕(現王)과 권속들이 망자를 심판하는 광경을 간단하게 묘사하였다. 이 작품은 비교적 작은 화면에 인물들을 크게 표현하여 화면이 꽉 찬 느낌을 준다. 채색은 녹색과 적색이 주조를 이루고 있으나 그중에서도 적색을 위주로 사용하는 등 19세기 후반 불화의 채색을 잘 따르고 있으며, 책상의 윗면을 목리문(木理文)으로 처리한 기법이라…","a":"청룡사 현왕도","c":"시도유형문화유산","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018110815553800.JPG"},{"q":"용문서원의 자리에 남아 있는 일두 ○○○의 ○○○이다. ○○○은 일찍이 아버지를 여의고 혼자서 공부하다가 김종직의 문하로 들어갔다. 성조 11년(1480)에 성조가 경학에 밝은 사람을 구하자 성균관에서 그를 천거하였다. 연산군 1년(1495)에는 안음현감이 되어 백성을 어질게 다스렸으며, 「편의수십조」라는 법을 지어 시행하자 정치가 맑아져, 백성들로부터 칭송을 들었다. 무오사화(1498)로 경성으로 유배되었고, 갑자사화(1504) 때 죽음을 당했다. 비는 거북받침돌 위에 비몸을 세우고 용을 조각한 머릿돌을 얹은 모습으로, 조각이 매우 정교하고 뚜렷하다. 비문은 갈천…","a":"함양 정여창 사당비","c":"문화유산자료","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664445.jpg"},{"q":"○○○○은 1897년 순교자 신석복 마르코(1828~1866년)의 출생지 바로 옆에 서 있는 성당으로 경남지역에서 가장 일찍 설립된 천주교회 본당이다. 신석복은 1828년에 명례리 1209년에 출생한 소금장수였는데 1866년 병인박해 때 김해 가산에서 붙잡혀 대구감영에서 순교했다. 순교할 때 “나를 놓아준다 해도 다시 천주교를 봉행할 것이다.”라는 말을 남겼다. 그의 유해는 지금 강 건너 진영 천주교 묘지에 봉안되어 있다. 명례 본당의 초대 주임이었던 강성삼 신부(1866~1903년)는 김대건 신부와 최양업 신부에 이어 한국의 세 번째 신부이다. 1926년에 명례에…","a":"밀양 명례성당","c":"문화유산자료","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2015120819191600.JPG"},{"q":"○○○○은 삼족당 김대유와 소요당 박하담을 모신 서원으로 선조 원년(1567)에 매전면 동산동 운수정에 두분의 위패를 모시고 향현사라 하다가, 선조 10년(1577)에 지금의 위치로 옮기고 ○○○○이라 하였다. 숙종 2년(1676)에 다시 지었으나, 고종 5년(1868) 흥선대원군의 서원철폐령으로 훼철되었다. 지금의 건물들은 고종 15년(1878)에 박하담의 후손들이 다시 지은 것이다. 대문을 들어서면, 안채와 득월정·행랑채가 ㄷ자 형을 이루고 그 뒤쪽으로는 선암서당이 있다. 선암서당은 앞면 5칸·옆면 2칸의 규모이며, 가운데 3칸은 대청마루이고 그 양쪽으로는 방을…","a":"선암서원","c":"시도유형문화유산","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640377.jpg"},{"q":"○○○○○는 1902년에 조성된 가사탱(袈裟幀)으로 수가사(繡袈裟) 형태를 그림으로 그린 것이다. 화면은 붉은 바탕 위에 세로로 27칸의 복전문(福田文)을 그리고, 좌우 2칸을 제외한 25칸에는 각 칸마다 위부터 4줄까지는 불(佛), 보살상, 그 다음 2줄은 호화로운 책갑(冊匣)에 들어있는 각종 불경, 맨 아랫줄에는 비구상(比丘像)을 그려 넣어 불상 50구, 보살 50구, 비구상 25구 등 총 125구에 달하는 많은 존상을 묘사하였다. 이러한 가사탱은 조선 말기 왕실에서 유행하던 장식화인 책거리병풍 형식을 따른 것으로 현재 유례가 매우 드믄데, 붉은 가사의 각 조선(…","a":"청룡사 가사도","c":"시도유형문화유산","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018110815563900.JPG"},{"q":"중생을 모든 병의 고통에서 구하고 치유하여 깨달음으로 인도한다는 약사부처를 그림으로 그린 불회도이다. 왼손에 약그릇을 들고 있는 약사부처를 가운데에 크게 배치하고, 약사부처 주위로는 맨 윗부분에 팔부신중을, 그 아래로는 머리에 화려한 보관을 쓴 보살들을 그렸다. 그리고 화면의 맨 아래 부분에는 좌우로 각각 2분씩 불법을 지키는 사천왕상이 배치되어 있다. 연꽃대좌에 앉아 있는 약사부처는 양 어깨를 모두 감싼 옷을 입고 오른 발을 왼무릎에 올려 놓은 길상좌(吉祥坐)의 자세로 큼직한 키모양 광배를 갖추고 있다.","a":"고성 운흥사 약사불회도","c":"시도유형문화유산","r":"경상남도","s":"하동군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642321.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다. 조선 정종 1년(1399)에 세워진 ○○○○는 임진왜란(1592) 때 불에 타 없어졌다. 광해군 6년(1614)에 남천리로 옮겨 지었으나 불이나서 정조 15년(1791)에 현재의 자리로 옮겼다. 그 뒤 여러 차례의 수리를 거쳐서 오늘에 이르고 있다. 현재 남아있는 건물은 대성전·명륜당·동재·서재·교직사 등이 있다. 대성전은 공자를 비롯하여 여러 성현들의 위패를 모시고 제사지내는 곳이고, 명륜당은 학생들이 공부하던 강당이다. 이곳의 건물 배치는 명륜당과 대성전이 위·아래로 배…","a":"단양 영춘향교","c":"시도유형문화유산","r":"충청북도","s":"단양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638553.jpg"},{"q":"감실은 정면 4칸, 측면 1칸으로 일반 가옥의 구조를 하고 있으며 앞면 4칸은 각 실의 구분 없이 각각 43cm으로서 주칸과 협칸의 구분 없이 동일한 척도로 계획되었다. 각 칸의 앞면으로는 둘레 10.5-11cm의 둥근 목재 기둥을 한칸 앞으로 내어 총 다섯 개의 기둥을 세웠으며, 안쪽 기둥 앞쪽으로 21cm 앞에는 난간을 설치하여 마감하였다. 전면 4칸에는 모두 이분합 격자교살문(格子交箭門)이 설치되어 있다. 측면의 경우 중앙의 2.8cm 두께의 기둥을 사이에 두고 전면 협칸은 19cm이고, 후면의 어칸 40cm이며, 벽면 위쪽은 삼각형과 벽체는 모두 판자로 막았다…","a":"온양민속박물관 소장 사당형감실","c":"시도민속문화유산","r":"충청남도","s":"아산시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/2019052217295500.jpg"},{"q":"지은 시기를 정확하게 알 수 없으나 신라 때부터 법통을 이어온 것으로 추정한다. 조선 인조 6년(1628)에 큰 화재로 대부분의 건물이 소실되었고 그 뒤 여러 차례 복원하면서 절 이름도 ‘○○○’로 바뀌었다. 경내에는 절의 중심 건물인 보광전을 비롯하여 명부전, 용화전 등의 법당이 있고 스님들이 생활하는 요사채와 해월루라는 누각이 있다.","a":"통영 용화사","c":"문화유산자료","r":"경상남도","s":"통영시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663799.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워서 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려 놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 뚜껑돌을 덮고 그 위에 거대한 덮개돌을 올린 바둑판식으로 구분된다. 영암군 서호면 ○○○에 모두 18기의 바둑판식 고인돌이 2줄로 넓게 분포되어 있다. 1984년 목포대학박물관에서 일부를 발굴 조사함으로써 고인돌의 구조와 성격이 밝혀지게 되었다. 고인돌 내부와 주변에서 민무늬토기·…","a":"영암엄길리지석묘군","c":"시도기념물","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654217.jpg"},{"q":"논산 ○○○○○은 자연적인 거대한 암반에 불신을 선각하고 불두는 따로 조각하여 붙이는 형식으로 이루어져 있다. 불두는 소발의 육계가 높고, 눈을 감고 있으며 입이 좁고 얼굴은 길고 갸름한 편이다. 목에는 삼도가 표현되어 있고, 몸체는 법의를 양 어깨에 걸쳐 길게 드리운 통견의로 선각하였다. 이 ○○○은 수려한 조각수법과 온후한 상호가 인상적이며, 간결하면서도 사실적인 조각기법 등 불상의 양식으로 볼 때 전형적인 고려시대의 ○○○이다. 논산 ○○○○○은 자연암반에 불신을 새기고 불두는 따로 만들어 올리는 전형적인 고려시대 ○○○의 형식을 갖추고 있는 6m에 이르는 대형…","a":"논산상도리마애불","c":"시도유형문화유산","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639298.jpg"},{"q":"개천면 ○○○○○은 죽포공 박영회(1827-1886)의 효행을 기리기 위하여 세운 것으로 각 내부에 붉은 색을 칠한 나무 기둥을 세워 먼 곳에서도 눈에 잘 띄고, 전면의 단청문양이 선명한 색채를 나타내고 있다 또한 경상남도 문화유산자료로 지정된 ○○○ 박진사고가(개천면 ○○○ 292-3)와 가까운 거리외 위치하고 있어 주위 주민들 뿐만 아니라 후세에 효에 대한 의식을 높이는데 도움이 됨","a":"고성 청광리 창효각","c":"문화유산자료","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666750.jpg"},{"q":"귀정사는 백제 무녕왕 15년(515)에 현오국사가 지은 사찰로 원래 만행사라 불렀던 것을 후에 귀정사라 고쳐 불렀다고 한다. 사찰이름을 바꾼 유래에 대하여는 백제의 왕이 3일간 승려의 설법을 들으며 귀정사에서 국정을 살폈기 때문이라고 전한다. 고려 목종 5년(1002)과 세조 14년(1468) 두 차례에 걸쳐 크게 고쳐지었는데, 이때가 귀정사의 전성시대였다. 그후 임진왜란과 정유재란으로 파손된 것을 현종 5년(1664) 설제대사가 비교적 옛모습대로 고쳐 짓고, 순조 4년(1804) 현일대사가 다시 보수하였으나, 한국전쟁 이후 공비토벌 작전상의 이유로 유엔군이 모두 불…","a":"귀정사지","c":"시도기념물","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653581.jpg"},{"q":"이 유적은 문경공(文敬公) 장암(丈巖) ○○의 ○○이다. ○○는 조선중기의 문신, 학자로 자는 중순(仲淳), 호는 장암(丈巖), 본관은 연일(延日), 좌의정 정철(鄭澈)의 후손이다. 송시열(宋時烈)의 문인으로 숙종 8년(1682) 생원이 되고 1684년 정시문과(庭試文科)에 급제하여 검열(檢閱)·정언(正言)을 지냈으나, 1689년 기사환국으로 인현왕후(仁顯王后)가 폐출되고 송시열이 사사(賜死)당하자, 그는 파직되고 문외출송(門外黜送)당했다가 경성에 유배되었다.[출처: 한국민족문화대백과사전(○○)] 이후 숙종 20년(1694) 갑술옥사(甲戌獄事)로 서인이 기용될 때 재…","a":"괴산 정호 묘소","c":"시도기념물","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1651469.jpg"},{"q":"이곳은 당초에는 서림사가 있었으나 가락국 수로왕때 장유화상이 중건하고 ○○○라 하였다고 전하며, 임진왜란때 절 건물 전부가 불에 타 소실되어 그후에 재건하였다 한다. 구전에는 지금부터 약 380년전에 세웠다고 하지만 확실치 않으며 조선시대 후기 건물이다. 이 불전은 다포계 양식의 맞배집으로 공사는 내외삼출목으로 되어있는데 외부쇠서의 윗몸에는 연꽃을 조각하였고 내외살미 위로는 용두와 봉두를 새겨놓아 화려하게 장식하였다. 내부는 불상위에 구개(보함)를 설치하고 중앙에만 우물천장을 가설하였으며 단청과 벽화가잘 남아있다. 현재의 건물은 이들 조각과 구조수법으로 보아 조선조…","a":"김해은하사대웅전","c":"시도유형문화유산","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642018.jpg"},{"q":"○○○○○ 석탑은 삼릉계(三陵溪) 정상에서 서북쪽으로 약 1.3km를 이어져 내려와 ○○○ 본류와 합쳐지는 한 지류인 계곡 안에 절터가 있고 그 남쪽에 위치한다. 《東京雜記》에 “바둑바위는 금오산에 있다. 바둑판 모양으로 깎은 돌이다. 이곳은 옛날 신라 때 신선들이 모여서 바둑을 두면서 놀던 곳이다.”라는 기술이 있다. 이 골짜기 아래 마을 사람들은 이곳을 ‘장구터’라고 하였으나, 일제강점기 때 일본인들에 의하여 ‘○○○’이라 불리면서 지금까지 그렇게 불린다. 이 석탑은 원래 도괴되어 있던 것을 2003년 말부터 2004년 초반에 이르는 사이에 原材를 최대한 활용하고…","a":"경주남산 포석계 기암곡 제2사지 동삼층석탑","c":"문화유산자료","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663753.jpg"},{"q":"절 이름이나 유래가 전해지지 않고 있으나 백제 절터로 추정된다. 남쪽으로 약간 경사진 곳에 절터를 배치했으며 주변에 금당터와 목탑터가 확인되었다. 많은 양의 백제 연꽃무늬 와당이 흩어져 있고, 장대석, 백제 기와와 토기 조각들이 출토되었다. 백제의 연꽃무늬 와당들로 보아 6세기 이전에 절이 지어진 듯 하며 가람배치는 1탑식으로 추정한다.","a":"용정리사지","c":"시도기념물","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652759.jpg"},{"q":"○○○○은 대전광역시 동구 신하동 해발 340m의 백골산 정상의 험준한 산세를 이용하여 쌓은 산성으로 둘레는 400m이다. 이 산성은 산의 정상부를 둘러쌓고 있는데, 이러한 형태를 테뫼식 산성이라 한다. 성벽은 가파른 지형에 쌓여진 까닭에 완전히 무너져 내린 부분이 많아 원래의 모습을 찾아보기 어렵다. ○○○○의 서쪽으로는 백제의 전략 거점인 계족산성이 있고, 동쪽으로는 신라의 유명한 관산성을 끼고 있어 백제가 신라로 들어오는 유일한 길목을 지키는 초소 역할을 하였음을 알 수 있다. 지금은 인공호수인 대청호가 버젓하게 자리를 잡고 있지만, 성이 축조될 당시만 해도 신…","a":"백골산성","c":"시도기념물","r":"대전광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645805.jpg"},{"q":"임진왜란과 병자호란 때 용감히 싸운 김유부(1549∼1621)의 충효와, 병자호란 때 전사한 김기남, 김란생 그리고 부군을 따라 순절한 최씨와 송씨의 절개를 기리기 위해 세운 사당이다. 어려서부터 무예에 뛰어났던 김유부는 임진왜란이 일어나자 전쟁터에 나가 싸울 것을 결심했다. 그러나 늙은 노모를 두고 갈 수 없어 등에 업고 나가 의병과 함께 용감히 싸웠다. 그의 아들 김기남과 김란생도 병자호란 때 적들과 싸우다 전사하였으며 이 소식을 들은 두 부인은 전쟁터에서 시신을 수습한 뒤 스스로 목숨을 끊었다. 이들은 나라에 충성하고 부모와 남편 섬기기를 몸소 실천하였으므로 충…","a":"밀양 탁삼재","c":"문화유산자료","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664510.jpg"},{"q":"○○○이 위치한 자리는 태조 이성계가 백일기도를 한 후 조선을 건국하고 왕위에 올랐다는 명당지로서 신라시대에는 왕용암, 고려시대에는 수심대, 조선시대에는 ○○○으로 불리웠다 한다. 1889년 평양에서 출생한 정원강은 수도생활을 위해 21세 때인 1910년에 ○○○을 찾았으며, 백옥성 도장에 머물면서 백옥성의 딸과 혼인을 하고, 천단, 정심원·태상전, 산신각, 칠성각, 용궁 등을 연차적으로 건립하여 ○○○ 지역을 재정비하였다. 서울의 삼각산에 기도하러 다니면서 독립운동가들과 인연을 맺고 독립운동을 하면서 조국 독립을 위한 기도와 독립운동가의 은신처로 사용하였고, 정원강…","a":"계룡산삼신당","c":"시도민속문화유산","r":"충청남도","s":"계룡시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658273.jpg"},{"q":"사도세자를 호위하던 무관 이석문이 살던 곳으로, 이석문은 사도세자가 죽은 뒤 세자를 그리워하여 조선 영조 50년(1774)에 북쪽으로 사립문을 내고 평생을 이곳에서 은거하며 살았다. 순조 21년(1821)에 손자 이규진이 안채와 사랑채를 새로 지었으며, 사랑채는 고종 3년(1866)에 다시 지어 오늘에 이르고 있다. 원래는 안채와 사랑채를 비롯하여 장판각, 안대문채, 마굿간, 아래채 등이 있었으나, 지금은 없어져 전해지지 않는다. 사랑채와 안채가 ㅁ자형을 보이고 있으며, 솟을대문이 남아 있어 당시 고관가옥의 특색을 보여주고 있다. 이 집은 비교적 연대를 믿을 수 있는…","a":"성주 응와종택","c":"시도민속문화유산","r":"경상북도","s":"성주군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658619.jpg"},{"q":"○○○○○은 금왕읍 무극리 탑골사지라는 옛 절터에 세워진 ○○○에 봉안되어 있는 불상으로, 금왕읍 오선리 오선초등학교 교정에서 출토되어 1970년경에 이곳으로 옮겨놓았다. ○○○○○은 1매의 화강석을 주형거신광 형태로 다듬어좌불상과 광배를 정교하게 조각하였으며, 불상의 현존 상태는 오른쪽 무릎 부분이 일부 파손이 되었지만 대체로 양호한 편이다. 불상의 조성시기는 대략 고려중기에서 조선 초기로 추정하고 있다. 불상의 머리에는 육계의 형태가 낮게 남아 있고 보발은 양옆으로 땋아 귀 뒤로 돌려졌으며 오른쪽은 귀밑까지 내려 어깨에 닿았다. 얼굴은 원만상이며 이마에는 백호공이…","a":"음성 보현암 석조아미타여래좌상","c":"시도유형문화유산","r":"충청북도","s":"음성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638919.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려 놓은 탁자식과, 땅속에 돌방을 만들고 작은 받침을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 전라남도 지방은 전국에서 고인돌이 가장 많이 분포하는 지역으로 지금까지 발견된 것만 해도 약 2만여 기가 넘는다. 순천에 있는 이 고인돌군은 1986∼1987년 ○○○ 수몰지구에서 발굴조사된 것 가운데 상태가 양호한 고인돌을 송광 고인돌 공…","a":"주암댐지석묘군","c":"문화유산자료","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662124.jpg"},{"q":"○○○란 임금이나 고관 등의 평생업적을 기록하여 그의 묘 남동쪽에 세워두는 비로, 이 비는 통일신라말의 학자인 ○○○ 선생을 기리고 있다. ○○○은 통일신라말에 새로 성장하는 6두품 출신의 지식인 가운데 가장 대표적인 인물로, 문장가로도 잘 알려져 있다. 12세의 어린나이로 당나라에 유학가서 7년만인 18세에 과거에 급제하였고, 그후 2년동안 중국의 낙양지역에 머물면서 시를 짓는데 몰두하기도 하였다. 그가 문장가로서의 이름을 높이게 된 계기는 879년 황소의 난이 일어났을 때로, 고변이 그를 치러갈 때 그의 종사관으로 따라가 「토황소격문」이라는 격문을 써서 황소의 마…","a":"함양 최치원 신도비","c":"문화유산자료","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663980.jpg"},{"q":"조선 광해군 때의 문신으로, 임진왜란이 일어나자 합천에서 의병을 모아 왜군을 물리쳤으며, 인조반정 때 집권 서인들에게 억울하게 죽임을 당하였던 내암 정인홍(1536∼1623) 선생의 손자인 정능(1590∼1619)에게 광해군 5년(1613)에서 광해군 11년(1619) 사이에 조정에서 내린 ○○○○○류 총 22점이다.","a":"정릉 교첩 및 교지","c":"시도유형문화유산","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642267.jpg"},{"q":"○○○○○은 ○○○○의 경내에 있다. ○○○의 창건 연대를 살펴보면 “○○○은 高·梁·夫 三姓이 처음 일어났을 때 비로소 세워졌다”고 충암 김 정은 ○○○중수기(--夫尊者之爲庵 肇造於三姓初起之時 而久傳於三邑鼎峙之後--)에서 밝히고 있다. ○○○○○에 관한 자료는 1650년(효종2년)에 안핵어사로 왔던 李慶億의 詩에 “ 千年孤塔在 천년을 지나온 탑 외로이 서 있는데”라고 ○○○을 敬畏하였다. 이 ○○○○○은 제주현무암으로 만들어졌다. 먼저 지대를 단단히 다진 후 8각형 기단을 구축하여 그 위에 괴임돌을 놓고 탑신을 얹어 옥개석을 동일석으로 만들었다. 탑신석은 석종형(石…","a":"존자암지세존사리탑","c":"시도유형문화유산","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643294.jpg"},{"q":"○○○은 약 700평의 대지에 대문채, 사랑채, 안채, 가묘, 고방채와 기타 3동의 부속채로 구성되어 있다. ○○○ 사랑채는 정면 5칸 측면 1칸에 전후퇴가 있고 우측부터 큰 사랑방 ＋작은 사랑방 ＋ 안마루 ＋ 중문간 ＋ 중 사랑방으로 짜여 전퇴에는 툇마루, 후퇴에는 벽장 등의 수장 공간이 부설되어 있다. 작은 사랑방과 안마루 사이에는 세 짝의 세살문을 달았으며 안마루 뒷벽은 판벽으로 하여 수장시설을 부가하였다. 큰 사랑방에도 중방위에 벽장을 시설하였으며 배면에 안채로 통하는 외짝 여닫이문을 달았다. 큰사랑방과 작은 사랑방 앞에 예강서원(禮岡書院)이라는 편액을 달았다…","a":"김해 시례리 염수당","c":"문화유산자료","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665963.jpg"},{"q":"고인돌은 청동기 시대의 대표적인 무덤으로 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 거대한 덮개돌[上石]이 지상에 드러나 있고 그 밑에 고임돌[支石], 묘역시설(墓域施設), 무덤방 등이 있는 구조를 가지고 있다. 하지만 지역과 시기에 따라 그 형태는 매우 다양하다. 일반적으로는 무덤방이 지상에 위치한 탁자식(卓子式)과 지하에 위치한 기반식(碁盤式) 또는 바둑판식으로 분류하고 있다. ‘○○○○○’은 수원시립중앙도서관 좌측의 ○○○ 구릉 지역에 위치하며, 2개 지점에 4기의 ○○○가 분포하고 있다. 1호와 2호 ○○○는 ○○○ 남쪽 경사면 해발…","a":"팔달산지석묘군","c":"시도기념물","r":"경기도","s":"수원시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646599.jpg"},{"q":"신안○○○○ 소장 ○○○ 3종(種) 7점(點)이다. 지정목록은 가정(嘉靖) 18년(1539) 주소종자녀분재기(朱紹宗子女分財記), 만력(萬曆) 5年(1577) 주춘영자녀분재기(朱春齡子女分財記), 천계(天啓) 3年(1623) 주량자녀분재기(朱樑子女分財記), 무자(戊子) (1708) 주찬문자녀분재기(朱纘文子女分財記), 을미(乙未)(1715) 주중휘자녀분재기(朱重徽子女分財記), 만력(萬曆) 22年(1594) 주량무과급제교지(朱樑武科及第敎旨), 옹정(雍正) 9年(1731) 예조입안(禮曹立案) (朱氏宗孫 고주중휘(故朱重徽)의 양자건)(5件 연접(連接)) 등으로 분재 문서들은 1…","a":"영해인량리주씨종택고문서","c":"시도유형문화유산","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641102.jpg"},{"q":"맹암 김영렬(∼1404)의 유지를 받들고 후손을 교육시키기 위해 세운 서원이다. 김영렬은 조선 전기 무신이다. 정종 2년(1400) 제2차 왕자의 난을 평정하고 태종을 왕위에 오르게 한 공으로 태종 1년(1401) 익대좌명공신 3등에 오른다. 태종 4년(1404) 참판승추부사로 있을 때 왜선 1척을 싸워 빼앗고 왜병을 포로로 잡은 공을 세웠다. 후에 우의정에 증직되었다. ○○○○은 1945년에 세운 건물로 왕신평야가 내려다 보이는 솔 숲에 남향으로 자리잡고 있다. 서원 안에는 제사 공간인 경훈사와 교육 공간인 강당, 남덕문(覽德門), 출입문 등의 건물이 있고, 밖에는…","a":"신천서원","c":"문화유산자료","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662668.jpg"},{"q":"조선 중기의 무신인 안위(1563∼?) 장군의 묘이다. 선조 25년(1592) 무과에 급제하였으며, 이듬해 거제 현령이 되었다. 1594년 제2차 당포해전 때 이순신의 지휘 아래 전부장(前部將)으로 공을 세웠으며, 1597년 부산의 왜군 화약고에 불을 질러 폭파시켰다. 이후에 전라 우수사를 거쳐 전라도 병마사 등 여러 관직을 역임하였다. 선조 30년(1597) 정유재란이 일어나자 통제사 이순신의 지휘 아래 왜선 20여 척을 격파하여 선조로부터『무경칠서(武經七書)』를 상으로 받았다. 후에 임진왜란 때의 전공자로서 선무공신(宣武功臣) 20명 가운데 한 사람으로 뽑혔다.…","a":"안위장군묘","c":"시도기념물","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653685.jpg"},{"q":"강원특별자치도 양양군에 위치한 ○○○○는 나라에서 ○○○에게 풍농풍어(豊農豊魚)와 마을의 안녕을 기원하기 위하여 제사를 지내던 곳이다. 우리나라는 일찍부터 산천과 바다에 제사를 지냄으로써 풍요와 안녕을 기원하였다. 세운 시기는 정확히 알 수 없으나『고려사』를 통해 고려시대에 이미 나타나 조선 초기에 국가 제사 장소로 정비되었던 것으로 보인다. 북서쪽으로 대나무와 솔밭이 있고, 서쪽은 민가와 접해있다. 남쪽과 동쪽은 밭으로 이용되고 있으며 높은 대지 위에 새로 지은 정전이 1동 있는데 일제시대에 철폐되었다가 1993년에 다시 세운 것이다. 정전의 서북쪽으로 정조 24년…","a":"양양동해신묘지","c":"시도기념물","r":"강원특별자치도","s":"양양군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1648427.jpg"},{"q":"조선 선조 35년(1602)에 충주목사 정구(鄭逑)가 이미 있던 백운서당에 주자를 모시고 백운서원이라 하였는데，현종 2년(1661)에 정구를 배향하고 ○○○○이라 하였다. 숙종 2년(1676) 나라에서 현판을 받아 사액서원이 되었고 고종 8년(1871) 흥선대원군의 서원철폐령 때 철거되었다. 고종 31년(1894)에 서원을 다시 지었는데，다음해 구 영정을 가져와서 봉안하였다. 교육 공간과 제사 공간으로 크게 나뉘는데，앞쪽 교육 공간에는 현재 주춧돌만 남아 있다. 그 뒤편의 제사 공간에는 ‘○○○○’이라는 현판이 걸린 사당이 있다. 사당은 앞면 3칸·옆면 2칸 규모이며…","a":"음성 운곡서원","c":"문화유산자료","r":"충청북도","s":"음성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660729.jpg"},{"q":"○○○○○는 1902년에 금어비구(金魚比丘) 두흠(斗欽)이 그린 것으로, 가로로 긴 직사각형의 화면 중앙에 산수와 소나무를 배경으로 오른쪽을 향하여 앉아있는 산신을 중심으로 하여 호랑이, 동자가 간단하게 묘사된 구도를 보여준다. 이 ○○○에 표현된 것과 같이 바위 위에 앉아 두 손을 나란히 무릎 위에 대고 측면을 향해 앉아 있는 산신의 모습은 서울 봉은사 ○○○ 및 김천 직지사 ○○○의 ○○○에서도 볼 수 있는데, 그 중 봉은사 ○○○는 경선 응석(慶船 應釋)등이 그린 것이고 직지사 ○○○는 봉은사 ○○○의 도상을 좌우를 바꾸고 일부 변화를 준 것으로 ○○○ 사신도를…","a":"청룡사산신도","c":"문화유산자료","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018102314350900.jpg"},{"q":"○○○○○각은 조선초기 문신 송유(宋愉, 1389~1446)의 어머니인 ○○○○의 명정 현판을 보관하는 건물이며 비는 류씨의 행적을 기념하기 위하여 세운 것이다. 류씨 부인은 류준(柳濬)의 딸로, 송극기(宋克己)에게 시집갔으나 22세의 젊은 나이에 과부가 되었다. 친정부모가 재가(再嫁)를 시키려고 하였으나 뜻을 굽히지 않고 어린 아들을 데리고 개경에서 수백리를 걸어 회덕의 시댁에 내려왔다. 시부모를 극진히 모시고 아들을 잘 보살펴 훌륭히 키워냈다 하여 1653년(효종 4)에 열녀로 정려가 내려졌다. 명정기에는 \"癸巳五月日\"이라 되어 있고, 비에는 \"崇禎癸巳五月日銘旌乙…","a":"고흥류씨정려각및비","c":"시도유형문화유산","r":"대전광역시","s":"대덕구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637216.jpg"},{"q":"○○○ 산성각에 걸려 있는 ○○○이다. 가로 95.5㎝, 세로 121㎝ 크기로 비단 바탕에 채색하여 그렸다. 고종 30년(1893)에 제작된 것으로, 민화풍의 나무와 폭포 및 호랑이의 모습 등은 전형적인 19세기 말의 ○○○ 양식을 잘 보여준다. 다만, 원색적이고 장식적이던 당시의 ○○○와는 달리 은은한 중간 색조를 사용한 점이 특이하며, 위엄과 격이 담긴 신선의 얼굴 묘사가 돋보인다.","a":"지장사 산신도","c":"문화유산자료","r":"서울특별시","s":"동작구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2025070417551700.JPG"},{"q":"전북특별자치도 익산시 해발 162m의 낭산 정상에 있는 산성이다. 구성, 마한성 등으로도 불리는데 마한성이라고 하는 것은 고조선의 기준왕이 내려와서 쌓았다는 전설에 의해서 불려지는 것이다. 그러나 이 지역에서 지금까지 마한시대와 관련된 유물들이 밝혀지지 않고 있어서 마한시대에 만들었다는 근거는 없다. 다만 성 안에서 백제 이래의 유물들이 발견되어 이 시기에 만들어진 것으로 판단되고, 후세에 와서 익산 일대가 마한의 옛 도읍지였다는 점에서 마한성이라 부르게 된 것으로 추정된다. 이 산성은 정상을 둘러싼 형태로 북쪽은 거의 정상에, 남쪽은 일부 골짜기를 감싸고 있다. 현…","a":"익산낭산산성","c":"시도기념물","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653333.jpg"},{"q":"증 순충보조공신 가선대부 이조참판겸동지의금부사 진평군이었던 하위보에게 자헌대부 이조판서겸지의금부사 진평군을 증직함. 아들 하협의 정운원종공신 1등 책훈에 따른 추증.","a":"고신(교지)","c":"시도유형문화유산","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001642720.JPG"},{"q":"불상 좌대는 15개의 못으로 돌아가며 고정해 당시 좌대의 고정기법을 확인할 수 있다. 또한 좌대 밑면에는 주서로 제작연대 및 원래의 봉안사찰, 시주자, 제작자 등을 기록해 두었는데 시주자나 화원의 이름 중 일부가 박락되어 있다. 높이 30cm의 소형 ○○상이며, 방형의 얼굴에 민머리를 한 지장보살상이다. 신체에 비해 머리가 큰 조선후기 불상의 특징을 따르고 있으며, 전체적으로 균형 잡힌 비례를 보이지만 어깨가 다소 빈약하고 무릎이 높은 편이며, 상의 규모에 비해 두 손이 크게 조성되었다. 얼굴은 이마가 넓은 방형이며, 콧대로부터 얼굴의 옆선까지 길게 그은 눈, 삼각형…","a":"합천 해인사 희랑대 목조 지장보살좌상","c":"시도유형문화유산","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643123.jpg"},{"q":"○○○는 신라 무열왕 1년(654) 원효대사가 벽방산 기슭에 세운 절이다. ○○○는 조선 숙종 12년(1686)에 처음 지었고 헌종 7년(1841)에 고쳐 지어 오늘에 이르고 있다. 앞면 3칸·옆면 2칸 규모를 갖추고 있으며, 문루의 기능은 없이 법회 장소와 종루의 기능으로 사용하고 있다 누각은 일반적으로 절의 중심 건물 앞에 세워 출입의 역할인 문루의 기능과 종을 걸어 놓는 종루의 기능, 법회를 행하는 강당의 기능을 함께 갖는 경우가 많다. 조선시대 경상남도지역에 있던 절에 만들어진 누각의 두드러진 특징을 갖고 있는 건축물이다.","a":"통영 안정사 만세루","c":"문화유산자료","r":"경상남도","s":"통영시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664174.jpg"},{"q":"봉천산 꼭대기에 설치하여 하늘에 나라의 태평과 백성들의 평안을 빌었던 곳으로, 벽돌을 쌓아올려 위로 갈수록 좁아드는 사다리꼴 형식을 하고 있다. 『강도지』에 의하면, 고려 때에는 나라에서 하늘에 제사를 지내는 제천의식을 거행하였던 곳이었으나, 조선시대 중기에 와서는 봉화를 켜두는 봉화대로 사용하였다 한다.","a":"강화 봉천대","c":"시도기념물","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2018112016152800.jpg"},{"q":"운곡(雲谷) 마을 가운데에 위치한 ○○○○은 모임당(慕任堂) 연안이씨(延安李氏)가 지은 건물이다. '의암(依巖)'은 조범구(趙範九)선생의 호로서, ○○○○이라는 당호는 후대인이 의암 조범구 선생의 덕망을 기리기 위해 붙인 건물명칭이다. 이 집으로 드나드는 대문 앞에 있는 탕건 모양의 큰 바위를 '탕건석'이라 하는데, 관습적으로 사람들이 이 탕건석을 '의암'으로 지칭하기도 한다. ○○○○은 조선 후기에 지은 건물로서, 정침(안채)과 사랑채, 안사랑채, 고방채, 대문간채, 사당, 뒤주채, 장독대 등 조선 시대 사대부 주택의 구성 요소를 고루 갖춘 집이다. 1986년 지방…","a":"상주 의암고택","c":"시도민속문화유산","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658929.jpg"},{"q":"본관이 청송인 송호 심자광의 살림집이다. 심자광은 조선 선조 25년(1592)에 태어나 1625년에 무과에 합격하여 여러 관직에 있었다. 사랑채에 적힌 기록에 따르면 조선 인조 12년(1634)에 건물을 지었다고 한다. 가옥 안에는 안채, 사랑채, 행랑채, 곳간채, 방앗간(화장실)이 남아 있는데 안채는 앞면 5칸·옆면 2칸 규모이고 사랑채는 앞면 5칸·옆면 2칸 규모이다.","a":"합천 대목리 심씨고가","c":"문화유산자료","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664291.jpg"},{"q":"창평면은 담양군의 남동부에 위치하는데 증암천의 한 지류가 동쪽으로 올라오면서 형성된 분지성 지형을 이루고 있다. 창평면의 남반부는 해발 300∼450m의 산으로 둥글게 둘러싸고 있고 북반부는 해발 200m내외의 산지가 분포하고 있는데 증암천은 동쪽에 좁게 열린 협곡을 흘러 고서면으로 이어지고 있다. 창평면의 중심부에는 하천을 따라 비교적 젊은 충적지가 형성되어 있는데 고분은 하천에서 100m 정도 떨어진 창평고등학교 동쪽의 논에 있다. 고분 주변이 논으로 경작되고 있고 서쪽은 창평고등학교를 만들면서 삭토하였기 때문에 고분의 입지지형을 파악하기 어렵지만 주변 지형을 통…","a":"담양창평리고분","c":"문화유산자료","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662253.jpg"},{"q":"○○○는 횃불과 연기를 이용하여 급한 소식을 전하던 옛날의 통신수단을 말하며 높은 산에 올라가서 불을 피워 낮에는 연기로 밤에는 불빛으로 신호를 보냈다. 기장군 기장읍 죽성리에 있는 이 ○○○는 중앙의 봉돈은 지름 2.4m, 둘레 9m의 돌로 쌓여 있으며, 높이 1.5m, 너비 1.5m, 지름 30∼40㎝의 화로가 있었다. 남쪽으로 해운대 간비오산 ○○○, 북쪽으로 임랑 및 아이 ○○○에 연결되어 있다. 고려 성종 4년(985)에 설치하였으며, 고종 31년(1894) 갑오개혁 때 현대적인 전화 통신체제로 바뀌면서 폐지되었고, 원형이 비교적 잘 보존된 편이다.","a":"기장남산봉수대","c":"문화유산자료","r":"부산광역시","s":"기장군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659343.jpg"},{"q":"창원 황씨 문중에서 세운 것으로 조상들의 제사를 모시는 곳이다. 여기에는 황석기·황상·황준·황윤·황우·홍어필의 위패를 모시고 있으며 해마다 음력 10월 15일에 제사를 지내고 있다. 황석기(？∼1364)는 고려말의 문신으로 1342년 조적(曹적)의 무리를 제거하고 왕을 모신 공으로 1등 공신이 되었다. 문장에도 뛰어난 분으로 여러 관직을 거쳐 1358년에는 문하시랑동중서문하평장사에 이르기도 하였다. 황상은 고려말의 무신으로 충혜왕 때 호군이 되었고 공민왕 때 밀직부사가 되었다. 그 뒤 홍건적과 왜구를 토벌하는데 공을 세웠는데 무예에 능하고 용맹이 뛰어났다. 건물로는…","a":"진주 동산재","c":"문화유산자료","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663808.jpg"},{"q":"○○○란 임금이나 고관의 평생업적을 기록하여 그의 무덤 남동쪽에 세워두는 것으로, 이 비는 조선 전기의 유학자인 ○○의 공적을 기록하고 있다. ○○은 연산군 10년(1504)에 과거에 합격한 후 여러 벼슬을 거쳐 관직이 승정원 동부승지에까지 올랐으나 기묘사화 때 화를 입어 17년간 유배생활을 하였다. 성품과 자질이 순수하고 행동에 지조가 굳고 법도가 있었다고 전한다. 비는 네모난 바닥돌 위에 비몸을 세우고 지붕돌을 올린 일반적인 모습으로, 지붕돌은 팔작지붕의 세부양식을 정교하게 본떴다. 영조 24년(1748)에 세운 것으로, 비문은 박필주가 짓고, 윤득화가 글씨를 썼…","a":"청주 박훈 신도비","c":"시도유형문화유산","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638679.jpg"},{"q":"흥선대원군 이하응의 별장인 ○○○에 딸린 사랑채로, 1958년 지금 있는 자리로 옮겼다. 건물은 ㄱ자형이며, 지붕 옆면이 사람 인(人)자 모양인 맞배지붕으로 되어있다. 지붕 끝 벽면은 붉은벽돌로 쌓았는데 가운데에 둥글게 창을 내었다. 대원군 별장은 규모는 작지만 건물의 짜임새가 훌륭하고 조선 후기 상류사회의 대표적인 예가 되는 사랑채로 ○○건축 연구에도 좋은 자료가 되고 있다.","a":"석파정 별당","c":"시도유형문화유산","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636100.jpg"},{"q":"○○○는 고려 명종 25년(1195) 보조국사 지눌이 처음 지은 사찰이다. 나라가 번성하면 이 절도 함께 번창할 것이라는 흥국의 염원을 담아 이름을 ○○○라 하였다. 불법 그 자체보다는 나라를 보호하고 지킨다는 의미가 강한 절이었기 때문에, 나라의 안정과 번영을 기원하던 기도처로의 역할이 컸다. ○○○은 관세음보살이 모셔진 법당을 말하며, 관음전이라고도 한다. 조선 명종 15년(1560)에 크게 다시 지어졌다가 정유재란(1597) 때 불에 탄 것을 인조 2년(1624)에 다시 지었다고 한다. 앞면 5칸·옆면 3칸 규모의 건물로, 지붕 처마를 받치면서 장식을 겸하는 공…","a":"흥국사 원통전","c":"시도유형문화유산","r":"전남광주통합특별시","s":"여수시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639880.jpg"},{"q":"이 책은 줄여서 ‘○○○○○’또는 ‘○○○’이라 부르기도 한다. 부처님의 말씀을 머릿속으로 이해하는데 그치지 않고 자신이 직접 체득하여 힘을 갖는 것을 기본사상으로 하고 있으며, 스님들이 수련하는 과정에서 필수적으로 배우는 경전이다. 이 책은 반랄밀제[般剌密帝: 중인도의 승려. 당(唐) 신룡 원년(705)에 광주의 제지도량에서 『○○○○』10권을 번역]가 번역하고, 송(宋)의 계환(戒環)이 쉽게 풀이한 것인데, 다시 세조(世祖)의 명(命)에 의하여 간경도감(刊經都監)에서 우리말로 번역한 것이다. 책판에 박아낸 목판본(木板本)의 후쇄본(後刷本; 같은 판에서 뒤에 인쇄하…","a":"대불정여래밀인수증요의제보살만행수능엄경 권9","c":"시도유형문화유산","r":"충청북도","s":"단양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018101216222900.jpg"},{"q":"○○○○○은 ○○○의 정상부(해발 571m)에 있는 산성이다. 소가야가 신라를 방어하기 위해 삼국시대에 쌓은 산성으로 전해져 왔으나, 발굴 조사에서 신라 말에서 고려 초에 쌓은 것으로 확인되었다. ○○○○은 ○○○에 있는 얕은 계곡 2개를 포함하여 쌓은 포곡식(包谷式) 산성이며, 전체 둘레는 약 1,381m이다. 산성을 ○○○의 정상부의 남동쪽 비탈면에 쌓아서 ○○ 읍내에서는 잘 보이나 바다에서는 보이지 않도록 하였다. 북쪽은 성벽이 없는데 이는 험한 지세를 이용하여 의도적으로 성벽축조를 생략한 것으로 추정된다. 산성의 평면 형태는 자연 지세에 맞추어 성이 쌓여 있어…","a":"고성 거류산성","c":"문화유산자료","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664027.jpg"},{"q":"경상북도 ○○시 사벌면 ○○○에 있는 이 성은 흙으로 쌓은 산성으로, 내부에 넓은 계곡을 포용하고 계곡을 둘러싼 주위의 능선을 따라 성벽을 쌓은 포곡식 산성 형태를 띄고 있다. 사벌면의 들판을 U자형으로 둘러싸고 있는 능선 가운데 있으며, 성의 안과 밖에서는 청동기 말기, 초기철기시대의 유물과 원삼국시대의 유물이 발견되고 있다.","a":"상주 금흔리 이부곡 토성","c":"시도기념물","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654618.jpg"},{"q":"엄흥도의 충성심을 기리는 건물들이다. 엄흥도는 조선의 지조있는 선비로 조선 6대 임금이었던 단종이 영월에서 시해 당하자 시신을 거두어 장사 지냈다고 한다. 17세기 중반 이후 충신과 사육신에게 표창을 하는 정책이 생기게 되고, 엄흥도의 충성심을 높이 평가해 그의 후손을 관리로 등용하였고 엄흥도를 육신사에 모시게 되었다. 영조 26년(1750)에는 엄흥도의 행적을 기리기 위해 별도로 묘를 마련했는데 영조 31년(1755)에 상절사라는 사당을 세웠다. 순조 33년(1833) 상절사는 의산서원으로 승격되었으나 흥선대원군의 서원철폐령으로 철거되었다. 이후 1900년에 의산서…","a":"충절사·상의재","c":"문화유산자료","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663100.jpg"},{"q":"○○○는 합천 해인사, 승주 송광사와 더불어 우리나라 3대사찰 중 하나로 경내는 크게 상로전, 중로전, 하로전의 3영역으로 나눌 수 있다. ○○○은 중로전에 있는데 고려 공민왕 18년(1369)에 지었으며, 조선시대 영조 1년(1725)에 청성대사가 보수해 현재에 이르고 있다. 앞면 3칸·옆면 3칸으로 지붕 옆모습이 사람 인(人)자 모양인 맞배지붕으로 되어있다. 지붕을 받치기 위하여 장식하여 만든 공포는 기둥 위와 기둥 사이에도 있는 다포계 양식으로 매우 화려하다. 세부장식에는 용무늬를 많이 썼고 건물 앞면 중앙칸에 문짝을 달은 것이 특징이다. 내부에는 약 2m 정도…","a":"양산 통도사 용화전","c":"시도유형문화유산","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641843.jpg"},{"q":"경상북도 김천시 대항면 ○○○의 박물관에 보관되어 있는 ○○○○으로 화강암으로 만들었다. 높이 45㎝, 무릎 폭 28㎝의 아담한 크기로, 본래 서운선사의 원불(願佛)로 전해진다. 호랑이를 어르는 모습에서 당당한 기품과 사실적인 표현기법이 돋보인다. 전체적인 모습으로 보아 고려시대 문화의 절정기인 인종(재위 1123∼1146), 의종(재위 1147∼1170) 때에 만들어진 것으로 추정된다.","a":"직지사석조나한좌상","c":"시도유형문화유산","r":"경상북도","s":"김천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640958.jpg"},{"q":"∙ 조선 후기의 문신 김성구가 건립한 가옥이다. 김성구는 본관은 의성(義城), 자는 덕휴(德休), 호는 ○○○이다. 1662년(현종 3) 사마시를 거쳐 1669년 식년문과(式年文科) 갑과로 급제하였고 이후 여러 벼슬을 지내다가 1693년(숙종 19) 강원도관찰사에 이르렀다. 김성구가 17세기에 처음으로 건립한 다음, 그 후손들이 다시 건립하여 지금에 이른다. ∙ ○○○ 종택은 정면 6칸 측면 5칸의 ㅁ자형 본채와 정면 3칸 측면 2칸의 사당, 정면 3칸 측면 1칸의 삼문, 정면 2칸 측면 1칸의 화장실로 구성되어 있는데, 경북지역 사대부가의 거주생활을 살펴볼 수 있다…","a":"봉화팔오헌종택","c":"문화유산자료","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2344060.jpg"},{"q":"○○○는 전라남도 장흥군 가지산에 있는 절로, 860년 신라의 승려 체징에 의해 창건되었다. 이 책은 ○○○○○의 배안에 넣어서 보관하던 유물 가운데 하나이다. ○○○○이 『반야심경』에 주석을 단 것으로, 흔히 ‘마하반야바라밀다심경해’로 알려져 있다. 중생의 헛된 생각을 바로 잡아 불생불멸의 경지에 이르도록 하여 중생으로 하여금 본심본성을 보이기 위한 경전이다. 책의 뒷부분에는 1411년 전라남도 고창의 문수사에서 판을 새겼다는 기록이 나오는데, 이 판본이 국내에 만들어진 유일한 것으로 알려져 있다.","a":"보림사사천왕상복장대전화상주심경","c":"시도유형문화유산","r":"전남광주통합특별시","s":"장흥군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2020022813515500.jpg"},{"q":"경남대학교 박물관 소장 ‘데라우치문고’(寺內文庫)는 조선 제3대 통감(統監)과 초대 총독(總督)을 지내고 일본의 총리대신(總理大臣)을 역임한 데라우치 마사다케(寺內正毅, 1852～1919)가 한국 재임 중에 수집한 자료를 일본으로 가져가 세운 데라우치문고(寺內文庫, 현 야마구치현립대학 소장)로부터 돌려받은 조선시대 문헌을 말한다. 일본 야마구치현립대학의 데라우치문고에는 조선과 관계된 문헌이 약 1,000여종 1,500여점 소장되어 있다고 한다. 경남대학교 박물관은 이중 98종 135책 1축(1,959점)을 1996년 1월 24일에 일본 야마구치현립대학(山口縣立大學)으…","a":"조천유묵","c":"시도유형문화유산","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018102913541000.jpg"},{"q":"전라남도 남원시 이백면 효기리는 통일신라 후기에 도선국사가 ○○○을 창건하였다고 전해지는 곳이다. 현재 이곳에는 1946년에 건립된 연화사가 있다. 이 ○○○○은 둥글 넓적한 얼굴에 코는 납작하게 표현되어 있다. 귀는 긴 편으로 뒤쪽에 치우쳐 붙어 있으며, 긴 목에는 3개의 주름인 삼도(三道)가 뚜렷하다 옷은 양쪽 어깨에 걸쳐져 있고, 양손 부분에는 구멍이 뚫려 있다. 전체적으로 볼 때 어깨에 비하여 몸이 간략하게 처리된 느낌이 든다. 연꽃 무늬가 새겨져 있는 대좌(臺座)는 불상과 분리되어 있다. 부처의 몸에서 나오는 빛을 형상화한 광배(光背)는 배(舟)모양의 타원형…","a":"미륵암석불입상","c":"문화유산자료","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661680.jpg"},{"q":"‘○○○ 청동 ○○○○ 좌상’은 넓은 끈으로 질끈 동여맨 두건(頭巾)을 머리에 쓰고 오른손에 보배 구슬을 쥔 형상을 하고 있는데, 이는 고려 시대의 전통을 이은 것이다. 바닥면에는 이 불상을 만든 사연이 새겨져 있는데, 1790년 관허당(觀虛堂) 설훈(雪訓) 스님과 용봉당(龍峰堂) 경환(敬還) 스님이 지장암에 봉안하기 위하여 이 불상을 만들었다고 한다. 이 불상을 만든 설훈, 경환 두 스님은 불상과 불화를 모두 다룰 수 있었던 18세기 후반의 뛰어난 승려 장인으로, 서울과 경기 지역을 중심으로 전국적으로 활동하였다. 조선 후기의 일반적인 불상과는 달리 신체 비례가 적…","a":"현등사청동지장보살좌상","c":"시도유형문화유산","r":"경기도","s":"가평군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2019042414433600.JPG"},{"q":"이 정려문은 조선 중엽의 충신 ○○○과 그의 아들을 추모하여 1796년에 세운 정려이다. 정면 1칸, 측면 1칸의 겹처마 맞배지붕으로서 전면은 8각으로 치석한 돌기둥을 사용하였는데, 기둥의 높이는 180cm 정도이다. 정려각의 네 면은 홍살로 꾸며져 있으며, 정면에 “○○○○○”이라는 현판이 걸려있다. 내부에는 ○○○ 부자가 행한 충절의 내용을 기록한 1기의 비석과 3점의 현판이 있는데 비석의 크기는 141×55×25cm 정도이다. ○○○은 임진왜란(1592년) 때 남원에서 1,000여명의 의병을 모아 운암전투에서 왜병을 격파하였고 그의 아들 경우(慶遇)는 군량미를…","a":"양대박부자충의문","c":"문화유산자료","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661842.jpg"},{"q":"신라와 백제의 황산벌 전투가 있었다는 충청남도 논산시 ○○○ 뒷산 기슭에 분포하는 수천 기의 백제무덤들이다. 광복후 도굴에 의해 대부분이 파괴된 상태로 4차례 발굴조사를 통하여 굴식돌방무덤(횡혈식석실묘) 20기, 앞트기식돌방무덤(횡구식돌방무덤) 18기, 독무덤(옹관묘) 1기가 발견되었다. 토기들은 굽다리접시(고배), 병형토기, 굽다리단지(유대호), 그릇받침(기대), 세발토기(삼족토기)를 비롯하여 많은 종류와 양이 출토되어, 계통·성격·분포·연구에 좋은 자료가 된다. 병형토기의 경우 이곳에서 4점이 나왔는데 한반도에서는 나주대안○○○에서 1점만이 출토된 희귀한 형태이다…","a":"논산표정리고분군","c":"시도기념물","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652845.jpg"},{"q":"○○○터에 남아있는 것으로, 석등 받침돌의 일부이다. 모두 2기가 남아있어 1기는 동쪽의 새로 복원해 놓은 석탑과 법당터 사이에 있고, 다른 1기는 중앙의 목탑터와 법당터 사이에 있다. 보통 석등은 불을 밝혀두는 화사석(火舍石)을 중심으로, 아래에는 3단의 받침돌을 두고 위로는 지붕돌과 머리장식을 얹어두는데, 이들은 3단의 받침돌 중 아래받침돌까지만 남아있다. 사각의 바닥돌 위에 놓인 아래받침돌은 윗면에 8잎의 연꽃을 두르고 그 사이에도 작은 잎을 조각해두었다. 동쪽에 있는 것이 꽃잎의 끝이 좀더 위로 말려 있을 뿐 거의 비슷한 모습이며, 맨 윗면에는 윗돌을 꽂아두기…","a":"미륵사지석등하대석","c":"문화유산자료","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661796.jpg"},{"q":"조선 후기의 자기를 굽던 가마터로 ○○○ 북쪽에 위치하고 있다. 이곳은 예전부터 가마터가 있었다고 전해져 왔던 곳이다. 도자기를 만들기 위해 흙을 채취했던 흔적과 갑발, 가마의 일부, 백자 조각 등이 확인된다. 도자기 조각은 완, 접시, 사발 등 기종이 다양하며 이 조각들로 미루어 볼 때 조선 후기에 도자기를 굽던 가마터로 추정된다. 이 지역의 도자사 연구에 귀중한 자료이다.","a":"사천사촌리도요지","c":"시도기념물","r":"경상남도","s":"사천시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657004.jpg"},{"q":"해안에서 북쪽으로 100m 거리에 자리한 가천마을에는 가장 아래쪽 밭 모서리에 한 쌍의 ○○○○가 5m 간격으로 서 있다. 이곳에서는 ‘미륵불’이라 하여 각각 암미륵, 숫미륵이라 부르기도 한다. 암미륵은 높이 3.9m, 둘레길이 2.3m의 크기로, 여인이 잉태하여 만삭이 된 모습을 한 채 비스듬히 누워있고, 숫미륵은 높이 5.8m, 둘레길이 2.5m 크기로, 남성의 성기 형상으로 서 있다. 아이를 갖지 못한 여인들이 아무도 모르게 숫미륵 밑에서 기도를 드리면 득남한다 하여 이 고장의 여인들 뿐만 아니라 다른 지방에서도 많이 다녀간다고 한다. 조선 영조 27년(1751…","a":"남해가천암수바위","c":"시도민속문화유산","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659050.jpg"},{"q":"인천광역시 ○○군 선원면 선행리에 위치한 ○○○는 김상용 선생을 비롯한 병자호란과 신미양요 때 나라를 지키다 순절한 충신 29명의 위패를 봉안한 사당이다. 1641년(인조 19)에 건립하여 현충사(顯忠祠)라 부르다가 1658년(효종 9)에 국왕으로부터 ○○○란 이름을 받아 ○○유수 허휘가 ○○○로 이름을 바꿨다. 김상용은 1636년 병자호란 때 왕실의 신주를 받들고 빈궁·원손을 수행해 ○○도에 피난했다가 이듬 해 성이 함락되자 성의 남문루(南門樓)에 있던 화약고에 불을 지르고 순절하였다. ○○○를 건립할 당시에는 모두 7명을 배향하였으나, 이후 황선신과 강흥업이 추향…","a":"강화 충렬사","c":"시도유형문화유산","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637043.jpg"},{"q":"○○○은 조선 명종 1년(1546)에 박원순이 지은 정자로, 오랜 세월이 흘러 낡은 것을 13대손인 박정현이 고쳐 지었다. 박원순은 김인후의 제자로 성리학을 공부하고 진사시에 합격하였으나 벼슬길에는 나아가지 않고 이곳에 정자를 짓고 제자들을 가르치며 지냈다. 정자 안에는 은행나무를 심고 연못을 파서 구곡수를 끌어 들이는 등 그윽한 분위기를 만들어 냈다. 박원순이 죽자 은행나무와 샘물이 모두 말랐다가 삼년 후에 다시 살아났다는 전설도 있다. 건물은 앞면 2칸·옆면 2칸 규모이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 꾸몄다. 앞면 2칸 중 왼쪽을…","a":"장성 청계정","c":"문화유산자료","r":"전남광주통합특별시","s":"장성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662033.jpg"},{"q":"안동 권씨 부정공파 이우당 권환의 종택으로 인조 18년(1640)에 지었다고 한다. 1963년에 건물 전체를 수리하였으며, 지금 있는 건물은 1994년에 일부분을 고친 것이다. 앞면 5칸·옆면 5칸의 안채는 목조기와집으로 ㅁ자형 구조를 하고 있다. 대청은 6칸이며 우물마루를 깔았다. 사랑채는 영조 49년(1773)에 정침을 수리하면서 높은 기단 위에 지었으며, 건물 주위에 난간을 둘렀다. 마을의 모든 건물은 북향인데 이 집만 북동향을 하고 있다.","a":"이우당종택","c":"시도민속문화유산","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658662.jpg"},{"q":"○○○는 1930년대 상효동 산85-1번지에 있던 쌍계암을 서홍동으로 이건하였다가 다시 이곳으로 옮겨 창건된 사찰이다. ○○○ 소장 ○○○○○은 1702년에 전라남도 순천 북령 동리산 대흥사(순천 북령 동리산 대흥사)에서 조성 봉안되었던 불상으로서 후일 쌍계암에 봉안되었다가 이곳으로 옮겨왔다. 이 불상은 과거칠불 중 제3불인 비사부불(毗舍浮佛)이며 국내에서는 처음으로 발견된 것이다. 불상의 재질은 경주불석(慶州佛石)이며 전체높이 61.5cm, 전체너비 44.5cm, 어깨너비 28.0cm, 무릎너비 42.0cm이다. 복장(腹藏)에는 불상 조성 발원문과 함께 다라니와 후…","a":"정방사소장석조여래좌상및복장유물일괄","c":"시도유형문화유산","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643329.jpg"},{"q":"옥천 조씨 절민공파의 종가로 조선 숙종 2년(1676)에 조치형(1642∼1754)이 지었다고 한다. 이 마을은 약 550여년 전에 옥천 조씨 조지곤이 처음으로 살기 시작하여 형성되었다. 마을에는 친족간에 화목과 우애를 돈독히 하는 감락재가 남아 있으며, 귀두정과 경운각이 있었다고 하나 지금은 남아 있지 않다. 안채, 사랑채, 문간채, 곳간, 제실, 아래채, 중문간 등으로 구성되어 있으며, 솟을대문이 있던 곳에는 주춧돌만 남아 있다. 이 집에는 조선시대의 교지·영지·전령·고서 등을 많이 소장하고 있으며, 식기류와 교지통, 생활집기류 등이 남아 있어 당시 생활모습을 살…","a":"승주조승훈가옥","c":"문화유산자료","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662170.jpg"},{"q":"경주에서 울산으로 향하는 도로의 동편, 토함산 준령의 서편에 위치해 있는 ○○○는 신라 성덕왕(聖德王) 18년(719)에 중아찬(重阿湌) 김지성(金志誠)이 세운 절이다. 무너져 있던 이 탑은 1965년에 다시 세웠으며 현재 높이는 약 3.3m이다. 기단은 2층으로 하였는데, 1층 기단은 4개의 돌로 구성되었고 각 면에는 모서리 기둥과 안 기둥을 각각 새겼다. 2층 기단의 각 면에도 모서리기둥과 안기둥을 각각 새겼으며 덮개돌은 2개의 돌로 구성하였다. 1층 몸돌과 지붕돌은 각각 1개의 돌로 하였고 몸돌에는 모서리 기둥을 조각하였다. 지붕돌에는 4단의 받침을 조각하였고…","a":"감산사지삼층석탑","c":"문화유산자료","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662553.jpg"},{"q":"○○○○는 결구가 치밀하며 치목과 세부 수법이 우수한 근대 한옥의 특징을 잘 보여주며, 영남의 기호사림의 학맥을 이어온 관련 인물의 유학사적 비중을 고려할 때 건축적 특징과 상징성을 지니고 있다.","a":"김해 화산정사","c":"문화유산자료","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666772.jpg"},{"q":"○○○는 통일신라 진성여왕 7년(893)에 도선국사가 남원고을 터의 기가 강하여 이를 누르기 위해 세운 것으로 전한다. 원래 절의 이름을 ‘대곡암’이라 하였으나 조선 철종 때 ‘○○○’로 바꾸었다. 절 경내에 있는 건물로는 ○○○, 칠성각, 선방, 요사 등이 있으며, ○○○은 철종 때 보수한 것이다. ○○○은 앞면 3칸·옆면 2칸 규모로, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕으로 꾸몄다. 안에는 아미타불을 모셨으며, 신장탱화, 후불탱화, 지장탱화를 모시고 있다.","a":"대복사극락전","c":"문화유산자료","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661663.jpg"},{"q":"○○○ 미륵전 안에 모시고 있는 이 ○○○○은 미륵불상으로 알려지고 있으나, 손모습으로 보아 석가여래가 책상다리를 하고 앉아있는 모습으로 보인다. 광배 윗 부분은 잘려나갔으며, 얼굴의 눈과 코 부위 등은 심하게 닳았고, 채색의 흔적이 일부 남아있다. 이 불상은 몸체에 비해 얼굴부위가 크게 묘사되어 있으며, 오른쪽 어깨를 완전히 드러낸 옷차림을 하고 있다. 큼직하게 표현된 두 손은 부처가 모든 악마를 굴복시켜 없앤다는 손 모양새를 취하고 있다. ○○○는 고려 초에 원광스님이 세웠다고 전해지는데, 이 불상은 제작 기법 등으로 보아 고려말에 지방에서 만든 작품으로 보인다.","a":"천고사석불좌상","c":"문화유산자료","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661798.jpg"},{"q":"○○○은 본관은 진주(晉州)이며, 자는 지옹(智翁)이고, 목사 양(壤)의 아들로서 김종직(金宗直)의 문인이다. 1487년 진사로 알성문과에 장원, 전적에 등용되었다. 1491년(성종22) 북정도원수 허종의 막하로서 야인 정벌에 종군하여 많은 전공(戰功)을 세우고 돌아왔다. 뒤에 평안도 평사로 전임, 연산군 초에 헌납, 부응교, 집의, 사성을 역임, 의주목사를 거쳐 평안도 병마절도사에 올랐다. 그 후 형조, 공조의 참판을 지내고 평안도 찰사, 이조 참판을 거쳐, 이조 판서에 승진하였다. 1506년(중종1) 중종 반정에 공을 세워 정국공신(靖國功臣) 1등으로 청주부원군에…","a":"류순정 영정","c":"시도유형문화유산","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636407.jpg"},{"q":"덕계 ○○과 그의 아들 ○○, ○○의 스승 ○○의 문집책판으로, 모두 132매이다. ○○은 남명 조식의 문인으로, 한때 퇴계 이황에게서 공부를 배웠다. 어머님이 돌아가시자 움막을 짓고 3년간 묘를 지켰으며, 그 효성이 조정에 알려져 상을 받기도 했다. 명종 13년(1558)에 문과에 급제하여 정언을 거쳐 선조 4년(1571)에 이조좌랑으로 춘추관기사관을 겸해『명종실록』편찬에 참여하였다. 만년에는 고향에 돌아와 학문에 몰두하면서 여생을 보냈다. 『덕계선생문집』10권 5책은 순조 17년(1817)에 간행된 것이다. 『○○○』은 ○○의 시문집으로 8권 4책으로 되어있다.…","a":"오건 덕계문집 목판, 오장 사호집 목판, 오한 수오당문집 목판","c":"시도유형문화유산","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641760.jpg"},{"q":"임진왜란 때 큰 공을 세운 충무공 이순신(1545∼1598) 장군의 위패와 영정을 모시고 있는 사당이다. 착량(鑿梁)이란 ‘파서 다리를 만들다.’라는 뜻으로 당포해전에서 참패한 왜군들이 쫓겨 달아나다 미륵도와 ○○반도 사이 좁게 이어진 협곡에 이르러 돌을 파서 다리를 만들며 도망한데서 붙인 이름이다. 이순신 장군이 임진왜란에서 혁혁한 공을 세우고 선조 31년(1598) 노량해전에서 전사하자 이를 애통하게 여긴 이 지방 사람들이 그의 충절과 위업을 기리기 위해 착량지가 내려다보이는 언덕 위에 초가를 짓고 정성껏 그를 모셔온 것이 이 사당의 시초가 되었다. 이후 고종 1…","a":"통영 착량묘","c":"시도기념물","r":"경상남도","s":"통영시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654753.jpg"},{"q":"조선 전기 황희 정승의 유물로서 옥으로 된 종이누르개(옥서진) 1쌍, 산호로 된 갓끈 1종, 옥 벼루 1개. 코뿔소 뿔로 된 띠(서각대) 1개, 재산분할문서 1매(분재문서) 들이다. 황희(1363∼1452)의 호는 방촌으로, 고려 공양왕 1년(1389)에 문과에 급제하였다. 1431년부터 1449년까지 영의정이 되어 세종대왕을 도와 국정을 통치하였으며, 관직을 벗은 후에도 중대사에 대해 세종의 자문을 해 주며 영향력을 발휘하였다. 그는 4군 6진의 개척, 외교 및 문물제도 정비, 문화진흥을 지휘하여 세종대의 태평성대를 이룩하는데 기여하여, 조선왕조에서 가장 훌륭한 재…","a":"황방촌유물","c":"시도유형문화유산","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640480.jpg"},{"q":"○○○○○는 풍광이 매우 수려한 반변천변의 나지막한 구릉 위에 세워진 정자이다. 안동권씨 용담(龍潭) 권지(權誌; 1567~1637)가 창건하였고, 아들인 번곡(樊谷) 권창업(權昌業; 1600~1663)이 물려받아 별서(別墅)로 삼았으며, 손자 산택재(山澤齋) 권태시(權泰時; 1635~1719)가 무너진 건물을 중건하여 학문 연구와 후학을 양성하는 강학처로 삼았다. 그 후 ○○○는 다시 폐허로 변하였다가, 1916년에 중당협실형(中堂挾室形) 정자로 중건되었다. 중건된 ○○○는 일제 강점기와 해방 이후의 혼란기를 거치면서 또 크게 퇴락하여, 현재는 1993년에 중건한…","a":"영양 남경대","c":"문화유산자료","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018102610412900.jpg"},{"q":"○○○는 신라 문무왕 16년(676)에 의상대사가 세운 절이다. 이후 여러 차례 재난을 당하여 무너진 것을 고려 명종 14년(1184) 보조국사 지눌이 ○○○을 비롯하여 7동의 건물을 복원하였으나, 임진왜란 때 화재로 소실되고 ○○○과 반학루, 삼층석탑만 남아 있다. ○○○은 앞면 3칸·옆면 2칸의 규모로, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다. 지붕 처마를 받치기 위해 장식하여 만든 공포의 앞쪽 기둥은 기둥 위에만 있는 주심포 양식으로 되어 있고, 뒤쪽 기둥은 새 날개 모양으로 장식한 익공 양식을 섞어 놓았다. 조선 중·후기의 건축물로 두 가지…","a":"보문사극락전","c":"문화유산자료","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662825.jpg"},{"q":"용암공의 덕을 후세에 전하기 위해 세운 비로, 이웃한 마을에 불이 나서 비석이 불에 타 형태가 일그러질 지경이 되자, 마을의 여러 유지들이 논의하여 다시 세운 것이다. 조선 순조 34년(1834)에 세웠으며, 비 양 옆에 기둥을 세우고 그 위에 지붕돌을 얹어 이를 보존하고 있다.","a":"창녕 진만석 영세불망비","c":"문화유산자료","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664472.jpg"},{"q":"조선시대의 관리가 한복이나 공복을 입을 때 두르던 띠이다. 겉에 물소뿔로 만든 장식이 달려있어 서대(犀帶)라 하는데, 조선시대 법전인『대전회통』에서는 정1품의 관리가 옷을 입을 때 사용하던 중요한 의장의 하나로 적고 있다. 외형을 살펴보면, 한지를 여러 겹 아교로 붙여 띠를 만들고, 밖에는 물소뿔을 얇게 다듬어 오려 붙인 후, 앞에는 착용할 때 필요한 금속구를 달아 놓았다. 태조 2년(1392) 삼척지방이 부(府)로 승격되면서 하사받은 것으로, 실직왕묘 안의 보대운한각(寶帶雲漢閣)에 ○○○와 서대기책이 함께 보관되어 있다.","a":"홍서대","c":"시도민속문화유산","r":"강원특별자치도","s":"삼척시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658179.jpg"},{"q":"○○○ 마을의 한 민가 안에 서 있는 한쌍의 돌장승이다. 장승은 마을이나 사찰입구에 세워 잡귀나 액운의 출입을 막고 사찰내의 재산과 경계를 표시하는 민간 신앙물로, 마을의 수호신이 되기도 한다. 이 장승은 각각 환웅과 단군 두분을 상징하는 것으로, 단군상은 크기 182㎝, 두상 55㎝, 밑둘레 158㎝이며 환웅상은 크기 172㎝, 두상 56㎝, 밑둘레 140㎝이다. 단군상은 앞면 가슴에 ‘왕검(王儉)’, 뒷면에는 ‘장백산(長白山)’이라 새기고, 환웅상은 앞면 가슴에 ‘환웅(桓䧺)’, 뒷면에는 ‘구룡연(九龍淵)’이라 새겨 놓았다. 원래 ○○○로부터 서북쪽으로 3㎞ 떨어…","a":"월천리석장승","c":"시도민속문화유산","r":"전북특별자치도","s":"부안군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658325.jpg"},{"q":"우석목·무석목·벅수머리 등으로 불리우는 이 석상은 제주목·정의현· 대정현의 성문 입구에 세워졌던 것이나, 현재는 제주도민속자연사박물관· 제주대학·제주시청·제주국제공항· 삼성혈·관덕정 등에 산재하여 있으며 제주시내에 21기, 성읍에 12기, 대정의 인성·안성·보성에 12기 도합 45기가 있다. 석상의 형태는 대체로 벙거지형 모자, 부리부리한 왕방울 눈, 큼지막한 주먹코, 꼭다문 입술 두손은 배위 아래로 위엄있게 얹은 모습을 하고 있다. ○○○○의 크기는 평균 신장이 제주 187Cm, 성읍 141Cm, 대정 134Cm 이며 제작 연대는 영조 30년(1754) 경으로 추정…","a":"돌하르방","c":"시도민속문화유산","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659167.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 조선 성종 4년(1473)에 관학산 밑에 처음 지었는데, 광해군(재위 1608∼1623) 때 동쪽으로 옮겼다가 헌종 3년(1837)에 지금 있는 자리로 옮겨 지은 것이다. 일제시대 폐교되어 금산향교에 합쳐졌다가 1946년 복원하였고 여러 차례 보수를 거쳐 오늘에 이르고 있다. 정문인 외삼문을 들어서면 앞쪽에 교육 공간인 명륜당이 있고, 그 뒤에 있는 내삼문을 통해 들어서면 제사 공간인 ○○○을 배치하였다. ○○○은 공자를 비롯하여 중국과 우리나라 유학자의 위패…","a":"개령향교대성전","c":"문화유산자료","r":"경상북도","s":"김천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662628.jpg"},{"q":"○○○은 영천만취당(국가민속문화유산)의 좌측에 자리하고 있는데, 능참봉 조병문이 둘째아들의 살림집으로 건립하였다고 한다. 현재 건물의 배치는 ＇ㄱ＇자형 평면의 사랑채가 전면에 남향으로 자리하고 뒤쪽에 ‘一’자형 안채가 위치하고 있다. 그러나 초건 당시에는 안채 전면 좌측에 3칸집이 자리하여 전체적으로 트인 ‘口’자형 배치를 이루고 있었으며, 안채 우측 쪽으로 협문을 두어 만취당으로 직접 연결되었으나 만취당 보수시 협문을 없앴다. 그리고 현재 출입부에 대문채가 있었고 사랑 좌측편에 고방 및 방앗간채가 자리하였다 한다. 그리고 고방채 앞쪽으로 마구 및 초당방이 있어 반가…","a":"금산당","c":"시도유형문화유산","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641075.jpg"},{"q":"장대는 지휘하는 사람이 올라서서 명령하는 대를 가리킨다. 진주시 남성동에 있는 이 장대는 ○○○ 서문에 속하는 곳이다. 『여지도서』에 보면 회룡루로 나오며, 규모는 작으나 ○○○의 남장대인 촉석루와 같은 다락집형이었다고 기록되어 있다. 지금의 건물은 허물어진 것을 1934년 서상필씨가 새롭게 고쳐지은 것으로, 앞면 3칸·옆면 2칸의 여덟 팔(八)자 모양의 팔작지붕으로 목조 기와집이다.","a":"진주성 서장대","c":"문화유산자료","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663791.jpg"},{"q":"풍산 홍씨 집성촌인 도래마을 깊숙한 곳에 자리잡고 있는 살림집이다. 원래 안채, 사랑채, 행랑채를 갖춘 집이었다고 하는데 지금은 안채만 남아 있다. 건물에서 발견된 기록(상량문)으로 미루어 1918년에 지은 것으로 추정한다. 안채는 6칸 크기의 一자형 집으로 부엌방과 부엌·안방·대청마루방으로 구성되어 있다. 대청마루에는 앞쪽으로 1칸 반 크기의 작은방을 두었고 뒤쪽에 함실아궁이를 만들어 놓았다. 비교적 건물의 규모가 크고 구성과 구조가 건실하여 당시 주택을 살피는데 좋은 자료가 되고 있다.","a":"나주홍기창가옥","c":"시도민속문화유산","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658357.jpg"},{"q":"○○○○○는 1기로서 두동면 ○○○ 비조마을 회관 옆에 위치하고 있다. 덮개돌은 화강암으로 비스듬히 뉘어 있으며, 네모꼴에 가까운데 크기는 길이 260㎝, 너비 185㎝, 두께 120㎝정도이다. 덮개돌 아래에는 사람머리보다 조금 큰 받침돌이 확인되어, 바둑판식 ○○○로 추정된다. 덮개석의 상부에는 성혈과 같은 흔적은 발견되지 않았으며, ○○○ 부근에서 돌도끼 한점이 출토되었다고 주민들은 전하고 있다. 이 ○○○○○는 울산광역시 기념물인 은편리 ○○○군과 함께 청동기시대 두동 지역의 정치·사회·문화 등을 연구할 수 있는 중요한 자료가 된다.","a":"만화리지석묘","c":"시도기념물","r":"울산광역시","s":"울주군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645901.jpg"},{"q":"영양 남씨 시조인 남민을 모시기 위한 여남서원의 강당이다. 남민은 당나라 사신으로 일본에 다녀오는 길에 태풍을 만나 신라로 들어오게 되었다. 이 때 당현종의 양해를 구해 신라 경덕왕으로부터 영양땅을 하사받아 머무르며 영양 남씨의 시조가 되었다. 처음에는 향현사를 지어 남민을 배향했는데 순조 30년(1830)에 강당과 동재·서재, 문루 등을 세워 여남서원이 되었다. 그 뒤 흥선대원군의 서원철폐령으로 폐쇄되었는데, 다른 건물은 모두 훼손되고 강당만 남아 ○○○○으로 부르게 되었다. 강당은 앞면 4칸·옆면 2칸의 규모로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작…","a":"여남강당","c":"문화유산자료","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662510.jpg"},{"q":"고려 후기의 문신인 ○○ 부부의 ○○이다. 고려 충숙왕 12년(1325) 음서로 팔관보판관이 되고 다음해 문과에 급제하였다. 그 뒤 여러 관직을 역임하였으며, 1358년 벼슬이 형부상서에 이르렀다. 공민왕의 각별한 총애를 입어 내불당 짓는 일을 감독하였으며, 공민왕이 친히 쓴 글씨 ‘탄상하교문(嘆賞下敎文)’을 받았다. 그의 친족은 모두 높은 관직에 올랐고, 이성계의 위화도 회군 이후 그의 집정기간에는 유력한 지지세력으로서 조선 건국에 크게 도움을 주었다. 묘는 고려 후기의 사다리꼴의 특징을 보여주고 있으며, 묘 앞에는 묘비·상석이 있다. 묘표석은 원형이 잘 보존되어…","a":"진천 이정 묘소","c":"시도기념물","r":"충청북도","s":"진천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650305.jpg"},{"q":"○○○○란 공이 있는 신하에게 나라에서 공신으로 명한다는 임명서를 말한다. 이 유물은 태종 1년(1401) 2월에 태종이 임금의 자리에 오르는데 공이 있는 인물 46명을 ○○○○으로 책봉한 후 개인에게 내린 ○○○○와 공신을로 책봉한 후 역대의 3공신인 개국, 정사, 좌명의 공신들이 하늘에 맹세한 후 작성한 ○○○이다. ○○○이 ○○○○ 3등에 책봉될 때 ○○○○와 공신도감에서 발급하는 인정서인 녹권이 함께 발급되었는데 현재 녹권은 남아 있지 않고 교서만 남아있는 형편이다. ○○○○는 ○○○, 이래, 윤목 등에게 내린 교서로 이의 내용은 이들 3인이 박포의 반란시에…","a":"김영열좌명공신교서및회맹록","c":"시도유형문화유산","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640985.jpg"},{"q":"취죽당 김응명의 8대손 김몽노(1828∼1884)의 생가이다. 대지를 2단으로 조성하여 사랑채 부분과 안채를 나누고 있다. 안채는 사랑에 덧대어 설치한 중문을 통하여 출입하게 하였고 뒤편에는 사당을 지었다. 사랑채의 구성은 좌우에 중간문과 고방을 두었고 왼쪽 온돌방에는 옛 방식인 중간설주가 서 있다. 오른쪽 온돌방에는 4짝 여닫이문을 달아 격식을 갖추었다. 사랑채 구성의 특이성으로 인하여 한옥 건축의 귀중한 자료로 평가되는 건물이다.","a":"운곡정사","c":"시도민속문화유산","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658786.jpg"},{"q":"조선 현종 때 문신인 강흡(1602∼1671)의 위패를 모신 사당이다. 강흡은 인조 8년(1630) 진사시에 합격하였으며, 세마부위란 벼슬을 지냈다. 병자호란 때 임금이 남한산성에서 중국 청나라에 무릎을 끓자 벼슬을 버리고 이곳에 들어와 은둔생활을 하였다. 그는 이곳에서 당시 태백오현(太白五賢)으로 추앙 받던 정양·심장세·홍석·홍우정 등과 어울려 공론을 벌이며 자연을 벗삼아 지냈다. 이 건물은 그를 추모하기 위해 숙종 5년(1679)에 세웠고 그 뒤 1938년 다시 고쳐 지었다. 규모는 앞면 2칸·옆면 2칸이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작…","a":"이오당","c":"문화유산자료","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662709.jpg"},{"q":"조계산 ○○○는 삼보사찰의 하나인 승보사찰(僧寶寺刹)로 매우 유서 깊은 삼국시대의 절이다. 국사전 바로 왼쪽에 위치한 진영각은 풍암스님의 문하 큰 스님들의 영정을 모신 건물이다. 풍암은 숙종 14년(1688)에 송광면에서 출생하여 영조 43년(1767)에 입적한 ○○○의 스님이다. 조선 후기 ○○○의 큰 스님들은 거의 풍암의 제자이므로, 편액도 ‘풍암영각(楓巖影閣)’이라 하였다. 절의 기록에 의하면 조선 철종 3년(1852)에 지었다고 하며, 원래 지금의 도성당이 있는 자리에 있던 것을 옮겨 지은 것이라고 한다. 앞면 3칸·옆면 2칸의 규모이며 지붕의 옆면이 사람 인…","a":"송광사진영당","c":"시도유형문화유산","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639939.jpg"},{"q":"○○○은 조선 중기의 문신이다. 관향은 창녕(昌寧)이며 자는 선백(善伯), 호는 도촌(陶村)이다. 내암 정인홍의 문하에 입문하여 수학하였으며 임란에 창의하였다. 선조 32년(1599)에 상의원 별제에 임명되었으나 부임하지 않다가 선조 40년(1607) 왕자사부(王子師傅)에 임명되기도 하였다. 그 뒤 공조좌랑, 온양군수 등을 역임하였다. 이 논서는 ○○○이 온양군수로 재직할 당시 관찰사 이춘원의 보고에 의하여 광해군이 내린 것이다. 논서는 한지로 현재 상태는 양호한 편이다.","a":"도촌조응인선생유서","c":"문화유산자료","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664527.jpg"},{"q":"조선 순조(재위 1800∼1834) 때 이조판서를 지낸 ○○○이 살았던 옛집이다. 원래는 한수면 북노리에 있었으나 충주댐 건설로 인하여 안채는 충주로 옮겨 지었고 사랑채는 이곳으로 옮겼다. ㄴ자 모양으로 꺾이는 부분인 중앙에 부엌을 놓아 구들을 시설하고, 앞면 끝에 대청을 배치하였다. 대청은 문을 달아 마루방으로 꾸몄고, 집의 맨 뒤쪽에 사랑방을 배치하여 제사를 지낼 수 있도록 한 점이 특이하다. 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕집이며, 잘 다듬은 네모 주춧돌과 각 방문 밑에 나무로 설치한 머름 등이 이 집의 격을 높여준다.","a":"제천 김세균 고가","c":"시도유형문화유산","r":"충청북도","s":"제천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638524.jpg"},{"q":"용화산 동쪽 경사면의 진주 소씨 묘지 가장 위쪽에 자리하고 있는 소자파 선생의 묘비이다. 소자파 선생은 조선 성종 14년 사마시에 합격하여 의빈부도사를 거쳐 중종 19년 구례의 임지에서 73세에 순절하였다. 그의 아들 소세양이 벼슬이 올라감에 의해 가선대부 이조참판과 숭록대부 의정부좌찬성겸의금부사를 추증받았다. 묘비는 화강암으로 만든 받침돌과 대리석으로 깍은 비몸·머릿돌을 갖춘 형태이다. 4각의 받침돌은 국화무늬를 조각하였다. 머릿돌은 앞·뒷면에 연꽃과 구름무늬를 새겨 넣었는데 그 조각이 매우 섬세하고 뛰어나다. 비문은 남곤과 이행이 짓고 글씨는 김희수와 성세창이 썼…","a":"소자파묘비","c":"문화유산자료","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661802.jpg"},{"q":"○○○ 내의 서산대사 유물관에 보관되어 있는 ○○○○○로, ‘십일면천수○○○○○’과 ‘준제○○○○○’2폭이 전하는데, 초의선사가 그린 것으로 알려져 있다. ‘십일면천수○○○○○’는 8각의 연꽃 받침대 위에 천수관음이 서 있는 모습으로, 불꽃모양의 광배를 뒤에 두르고 있다. 작은 붓으로 정교하게 그려 놓은 얼굴과 머리의 묘사는 매우 능숙하면서도 도식적이다. 보살은 모두 43개의 손을 갖추고 있는데, 37개의 손마다 갖가지 모양의 물체를 들고 있으며, 손바닥 중앙에 1개씩의 눈을 그려 놓았다. ‘준제○○○○○’는 위의 그림과 비슷한 필치와 색채로 그렸는데, 천수관음이 서…","a":"대흥사관음보살도","c":"시도유형문화유산","r":"전남광주통합특별시","s":"해남군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640115.jpg"},{"q":"○○○○○은 신체에 비해 얼굴이 크고 좌우가 넓은 장방형이며, 변형통견식으로 착의한 가사와 수평형 승각기에서 보이는 도식적이고 딱딱한 옷주름 표현 등에서 전형적인 조선후기 조각의 표현이 엿보인다. 또한 석조라는 재질적인 영향으로 손, 발, 옷주름 등 두텁고 세밀하지 못한 조각적 한계를 가지고 있다. 특히 이 像이 취한 변형된 항마촉지인은 칠곡 송림사 목조여래좌상(1655년), 기장 장안사 척판암 ○○○○○, 프랑스기메박물관 석조보살좌상, 호암미술관 ○○○○○ 등에서도 나타나는데, 17세기에 처음 등장하기 시작하여 조선후기 석조상에서 보이는 특징이라 할 수 있다. 그리…","a":"창원 봉림사 석조여래좌상","c":"문화유산자료","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666437.jpg"},{"q":"조선 선조 때 문신인 ○○○의 공적을 기리기 위해 1640년(인조 18)에 건립한 비이다. 본관은 동래(東萊)이고 호는 사암(思菴)이다. 왕명을 받아 권신 윤원형(尹元衡)의 사건을 강직하게 조사하여 명성을 얻었다. 청백리로서 명망이 높았다. ○○○는 묘역 아래에 있는 혁림사(赫臨祠; 동래정씨 사당) 경내의 비각 안에 세워져 있다. 사각형의 받침돌에 비신(碑身; 글씨를 새기는 부분)을 세우고 이수(螭首; 용을 새겨 장식한 비석의 머릿돌)를 올린 방부이수(方趺螭首) 양식을 갖추고 있다. 이수의 앞면에는 용 두 마리가 하나의 여의주를 서로 차지하고자 다투는 모습을 사실적으…","a":"정대년신도비","c":"시도유형문화유산","r":"경기도","s":"여주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637652.jpg"},{"q":"고종의 아버지 흥선대원군 이하응(李昰應, 1820∼1898)의 무덤이다. 흥선대원군은 1907년에 흥선대원왕으로 추봉되었고 1908년에 무덤도 ○○으로 승격되었다. 묘역은 여흥부대부인(驪興府大夫人)과 합장한 단분(單墳 ; 하나의 봉분)의 형태이다. 묘역의 석물들은 백색 화강암으로 만들어 재질이 우수하며 조각기법은 수려하고 섬세하여 뛰어난 예술성을 보인다. 이는 왕실에서 제작하였기 때문인데, 근대 조선 왕실의 희귀한 능묘 석물이기에 더욱 중요하다. 봉분 주변에는 원(園)이라는 무덤의 격식에 맞추어 석양을 바깥쪽을 향하여 배치하였는데 1907년 이후에 위치를 변경한 것이…","a":"흥원(흥선대원왕)","c":"시도기념물","r":"경기도","s":"남양주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646091.jpg"},{"q":"조선시대 명장 충의공 정문부(1565∼1624) 장군의 뜻을 기리기 위해 세운 사당이다. 충의공 정문부는 조선 중기의 문신이자 의병장이다. 선조 21년(1588) 과거에 급제하였으며, 선조 25년(1592) 임진왜란이 일어나자 의병을 조직, 왜적과 싸워 승리하였다. 또한 선조 26년(1593) 백탑교 전투에서는 왜군을 크게 무찔러 관북지방을 완전히 수복하기도 하였다. 이후 여러 벼슬을 하였으나 이괄의 난에 연루되어 고문을 받다가 죽었다. 시호는 충의(忠毅)이다. 건물은 앞면 3칸·옆면 2칸 규모로, 지붕은 옆에서 볼 때 사람 인(人)자 모양을 한 맞배지붕으로 꾸몄다.","a":"진주 충의사","c":"문화유산자료","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663953.jpg"},{"q":"이 책판은 임진왜란 때 승장으로 공을 세운 사명대사의 시와 글들을 모아 편집한 시문집이다. 사명대사가 세상을 떠나자 사명대사의 제자 혜구스님이 일부 간직하고 있던 시와 글을 ○○에 각인한 것이다. 이 책판의 권 1에는 사, 권 2에는 오언율시, 권 3에는 칠언율시, 권 4에는 오언절구, 권 5에는 사명대사가 선에 대해 말한 글귀를 모은 선게, 권 6에는 잡문과 시들이 실려있다. 뒤에는 부록으로 비문과 행적이 붙어있다. 이 책판은 사명대사의 사상연구 및 개인 전기의 귀중한 자료로 평가된다.","a":"밀양 표충사 사명집 목판","c":"시도유형문화유산","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642126.jpg"},{"q":"○○○○○ 동제는 마을 입구에 있는 당숲에 있는 느티나무를 신목으로 삼아 서낭제를 오층석탑과 삼층석탑에서 동제를 지내고 있는 마을 공동체의 민속신앙이다. 고려시대에 만든 것으로 추정되는 오층석탑은 풍수신앙과 탑 숭배 신앙이 함께 나타나고 있으며 음력 정월 초하룻밤에 동제를 지내고 있다.","a":"괴산 송덕리 동제장","c":"시도민속문화유산","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/2019041917011800.jpg"},{"q":"○○○○은 조선시대 문집 및 고지도에서도 확인되는 서울의 주요 경승지인 삼청동의 입구를 상징하는 지표이며, 중국의 설암 필법을 받아들인 한석봉 이후 우리나라 현판 대자의 전형을 보여주는 뛰어난 글씨로 문화유산자료 지정가치가 있다.","a":"삼청동문","c":"문화유산자료","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018102315323800.jpg"},{"q":"○○○ 대웅전 남쪽의 산 중턱에 자리하고 있는 탑으로, 2층 기단(基壇) 위에 3층의 탑신(塔身)을 올렸다. 아래층 기단에는 희미한 안상(眼象) 무늬가 보이고, 위층 기단에는 기둥 모양이 조각되어 있다. 탑신은 1층 몸돌에 비해 2층부터 급격히 줄어 들고 있으며, 각 층의 몸돌 모서리마다 기둥 모양의 조각을 두었다. 약한 경사가 흐르는 지붕돌은 네 귀퉁이에서의 치켜올림이 크지 않고, 밑면에 1층은 4단, 2·3층은 3단의 받침을 각각 두었다. 꼭대기에는 노반(露盤:머리장식받침돌), 복발(覆鉢:엎어놓은 그릇모양의 장식), 뒤집혀진 앙화(仰花:활짝 핀 연꽃모양 장식) 등…","a":"고운사삼층석탑","c":"문화유산자료","r":"경상북도","s":"의성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662387.jpg"},{"q":"대구 팔공산 기슭의 ○○○에 있는 불상으로 윗쪽이 뾰족한 삼각의 자연 암반 서쪽면과 남쪽면에 선으로 여래상과 보살상을 조각하였다. 서쪽면에 새겨진 높이 4m의 여래상은 연꽃이 새겨진 화려한 대좌(臺座) 위에 앉아있다. 얼굴은 네모나며, 눈은 가늘게 뜨고 있고, 입가에는 약간의 미소를 띠고 있다. 대좌의 높이에 비해 양 무릎이 넓게 표현되어 균형은 잡히지 않고 있으나 비교적 안정감을 보이고 있다. 신체는 복부아래에만 옷이 표현되어 있으며 비록 선으로 새겼지만 대좌의 정교한 수법이 주목된다. 높이 4.5m인 남쪽면의 보살상은 옷이 길게 흘러내려 양 무릎이 노출되지 않고…","a":"동화사염불암마애여래좌상및보살좌상","c":"시도유형문화유산","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636867.jpg"},{"q":"이 ○○○는 조선조 인조때의 명신인 荷潭 ○○○선생의 ○○○로 1670년(현종11년) 8월에 세워졌다. 이 비석의 비문은 당대의 명문장가인 조경(趙絅)이 忠翼公 金時讓의 아들인 김휘(金徽)의 요청으로 지었으며, 글씨와 전자(篆字)는 당대 최고의 서예가인 이정영(李正英)이 썼다. 전형적인 조선의 ○○○ 양식을 잘 갖추고 있는 이 비는 양질의 화강암과 웅장한 규모 그리고 명문장과 명서체 등으로 높이 평가 받고 있다. 방형대석과 비신, 가첨석을 갖춘 전형적인 ○○○를 최근에 난간석을 돌려 보호하고 있다. 모두 화강암으로 만들었으나 암질이 차이가 있다. 방형대석은 그 크기가…","a":"괴산 김시양 신도비","c":"문화유산자료","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660828.jpg"},{"q":"○○은 전동면 송성리에 위치하고 전체둘레 790m, 폭 2m, 높이 2∼5m이며, 성벽은 거의 무너져 있으나 남쪽 성벽만 원형을 보존하고 있다. 전설에 의하면 전의이씨(全義李氏) 시조인 이도가 성을 쌓고 살던 곳이라는 전설이 있어 ○○이라고 한다. 성내에서 백제 말기에 속하는 기와편들이 출토되고 있어 금○○과 함께 백제시대 조성된 산성으로 추정된다.","a":"이성","c":"시도기념물","r":"세종특별자치시","s":null,"i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2023050113232000.JPG"},{"q":"조선 정조가 명릉(숙종의 묘:현재 사적)을 참배하고 돌아오는 길에 할아버지인 영조의 옛 일을 회상하면서 친히 글을 짓고 세운 비이다. 네모난 받침돌 위에 비몸을 세우고, 옆면에서 볼때 지붕선이 여덞팔(八)자와 비슷한 팔작지붕을 모방한 지붕돌을 올리고 있다. 비문의 내용은 영조가 왕자인 연잉군으로 있을 때 부왕인 숙종의 탄신일을 맞아 명릉을 참배하고 돌아오는 길에 이곳 금암발참(黔巖撥站)에서 쉬게 되었다고 한다. 잠시 후 덕수천(창릉천)을 건너가는 소도둑을 잡았다는 말에 참장(站將)을 불러놓고 “필시 흉년에 춥고 배가 고파 도둑질을 했을 것이니 선처하라”는 명을 내린다…","a":"금암기적비","c":"시도유형문화유산","r":"서울특별시","s":"은평구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636124.jpg"},{"q":"현재 ○○○ 나한전(羅漢殿)에는 석가삼존불상(釋迦三尊佛像) 좌우로 각각 8구(軀)씩 16구(軀)의 나한전(羅漢像)과 제석상(帝釋像) 1구(軀), 사자상(使者像) 1구(軀), 인왕상(仁王像) 2구(軀) 등 총 20구(軀)의 상이 봉안되어 있다. 모두 소조상(塑造像)으로 현재는 화려한 채색이 되어 있는데 각 상은 47cm에서 53cm에 이르는 그리 크지 않은 아담한 규모이다. 16구의 나한(羅漢)은 향우측(向右側)에 제1(빈도라바라다바자), 3(가나가바라타자), 5(나쿠라), 7(카리카), 9(지바카), 11(라후라), 13(안가다), 15(아지타) 존자(尊者)가, 향좌…","a":"진관사 소 십육나한상","c":"시도유형문화유산","r":"서울특별시","s":"은평구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636350.jpg"},{"q":"○○○성은 진도군 군내면 녹진리에 있는 ○○○ 정상에서 동남쪽 500m 밑의 허리에 있는 작은 봉우리(67m)에 있는 성이다. 성의 둘레는 460m이며, 서쪽이 동쪽보다 높은 서고동저형(西高東低型)의 테뫼식 해협 ○○○으로 도랑을 판 흙과 막돌을 섞어 쌓고 외벽을 깎아 접근이 어렵도록 되어 있다. ○○○○○은 명량대첩의 역사현장이란 점에서 중요한 의미를 갖는다. 이 곳은 당시 전쟁에 이용했을 것으로 보이는 관방 유적이며, 성안에서 백제 와당이나 신라 토기를 수습한 점, 그리고 많은 성 가운데에서도 물목을 지키는 ○○○이라는 점에서 지리적으로 중요하여 보존하고 보호할…","a":"진도망금산관방성","c":"시도기념물","r":"전남광주통합특별시","s":"진도군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654362.jpg"},{"q":"(1) 책판의 크기 전체 길이 53cm, 너비 20cm, 두께 약 2cm이며, 마구리 길이는 28cm이다. 광곽(匡廓)의 가로는 34.5cm, 세로는 20cm이다. (2) 책판의 수량 서문 3매 6장, 1권 21매 39장, 2권 18매 35장, 3권 22매 42장, 4권 11매 22장, 5권 25매 49장, 6권 12매 24장, 7권 21매 39장 등 총계 133매 256장이다 (3) 책판의 저자 강대수(姜大遂 : 1591-1658). 자는 학안(學顔), 호는 한사(寒沙), 본관은 진양이며, 당암(戇庵) 강익문(姜翼文)의 아들이다. 합천 임북 (林北) 출신으로 내암(…","a":"한사집책판","c":"문화유산자료","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665753.jpg"},{"q":"○○○는 옛 선현의 자취를 살피어 후세에 전하고 그를 기리고자 세워두는 것으로, 이 비는 임진왜란 때의 의병장인 ○○○의 공적을 기리고 있다. ○○○는 호가 ○○○이며 선조 18년(1585) 34세의 나이에 별시에 뽑혔으나 지은 글이 왕의 뜻에 거슬린다 하여 무효가 되자, 일찌감치 과거에 나갈 뜻을 포기하였다. 그러던 중 임진왜란이 일어나 관군이 크게 패하자 의령 등지에서 의병을 일으켜 관군을 대신하여 적과 싸웠다. 그 공으로 유곡찰방에 임명된 후 여러 관직을 거쳤으나 곧 벼슬을 버리고 현풍으로 돌아갔다. 정유재란 때에는 밀양, 영산, ○○, 현풍의 네 고을에서 의병…","a":"창녕 망우당 곽재우 유허비","c":"문화유산자료","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663830.jpg"},{"q":"상주시내의 북천(北川) 북쪽 산 기슭에 자리하고 있는 비로, 임진왜란 때 종사관으로서 왜적과 맞서 싸우다 순절한 윤섬·이경류·박호와 이 지역출신으로 의병장이 되어 각종 전투를 벌이다 의롭게 생을 마친 김준신·김일의 충절을 기리고 있다. 이들은 임진왜란이 끝난 후에도 오랫동안 그 공적을 인정받지 못하다가, 영조 14년(1738) 이 지역의 사림들에 의해 김일을 제외한 4인을 위한 사당을 지어 제사를 드리게 되었으나, 이에 반대하는 의견이 생겨나 3년 후 다시 없애게 되었다. 정조 14년(1790)에야 다시 옛 사당터에 경절단(景節壇)이라는 제단을 짓고, 이들 4인과 더…","a":"충신의사단비","c":"시도기념물","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654629.jpg"},{"q":"○○○○○은 대좌와 광배가 없고 코가 약간 결손된 것 외에는 완전한 형태를 갖추고 있어 조선시대 불상을 연구하는데 좋은 자료이다. 그리고 불상의 양식으로 보았을 때, 신라ㆍ고려시대 석조불상의 전통을 이어 받았으며, 특히 입체의 화강암제 석조불상이 조성되는 예가 조선시대에는 극히 드문 상황이고, 완형의 조선시대 불상이다.","a":"동해사 석조여래입상","c":"문화유산자료","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663498.jpg"},{"q":"조선 중기의 문신인 장만(張晩, 1566~1629)의 본관은 인동(仁同)이고, 호는 낙서(洛西)이다. 1624년(인조 2)에 이괄(李适)의 난을 평정한 공으로 진무공신(振武功臣) 1등에 녹훈되었다. 장만의 초상화는 관복본과 유복본(儒服本) 2점이 전한다. 사모에 단령을 입고 의자에 앉은 장만의 <관복본 초상>은 진무공신에 녹훈될 때 충훈부에서 그려준 공신도상으로 추정된다. 장만의 일대기를 기록한 행장(行狀)에는 이괄(李适)의 난 때 병든 몸을 수레에 싣고 야전에서 지내다 한쪽 눈을 잃었다고 나온다. 얼굴에서 눈동자는 정면을 향했으나 코는 측면을 그렸고, 입은 좌우대칭…","a":"장만선생영정및공신록권","c":"시도유형문화유산","r":"경기도","s":"김포시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637630.jpg"},{"q":"돈대는 적의 움직임을 살피거나 공격에 대비하기 위해서 영토 내 접경지역 또는 해안지역의 감시가 쉬운 곳에 마련해 두는 초소이다. 대개 높은 평지에 쌓아두는데 밖은 성곽으로 높게 하고 안은 낮게 하여 포를 설치해 둔다. 이 돈대는 자연적인 지형을 이용하여 그 위에 작은 요새를 만든 것이다. ○○○○는 1679년(숙종 5)에 쌓은 48돈대 가운데 하나로 ‘긴○○○’라고도 불린다. 해안으로 돌출된 지형에 자리 잡아서 관측과 방어에 매우 유리한 조건을 갖췄다. 내부 지름이 31m인 원형 구조로 둘레가 128m, 석벽 높이 210㎝~350㎝이다. 40∼120㎝의 네모난 돌을…","a":"강화 장곶돈대","c":"시도기념물","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645579.jpg"},{"q":"구암(久菴) ○○○은 본관이 청주(淸州)이며, 실증적이며 고증학적인 방법으로 조선의 역사·지리를 연구해 『동국지리지(東國地理志)』, 『기전고(箕田考)』 등을 저술했다. ‘○○○ 묘’는 부인 함창 김씨(咸昌金氏) 합장(合葬) 단분(單墳)으로 조성되었다. 봉분 앞에 혼유석, 묘표, 석상이 놓여 있으며, 그 앞으로 망주석과 문인석이 건립되어 있다. 묘표는 원수방부(圓首方趺; 둥근 머릿돌과 사각 받침돌의 비석 형태) 형태다. 묘역 언덕 아래에 건립된 ‘○○○○○’는 1644년에 건립되었으며, 이수귀부(螭首龜趺; 용이 조각된 비석 머리와 거북 형태의 비석 받침) 형태이다. 이…","a":"구암한백겸묘및신도비","c":"시도기념물","r":"경기도","s":"여주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646905.jpg"},{"q":"고창 ○○○○은 관아에서 업무를 처리하던 중심 건물로 당시 현감이 집무하던 곳이다. 조선 명종 20년(1565)에 세웠으며, 한때 무장초등학교 교실로 사용하기도 하여 변형이 된 것을 1989년 원형으로 복원하였다. 앞면 6칸·옆면 4칸 규모이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕집으로 전체적으로 장중한 느낌을 주는 조선시대 건축물이다.","a":"고창무장동헌","c":"시도유형문화유산","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639416.jpg"},{"q":"1910년경 현 소유주의 아버지가 지었다고 전하는 집이지만 세운 시기를 정확하게 알 수는 없다. 이 집은 해변의 숲과 넓은 들판을 앞에 두고 낮은 산을 등진 곳에 자리잡고 있는 ㅁ자 평면을 갖춘 집이다. 안채는 앞면 4칸·옆면 2칸 규모로 부엌 왼쪽에 안방과 상방·사랑방을 두고 앞쪽으로 곳간과 마구간을 두었다. 사랑채에는 대청과 광, 방을 배치하였는데 앞쪽으로 대청과 연결되는 툇마루가 있어 방을 연결시키고 있다. 헛간채는 ㄱ자형 평면을 갖추고 있으며 곳간과 닭장으로 사용하고 있다.","a":"강릉박치규가옥","c":"문화유산자료","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660488.jpg"},{"q":"‘탑골동’또는 ‘절골동’이라 불리우는 ○○○ 산골짜기에는 이름이 알려지지 않은 자그만 절터가 하나 있다. 절터에서 조금 떨어진 산 기슭에 이르면 아담한 모습의 이 탑이 보이는데, 2층의 기단(基壇) 위에 3층의 탑신(塔身)을 올려놓은 모습이다. 아래층 기단은 네 면의 가운데와 모서리에 기둥모양을 본떠 새겼고, 위층기단은 모서리에만 조각을 해 두었다. 탑신부의 각층 몸돌을 덮고있는 지붕돌은 곡선을 이루는 낙수면과 수평을 유지하는 처마의 조화가 아름답다. 네 귀퉁이에서의 들어올림도 가벼우며, 밑면의 받침은 1층에서부터 5단·4단·3단으로 점차 줄어들고 있다. 꼭대기에는…","a":"정산남천리석탑","c":"시도유형문화유산","r":"충청남도","s":"청양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639097.jpg"},{"q":"유헌 정황(丁煌)의 후손들이 대대로 살아온 종가이다. 유헌 정황은 인종의 장례 때 예법을 준수할 것을 주장하다가 정미사화 때 거제도로 유배되어 일생을 마쳤다. 안채, 사랑채, 행랑채, 대문으로 구성되어 있으며 안채와 행랑채는 1854년 지었고 대문은 1927년에 지었다. 안마당을 중심으로 안채와 사랑채, 헛간채가 튼 ㄷ자형으로 배치되고 사랑채 옆에 행랑채가 경사지게 놓였다. 조선 후기와 일제시대에 걸쳐 지은 상류주택이며, 근처의 작은 종가인 정상윤 가옥과는 대조적이다. 같은 시기에 지었지만 정상윤 가옥이 크고 화려한데 비해, 이 집은 큰 종가이면서도 규모가 작고 소박…","a":"창원정씨종가","c":"시도민속문화유산","r":"전북특별자치도","s":"장수군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658334.jpg"},{"q":"◦ 진당산 서쪽 기슭 폐사지에 매몰 방치되었던 석탑을 1974년 발굴하여 현재의 위치에 이전하고 복원하였음. ◦ 화강암으로 되었으며, 높이는 350cm이고, 건립연대는 알 수 없음. 다면 이 탑은 체감율이 거의 없어 둔중한 느낌을 주고, 형식이 간략화되는 것 등으로 보아 고려시대의 양식으로 보임. ◦ 거칠게 다듬은 기단부에는 우주나 탱주의 모각(模刻)은 없고, 받침돌만 모각이 있으며, 탑신석에는 우주와 3단의 받침돌 모각이 있음. 맨 꼭대기 5층의 탑신석과 옥개석이 없어 현재는 4층만 남아있음.","a":"보령리오층석탑","c":"문화유산자료","r":"충청남도","s":"보령시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661123.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다. 정확히 지어진 연대는 알 수 없으나 연산군 5년(1499)에 향교를 없애고 중종 13년(1518)에 백련동에 향교를 지었다. 그러나 매년 제사 때마다 호랑이가 나타나서 숙종 30년(1704)에 봉성산 아래인 현 위치로 옮겼다. 1825년에 명륜당을 수리하였고, 그 뒤에도 여러 차례 수리가 있었다. 현재 남아있는 건물은 대성전 ·명륜당 ·동재 ·서재 ·동무·서무 ·외삼문 등이 있다. 경사지에 위치하고 있어서 앞쪽 낮은 곳에는 배움의 공간은 명륜당과 동재·서재가 있고, 뒤쪽 높…","a":"구례향교","c":"시도유형문화유산","r":"전남광주통합특별시","s":"구례군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639964.jpg"},{"q":"○○○○는 신라 제54대 경명왕(景明王)의 제8왕자인 월성대군(月城大君)의 자손으로 고려 후기에 두각을 나타내기 시작하여 조선 전기와 중기에 크게 융성하였다. 중시조인 박구(朴龜,1337∼1404)는 고려 중군사정부령(中軍司正副令)을 역임하였는데, 고려가 망하자 이 곳에 칩거하면서 자신을 감춘다하여 호를 ‘장아(藏我)’라 하고 뒷산을 장아산이라 하였다. 장아산(해발 73.6m)서쪽 구릉에 위치한 ○○○○○에는 현재 박구와 그의 후손인 박간(朴幹), 박휘(朴徽), 박신겸(朴信謙),박호겸(朴好謙), 박홍중(朴弘中) 등 11기의 묘가 남아 있다. 그 중 통훈대부 추산(秋山…","a":"월성박씨 종중 묘역","c":"시도기념물","r":"인천광역시","s":"남동구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2016030809514300.JPG"},{"q":"이 건물은 의성김씨 청송 입향조인 도곡공(道谷公) 김한경(金漢卿, 1456~1552)의 묘 아래에 세운 재사(齋舍)이다. 건립연대는 잘 알 수 없으나 18세기의 건축물로 추정된다. 김한경은 조선 세조(世祖) 2년(1456) 개성 풍덕에서 태어나 제용감정(濟用監正)에 올라 중종(中宗) 원년(1506) 정국공신(靖國功臣)에 녹훈되고 지중추부사에 제수되었다, 그 후 세상이 어지러워지자 청송 도동으로 옮겨와서 후학 양성에 평생을 바쳤다. 정면 5칸 측면 2칸의 겹처마 팔작지붕 건물로 넓은 마루를 중심으로 좌우 양측에 2칸의 온돌방이 배치되었다. 오른쪽 온돌방에는 사성재(思成…","a":"도리 추원당","c":"시도유형문화유산","r":"경상북도","s":"청송군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640862.jpg"},{"q":"이 영정은 ○○○○○선사의 좌안7분면 바닥가부좌상으로, 돗자리위에 방석을 깔고 왼손엔 불자를 쥐고, 오른손으로는 앞에 놓여진 서안위의 서책을 넘기려고 하고 있다. 화면은 녹색바탕에 운보문의 충진구도인 상단벽면과 돗자리의 이단구도로 이루어져 있다. 화면 향우측에는 양종도총섭○○○○○지진(兩宗都摠攝退隱堂等慧之眞) 화제가 있다. 화면크기는 가로 79.3cm, 세로 121.0cm이다.","a":"퇴은당 등혜 진영","c":"시도유형문화유산","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001643021.JPG"},{"q":"○○는 반구 모양이며 전체높이가 약 21.5㎝, 몸통 지름이 약 15.2㎝이다. 투조(透彫)된 덮개, 공 모양 몸통, 손잡이 2개, 다릿발 3개 등으로 이루어져 있다. 덮개는 4개의 다리와 4개의 손톱을 가진 용이 하늘로 올라가는 모양이며 꼭지가 용의 머리이다. 몸통 윗부분에는 3마리의 봉황이 보이고 아랫부분에는 소가 보이며 다른 부분에 보상화무늬도 새겨져 있다. ○○은 타원 모양이며 전체높이가 약 7.5㎝, 몸통 지름이 약 9.2㎝이다. 덮개, 몸통, 원통형 다리 등으로 이루어져 있는데, 몸통은 소박한 원통처럼 생겼고 봉황무늬와 보상화무늬가 새겨져 있다. 2009년…","a":"함양 하륜 부조묘 소장 향로 및 향합","c":"문화유산자료","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666587.jpg"},{"q":"『반야바라밀다심경』은 줄여서 ‘반야심경’이라고 부르는데, 여러 종파에서 공통적으로 읽고 외우는 보편적인 경전이다. 이 불경은 ○○○○이『반야바라밀다심경』을 구절마다 상세히 해설을 붙인 책으로 1책의 목판본이다. ○○○○은 당나라의 고승으로, 원성왕 7년(791) 선원을 창건하여 영산(靈山)이라 하였는데, 법을 전한 문인이 1,000명이나 되었으며 스스로 호를 ○○○○이라 하였다. 이 판본은 조선 태종 11년(1411)에 전북 고창 문수사에서 간행된 것으로서 조선 전기 불경연구 및 서지학 연구의 귀중한 자료로 평가된다.","a":"범어사 태전화상주심경","c":"시도유형문화유산","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636664.jpg"},{"q":"고려 말∼조선 초의 인물 ○○○의 무덤으로, 묘 및 상석(床石) 1기, 문인석 2기, 묘비 1기 등이 남아 있다. ○○○는 고려 1372년 출생하였으며 1410년에 종4품 선략장군으로 두모포(豆毛浦)의 관군을 배수받았고, 1419년에는 대마도 정벌에 참가하기도 하였다. 이후 부친의 병환을 돌보기 위해 낙향하였으며, 일흔 일곱인 1448년에 사망하였다. 전체 묘역은 3단으로 구성되어 있다. 상단에는 묘와 상석, 중단의 동·서에는 문인석, 그리고 하단의 동쪽에는 묘비가 배치되어 있다. 묘는 전형적인 조선 초기의 네모난 묘로, 묘의 앞쪽에는 상석이 놓여져 있는데 고석(鼓石…","a":"밀양 손유호 묘","c":"시도기념물","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657034.jpg"},{"q":"○○○는 신라 지증왕 때 연기조사가 ‘영악사’라는 이름으로 세웠고, 후에 도선국사가 ‘○○○’로 바꾸어 불렀다고 한다. ○○○은 신라 선덕여왕 때 자장율사가 지은 것으로 임진왜란 때 소실된 것을 숙종 6년(1680)에 새로 지었다. 앞면 3칸·옆면 2칸 규모로 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 기둥 위에만 있는 주심포 양식으로 꾸몄다. 건물 안쪽에는 아미타불을 모시고 있으며, 건물 앞면 좌우 칸의 창호와 벽체 그리고 난간 형태의 머름 등의 설치가 특이하다.","a":"사천 다솔사 극락전","c":"문화유산자료","r":"경상남도","s":"사천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664182.jpg"},{"q":"1925년 석곡리 미륵골의 옛 절터에서 출토되어 이곳에 옮겨 놓은 2구의 불상으로, 발견 당시는 머리 부분과 팔, 무릎 등이 손상을 입고 있었으나 지금은 복원하였다. 2구의 불상 모두 머리에는 작은 소라 모양의 머리칼을 붙여 놓았으며, 그 위로 상투 모양의 머리묶음이 뚜렷하다. 얼굴에는 인자한 웃음을 짓고 있고, 귀는 어깨에 닿을 정도로 길게 표현되었다. 왼쪽 어깨만을 감싼 옷은 어깨 위에 반달 모양의 옷자락이 표현되어 있는데 이는 신라 석불상에서 많이 보이는 독특한 수법이다. 오른쪽 불상은 손바닥을 편 채 왼손 위에 오른손을 포개고 두 엄지 손가락을 맞대고 있는 모…","a":"의령 중교리 석조여래좌상","c":"시도유형문화유산","r":"경상남도","s":"의령군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641337.jpg"},{"q":"○○○○입문(誡初心學入文), 묘법연화경 권제1(妙法蓮華經 卷第一) 등 10책 모두 370년이 넘은 고전적(古典籍)이며, 불교사의 희귀 자료이다. 2004년 성주사 안심료(安心寮)에 임시 봉안된 불상을 지장전 건립과 함께 이전하여 개금(改金) 및 개채(改彩)하면서 지장보살불의 복장유물을 확인한 결과 지장보살과 시왕을 비롯한 권속일체가 1681년 신조된 사실과 조성한 화원 및 시주자 명단이 열거되어 있으며, 당시 성주사의 명칭이 웅신사(熊神寺, 곰절) 임을 알 수 있다.","a":"계초심학인문","c":"시도유형문화유산","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018103117272700.JPG"},{"q":"전남 함평군 나산면에 자리잡은 이 가옥은 정유재란 때 순절한 이충인(1526∼1597)이 지었다고 한다. 지은 시기는 정확하게 알 수 없지만, 안채 건물에서 발견한 기록으로 미루어 17∼18세기에 지은 것으로 보인다. 원래 문간채, 행랑채, 사랑채 등을 고루 갖춘 짜임새 있는 양반집이었다고 하나 지금은 모두 없어지고 안채만 남아 있다. 안채는 앞면 7칸 규모의 一자형 평면구조를 이룬다. 기둥은 앞면과 오른쪽 부분에만 둥근기둥을 세우고, 그 외 나머지는 사각기둥을 세웠다. 집을 지으면서 심었다고 전하는 커다란 동백나무와 모과나무 한 그루가 현재 집 주위에 남아 있다.…","a":"함평이규행가옥","c":"문화유산자료","r":"전남광주통합특별시","s":"함평군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662120.jpg"},{"q":"영조 23년(1747년)에 이재< 李縡 >가 쓴 비로써 현재 비각안에 보호되어 있다. ○○○○은 송시열< 宋時烈 >이 정읍에서 사약을 받은 후, 그 무고함이 밝혀져 숙종 21년(1695년) 사액< 賜額 >이 내려 세워졌으나, 고종 8년(1871년) 철거되었다. 그 유허에 비를 세웠는데 높이 195㎝, 너비 78㎝, 두께 19㎝이다.","a":"고암서원묘정비","c":"문화유산자료","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661696.jpg"},{"q":"조선 현종 2년(1661)에 왕이 내린 교지로서, 김집(金集,1574∼1656) 선생을 효종 종묘에 모시도록 명하는 문서이다. 김집은 조선 중기의 유학자로, 광해군 2년(1610)에 헌릉참봉에 임명되었으나, 광해군의 문란한 정치를 반대하여 나아가지 않았다. 그뒤 동부승지, 우부승지, 공조와 예조의 참판, 대사헌 등의 벼슬을 지냈으며, 효종 때에는 왕과 함께 북벌을 계획하기도 했다. 이이의 학문과 김장생의 예학을 이어받아 이를 송시열에게 전해주어 기호학파를 형성하였으며, 이황을 이어받은 영남학파와 함께 조선 유학계의 쌍벽을 이루었다. 그가 죽은 후 문묘와 효종묘에 함께…","a":"김집교지","c":"문화유산자료","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661363.jpg"},{"q":"임진왜란 때 젊은 나이로 전사한 배인길(1571∼1592)과 그 소식을 듣고 자결한 그의 부인인 월성 이씨의 충열을 기리기 위해 나라에서 내린 한 쌍의 정려문이다. 배인길은 어려서부터 학문과 무예를 익혔으며 22세 때 임진왜란이 일어나자 당시 예안 현감인 신지제의 휘하에 들어가 용궁전투에 참전했는데 전투 중 전사하였다. 정려(旌閭)란 나라에서 충신·효자·열녀를 표창하여 그들이 살던 마을에 세워 주던 문으로 배인길은 충신으로서, 그의 부인은 열녀로서 하사 받은 것이다. 보통 충효열이 따로 지정된 것이 일반적이나 이처럼 두 사람을 함께 인정하여 세운 ○○○는 특이한 예가…","a":"쌍절려","c":"문화유산자료","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663265.jpg"},{"q":"이 돌비석은 ○○○의 경계를 표시하기 위해 세운 장생(長生 혹은 長牲)으로서 ‘장승’이라고도 한다. 장생은 수호신, 이정표, 경계표 등의 역할을 하며, 풍수지리설과 함께 민속신앙과도 깊은 관계를 맺고 있다. 이 장생은 경계 표시로서의 성격이 강하다. ‘○○○’이라고 한 것은 국가의 명에 의해 건립된 장생이라는 뜻이다. ○○○의 장생표는 7기였으나 1085년(선종 2) ○○○에서 호부에 보고하여 12기를 다시 세웠으며, 그 땅이 사방 둘레가 47,000보 가량이라고 전한다. 현재까지 ○○군 상남면 ○○○와 양산 하북면 백록리에 위치한 ○○○○○ 2기가 남아있다. ○○○…","a":"울주 상천리 통도사 국장생 석표","c":"시도유형문화유산","r":"울산광역시","s":"울주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637246.jpg"},{"q":"김종직의 학문과 덕행을 기리고 지방민의 유학교육을 위하여 지은 서원으로 조선 명종 22년(1567)에 짓고 위패를 모셨다. 임진왜란으로 불탄 것을 선조 39년(1606)에 다시 지었다. 인조 12년(1634)에는 이름을 ○○○○으로 바꾸고, 박한주와 신계성을 더하여 모셨다. 숙종 6년(1680)에 지금의 위치로 옮겨지었다. 현종 11년(1670)에는 사액을 받아, 나라에서 공인과 경제적 지원을 받았다. 고종(재위 1863∼1907) 때 서원철폐령으로 헐리었다가 고종 11년(1874)에 강당을 짓고 예림재라 하였으며, 다시 ○○○○으로 복구하여 오늘에 이르고 있다. 건…","a":"밀양 예림서원","c":"시도유형문화유산","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641514.jpg"},{"q":"안채와 사랑채 2동으로 이루어진 집인데 본래 상태를 유지하고 있는 것은 안채이다. 안채는 ㄱ자형 평면을 갖추고 있으며 대청을 중심으로 왼쪽에 건넌방 2칸, 오른쪽에 안방과 부엌을 직각으로 배치하였다. 건넌방 앞에서 대청까지 툇마루를 설치하였고 안방의 바깥쪽으로도 툇마루를 두었다. 사랑채는 一자형 평면을 갖추고 있으며 대문을 중심으로 왼쪽에 광을, 오른쪽에는 사랑방 2칸을 두었다. 그 오른쪽에 세운 별채는 외양간과 디딜방앗간으로 구성되었으나 방앗간은 현재 헛간으로 사용하고 있다. 처음 지은 시기를 알 수 없지만 기와에 남아 있는 기록으로 지금 있는 집은 1941년에 세…","a":"평창지동봉가옥","c":"문화유산자료","r":"강원특별자치도","s":"평창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660471.jpg"},{"q":"이 ○○○는 조선 말기 용계(龍溪) ○○○의 덕을 기리기 위해 개국(開國) 539년, 즉 1930년에 설치한 비이다. 비문은 부제학(副提學) 정만조(鄭萬朝)가 짓고 판돈영(判敦寧) 윤용구(尹用求)가 썼으며 ○○ 서문은 윤명학(尹命學)이 지었다. 건립연대가 얼마 안되었으나 비석 건립연호를 개국(開國)으로 사용한 것이 매우 특이한 사례이다. 후대에 각자(刻字)한 것으로 추정되나 현재로서는 확인할 수 없다. 비의 규모는 높이 155㎝, 폭 60㎝의 오석이다. 1932년에 건립한 ○○은 8.68㎡ 규모로 전면 1칸, 측면 1칸으로 목조기둥에 팔작지붕의 기와집으로 대체로 원형…","a":"보은 김진묵 송덕비 및 비각","c":"문화유산자료","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660785.jpg"},{"q":"이 불화는 1907년 월초거연(月初巨淵)이 화주(化主), 강재희(姜在喜)가 대시주가 되어 대황제폐하 성수만세(聖壽萬歲), 황태자전하 경수천세(慶壽千歲), 황태자비전하윤씨 보령천추(寶齡千秋), 황귀비전하엄씨 보수제년(寶壽齊年), 의친왕전하 보수무강(寶壽無疆), 의친왕비전하 보록장춘(寶籙長春), 영친왕전하 보소여해(寶笑如海) 등을 기원하며 제작 봉안한 ○○○이다. 편수(片手) 보암긍법(普庵肯法)과 두흠, 금어 범화정운, 운호재오, 행언이 함께 그렸으며 규격이 가로 248.3cm에 세로 150.8cm로, 대부분의 ○○○와 달리 가로로 긴 화폭이며, ○○○로서는 매우 큰 규…","a":"수국사 현왕도","c":"시도유형문화유산","r":"서울특별시","s":"은평구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636438.jpg"},{"q":"고려 후기 충숙왕 때의 문신인 충목공 ○○○ 선생의 묘소이다. ○○○은 1243년(고종 30년) 출생했으며, 고려 원종 때 문과에 급제하였고 1309년(충렬왕 34) 전라도안찰사를 거쳐, 밀직사사에 올라 지공거(知貢擧)가 되어 여러 인물을 선발하는 일을 맡았다. 충숙왕 초에는 가락군에 봉해지고 충숙왕 8년(1321)에 수첨의찬성사를 거쳐 정승에 올랐다. 묘는 도굴된 상태로 방치되었다가 1985년 후손 허관구(許官九)에 의해 세상에 알려졌다. 1988년 6월 묘지 발굴 당시 고려청자 잔 여러 조각, 고려 토기조각 수십 점, 얇은 청동 조각 여러 점, 나무관에 사용한 쇠…","a":"허유전 묘","c":"시도기념물","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645597.jpg"},{"q":"19세기 후반 불화의 특징을 잘 보여주는 작품으로 군도(群圖)형식의 ○○○○○에서는 드물게 시왕 각각에 명칭 및 <수생경(壽生經)>에 의한 간지를 적어놓아 정확한 시왕의 명칭을 알 수 있다는 점에서 매우 중요한 자료이다.","a":"사자암 지장시왕도","c":"시도유형문화유산","r":"서울특별시","s":"동작구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018102317324600.jpg"},{"q":"현재 ○○○ 법당에 봉안되어 있는 돌로 만든 삼존불좌상으로 삼존불 가운데 본존상은 좌우의 두 상에 비해 약간 큰 편이다. 중앙에 있는 본존불은 원래는 얼굴이 동그랗고 온화한 모습의 불안(佛顔)이었던 것으로 보이나, 지금은 마멸이 심하여 이목구비를 잘 알아볼 수 없다. 목과 백호가 새겨진 부분도 손상되어 후보(後補)된 상태이다. 대의는 어깨를 드러내는 편단우견식으로 입었고 어깨와 무릎에는 넓은 띠주름이 새겨져 있다. 오른손은 올려 수인을 결하고 있다. 향우측의 협시상은 머리 위에 원통형 보관을 쓰고 두 손으로 화염보주같은 지물을 들고 있으며 양 어깨 위에는 넓은 옷주름…","a":"도선사 석 삼존불상","c":"시도유형문화유산","r":"서울특별시","s":"노원구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636479.jpg"},{"q":"○○○ 안에서 군사가 주둔하던 중군영(中軍營)의 문이었으나 광복 이후 8·15해방을 기리는 뜻으로 ○○○라 불렀다. ○○○는 원래 ○○○의 북문인 공북루 옆에 있던 것을 현 위치로 옮기고 웅심각이라 불렀는데, 1946년에 백범 김구와 성재 이시영이 이곳에 와서 나라를 다시 찾았다는 뜻을 기리고자 고쳐 부르게 되었다고 한다. 앞면 3칸·옆면 2칸 규모의 2층 누각으로 모든 면이 개방되어 있으며, 왼쪽에는 오르내릴 수 있도록 층계를 만들어 두었다. 지붕은 옆에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 꾸몄다.","a":"공산성광복루","c":"문화유산자료","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660948.jpg"},{"q":"높이 1.8m로 용인시 원삼면 ○○○ 마을 안에 위치한 석불상이다. 큼직한 육계(肉髻; 상투 모양으로 솟은 붓다의 정수리, 지혜를 상징)에 둥근 얼굴과 어깨에는 양감이 살아 있고, 두꺼운 법의의 묵직한 표현 등은 경기도 지역에서는 흔치 않은 고려 시대 이전의 옛 불상 양식을 보여주는 사례이다. 머리에는 넓은 육계가 있으며 마모가 심해 얼굴은 알아보기 어렵고, 목의 삼도도 명확하지 않다. 법의(法衣; 불교의 승려가 입는 옷)는 양 어깨에 걸쳐져 목에서 ‘Y’자형 옷깃을 표현하고, 어깨에서 굵은 주름, 가슴에서 U자형의 옷 주름을 형성하고 있다. 오른손은 손바닥을 밖으로…","a":"용인목신리석조여래입상","c":"문화유산자료","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660052.jpg"},{"q":"경상북도 의성군 단북면 정안리에 있는 불상으로, 커다란 신체에 비해 어딘지 모르게 탄력이 없어 보이고 어색한 자세를 취하고 있다. 네모진 얼굴과 평면적인 신체는 형식적인 모습이 보여 고려시대 불상의 특징을 잘 나타내고 있다. 양 어깨를 감싼 옷은 몸에 밀착되어 물결무늬의 주름을 그리면서 아래로 흘려 내리고 있다. U자형으로 넓게 터진 상체의 옷깃 안에는 띠를 맨 속옷이 표현되어 있고, 불상 앞에는 대좌(臺座)로 쓰였던 돌이 놓여 있다. 오른손이 없어지고 약간의 손상이 있으나 통일신라 후기의 불상 양식을 잘 나타낸 뛰어난 작품이다.","a":"의성정안동석조여래입상","c":"시도유형문화유산","r":"경상북도","s":"의성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640627.jpg"},{"q":"조선 숙종 35년(1709) 정월에 제작된 제주도 지도와 그 서문(序文)이다. 지도는 도면 전체를 3단으로 나누어 상단과 하단에는 제주도의 지리적 상황을 기록하고 가운데에는 지도를 그려 놓았다. 지도는 본토 쪽에서 제주도를 바라보는 것을 가정하여 그린 것으로, 제주도의 남쪽이 지도의 상부가 되어있다. 주요한 오름은 거의 표기하였는데 산 모양의 그림으로 오름의 이름을 대신하고 있으며 포구도 자세하게 기록하고 있다. 주변의 바다를 파도 무늬로 표현하였는데 이러한 바다의 표현법은 조선시대 전기의 표현법을 이은 것이다. 서문은 간략하면서도 정확하게 정리되어 있는데, 이를 통…","a":"탐라지도및지도병서","c":"시도유형문화유산","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643287.jpg"},{"q":"○○○는 조선 명종 3년(1548) 하서 김인후가 처향(妻鄕)인 순창의 점암촌에 이거하고, 초당을 세워 훈몽이라는 편액을 걸고 강학했던 곳이다. 김인후가 ○○○에 머물렀던 시기는 1548년부터 그가 부친상을 당하여 장성으로 돌아간 1549년까지 약 2년간이다. 이후, 1680년경 김인후의 5대 손인 김시서가 인근에 자연당을 짓고 기거하며 ○○○를 중건하여 후학을 양성하였으나, 다시 퇴락하였다. 1820년경 김인후의 후손들이 점암마을에 ○○○를 중건하고, 어암서원을 건립하여 김인후, 김시서, 정철, 이이의 위패를 봉안하였으나, 대원군의 서원철폐령에 의하여 훼철되었다.…","a":"훈몽재 유지","c":"문화유산자료","r":"전북특별자치도","s":"순창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661894.jpg"},{"q":"○○○ 성보박물관에 소장되어 있는 신중탱화로서 견본채색(絹本彩色)이며, 제석천(帝釋天)과 동진보살(童眞菩薩)을 동자상(童子像)과 신중상(神衆像)이 둘러싸고 있는 모습이다. 1792년에 조성된 불화이다. 「건륭오십칠년임자팔월신중회화성우○○○봉안우원적산금봉암.....(乾隆五十七年壬子八月神衆會畵成于通度寺奉安于圓寂山金鳳庵.....)」의 화기(畵記)가 있다.","a":"양산 통도사 건륭57년명 신중도","c":"시도유형문화유산","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642339.jpg"},{"q":"우석목·무석목·벅수머리 등으로 불리우는 이 석상은 제주목·정의현· 대정현의 성문 입구에 세워졌던 것이나, 현재는 제주도민속자연사박물관· 제주대학·제주시청·제주국제공항· 삼성혈·관덕정 등에 산재하여 있으며 제주시내에 21기, 성읍에 12기, 대정의 인성·안성·보성에 12기 도합 45기가 있다. 석상의 형태는 대체로 벙거지형 모자, 부리부리한 왕방울 눈, 큼지막한 주먹코, 꼭다문 입술 두손은 배위 아래로 위엄있게 얹은 모습을 하고 있다. ○○○○의 크기는 평균 신장이 제주 187Cm, 성읍 141Cm, 대정 134Cm 이며 제작 연대는 영조 30년(1754) 경으로 추정…","a":"돌하르방","c":"시도민속문화유산","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659171.jpg"},{"q":"해미면 ○○○ 유적은 해미천을 따라 바닷물과 민물이 만나는 지점으로 선사문화가 형성되기 좋은 조건을 갖춘 곳이다. 1970년에 국립중앙박물관에서 4차례의 발굴조사를 실시하여 수혈주거지 11기, 부석유구(敷石遺構) 1개소, 석총 1기, 야외노지 1기의 유적이 확인되었다. 부석유구에서 신석기시대 빗살무늬토기편 이 수습되었고, 무문토기는 바리토기·사발·잔·목항아리가, 석기로는 화살촉·돌검·돌끌·숫돌·반달돌칼·돌도끼, 가락바퀴 등이 수습되었다. 유적은 발굴조사결과 BC 8세기경에 조성된 신석기·청동기시대 유적으로 특히 청동기시대 중기의 문화양상을 살펴볼 수 있는 좋은 자료이…","a":"서산휴암리선사유적지","c":"시도기념물","r":"충청남도","s":"서산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653189.jpg"},{"q":"전남 장흥군 유치면 봉덕리에 위치한 ○○○의 ○○○○ 속에 들어있던 유물 중 하나이다. 『○○○○○』은 ○○○○바라밀경을 풀어 쓴 경전이다. ○○○○바라밀경은 줄여서 ‘금강경’이라고 부르기도 하며 우리나라에서는 반야심경 다음으로 많이 읽힌 책이다. 이 책은 본래 고려대장경에 속해 있었는데, 이 판본만 별도로 조선 전기에 간행한 것으로 보인다. 조선시대에 간행한 것에 대한 기록은 따로 남아 있지 않지만, 원판은 1236년 해인사대장경을 만들기 위해 설치한 기구인 대장도감에서 만들었다는 기록이 남아 있다.","a":"보림사사천왕상복장금강반야론","c":"시도유형문화유산","r":"전남광주통합특별시","s":"장흥군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2020022813485400.jpg"},{"q":"○○○○○은 시조인 동래부원군 정난종鄭蘭宗의 위패를 봉안한 사당이 있는 종갓집이다. 조선 전기의 문신인 정난종의 아들 정광보鄭光輔가 아버지 무덤을 만들 때 지은 건물로 알려져 있다. 이 ○○은 중앙에 ㄱ자로 안채를 배치하고, 주변으로 큰사랑채와 작은사랑채를 두었으며, 남쪽으로 곳간인 광채를 배치하였다. 북쪽으로 신주를 모시는 사당이 있고, 남쪽 바깥쪽으로는 마굿간인 마방채를 두었다. 사람의 생활공간을 중심에 두고 주변에 제례를 준비하거나, 손님의 이동을 맞이하는 공간을 배치하여 종갓집의 기능성이 엿보인다. ○○○○○의 안채는 상량문에 의하면 정조 7년(1783)에 세…","a":"군포 동래정씨 동래군파 종택","c":"문화유산자료","r":"경기도","s":"군포시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660152.jpg"},{"q":"임진왜란 때 승병으로서 나라를 구하는데 큰 공을 세운 서산대사·사명대사·기허당 3대사의 충열을 기리기 위해 세운 서원이다. 원래는 사당이었던 것을 조선 헌종 5년(1839) 지금의 위치인 영정사 안으로 옮겨 ○○○○이라 이름짓고 절의 이름 또한 표충사로 고쳤다. 고종 8년(1871) 대원군의 서원철폐령으로 없어졌다가, 1927년 절을 다시 지을 때 ○○○○ 건물도 함께 복원하였다. 그러나 일부 승려들이 절 안에는 서원이 있을 수 없으며 부처님과 3대사의 영정이 함께 있는 것은 더욱 안되는 일이라며 반대하였다. 결국 1971년에 ○○○○을 절의 서쪽에 위치한 팔상전으로…","a":"밀양 표충서원","c":"시도유형문화유산","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641457.jpg"},{"q":"경상북도 청도군 청도읍 ○○○○○문 양쪽에서 서 있는 ○○○상이다. 절을 지키고 있는 이 ○○○상은 몇 조각의 나무를 이어서 만들었는데 높이가 3.4m∼3.8m로 상당히 큰 편에 속한다. ○○○이란 수미산(須彌山) 중턱에 살면서 동서남북을 지키고, 불법을 수호하는 신을 가리킨다. 각각 비파·칼·탑·여의주 등 가지고 있는데, 들고 있는 물건이 다를 뿐 다른 표현 방법은 비슷하다. 발로 악귀를 밟고 있지만 얼굴은 험상궂거나 분노하는 표정이 아니고, 오히려 웃음까지 짓고 있는 해학적인 모습이다. 이런 모습은 조선 후기 ○○○상에서 흔히 보이는 특징이다. ○○○상 속에서 나…","a":"적천사목조사천왕의좌상","c":"시도유형문화유산","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640579.jpg"},{"q":"○○○○○는 임진왜란 의병장인 이달(李達) 장군의 묘하에 건립한 재실이다. 1880년(고종 7)에 중건된 목조와가(木造瓦家) 건물이며 1940년에 한차례의 보수가 있었다. 정사는 철마산의 남사면부 끝자락에 남향하여 자리잡고 있는데 장좌천의 상류부이다. 강당과 대문채가 서로 마주 보고 있으며 대문의 남동쪽에는 고직사가 있다. 정사는 정면 4칸, 측면 1.5칸의 홑처마 팔작지붕이다. 평면은 좌측부터 툇마루가 딸린 온돌방 2칸, 마루 1칸, 툇마루가 딸린 온돌방 1칸으로 구성되어 있다. 공포양식은 장여수장집이며 상부가구는 도리가 세 개인 3량가이다. 대문채는 3면 3칸 규…","a":"고성 철산정사","c":"문화유산자료","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665507.jpg"},{"q":"수지면 신덕마을 뒤 ○○○ 입구에서 약 6㎞ 정도 올라가면 산 정상이 있고 정상에 있는 묘를 좌측으로 하고 내려서면 높이 5m 내외의 거대한 암벽이 자리하고 있다. 암벽의 하단 약 2.5m 지점에 새겨진 이 마애불은 현재 무릎 이하 부분이 결실되어 정확한 규모는 알 수 없으나 연화좌대를 포함한 불상의 높이는 3.2m, 어깨폭 78㎝, 두부길이 58㎝에 이르는 대형의 ○○○○○이다. 비만형의 얼굴에 장대한 신체는 건장한 체구를 이루고 있으며 눈은 좌우로 치켜 올라간 듯하고 두툼한 코, 꽉 다문 입 등 전체적으로 경직된 표정을 짓고 있다. 민머리 위에는 상투 모양의 육계…","a":"견두산마애여래입상","c":"시도유형문화유산","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639748.jpg"},{"q":"○○○는 운차산 기슭에 있는 절로 지은 시기는 정확히 알 수 없고, 다만 통일신라 진성여왕(재위 887∼896)대에 최치원이 지었다고 전하고 있다. 임진왜란으로 대부분의 건물이 불탔으나 ○○○만은 칡뿌리 등이 건물을 감싸고 있어 화를 면하였다고 하여 당시에는 갈천사로 불렀다고 한다. 현재는 ○○○과 요사채만 남아 있다. ○○○은 고종 7년(1870)에 고쳐 세웠는데 규모는 앞면 3칸·옆면 2칸이며, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 새 날개 모양인 익공 양식으로 꾸몄다. 창호는 가운데 칸에는 4…","a":"서동사대웅전","c":"문화유산자료","r":"전남광주통합특별시","s":"해남군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662164.jpg"},{"q":"이 작품은 1687년(숙종 13)에 석각(石刻)으로 제작된 ○○○○○를 기본으로 하여 하늘의 별자리를 종이에 필사한 천문도로, 하늘의 모양(별자리)을 차례대로 나눈 그림이란 뜻이다. 화면 제일 위 상단에는 구획하여 향우측에서 향좌측으로 행서체로 ‘天象列次分野地圖’라 썼으며, 그 아래로 천문도와 명문이 기록되어 있다. 이 천문도의 정확한 제작 경위는 알 수 없으나, 천문역법을 익히기 위해 음양과(陰陽科) 출신의 집안에서 교재용으로 만들었을 가능성과 관상감(觀象監, 조선시대 천문역법을 관장하던 기관) 내부에서 포폄고과(褒貶考課)를 위해 잘 알아볼 수 있게 만들었을 개연성…","a":"천상열차분야지도","c":"시도유형문화유산","r":"부산광역시","s":"남구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2327377.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 무덤방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려놓은 탁자식과, 땅속에 무덤방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 제주시 도련동에 있는 이 고인돌은 바둑판식으로 덮개돌 크기는 길이 2.22m, 너비 2.05m이며 모양은 타원형에 가깝다. 받침돌은 없어졌지만 덮개돌 한쪽이 들려 있고, 제주도 고인돌의 유형인 아치 모양으로 된 것으로 보아 원래는 있었을…","a":"도련지석묘2호","c":"시도기념물","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657660.jpg"},{"q":"부도는 승려의 무덤을 상징하여 그 유골이나 사리를 모셔두는 곳이다. 이 부도는 국태민안(國泰民安)을 비는 사찰인 전국의 3안국(지리안국, 서산안국, 금산안국) 중 지리산의 안국사에 있는 것으로, 명당의 혈(血)에 해당하는 곳에 자리잡고 있어 더욱 중요성을 띤다. 전체적으로 8각을 기본형태로 하고 있으며, 아래·가운데·위의 3단을 이루는 기단(基壇) 위에 탑신(塔身)을 올리고 머리장식을 얹은 모습이다. 아래받침돌에는 복련(覆蓮:엎어놓은 연꽃무늬)을 두르고 윗받침돌에는 이와 대칭되는 앙련(仰蓮:솟은 연꽃무늬)을 장식하였다. 가운데받침돌에는 ‘은광대화상’이라 새겨 주인공을…","a":"함양 안국사은광대화상 승탑","c":"시도유형문화유산","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642277.jpg"},{"q":"무안면 가례리 ○○○○에 보관되어 있는 ○○○로 재단법인 화쟁교원(이사장:김용대)에서 수집한 33종 52권인데 목록은 다음과 같다. 1. 대장일람(大藏一覽) 10권 2책 = 明홍무 13년(1380년) 2. 사기영선(史記英選) 3권 = 세종 2년(1527년) 3. 팔양신주경(八陽經) 1권 = 건융 56년(1791년) 4. 도서(都序) 1권 = 강희 20년(1681년) 5. 불설아미타경(佛說阿彌陀經) 1권 = 선조 39년(1605년) 6. 송운집(松雲集) 1권 = 만력 3년(1574년) 7. 호법론(護法論) 1권 = 순치 5년(1648년) 8. 범망경(梵網經) 1권 =…","a":"밀양영산정사고불서","c":"시도유형문화유산","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642294.jpg"},{"q":"조선 중기의 무신 ○○○ 장군의 묘이다. 1587년(선조 20)에 남해안에 출몰한 왜구를 토벌하는 데에 큰 공을 세웠다. 이후 왜구가 다시 흥양에 침입하자 출병하여 손죽도 해상에서 적과 싸우다 전사하였다. 묘역은 그의 부인인 경주 김씨(慶州金氏)·용인 이씨(龍仁李氏)와 함께 매장된 삼분(三墳 ; 봉분이 3개인 무덤)의 형태이다. 그 중 장군의 봉분은 중앙에 있는데, 시신을 수습하지 못하여 옷으로 대신하였다고 전한다. 묘표(墓表; 무덤 주인공의 이름 등을 새긴 비석)는 원수방부형(圓首方趺形; 둥근 머릿돌과 사각 받침돌의 비석 형태)이며, 후대에 세워진 것이다. 묘역 입…","a":"이대원장군묘및신도비","c":"시도기념물","r":"경기도","s":"평택시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646111.jpg"},{"q":"오포대는 목포시 유달산 입구의 이충무공 동상 남서쪽에 있다. 예전에 오포는 포탄 없이 화약만 넣고 포를 쏘아, 시민들에게 정오가 되었음을 알려주는 기능을 하였다. 처음의 포는 조선식 선입포로 현종 10년(1669)에 제작되었는데, 경기도 광주에서 가져온 것이라고 한다. 1913년 일본식 대포를 구입하여 새로 배치하였으며, 그전의 대포는 송도신사에 보관하던 중 일제시대 후기에 오포대의 대포와 함께 일본정부가 가져갔다고 한다. 당시의 오포대는 현재의 유달산공원의 전망대로 사용되고 있으며, 오포는 주변에 모형을 만들어 전시하고 있다.","a":"목포오포대","c":"문화유산자료","r":"전남광주통합특별시","s":"목포시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662091.jpg"},{"q":"세계적으로 최고의 역사성을 가진 여성 전문직 용품으로 ○○ 해녀들의 천연자연 환경 적응에 대한 과학적, 실용적, 창의적인 작업기능을 가진 ○○○○○ 15점에 대하여 민속지식이 잘 응축되어 있고 해산물 채취에 대한 지혜의 소산으로서 문화유산적 가치가 높이 평가되고 있음.","a":"제주 해녀의 물옷과 물질도구","c":"시도민속문화유산","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659292.jpg"},{"q":"이 ○○은 금강산에 대한 상세한 지리 표현과 화려한 색채효과로 그림지도 역할과 함께 장식화로서 제작된 지본담채의 12폭 ○○이다. 현재 전하는 ○○○○는 대부분 조선 중엽 이후 것으로 대체로 정통화법채, 민화채, 판화채의 세 종류로 나누는데, 이 그림은 민화채를 많이 원용하고 있으면서 청록산수화의 심원한 멋을 보여준다. <동국세시기>에 의하면 단오 때 금강산 일만이천봉을 부채에 그리는 풍습이 있었다 하는데, 이는 정초에 세화가 유행했듯이 단오 때는 단오화로서 유행했던 것이다. 또한 죽기 전에 한번은 금강산에 가 보아야 지옥에 가지 않는다는 민간신앙에서 금강산도가 민화…","a":"금강전도 12첩 병풍","c":"시도유형문화유산","r":"부산광역시","s":"서구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636717.jpg"},{"q":"들판 한 가운데 서 있는 탑으로, 탑이 속했던 절의 구체적인 역사는 전하고 있지 않다. 탑은 1층 기단(基壇) 위에 탑신부(塔身部)를 세우고 머리장식을 갖춘 모습이다. 기단은 각 면의 모서리마다 기둥조각을 가지런히 새겨 넣었다. 탑신부는 몸돌과 지붕돌이 각 한돌로 이루어졌으며 위로 오를수록 크기가 알맞게 줄고 있어 안정감을 준다. 두꺼워 보이는 지붕돌은 밑면에 4단씩의 받침을 두었고, 처마는 네 귀퉁이에서 약간 치켜 올라갔다. 꼭대기에는 머리장식으로 보이는 파손된 석재가 놓여있다. 기단이 1층인 점과 가운데기둥조각이 생략된 점, 두꺼운 지붕돌, 4단의 지붕돌받침 등으…","a":"신안읍리삼층석탑","c":"시도유형문화유산","r":"전남광주통합특별시","s":"신안군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2016082917531100.JPG"},{"q":"이 집은 독립운동가로서 해방 후 초대 국회의장을 역임한 해공 ○○○ 선생(1894 ～1956)이 국회의장직에서 물러난 1954년 8월부터 1956년 5월 5일 민주당 대통령 후보 자격으로 호남 지역 유세를 위해 전주로 내려가던 중 갑자기 세상을 떠나기까지 약 1년 9개월 여 거주한 곳이다. ‘ㄱ'자형 안채와 사랑채 2동으로 구성 된이 집은 집장수들이 조선시대 양반가의 집을 모방하여 1930년대에 지은 도시형 한옥으로 겹처마 팔작지붕 오량가(五樑架) 집이다. 겹처마이면서도 처마를 짧게 내어 채광을 고려하고, 굴도리를 사용하였으며, 건물 규모에 비해 단면이 과대한 대들보…","a":"해공신익희가옥","c":"시도기념물","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2018102309485700.JPG"},{"q":"강학공간인 ○○○와 그 곳에 소장되어 있는 41건의 ○○○이다. ○○○는 강명재라로도 불리는데, 원래는 1628년에 밀양김씨 운계 김홍발이 노동에 정착하면서 건립의 계기가 마련되었다고 볼 수 있지만 당시 건조물의 연혁에 대해서는 문헌 자료가 자세하지 않다. 그 뒤 18세기 후반에 강학공간 등 공동체 공간으로 활용되었다. 현재의 건물은 1843년에 지어진 것으로 1936년에는 노동사를 지었고, 1982년에 새로이 고쳐 지어졌다. 고반(考槃)의 의미는〈시경(詩經)〉위풍편(衛風篇)의 '산골짜기 시냇가에 움막을 이룩하니 어진 은자의 마음은 넓도다.'라는 구절에서 따온 것이라…","a":"영암고반재및소장고문서일괄","c":"문화유산자료","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662266.jpg"},{"q":"이 영정은 ○○○○○선사의 좌안7분면 바닥가부좌상이다. 화면은 주색 상단벽면과 돗자리의 이단구도이며, ○○선사는 왼손엔 주장자를 오른손엔 염주를 쥐고 돗자리위에 가부좌하고 있다. 화면 향좌측에 ‘○○○대사○○지진(秋波堂大師芝沾之眞)’의 화제가 있고 향우측엔 영찬이 있다. 이 영찬의 기록에서 1887년에 조성되었음을 확인할 수 있다. 화면크기는 가로 76.6cm, 세로 103.7cm이며 바탕은 1폭의 면본으로 이루어져 있다.","a":"추파당 지첨 진영","c":"시도유형문화유산","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001643030.JPG"},{"q":"《○○○○○》는 1443년(세종 25)에 서장관(書狀官)으로 일본에 다녀온 신숙주(申叔舟 : 1417~1475)가 1471년(성종 2) 왕명을 받아 그가 직접 관찰한 일본의 정치·외교관계·사회·풍속·지리 등을 종합적으로 정리, 기록한 책으로 15세기의 한일관계와 일본 사회 연구에 귀중한 자료이다. 이와 같은 사료적 가치 때문에 1933년 조선사편수회에서 영인 간행하였고, 1974년에도 민족문화추진회(오늘날 한국고전번역원)에서 《해행총재(海行摠載)》를 간행하면서 ○○○○○를 영인 수록하였다. 현재 국내에서 공개되어 전하는《○○○○○》의 간본으로는 5장 분량의 초주갑인자…","a":"해동제국기","c":"시도유형문화유산","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636546.jpg"},{"q":"○○○의 출입통로로 이용되고 있는 ○○○는 성의 남문에 해당되며, 조선시대에는 삼남의 관문이었다. 원래 토성(土城)이었던 것을 석축성(石築城)으로 고쳐 세운 것은 조선 전기의 일이다. ○○○도 그 때 세운 것으로 알려졌는데, 그 뒤에도 여러 차례 고친 것으로 보인다. 지금 있는 건물은 1971년에 전부 해체하여 원래대로 복원한 것이다. 앞면 3칸·옆면 2칸 규모로, 지붕은 옆에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 새 날개 모양으로 장식한 익공 양식으로 꾸몄다.","a":"공산성진남루","c":"문화유산자료","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660942.jpg"},{"q":"풀과 나무의 모습을 채색하여 그린 4폭 병풍으로, 각 그림의 크기는 가로 65.5㎝, 세로 222.5㎝ 이다. 원래는 8폭이었을 것으로 추정된다. 각 폭에는 오동나무, 단풍나무, 매화, 모란 등 각기 다른 초목을 한 종류씩 그려 놓았는데, 오동나무를 제외하면, 각 폭마다 짙은 묵으로 그린 기이한 모습의 돌이 함께 표현되어 있다. 어떤 폭은 푸른색의 바위와 붉은 꽃을 그려 색깔의 대비를 보여주기도 한다. 이러한 표현은 조선 후기인 19세기 궁중 가리개 등의 유물에서도 찾아볼 수 있다. 단원 김홍도(1745∼?)의 그림으로 정조가 용주사 창건시 하사하였다고 전하고 있으나…","a":"용주사병풍","c":"시도유형문화유산","r":"경기도","s":"화성시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637361.jpg"},{"q":"○○의 주인공은 ○○○○ 거제 현령 하계지(河繼支)의 아내이며, 지평 운수당 하윤(河潤)의 어머니입니다. ○○는 조선 중기에 축조된 것으로 비문의 찬자는 강백진(康伯珍, 1449-1504)입니다. 좌대와 비신과 가첨석이 하나의 돌로 되어 있는 것이 특징이며, 부인의 ○○로서는 유례가 드물게 그 크기가 크고 원형이 비교적 잘 보존되어 있습니다. ○○○ 또한 희귀한 형태를 띠고 있으므로 ○○와 ○○○을 경상남도 유형문화유산으로 지정하고자 합니다.","a":"진주 가봉리 숙부인 상산박씨 묘비 및 석인상","c":"시도유형문화유산","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2023063021402100.JPG"},{"q":"이 석상은 현재 ○○○ 문수전에 봉안되어 있으며, 일명 문수보살상으로 알려져 있다. 규모는 높이 167㎝, 머리높이 53㎝, 머리폭 27㎝, 신체폭 55㎝ 정도이다. 「○○○사적기」에 의하면 신라 승려 자장율사가 당나라에 건너가 청량산에서 기도를 거듭한 끝에 문수보살의 계를 깨닫고 돌아와 우연히 이 곳을 지나다 보니 산세가 당나라의 청량산과 비슷하여 굴속에 들어가 7일 기도를 하자 문수보살이 나타나서 이곳에 문수도량을 개설하였다고 한다. 석상은 돌로 만든 대좌 위에 세워져 있으나 무릎 이하 부분이 절단되었다. 얼굴은 긴 타원형으로, 승려 모양의 머리에 귀가 큼직하게…","a":"문수사석조승상","c":"문화유산자료","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661865.jpg"},{"q":"향로란 절에서 마음의 때를 씻어준다는 의미를 가진 향을 피우는데 사용하는 도구를 말한다. 이 향로의 전체 높이는 110㎝이고 몸체 높이 80㎝, 뚜껑 높이 30㎝, 다리 높이 25㎝이다. 조선시대에 만들어진 것으로 추정되며, 뚜껑 중앙부에 사자가 웅크리고 앉은 모양을 만들어 붙였다. 이 사자상이 꼭지 겸 손잡이이며, 옆구리에도 사자 머리 모양의 손잡이를 만들어 붙였다. 표면에는 덩굴 무늬와 모란꽃 무늬를 은상감 하였으며, 그 원형이 잘 보존되어 있다.","a":"청동은입인동문향로","c":"시도유형문화유산","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639468.jpg"},{"q":"수명장수와 현세의 복을 구하기 위해 그려지는 ○○○는 산왕(山王)으로 신앙되던 호랑이를 의인화하여 묘사한 불화이다. 불교가 민간신앙과 결합하면서 토착화하는 과정에서 산신에 대한 신앙이 유행하면서 사찰의 산신각, 산왕각, 삼성각 등에 봉안되었다. 이 ○○○는 화기에 의하면 1901년(광무5년)에 환옹후진(幻翁嗅眞)이 증명(證明)을 맡고, 수경당승호(繍瓊堂承琥)가 수화사(首畵師)로 예운당상규(禮芸堂尙奎), 창오(昌旿), 상근(尙根), 영욱(靈昱), 긍엽(亘葉)등이 제작에 참여한 작품으로 칠성도, 독성도 등과 함께 봉안된 것이다. 화면에는 깊은 산과 골짜기를 배경으로 노인…","a":"지장암 산신도","c":"시도유형문화유산","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636489.jpg"},{"q":"율곡 이이의 위패를 모시고 제사지내는 곳으로 조선 인조 8년(1630) 이이의 학문과 덕행을 추모하기 위해 학산리에 석천서원을 처음 짓고 위패를 모셨다. 효종 3년(1652)에 지금의 위치로 옮겼는데, 현종 1년(1660)에는 ‘송담’이라고 쓴 현판을 임금으로부터 하사받고 옛 선현들에 대한 제사와 지방의 교육을 담당하여 왔다. 영조 32년(1756)에는 묘정비를 세워 서원의 사적과 이이의 업적을 기록하였다. 고종 5년(1868) 대원군의 서원철폐령으로 인하여 서원이 없어졌다가 1904년 지방 유지들의 모금으로 다시 지어졌다. 서원의 안에는 위패를 모신 사당인 송담사,…","a":"송담서원","c":"시도유형문화유산","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637963.jpg"},{"q":"경상북도 안동시 미질동에서 발견된 것으로 ○○○에 있었던 것인데, 안동댐 건설로 인해 ○○○가 없어지면서 인근의 봉정사로 옮겨 보관하고 있다. 금가루가 칠해져 있어 자칫 금동불상으로 오해를 받기도 하지만 석불이다. 머리에는 상투 모양의 머리묶음이 있고 얼굴은 둥근 편이다. 옷은 양 어깨에 걸쳐 입고 있으며, 가슴부분에 표현된 나비 리본 모양의 매듭이 인상적이다. 손은 오른손을 무릎 위에 올리고 손가락이 아래로 향한 모습으로 땅속의 악귀를 물리친다는 의미를 지닌다. 불상이 앉아있는 대좌(臺座)는 반원형으로 연꽃무늬가 새겨져 있다.","a":"안정사석조여래좌상","c":"시도유형문화유산","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640305.jpg"},{"q":"길쭉한 몸체에 타원형의 굽을 붙인 장군이다. 몸체를 세로로 백토분장(白土粉粧)한 후 양쪽에 두 줄의 선문대(線文帶)를 둘렀으며 한 쪽은 안굽의 형태로 처리하고 다른 쪽은 이중동심원(二重同心圓)을 그렸다. 몸체의 양면에 ○○○○○을 좌우 대칭으로 배치하고 안굽으로 처리한 면의 반대편에는 간략한 철화당초문(鐵畵唐草文)을 배치하였다. 무광택의 유약(釉藥)이 시유(施釉)되었다. 빙렬(氷裂)은 거의 없다. 굽은 밖으로 벌어진 다리굽으로 굽다리바닥의 유약을 훑어내고 모래를 받친 흔적이 희미하게 남아 있다. 유약(釉藥)이 잘 녹지를 않아 그릇면(器面)이 뿌연 느낌을 주고 있으나…","a":"분청사기철화모란문장군","c":"시도유형문화유산","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2593087.jpg"},{"q":"이곳은 신말주 선생과 정부인 설씨를 비롯하여 ○○○ 선생 등 그의 후손들이 살았던 곳으로, 1996년부터 복원사업을 추진하고 있으며 세거지 좌측에는 보물 ○○○○권선문첩(勸善文帖)을 비롯한 여러점의 문화유산 보호각이 위치하고 있으며 보호각 뒤쪽에는 귀래정(歸來亭)과 수백년 된 노송들이 서 있다.","a":"설씨부인, 신경준선생유지(귀래정신말주후손세거지)","c":"시도기념물","r":"전북특별자치도","s":"순창군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653629.jpg"},{"q":"◦ 보령읍성은 1400년까지 처음에는 현 위치의 1km 남쪽 구성재 부근에 있다가 옮겨져서 서쪽 2km지점의 봉당성에 있었음. 국방 강화 차원에서 읍성의 신축이 이루어지던 때인 1430년(세종12)에 순찰사 최윤덕이 현재의 위치에 터를 잡고, 서산군수 박눌생, 보령현감 박효성 등이 힘을 합하여 완성한 석성(石城)임. ◦ 1431년 부임한 현감 정대(鄭帶)가 이듬해부터 객관(客館)을 비롯 성내 140칸의 건물을 완성하였음. ◦ 성의 둘레는 약630m에 달하고, 높이 약3.5m, 적대 8개소, 성문 3개소, 옹성 2개소, 여장 412타, 성내 우물 3개소, 해자 약 60…","a":"보령성곽","c":"문화유산자료","r":"충청남도","s":"보령시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661134.jpg"},{"q":"○○○는 안동김씨와 아주신씨 두 문중에서 함께 한 재사에서 하나의 산에 위치한 조상의 묘소를 수호하고 묘제를 올리고 있다는 점에서 민속적으로 독특한 사례이다. 16세기 초⋅중엽에 창건된 후, 현재에 이르기까지의 중수와 이건의 과정이 편액된 현판의 내용을 통해 자세하게 파악되며, 강당은 위치에 따른 위계의 표현하기 위하여 원기둥과 네모기둥을 구분하여 사용하고 있고 기둥 위치에 따라 장식적인 익공과 낮은 위계의 민도리 구조를 구분하여 사용하고 있어서 건축계획적인 의도를 분명히 확인할 수 있다. 또한 평면형식, 보머리 가공 형식, 외기도리의 충량과 고미반자를 위한 직각보의…","a":"예천 직산재","c":"시도민속문화유산","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/2018101612081700.JPG"},{"q":"조선시대 중종 때의 거유 남명 조식선생께서 30년간 강학하던 곳으로 조선 선조 21년(1588년) 향인들의 청에 의해 ○○부사 양사준이 정자의 동쪽에 서원으로 착공했으나 왜란으로 중지된 것을 광해군 원년(1609년) 안희, 허경윤에 의해 준공되어 신산 서원이라고 하였으며, 순조 23년(1823년) 송윤증 등이 중건하였다. 대원군의 훼철령 으로 철거되었다가 해방 후 다시 중수한 것이 지금 건물인데 팔작지붕의 목조건물로 정면 5칸, 측면 2칸이다. 사당영역이 없이 강학공간만으로 이루어진 서원형식을 가지고 있다. ※ 안내문 이곳 ○○○은 관리인이 상주하지 않고 있으며, 문…","a":"김해 산해정","c":"문화유산자료","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664119.jpg"},{"q":"조선 세조와 성종간의 문신인 ○○○ 선생의 묘역이다. ○○○은 1455년(세조 1)에 좌익공신에 올랐다. 봉분은 부인 청주 정씨(淸州鄭氏)와 합장한 하나의 봉분이고 둘레석은 현대의 것이다. 봉분의 정면 오른쪽에 묘표가 2기 있는데, 1기는 ○○○, 다른 1기는 청주 정씨의 묘표이다. 청주 정씨의 묘표는 하엽수방부형(荷葉首方趺形; 뒤집은 연잎을 장식한 머릿돌과 사각 받침돌의 비석 형태)으로 연엽의 조각이 깊고 명확한 15세기 후반의 대표적인 형식이다. ○○○ 묘표는 원수방부형(圓首方趺形; 둥근 머릿돌과 사각 받침돌의 비석 형태)으로 16세기 전반기의 형태이다. 문석인은…","a":"정창손묘역석물","c":"문화유산자료","r":"경기도","s":"양평군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660128.jpg"},{"q":"\"정침은 인종(1545년) 때부터 ○○읍 거촌리에 세거한 晩翠堂 邊永淳(1523~)의 4대손 通德郞 邊洙(1631~1698)가 1653년에 건립한 후 1854년에 중수하고 그 뒤 1984년에는 신응수 대목장이 중건하였다. 사당은 만취당 변영순의 3대손 邊有藩(1605~1671)이 숭조 정신을 함양 계승하기 위하여 1653년에 건립한 후 1930년경 일부 수리가 있었으나, 전체적으로는 원래 모습이 잘 남아 있다. 정자(○○○)는 만취당의 6대손 睡穩堂 邊尙勳(1678~1737)이 1713년에 후학교육과 후진양성을 목적으로 서당을 겸한 정자 건물로 건립하였으며, 1898…","a":"봉화 수온당 고택","c":"문화유산자료","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663773.jpg"},{"q":"임진왜란(1592) 때 의병장이었던 삼괴 ○○○ 장군의 뜻을 기리기 위하여 세운 ○○○ 및 ○○지이다. ○○○은 선조 23년(1590) 신립 장군의 부장이 되고, 이듬해 사헌부 감찰이 되었으나 곧 사직하고 고향으로 돌아왔다. 임진왜란이 일어나자 의병 2,000명을 모아 관군과 합세하여 ○○○에서 1만여 명의 왜적과 싸워 김천방면으로 물리쳤다. 그러나 곧 금산방면에서 공격해 온 왜군의 협공을 받아 사촌동생 호현과 함께 전사하였다. 장군의 높은 뜻과 애국충정을 기리기 위하여 이곳에 1978년 사당을 건립했다.","a":"영동 추풍령 전적 및 장지현 순절비","c":"시도기념물","r":"충청북도","s":"영동군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650321.jpg"},{"q":"○○○ 대웅전 앞마당에 동서로 나란히 서 있는 2기의 석탑이다. 두 탑 모두 기단(基壇)을 1층으로 두어 전체의 무게를 버티도록 하고, 그 위로 3층의 탑신(塔身)을 올린 모습이다. 기단과 탑신부의 각 몸돌은 4면마다 기둥을 본떠 새겼는데, 기단은 면의 모서리와 가운데에 조각을 두고 몸돌은 모서리에만 새겼다. 각 층의 지붕돌은 밑면에 4단씩의 받침을 마련하였고, 윗면은 얇고 평평하며, 처마는 네 귀퉁이가 위를 향한 채 부드러운 곡선을 그리고 있다. 두 탑의 규모나 양식이 거의 같은데, 전체적인 조각수법이나 지붕돌 등의 모습으로 보아 고려시대 중기에 동시에 세웠던 것으…","a":"향림사삼층석탑","c":"시도유형문화유산","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639977.jpg"},{"q":"비슬산 중턱의 옛 절터에 남아 있는 탑이다. 높은 벼랑 끝에 서 있는 이 탑은 2층 기단(基壇) 위에 3층의 탑신(塔身)을 올린 모습으로, 절내의 여러 석재들과 더불어 쓰러져 있던 것을, 1988년에 겨우 복원한 것이다. 일반적인 탑과 달리 절벽의 높은 바위를 바닥돌 삼아 그 위로 기단과 탑신을 올려놓았다. 기단과 탑신의 몸돌에는 모서리마다 기둥모양의 조각을 둔 것 외에는 거의 꾸밈을 하지 않아 소박하다. 만들어진 시기는 절의 창건과 때를 같이하는 9세기 통일신라시대로 추측된다. 오랜 세월 무너져 있었으면서도 당당함을 잃지 않고 오히려 주변 산세를 다스리고 있는 듯한…","a":"대견사지 삼층석탑","c":"시도유형문화유산","r":"대구광역시","s":"달성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636921.jpg"},{"q":"○○○○○은 ○○○ 난골마을 구릉에 1기, 경작지의 논두렁에 1기가 있으며, 서로 300m 간격으로 떨어져 있다. 덮개돌은 화강암으로 땅 위에 비스듬히 놓여 있는데 논두렁에 있는 것은 크기가 길이 210㎝, 너비 210㎝, 두께 90㎝정도이며 받침돌은 보이지 않는다. 구릉에 있는 것은 길이 180㎝, 너비 150㎝, 두께 90㎝정도이며, 받침돌로 추정되는 돌들이 덮개돌 아래에 깔려 있다. 내부 구조는 학술조사를 실시하지 않아 자세히 알 수 없다. 이 ○○○○○은 청동기시대 ○○○ 일대의 정치·사회·문화 등을 연구할 수 있는 중요한 자료가 된다.","a":"창평동지석묘군","c":"시도기념물","r":"울산광역시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645903.jpg"},{"q":"○○군 여항면 주동리, 내곡리 일원에 위치한 ○○○○○는 ○○의 진산인 여항산 동쪽에 마주한 ○○, 일명 봉화산(해발 675.5m) 정상부에 위치해 있다. 조선 전기에 축조되어 후기까지 경상도 방면의 직봉(直烽) 2로 중 간봉(間烽) 2로로서 기능을 수행하였으며, 진해의 가을포봉수를 받아 의령의 가막산봉수에 연결되었다. 함주지에 의하면 연대 1, 연굴 5, 화덕 1, 망덕 1개의 봉수시설이 있었다고 기록하고 있으나 현재 연대1, 건물터 2곳만 확인되고 있다.","a":"함안 파산 봉수대","c":"시도기념물","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656782.jpg"},{"q":"○○○○○에서 소장하고 있는 고서 12책 및 고문서 1책이다. 이들 고서 및 고문서는 어정규장전운(御定奎章全韻) 동활자본 1책, 신증동국여지승람(新增東國輿地勝覽) 목판복각본 1책, 삼경사서정문(三經四書正文) 목판복각본 1책, 송운대사분충서난록(松雲大師奮忠서難錄) 목판본 1책, 천지명양수륙재의찬요(天地冥陽水陸齋儀纂要) 목판본 1책, 법집별행록절요병입사기(法集別行錄節要幷入私記) 목판본 1책, 관세음보살대비심다라니경(觀世音菩薩大悲心陀羅尼經) 목판본 1책, 대장일람경(大藏一覽經) 목판본 1책, 대장일람집(大藏一覽集) 목판본 2권 1책, 중각현행경(重刻現行經) 목판본 1책,…","a":"양산 성전암 문적","c":"문화유산자료","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664866.jpg"},{"q":"장산리 마을 맨 위쪽에 자리잡은 옛집으로, 조선 선조 36년(1603)에 처음 지었으며 순조 25년(1825)에 수리를 하였다고 한다. 집은 크게 안채와 사랑채, 사당으로 구성되어 있다. 안채는 앞면 5칸·옆면 2칸 규모의 ㄷ자형 집이다. 왼쪽부터 부엌·골방·큰방·대청·작은방을 배치하였다. 사랑채는 ‘망인당(望仁堂)’이라고 하며, 앞면 4칸·옆면 2칸 규모이고 앞에 퇴칸이 있는 집이다. 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이고, 누의 형식을 갖추고 있다. 앞면에는 난간을 설치하였으며, 누 아래에는 둥근기둥을 세웠다. 전체적으로 집의 높이가 낮으며 짜…","a":"담양김선기가옥","c":"문화유산자료","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662174.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 뚜껑돌을 덮고 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 거창 ○○○ 구릉지대에 3기의 고인돌이 있다. 이 가운데 제일 남쪽에 있는 것은 탁자식으로 덮개돌의 크기는 길이 2.86m, 너비 2.50m이다. 북쪽으로 약 5m 지점에 있는 것은 현재 덮개돌만 땅 위에 드러나 있는데 탁자…","a":"거창내오리지석묘","c":"시도기념물","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655101.jpg"},{"q":"○○○의 사적을 기록한 비로, 대웅전 동쪽 약 30m 위치에 건립되어 있다. 비는 화강암 석재로 만들어졌으며, 비좌․비신․개석을 갖춘 형식이다. 비문에는 ‘신라 원효(元曉) 스님이 창건하고 도선국사(道詵國師)가 중건하여 관음사(觀音寺)라고 개칭하였고, 고려 태조(太祖)가 중수하여 ○○○라고 하였다’는 기록이 있다. 여말선초(麗末鮮初)에는 나옹(懶翁)ㆍ무학(無學) 등의 고승이 오래 머물면서 선풍(禪風)을 드날렸다. 조선 태조(太祖) 때 왕명으로 비가 중수된 사실이 기록되어 있다. 비문의 뒷면 음기에는 시주자의 명단이 새겨져 있다. ○○○의 개석은 팔작지붕형이고 지대석(…","a":"삼막사사적비","c":"시도유형문화유산","r":"경기도","s":"안양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637582.jpg"},{"q":"지은 시기를 정확하게 알 수 없으나, 전하는 말에 따르면 약 70년 전에 지은 것으로 추정한다. 건물 구조는 안채, 곳간채, 대문채 등으로 구성되어 있다. 안채는 앞면 4칸·옆면 3칸 규모로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양의 팔작지붕이며 ㄱ자형 평면을 갖추었다. 곳간채는 앞면 3칸·옆면 1칸 규모에 一자형 평면을 이루고 있다. 대문채는 앞면 6칸·옆면 1칸 규모이며, 지붕은 옆면에서 볼 때 사람 인(人)자 모양을 한 맞배지붕으로 꾸몄다.","a":"산청대포리민씨고가","c":"문화유산자료","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664219.jpg"},{"q":"세종25년(世宗;1443) 전라도 화암사(花岩寺)에서 찍은 목판본으로 당대의 명필인 성달생(成達生)*이 쓴 것이다. 시주(施主)에 이녕대군(李寧大君), 영흥대군(永興大君) 등이 동참했으며, 사육신 중 한사람인 성삼문(成三問)이 감찰(監察)로 등장한다. 이와 동일한 판본으로 전남 영광군 군남면 용암리 월명산 890번지 소재 연흥사(烟興寺) 소장(所藏) 『○○○○○』이 전라남도 유형문화유산 175호로 지정되어 있으며 이 책은 화암사판의 번각본(飜刻本:한 번 새긴 책판을 본보기로 삼아 그 내용을 다시 새긴 책)으로 보인다.","a":"묘법연화경 권4~7","c":"시도유형문화유산","r":"충청북도","s":"단양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638876.jpg"},{"q":"전북특별자치도 무주군 적상면 ○○○에 있는 사고를 보관한 곳으로 사고(史庫)는 조선 왕조의 역사에 관한 기록이나 중요한 서적을 보관하던 곳을 말한다. 임진왜란(1592) 때 서울의 춘추관을 비롯한 전국의 사고가 불에 탄 후, 정족산·태백산·오대산 등 5곳에 새로운 사고를 설치하였다. 그러나 이중 묘향산 사고가 북방 후금의 위협으로 관리가 어렵게 되자 광해군 6년(1614)에 천연 요새인 ○○○에 실록을 옮겨 보존하였다. 인조 19년(1641)에는 선원각을 세우고 왕실의 족보인 『선원록』을 소장하면서 완전한 사고의 역할을 하게되었다. 총 5,515책이 보관되어 있었으나…","a":"적상산 사고지 유구","c":"시도기념물","r":"전북특별자치도","s":"무주군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653635.jpg"},{"q":"○○○○○는 'ㄷ' 자형 건물로서 평면 구성은 전·후면의 특징을 살려 정면 날개에는 온돌방(齋)을 드리고 후면에는 누마루와 대청(중앙 3칸)을 두는 등 양면성이 건물 평면에 잘 드러나 있다. 조선후기에 건립하여 사우의 강당과 마을 서당 재실로 활용한 건조물이다.","a":"강진 효정재","c":"시도민속문화유산","r":"전남광주통합특별시","s":"강진군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658437.jpg"},{"q":"경상북도 경주시 배동 ○○○○에 있는 높이 10m가량 되는 바위에 새겨진 앉아 있는 모습의 여래상이다. 이곳은 신라 아달라왕, 신덕왕, 경명왕의 큰 무덤이 있어서 ○○○○이라고 불리는 곳이다. 서쪽을 향하고 있는 불상은 몸은 모두 선으로 그은 듯이 새기고 얼굴만 도드라지게 표현한 독특한 조각수법을 보이고 있다. 이 불상은 고려시대에 새긴 것으로 추정되며 이런 유형의 불상을 연구하는데 중요한 위치를 차지하고 있다.","a":"삼릉계곡선각여래좌상","c":"시도유형문화유산","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640595.jpg"},{"q":"원동면 ○○○ 화제초등학교 교사 뒤쪽 낮은 구릉상의 민묘가 있는 지역 일대가 양산 ○○○○○이다. 양산 ○○○○○에서는 녹청자 가마와 도편(陶片)이 확인되었다. 채집된 도편은 모래 등 잡물이 섞인 거친 태토를 사용하여 만들었다. 또한 철분 함량에 따라 녹색, 갈색, 회색 등이 발색되었는데, 표면은 고르지 못하다. 양산 ○○○○○에서 수습된 녹청자편은 인천시 북구 경서동, 전라남도 해남군 산이면 진산리 가마에서 발견된 녹청자와 비슷한 특징이 있다. 발견된 도편은 거의 대부분 문양이 없으며, 주로 대접류와 접시류가 채집되었다. 일반적으로 녹청자는 해무리굽청자와 함께 고려…","a":"양산화제리도요지","c":"시도기념물","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656494.jpg"},{"q":"배를 타고 들어오는 외적의 침입을 막기 위해 제주도에서는 해안선을 따라가며 성을 쌓았는데 이를 ○○○○이라 한다. 현재 성벽이 남아있는 곳으로는 온평리, 행원리, 한동리, 동복리, 북촌리, 애월리, 고내리 등 14곳이 있다. 김상헌이 지은 『남사록』에는 ○○○○을 일러 ‘탐라의 만리장성’이라 부르고 있다. 현재 남아 있는 북촌 ○○○○ 성벽의 길이는 약 250m이다.","a":"북촌환해장성","c":"시도기념물","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657913.jpg"},{"q":"민족 금융기관이었던 ○○○○의 본점 건물이다. 충청남도 서북지역의 교통 및 상업 중심지에 자리한 ○○○○은 조선총독부가 들어선 후 더욱 더 심해진 일본의 금융압박 속에서도 민간자본을 형성하는데 큰 역할을 하였던 민족계 지방은행이다. 2층의 서양식 건물로, 중후한 멋과 비례감이 잘 조화를 이루고 있다. 1, 2층의 창문을 하나로 연결하여 근대적인 감각을 살렸으며, 출입구 부분을 돌출시켜 그 위의 지붕을 곡선으로 처리하는 등 앞면을 강조하였다. 1913년 지역의 민간유지들에 의해 건립된 이 건물은 작은 규모이면서도 당당한 외관을 갖추고 있다.","a":"예산호서은행본점","c":"시도기념물","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652793.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. 원래 있던 자리와 처음 지은 연대는 알 수 없으나, 조선 전기에 세운 것으로 보이며, 태종 17년(1417) 지금 있는 자리로 옮긴 것으로 전한다. 건물 배치는 앞에 교육 공간을 두고 뒤에 제사 공간을 배치한 전학후묘의 형식을 따르고 있다. 정문인 외삼문을 지나면 안마당에 교육 공간인 명륜당과 학생들의 기숙사인 동재·서재가 있고, 뒤쪽 높은 곳에 중국과 우리나라 성현의 위패를 모시고 제사를 지내는 대성전을 두었다. 조선시대에는 나라에서 토지와 노비·책 등을 지원받아 학생…","a":"상주 함창향교","c":"시도유형문화유산","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641286.jpg"},{"q":"○○○ 극락보전에 모셔져 있는데, 구체적인 기록이 없어 만든 때와 만든 이는 알 수 없다. 단지 ○○○의 다른 현판에 ‘1745년(영조21)에 없어진 절을 다시 세우면서 ○○○라 하였다’고 기록되어 있는데, 이때 불상도 함께 만든 것으로 보인다. 불상은 신체에 비해 머리가 큰 편으로 얼굴을 앞으로 약간 내민 구부정한 자세에 근엄한 표정을 짓고 앉아 있다. 네모진 얼굴과 신체, 지나치게 두꺼워 몸의 양감이 드러나지 않는 옷자락 표현 등, 조선 후기 불상의 특징을 따랐다. 머리칼은 날카로운 나발(螺髮. 소라 껍데기처럼 꼬불꼬불 틀어 말린 머리카락)이며 살상투(肉髻.인도…","a":"쌍계사목조여래좌상","c":"시도유형문화유산","r":"경기도","s":"안산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637744.jpg"},{"q":"태봉산 남쪽의 언덕에 위치한 무덤들이다. 원래는 100여기 이상의 무덤이 있었던 것으로 보이나, 개간과 도굴로 대부분 파헤쳐져 지금은 능선을 따라 2∼3기만 확인할 수 있다. 봉분의 규모는 외형상 대형이 지름 25∼30m·높이 6∼8m이며, 중형은 지름 15∼20m·높이 4∼5m, 소형은 지름 10m 내외, 높이 3m 정도이다. 내부는 돌로 돌방(석실)을 만들고 천장을 좁혀 뚜껑돌을 덮고, 입구와 통로가 있는 앞트기식돌방무덤(횡구식석실분)이라 생각된다. 아직 조사가 없어 정확한 연대나 성격은 밝혀지지 않았지만, 가야 무덤에 대한 연구 뿐만 아니라 가야사의 실체 해명에…","a":"산청 생초고분군","c":"시도기념물","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654743.jpg"},{"q":"○○ 정씨의 3대 가족무덤이다. 고려 충숙왕 때 숭정대부 의정부 찬성사를 지낸 정신중의 부부 합장무덤과 조선 전기 대유학자이며 문장가인 문정공 정이오 부부의 무덤, 그리고 조선 전기에 우의정을 지내고 단종을 위해 순절한 충장공 부부의 무덤이다.","a":"진주 상대동 고분군","c":"시도기념물","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655935.jpg"},{"q":"좌측에는 윤제형가옥이 있고 우측에는 윤승구가옥이 위치하고 있으며 ‘ㄱ’자 형의 안채와 ‘ㄴ’자형의 문간채가 함께 튼 ‘ㅁ’자형의 배치를 하고 있으며 안채는 안채마루 종도리는 광무 5년(1901년) 상량한 것으로 기록되어 있음. 안채의 부엌공간이 현대식으로 개조되고 부분적인 구조도 원래의 모습에서 변형된 부분이 있으나 전체적으로는 20세기 초창양식을 유지하고 있음","a":"아산 박우현가옥","c":"문화유산자료","r":"충청남도","s":"아산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2019052217361400.JPG"},{"q":"2층 기단(基壇) 위에 3층의 탑신(塔身)을 올린 석탑이다. 아래층 기단은 밑부분이 땅 속에 묻혀있어 자세한 구조를 알 수 없고, 탑신은 몸돌 모서리마다 기둥 모양을 새겨 놓았다. 3층에는 머리장식의 네모난 받침돌이 몸돌 대신 끼워져 있고, 각 층의 지붕돌 밑면에는 4단의 받침을 두었다. 꼭대기에는 복발(覆鉢:엎어놓은 그릇모양의 장식)이 놓여 머리장식을 하고 있다. 소박한 모습의 탑으로, 통일신라시대에 세운 것으로 추정된다. 1999년 석탑을 잘 보존하기 위해 해체 복원하였다.","a":"영양신구동삼층석탑","c":"문화유산자료","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662532.jpg"},{"q":"○○○○은 대구광역시 남구 대명동에 있는 대덕산 정상에서 북쪽의 안지랭이 계곡을 감싸며 쌓은 포곡식 산성으로 ‘앞산산성 ’이라고도 부른다. 포곡식 산성은 성곽이 하나 또는 여러 개의 계곡을 감싸고 축성된 것으로, 장기간 전투에 사용하기 위해 쌓은 성을 말한다. 옛 기록에 의하면 성불산의 옛 성이 수성현에 있었으나, 지금은 산의 능선과 비탈부근에 깬 돌로 성을 쌓은 흔적만이 남아 있다. 성의 둘레는 3,051척이라고 기록되어 있는데, 그 범위는 약 3㎞에 달한다. 자연 암벽을 최대한으로 이용한 산성으로 성 안에서 발견된 옛 그릇조각과 기와조각으로 보아, 통일신라에서 고…","a":"대덕산성","c":"시도기념물","r":"대구광역시","s":"남구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645349.jpg"},{"q":"조선 중기의 문신이며 시인인 송강 ○○의 ○○이다. 명종 17년(1562) 별시문과에 장원급제하였고, 여러 관직을 두루 거쳐 선조 17년(1584)에 대사헌이 되었다. 1589년 우의정이 되어 서인의 대표로 동인을 추방하였으며, 다음해 좌의정에 올랐다. 1591년 광해군의 책봉을 건의하여 파직하였으나, 1592년 임진왜란이 일어나자 경기·충청·전라의 3도체찰사가 되었고, 1593년 중국 명나라에 사신으로 다녀왔다. ○○은 정치가로서 큰 일을 많이 하였지만, 붕당 싸움에 말려 반대당의 배척을 받았다. 그러나 가사문학의 대가로 국문학에 크게 공헌하였으며, 작품으로는『관동…","a":"진천 정철 묘소","c":"시도기념물","r":"충청북도","s":"진천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650526.jpg"},{"q":"○○○ 1527번지선 동남쪽 경계에 위치하도 있으며 남방식 ○○○형태를 취하고 있다. 뚜껑돌 형태는 장타원형으로 뚜껑돌 북서쪽이 73cm정도 들려있다. 북쪽과 남쪽 모서리에 지석이 고여 있으며, 동서측면에는 덜을 다듬은 치석 흔적이 있고, 뚜껑돌 아래에는 잡석으로 채워져 있다. 장축 290cm, 단축 170cm, 두께 70cm이며 축조시기는 탐라시대 전기 AD 1~300년경이다.","a":"상예동지석묘4호","c":"시도기념물","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657720.jpg"},{"q":"광양시 다압면 신원리 산20-1번지에 위치한 ○○○은 하동 쌍계사의 말사로 1959년에 건립된 근래의 사찰이다. 이 절은 다압에서 하동으로 건너는 섬진교 못미쳐서 불암산의 북동쪽 경사면에 위치하고 있다. 전남지방에서는 대○○○○○에서 처음으로 복장물(발원문, 진신사리보치진언문, 후령통 등)이 발견되었으며, 보살상의 절대연대, 봉안처, 조성동기, 시주자 등의 중요내용을 알 수 있다. 보살상은 조선후기의 양식이나, 법의에서 반단(半袒)형식이 없고 군의(裙衣)의 상단이 띠매듭 없는 일자형이며 상현좌를 이루고 있는 특징이 있으며 규모는 총고 62㎝이다. 이러한 형식의 보살상…","a":"광양무등암목조대세지보살좌상","c":"문화유산자료","r":"전남광주통합특별시","s":"광양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2019052019233800.jpg"},{"q":"○○○○○ 칠성탱은 光武 4년(1900)에 제작된 조선말기 탱화이지만 나름대로 화격을 갖춘 칠성탱이다. 또한 이 ○○○ 칠성탱은 구도에서나 세부 묘사에서 화사의 창의성이 보여주고 있고, 채색 또한 안정되어 있는 좋은 작품이다.","a":"밀양 표충사 대원암 칠성도","c":"문화유산자료","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666348.jpg"},{"q":"○○○○은 임진왜란 때 의병을 일으켰다가 순절한 권복흥의 사당으로 조선 영조 15년(1739)에 건립되었다. 조선 고종 5년(1868) 때 훼철된 후 1924년에 다시 단을 설치하고 복향하였다. ○○○○은 강당인 숭의당○르 중심으로 하여 부속건물들이 배치되어 있다. 이 중 문화유산자료로 지정된 강당은 홑처마 굴도리 3량집으로 좌우에 방을 배치하고 중간에 3칸의 대청이 만들어져 있다. 정면에는 단계사, 대청 뒷벽에는 숭의당 현판이 각각 걸려있다. 특히 강당의 좌우 협칸 전면 상부의 기둥 사이에 도리방향으로 설치된 들보 등은 전통목구조의 특징을 잘 보여준다.","a":"단계서당","c":"문화유산자료","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663508.jpg"},{"q":"○○○는 충무공 최필달의 위패를 모신 사당으로 1900년대 초에 문중과 유림이 논의하여 짓게 되었다. 고려 개국공신 중 한 사람으로 강릉 최씨의 시조인 충무공은, 그 당시의 학문을 바로 세우고 예를 가르친 문무를 겸한 학자로서 ‘해동부자(海東父子)’라고 불렸다. ○○○는 앞면 3칸·옆면 2칸 규모이며，지붕 옆면이 사람 인(人)자 모양인 맞배지붕집이다. 또한 사당의 경내에는 문정공 최수성의 위패가 모셔진 사당 문정묘가 있다. 후손인 최명수와 진사 정채화 등이 1936년 남문동에 건립하였는데, 주변에 주택 등의 건물이 들어섬에 따라 1982년 지금의 위치로 옮겨졌다. 최…","a":"황산사","c":"시도유형문화유산","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638000.jpg"},{"q":"우석목·무석목·벅수머리 등으로 불리우는 이 석상은 제주목·정의현· 대정현의 성문 입구에 세워졌던 것이나, 현재는 제주도민속자연사박물관· 제주대학·제주시청·제주국제공항· 삼성혈·관덕정 등에 산재하여 있으며 제주시내에 21기, 성읍에 12기, 대정의 인성·안성·보성에 12기 도합 45기가 있다. 석상의 형태는 대체로 벙거지형 모자, 부리부리한 왕방울 눈, 큼지막한 주먹코, 꼭다문 입술 두손은 배위 아래로 위엄있게 얹은 모습을 하고 있다. ○○○○의 크기는 평균 신장이 제주 187Cm, 성읍 141Cm, 대정 134Cm 이며 제작 연대는 영조 30년(1754) 경으로 추정…","a":"돌하르방","c":"시도민속문화유산","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659182.jpg"},{"q":"대나무숲을 뒤로 하고 자리잡은 옛 집이다. 안채는 1908년에 지은 것이고 기타 건물은 이보다 약간 후대에 지은 것이다. 안채는 이 지방에서 흔히 볼 수 있는 一자형으로 되어 있고, 안채 앞쪽으로 좌우에 아래채와 헛간채가 있어 전체적으로 ㄷ자형을 이루고 있다. 사랑채는 입구의 오른쪽에 북향하여 배치되었고 그 앞에 사랑마당이 있다. 안채는 겹집 형태의 7칸 집으로 앞뒤에 퇴칸을 둔 큰 규모이다. 지붕은 옆면이 여덟 팔(八)자 모양인 팔작지붕이다. 왼쪽부터 부엌·큰방·대청마루·작은방으로 구성되었다. 대청마루는 안마루·바깥마루로 나누어 안마루는 물건 수납공간으로 사용하고…","a":"보성이종선가옥","c":"시도민속문화유산","r":"전남광주통합특별시","s":"보성군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658367.jpg"},{"q":"추탄(秋灘) ○○○ 선생은 본관이 해주(海州)이며, 조선 중기 사대부이다. 선생은 1582년 사마시에 급제하였고, 1592년에 임진왜란이 일어나자 정철(鄭澈)의 종사관으로 발탁되었다. 이후 여러 벼슬을 거쳐 영의정에 이르렀다. ○○○ 선생의 묘소는 부인 경주 이씨(慶州李氏)와 쌍분(雙墳)으로 조성되었다. 봉분 앞에는 석상과 향로석이 놓여 있으며, 봉분 북쪽에 묘갈(墓碣)이 건립되어 있다. 묘역 좌우로 동자석, 망주석, 문인석이 건립되어 있다. 1647년에 건립된 원수방부(圓首方趺; 둥근 머릿돌과 사각 받침돌의 비석 형태) 형태의 묘갈은 김상헌(金尙憲)이 짓고, 송준길…","a":"오윤겸선생묘","c":"시도기념물","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646418.jpg"},{"q":"신도비란 임금이나 고관의 평생업적을 기록하여 그의 무덤 남동쪽에 세워두는 것으로, 이 비는 조선 중기의 문신인 ○○○ 선생을 기리고 있다. ○○○은 이항복과 김장생의 제자로, 조선 선조 때 승문원에서 처음으로 벼슬을 시작하여 강화유수를 지내었고, 병으로 생을 마칠 때까지 도승지, 호조판서 등의 여러 관직을 맡아 보았다. 광해군 9년(1617)에는 일본에 회답사의 종사관으로 다녀오고, 인조 2년(1642) 이괄의 난이 일어나자 전라절도사로서 커다란 공을 세웠다. 인조 5년(1627) 정묘호란 때에는 병조참판으로 청나라의 사신과 교섭하여 화의를 성립시키기도 하였다. 비는…","a":"효민공 이경직 묘역","c":"시도유형문화유산","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636288.jpg"},{"q":"이 불화는 1887년 상궁들의 시주로 19세기말 서울, 경기지역의 대표적 화승인 보암 긍법(普庵 亘法)을 비롯하여 금운 순민(錦雲 洵玟), 봉규(奉奎), 종현(宗現) 등이 그린 ○○○로 팔상의 각 장면 중에서 주요한 장면만을 부각시켜 그린 그림이다. 각 相의 내용은 효과적으로 전달되고 있으며 전체적으로 구성이 안정되어 있고 청색의 사용을 자제함으로서 격조를 느끼게 한다. 따라서 19세기 후반 서울·경기지역 화승의 새로운 도상과 양식을 대표하는 작품이다.","a":"경국사 팔상도","c":"시도유형문화유산","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2594863.jpg"},{"q":"○○○ 큰법당에 봉안된 삼장탱(三臧幀)이다. 상하 2단으로 크게 구분하고 상단에는 천장보살을 중심으로 좌우에 보살을 배치하고 그 사이에 권속들로 가득 메우고 있다. 하단에는 이들 보살의 협시와 권속들로 채워져 있다. 이들 삼장보살은 하나의 방형 수미단 위에 중앙 천장보살의 신광만 바탕을 금니로 처리하였을 뿐 나머지는 모두 이중륜광의 두 ·신광을 갖추고 결가부좌 하였다. 채색은 주로 적색과 청색, 백색, 황색을 주로 사용하였으며 부분적으로 금니를 사용하였는데, 천장 ·지지·지장보살상의 몸색은 황색을 사용하였고 나머지 인물들은 백색으로 처리하였다. 제작연대는 고종 18년…","a":"강화 청련사 삼장보살도","c":"시도유형문화유산","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637124.jpg"},{"q":"이 불상은 엄지와 중지를 맞대어 하품중생인(下品中生印)의 수인(手印)을 하고 있는데 조성기(造成記)가 남아 있지 않아 정확한 조성연대는 알기 어려우나 얼굴과 신체, 의복 등 표현 면에서 고려후기～조선 초기의 전형적인 양식을 보여주고 있다. 머리는 전체가 촘촘한 나발(螺髮)로 이루어져 있고 육계(肉髻)는 낮고 넓적하게 표현되었다. 머리와 육계의 경계선 부분에는 중간계주(中間髻珠)를 장치하였던 구멍이 크게 나있다. 얼굴은 이마 부분이 넓고 턱 부분으로 내려오면서 좁아져 역삼각형에 가깝게 둥글고 미간에는 지름 2.0cm, 깊이 1.3cm 크기의 큼직한 백호공(白毫孔)이 뚫…","a":"금동불좌상(아미타불)","c":"시도유형문화유산","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2590332.jpg"},{"q":"○○○는 지리산 남쪽 기슭에 있는 절로 통일신라 성덕왕 23년(723)에 삼법이 지었다. 지었을 당시의 이름은 옥천사였으나 통일신라 정강왕(재위 886∼887) 때 이름을 바꾸었다. 임진왜란 때 불타 없어진 것을 벽암이 조선 인조 10년(1632)에 새로 지어 오늘에 이르고 있다. ○○○의 ○○○○○은 ○○○ 내에 있는 전각으로 중국 불교 선종의 6대조인 혜능대사의 정상, 즉 두개골을 모시고 있는 건물이다. 통일신라 경애왕(재위 924∼927) 때 진감선사가 건물을 세워 육조영당이라 하였으며, 후에 금당이라 불렀다고 한다. 건물 안에는 7층석탑이 있는데 이 탑은 18…","a":"하동 쌍계사 육조정상탑전","c":"시도유형문화유산","r":"경상남도","s":"하동군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641648.jpg"},{"q":"원래 사찰이 있었던 것으로 여겨지는 곳에 있는 작은 건물 안에 모셔져 있는 ○○○○이다. 연꽃무늬가 새겨진 8각의 받침대 위에 앉아 있는 모습의 이 불상은 높이가 81㎝로 비교적 작은 규모이다. 작은 소라모양의 머리칼을 붙여 놓은 머리 모양을 하고 있으며, 넓은 얼굴에 코는 두툼하고 입은 약간 튀어나오게 표현되었다. 옷은 양어깨에 모두 걸쳐 입고 있는데, 옷주름의 표현이 극히 형식적이다. 이 불상은 고려 전기(11세기 경)에 만들어진 것으로 추정된다.","a":"의성중률리석불좌상","c":"문화유산자료","r":"경상북도","s":"의성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663293.jpg"},{"q":"일명 ‘손병사고택’으로 널리 알려진 이 집은 안마당을 중심으로 안채가 있고, 그 좌우에 곳간과 행랑방을 둔 별채가 있다. 길게 다듬은 돌로 이루어진 안채 축대는 3곳으로 오르내리도록 돌층계를 설치하였으며, 부엌 안쪽 구조가 특이하다.","a":"밀양다죽리손씨고가","c":"문화유산자료","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664074.jpg"},{"q":"진해의 해군통제부 내에 있는 건물로 어떤 용도로 지어졌는지 정확히 알 수는 없으나 일제시대에 일본군 통신대가 사용하였다고 한다. 해방 이후 해군에서 건물을 인수하여 수리한 후 ○○○○○의 ○○으로 사용하였다. 1979년에 수리하여 현재에 이르고 있다. ○○은 집무실 겸 응접실·침실·경호실과 기타 부속실로 구성된 ㄱ자형 건물로 지붕은 옆면이 여덟 팔(八)자로 가장 화려한 팔작지붕이다. 이곳은 한식의 구조와 양식의 외관을 갖춘 곳으로 한식과 양식을 절충한 모습을 보여주는 건물이다. ○○에서 조금 떨어진 곳에 육각형의 작은 ○○가 있는데 나무로 짜여져 있으며, 지붕은 갈대…","a":"창원 이승만 대통령 별장 및 정자","c":"시도유형문화유산","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642099.jpg"},{"q":"경상남도 ○○군 적중면 ○○○에 있는 삼존석불로 중앙에 본존불인 비로자나불좌상이 있고 그 좌우에 입상불 2구가 배치되어 있다. 비로자나불좌상은 높이 160㎝, 너비 70㎝이며, 손은 가슴 앞에서 왼손이 오른손 검지를 감싸고 있는 모습을 하고 있다. 옷은 마멸이 심해 구분하기 어려우나 왼쪽 어깨에만 걸친 형태이며, 발은 몸에 비해 작게 표현하였다. 양 옆의 입불상은 높이 120㎝, 너비 40㎝이며, 마멸이 심해 판단할 수 없으나 조각수법이 특이하다.","a":"합천 죽고리 석조비로자나삼존상","c":"시도유형문화유산","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642281.jpg"},{"q":"○○○○은 조선시대에 백성들에게 세금을 매기거나 나라에서 필요한 노동력을 얻기 위해 작성한 호구조사 기록문서이다. ○○○○의 작성은 3년마다 만들었으며, 각 읍·면에서 감독관이 각 집안별로 호구단자(실태조사기록) 2부를 만들어 군현에 보내졌다. 군 현에서는 호구단자를 호적과 비교한 후 1부는 호주에게 교부하고 1부는 호적작성의 자료로 삼았다. 또한 군현에서는 호적을 3부로 만들어 1부는 군현에, 1부는 감영에, 1부는 호조에서 관리하여 세금을 매기는 자료로 활용했다. ○○○○에는 각 집의 호주·부·조·증조·외조의 신분 직역이 기재되어 있어 한 읍 내지는 면의 주민상을…","a":"언양현호적대장","c":"시도유형문화유산","r":"울산광역시","s":"남구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637267.jpg"},{"q":"경상남도 ○○군 ○○면 북촌리에 있는 이 산성은 계곡을 둘러싸며 주위의 산 능선을 따라 일정하지 않은 모양으로 쌓은 산성이다. 성의 둘레가 약 1.7㎞에 달하는 대규모의 산성이고, 남서쪽 성벽은 바깥만 돌로 쌓고 안쪽은 흙과 잡석으로 채우는 방식으로 쌓았다. 만든 연대를 알 수 있는 기록이나 유물을 발견하진 못했지만 만든 방식이 근처의 성산산성, 문안산성과 동일하다. 그리고 성 안에서 발견되는 일부 토기와 기와조각 등으로 미루어 보아 이것은 통일신라시대까지는 거슬러 올라갈 수 있을 것으로 추정한다.","a":"함안 성점산성","c":"시도기념물","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656242.jpg"},{"q":"영덕 ○○○ 마을 내에 있는 ○○○은 남용(南鎔)이 조선 고종 37년(1900)에 건립한 것을 1942년에 남응호(현 소유자의 아버지)가 매입하였다고 한다. ‘○○○’이라는 이름은 현 소유자 남명순(현 소유자)의 할아버지인 남조영의 처가 동네 이름인 경주 사곡을 딴 것이라 한다. 이 ○○○은 정면 4칸·측면 5칸의 ㅁ자형 건물로 자연석 기단과 자연석 주초 위에 네모기둥을 세웠으며, 벽체·기단·굴뚝 등은 시멘트로 덧 발라져 있다. 대문칸을 중심으로 좌측에 1칸 마굿간이 있고, 우측에 아랫방과 사랑대청이 있다. 우익사는 사랑대청과 연결하여 2칸의 사랑방, 반칸의 통래칸으…","a":"영덕괴시리사곡댁","c":"문화유산자료","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663410.jpg"},{"q":"○○○ 입구의 밭 가운데 자리하고 석탑으로, 2층 기단(基壇)에 3층의 탑신(塔身)을 올린 모습이다. 위 ·아래층 기단과 탑신의 몸돌에는 기둥모양이 조각되어 있다. 지붕돌은 밑면의 받침이 1층과 2층은 4단, 3층은 3단이며, 네 귀퉁이가 살짝 들려있다. 기단의 맨윗돌 일부분이 깨지고, 꼭대기의 머리장식이 없어졌지만 다른 부재들은 비교적 잘 남아 있다. 전체적으로 각 부재들의 비례와 균형이 잘 맞아 안정감이 느껴지는 탑으로, 통일신라 후기에 세운 것으로 보인다.","a":"용화동삼층석탑","c":"시도유형문화유산","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640250.jpg"},{"q":"해발 24m의 낮은 구릉지에 있다. 성벽은 구릉의 정상부를 중심으로 외곽을 감싸는 형태로 축조되어 있다. ○○ 주변은 낮은 구릉과 평야가 펼쳐져 있어 남쪽과 서쪽은 아산만 일대까지 바라보인다. ○○ 북쪽 2km 지점에는 진위천과 안성천이 합류하여 아산만으로 향하고 있으며 동서교통의 요충지이기도 하다. ○○의 평면 형태는 남북이 긴 장방형이다. 전체 둘레는 337m이며 외벽이 높이는 8∼10m 다. 성벽은 부분적으로만 조사되었다. 토성벽은 성토층이 두껍고 경사지게 조성된 것으로 보아 판축공법이 아니라 성토다짐공법으로 쌓은 것으로 보인다. 문지는 동벽과 서벽의 중간부분에…","a":"농성","c":"시도기념물","r":"경기도","s":"평택시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646157.jpg"},{"q":"○○○는 청동기 시대의 대표적인 무덤으로 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 거대한 덮개돌[上石]이 지상에 드러나 있고 그 밑에 고임돌[支石], 묘역시설(墓域施設), 무덤방 등이 있는 구조를 가지고 있다. 하지만 지역과 시기에 따라 그 형태는 매우 다양하다. 일반적으로는 무덤방이 지상에 위치한 탁자식(卓子式)과 지하에 위치한 기반식(碁盤式) 또는 바둑판식으로 분류하고 있다. ‘○○○○○’은 여계산(해발 158m)과 석산(해발 135m) 사이에 형성된 곡간 평지상에 위치한다. 3개 지점에 11기의 ○○○가 분포하는데, 이 가운데 9기의…","a":"오산금암리지석묘군","c":"시도기념물","r":"경기도","s":"오산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646472.jpg"},{"q":"갑사는 백제 구이신왕 원년(420)에 아도화상이 처음 지었고, 통일신라 문무왕 19년(679)에 의상이 고쳐 지었다고 한다. 그 뒤 고려시대와 조선시대를 거치면서 여러 차례 고치고 넓혀 지어 오늘에 이르고 있다. 표충원은 영조 14년(1738) 임진왜란 당시 왜적을 격퇴한 공을 기리기 위해 세운 사당이다. 건물 안에는 서산대사 휴정·사명대사 유정·기허당 영규대사의 영정을 모시고 있다.","a":"갑사표충원","c":"문화유산자료","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660954.jpg"},{"q":"『법화경』은 ○○○○○을 줄여서 부르는 말로, 부처가 되는 길이 누구에게나 열려 있다는 것을 중요사상으로 하고 있다. ○○○○○은 천태종의 근본경전으로 화엄종과 함께 우리나라 불교사상 확립에 크게 영향을 끼친 불교경전이다. 우리나라에 유통된 불교경전 가운데 가장 많이 간행된 것으로 정확히 언제부터 유통되었는지 알 수 없지만 신라 고승들의 주석서가 전해지는 것으로 보아 삼국시대부터 유통되어진 것으로 추정된다. 고려시대에는 왕실을 중심으로 공덕을 쌓기 위해 여러 차례 간행되었고, 조선시대에도 계속 간행되었다. 정종 2년(1399) 정천익에 의해 간행된 판본이 현재까지 전…","a":"범어사 묘법연화경","c":"시도유형문화유산","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636676.jpg"},{"q":"만운 ○○○의 영정을 모신 곳이다. ○○○은 조선 중기의 무신으로 미천한 집에서 태어났다. 병조판서 이항복에게 사서를 배웠으며 머리가 총명하였다. 임진왜란이 일어나자 권율 장군 아래에서 종군하였고 키가 작으면서도 씩씩하여 덕장이라는 칭송을 들었다. 이괄의 난이 일어나자 이를 평정하여 1등 공신으로 책정되고 ○○○에 봉해졌다. 천문·지리·복서·의술 등 다방면에 걸쳐 뛰어났으며 청렴하기로 이름이 높았다. 시호는 충무(忠武)이다. 이곳은 후손인 정백흥이 순조 11년(1811)에 지었으며 앞면 3칸·옆면 1칸 규모의 건물로, 지붕은 옆면에서 볼 때 사람 인(人)자 모양의 맞…","a":"금남군정충신영정각","c":"문화유산자료","r":"전북특별자치도","s":"장수군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661647.jpg"},{"q":"동암 권이번의 학덕을 추모하고 후학을 양성하기 위해 세운 서당이다. 권이번은 임금이 타는 수레와 말에 관련된 일을 하는 기관인 사복시의 장(長)인 사복시정을 역임했다. 이 서당은 그의 후손인 사와·사주·사직 등이 조선 영조 25년(1749)에 세웠다. 그 뒤 정조 9년(1785)에 동산사를 세우면서 지금 있는 자리로 옮겨 오늘에 이른다. 서당은 앞면 3칸·옆면 2칸 규모로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 꾸몄다.","a":"동암서당","c":"문화유산자료","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663091.jpg"},{"q":"조선의 군사업무를 담당하던 ○○○의 청사건물이다. 고종 5년(1868)에 덕의당·청헌당과 함께 지어졌다. 원래 광화문 남쪽 현재의 정부종합청사 자리에 있던 것을 ○○○ 청사의 중심이 되는 ○○○만을 1930년대에 지금의 위치로 옮겼다. 앞면 7칸·옆면 4칸 규모이며, 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕집이다. 중앙 3칸은 대청이고 양 옆에 1칸의 온돌방이 있으며 그 옆에는 광이 있다. ○○○○○은 조선시대 관아건물로서 희귀한 문화유산이다.","a":"삼군부 총무당","c":"시도유형문화유산","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636122.jpg"},{"q":"○○○○○는 서방극락세계를 관장하면서 중생들에게 무한한 안락과 수명을 보장해주는 ○○○불의 설법장면을 그린 것으로 『정토삼부경(淨土三部經)』에 근거한 불화이다. ○○○ 요사에 마련된 법당 안에 봉안된 ○○○○○는 원래 극락보전(極樂寶殿)에 봉안되었던 불화로 현재는 불단(佛壇)에 가려 화면의 1/3 밖에 볼 수 없다. 불화는 가로 220㎝, 세로 185㎝의 비단바탕에 진한 채색으로 그려져 있다. 중앙의 ○○○불은 키형의 두광과 신광을 두르고, 높은 대좌 위에 결가부좌하였다. 대의 안쪽에 복견의(覆肩衣)와 승각기(僧脚崎)를 입고, 대의를 변형우견편단으로 걸치고 있다. 단…","a":"쌍계사아미타회상도","c":"문화유산자료","r":"경기도","s":"안산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660230.jpg"},{"q":"조선시대 청동으로 만든 높이 110㎝, 입 지름 82.5㎝의 종이다. 종을 매는 용뉴에는 두 마리의 용이 서로 등지고 앉아, 여의주를 물고 하늘로 오를 듯한 모습을 하고 있다. 종의 윗쪽 띠에는 2자씩으로 연결된 80여자의 범자가 새겨 있으며, 아래쪽 띠에는 연꽃 덩굴무늬가 새겨 있다. 범자무늬 아래에는 4곳에 정사각형의 유곽이 배치되었는데, 유곽은 덩굴무늬를 그려 만들었다. 유곽 안에는 9개의 도드라진 유두가 있으며, 유곽과 유곽 사이에는 삼존불이 양각되어 있다. 아래쪽 띠 위편에는 ‘건륭 41년’으로 시작되는 글이 있어, 1776년에 만들었음을 알 수 있다. 이…","a":"고성 옥천사 동종","c":"시도유형문화유산","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641486.jpg"},{"q":"이 일대는 울릉도에서 밀집 분포하고 있는 무덤 중 하나이다. 무덤은 산록경사면에 괴석을 이용하여 축대 또는 기단을 쌓아 평평하게 하고, 그 위에 시신을 모시는 돌덧널무덤(석곽묘)을 만들었으며, 그 위에 돌로 봉분을 만들은 적석총 형태이다. 돌덧널(석곽) 입구의 앞은 수직벽으로 되어 있어 마치 신전의 정면처럼 보이는데 이러한 형식은 삼국시대 울릉도에서만 나타나는 특징이다.","a":"울릉남서동고분군","c":"시도기념물","r":"경상북도","s":"울릉군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654518.jpg"},{"q":"『○○○○○』은 조선시대 영남사림학파의 영수인 ○○○의 시문집 책판이다. ○○○은 조선 전기의 문신으로 1459년 문과에 급제하여 홍문관제학, 공조 ·이조참판 등 여러 벼슬을 거쳤다. 문장과 역사에 뛰어나 조선시대 도학(道學)의 정수를 이어가는 중추적 구실을 하였다. 이 문집은 성종 24년(1493)에 ○○○의 조카 장중진이 최초에 작성된 원고를 모아 ○○○의 문도였던 조위가 편집을 하였으나, 미처 간행하지 못하고 무오사화로 인해 모두 소실되고 말았다. 다시 장중진이 그 나머지 글을 모아 중종 12년(1517)에 선산에서 ○○본으로 간행하였다. 『○○○○○』은 시집이…","a":"김종직 점필재문집 및 이존록 목판","c":"시도유형문화유산","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641782.jpg"},{"q":"‘○○○○○’는 서운산 ○○○의 중수를 기념하기 위해 조선 경종 원년(1721)에 세운 비로 부도군(浮屠群)이 있는 사찰 입구에 위치한다. 직사각형 비좌(碑座) 위에 세운 비신과 그 위에 올린 이수(螭首)로 구성되었다. 비신은 화강암인데 비문이 마멸되어 판독할 수 없는 곳이 여러 곳이다. 비명과 서문은 나준(羅浚)이 짓고, 황하민(黃夏民)이 썼으며, 전액(篆額)은 김진상(金鎭商)이 썼다. 비문의 내용을 살펴보면, 서문에 고려 지정연간(至正年間 : 1341∼1367)에 나옹(懶翁)이 중창한 사실과 숙종 46년(1720년)에 도인(道人)이 중수한 내용 등 연혁이 차례로…","a":"청룡사사적비","c":"시도유형문화유산","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637580.jpg"},{"q":"우석목·무석목·벅수머리 등으로 불리우는 이 석상은 제주목·정의현· 대정현의 성문 입구에 세워졌던 것이나, 현재는 제주도민속자연사박물관· 제주대학·제주시청·제주국제공항· 삼성혈·관덕정 등에 산재하여 있으며 제주시내에 21기, 성읍에 12기, 대정의 인성·안성·보성에 12기 도합 45기가 있다. 석상의 형태는 대체로 벙거지형 모자, 부리부리한 왕방울 눈, 큼지막한 주먹코, 꼭다문 입술 두손은 배위 아래로 위엄있게 얹은 모습을 하고 있다. ○○○○의 크기는 평균 신장이 제주 187Cm, 성읍 141Cm, 대정 134Cm 이며 제작 연대는 영조 30년(1754) 경으로 추정…","a":"돌하르방","c":"시도민속문화유산","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659175.jpg"},{"q":"○○○는 임금이나 고관의 평생업적을 기록하여 그의 무덤 남동쪽에 세워두는 것으로, 이 비는 조선 중기의 문신인 중봉 ○○ 선생의 행적을 기리고 있다. ○○은 명종 20년(1565) 성균관에 입학하여 2년 후인 1567년 병과에 급제하였다. 그후 호조좌랑·성균관전적·사헌부감찰·전라도도사 등을 역임하였으며, 관직에서 물러난 뒤에는 ○○군 안읍 밤티로 들어가 제자양성과 학문에 전념하였다. 선조 25년(1592) 임진왜란이 일어나자 의병 1,600여명을 모아 청주성을 수복하였으나 충청도순찰사의 방해로 해산당하여, 불과 700여명의 남은 병력을 이끌고 금산으로 행진하였고 고바…","a":"옥천 조헌 신도비","c":"시도유형문화유산","r":"충청북도","s":"옥천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638681.jpg"},{"q":"부산대학교박물관 소장 ○○○○○은 화면에 배경 없이 책을 중심으로 문방구와 도자기, 고동기(古銅器), 소과(小菓) 등의 기물(器物)을 배치한 나열식 ○○○그림을 본으로 하여 비단에 전통 ○○로 제작한 8폭의 ○○이다. ○○○○은 각 폭마다 서가 없이 책과 여러 종류의 기물(器物)이 상하에 배열된 밑그림에 수를 놓았다. 8폭 ○○으로 장황(裝潢·粧潢)[비단이나 두꺼운 종이를 발라서 책이나 화첩(畫帖), 족자 따위를 꾸미어 만든 것]되어 있다. 제8폭을 제외하면 각 폭 상단에 서적들이 여러 겹으로 쌓여 있고 그 아래에 여러 종류의 기물들이 나열되어 있다. 옛 청동기, 색…","a":"자수 책거리 병풍","c":"시도유형문화유산","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636741.jpg"},{"q":"조선 선조~인조 연간 문신인 ○○○의 묘와 ○○○이다. 1617년(광해군 9) 인목 대비 폐모론에 이항복·정홍익과 함께 반대하여 남해에 유배되었다가 인조반정으로 복귀되었다. 묘역은 부인 경주 이씨(慶州李氏)와 합장한 단분(單墳; 하나의 봉분)의 형태이다. 봉분 정면 오른쪽에는 옛 묘표(墓 ; 무덤 주인공의 이름 등을 새긴 비석)와 최근에 건립한 묘표가 세워져 있다. 옛 묘표는 보편적인 원수방부형(圓首方趺形; 둥근 머릿돌과 사각 받침돌의 비석 형태)이다. 비문은 박세채가 짓고 증손인 김유(金濡)가 썼으며 건립 연대는 기록되지 않았으나, 17세기의 양식을 지니고 있다.…","a":"김덕함묘및신도비","c":"시도기념물","r":"경기도","s":"파주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2018010218500600.jpg"},{"q":"이 지방 출신으로 과거에 합격한 사람들이 고장의 발전과 미풍양속을 위해 함께 모여 의논하던 곳이다. 조선초에 지어졌으나 훼손되어 순조 10년(1810) 다시 건립하였다. 생원, 진사에 합격한 사람과 대과에 합격한 사람들이 ○○○에 모여 자신들의 우의를 두텁게 하고 주민의 교화와 풍속을 바로 잡는데 힘썼다. 또한 정치활동에 대한 건의와 자문도 하던 원로원 구실을 하였다. 고종 31년(1894) 과거제도가 없어짐에 따라 모임도 함께 없어졌는데, 그 후손들이 모선계를 조직하여 관리해 오고있다. 앞면 3칸·옆면 3칸 규모이며, 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕집이…","a":"계련당","c":"시도유형문화유산","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637950.jpg"},{"q":"부여 ○○○ 명부전에는 중앙 불단 위의 ○○○○을 중심으로 그 측면에 무독귀왕(無毒鬼王)과 도명존자(道明尊者)의 삼존상이 있고 시왕(十王)이 각각 좌우에 5왕씩 대칭으로 모셔져 있다. 그 옆으로 판관(判官)과 사자(使者), 인왕(仁王) 등이 있다. 각기 다양한 모양의 존상들은 색채가 화려하고 옷에 새겨진 문양 등이 섬세하며 각기 17∼18세기에 유행했던 시대적 조각양식과 조선후기에 성행했던 명부신앙을 잘 보여주고 있는 바, ○○○의 불교유물들과 관련하여 생각해 볼 때 17세기 중엽에 조성된 것으로 추정되며 명부전의 모든 존상들을 잘 갖추고 있다. ○○○ 명부전은 18…","a":"부여무량사지장보살및시왕상일괄","c":"시도유형문화유산","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2019052011081200.jpg"},{"q":"삼척 ○○○ 마을의 국도 도로변에는 금옥각(金玉閣)이라는 비각이 마련되어 있는데, 그 안에 이 2기의 철비를 모시고 있다. 하나는 삼척부사 이규헌에 대한 고마움과 어진 정치를 영구히 기리기 위해 세워놓은 것이고, 다른 하나는 옆의 비를 세우는데 참여한 주민들의 공을 잊지 않고자 세워둔 것이다. 이규헌은 조선 헌종 원년(1835) 삼척부사로 부임해 와 1839년까지 지내면서 이 지역의 백성들을 위해 어진 정치를 폈다. 특히 조선 헌종 3년(1837) 가뭄과 홍수로 백성들이 굶주리게 되자 역둔창의 양곡을 나누어주어 많은 백성들을 구하기도 하였다. 철로 빚은 2기의 비는…","a":"삼척역둔리철비(부사이규헌영세불망비및금옥첨원비)","c":"문화유산자료","r":"강원특별자치도","s":"삼척시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660560.jpg"},{"q":"○○○○○는 1923년 세운 사당으로 단종복위운동 때 사육신의 한 사람이었던 박팽년(1417∼1456)과, 사육신에 포함되지는 않지만 함께 복위운동을 도모했던 박심문(1408∼1456)을 모신 곳이다. 박팽년은 조선 전기 문신으로 1434년(세종 16) 문과에 급제한 후 1453년(단종 1) 우승지를 거쳐 형조참판이 되었으며 1455(세조 1)에는 집현전의 관원이 되었다. 단종이 왕위를 빼앗기자 성삼문 등과 함께 단종복위운동을 펼치는 중 발각되어 심한 고문으로 옥중에서 숨을 거두었다. 박심문 역시 조선 전기 문신으로 1436년(세종 18) 문과에 급제하였다. 그는 함…","a":"창계숭절사","c":"문화유산자료","r":"대전광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659690.jpg"},{"q":"조선 후기 무신이면서 외교가였던 ○○이 살던 집이다. ○○은 중요 관직을 두루 거쳤으며 강화도조약과 조미수호조약 등을 체결하여 조선의 개항에 중요한 임무를 수행하였다. 이 집은 1850년경 ○○이 전통 한옥 형태로 지은 건물이다. 세울 당시에는 사랑채와 행랑채, 안채 등이 있었으나 현재는 안채와 광채만 남아 있다. 안채는 2층 기단 위에 세운 ㄱ자형 평면을 갖춘 집으로 오른쪽은 옆면에서 볼 때 사람 인(人)자 모양을 한 맞배지붕이고, 왼쪽은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 광채는 부속 건물로 곡식이나 여러 생활용품을 보관해 두던 곳이다.","a":"진천 신헌 고가","c":"문화유산자료","r":"충청북도","s":"진천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660711.jpg"},{"q":"성균관 대사성(成均館 大司成) 이정보(李鼎輔,1693년～1766년)가 태학속전(太學續典)이 완성된 것을 기념하여 9명의 참여 유생(儒生)들과 함께 만든 계첩(稧帖)이다. 능화문(菱花文) 장지로 된 표지에 묵서(墨書)로 ‘○○○○’이라는 표제가 적혀 있고 제 1면에 참여자 명단인 좌목(座目), 제 2면에 성균관의 평면도인 반궁도(泮宮圖), 제 3면과 제 4면에 진사 신석규(辛錫奎)와 박익령(朴益齡)이 쓴 발문(跋文)이 각각 수록되어 있다. 신석규의 발문에 의해 이 화첩이 영조 23년(1747년)에 제작되었음을 알 수 있다. 좌목(座目) 부분에는 자(字),생년(生年),본…","a":"태학계첩","c":"시도유형문화유산","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2590377.jpg"},{"q":"조선시대 곡식을 운반하기 전에 쌓아두던 창고의 하나로 ‘공진창’이 처음 명칭이다. 성종 9년(1478) 『경국대전』에 의하여 모든 제도가 정비되면서 충청도에서 세금으로 거둔 곡식은 모두 이곳으로 모았다가 일정한 시기에 서울의 창고로 운송하도록 하였다. 지금은 창고터 주변에 만든 성지(城地)가 약 680m 정도 남아 있는데, 겨우 터만을 알아 볼 정도이다. 처음에는 창고가 없어 한데 쌓아 두었으나, 중종 18년(1523)에 비로소 창고 80칸을 건축하였다고 한다. 이곳에서 충청도 지방 39개 목·군·현의 조세로 바친 쌀을 모아 두고 배로 수도까지 운반하였다.","a":"아산공세곶고지","c":"시도기념물","r":"충청남도","s":"아산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1651940.jpg"},{"q":"임진왜란 때 나라를 위해 싸우다 죽은 제말(諸沫)과 그의 조카인 제홍록(諸弘錄)의 공적을 기리기 위해 세운 비이다. 임진왜란이 일어나자 당시 성주목사로 있던 제말은 의병을 모아 왜군에 맞서 싸우다 제홍록과 함께 전사하였다. 선조는 그의 공을 치하하여 병조판서로 벼슬을 높이고 이 비를 세우도록 하였다. 비의 형태는 네모난 바닥돌 위에 비몸을 세우고 용을 조각한 머릿돌을 얹은 모습이다. 정조 16년(1792)에 세운 것으로, 비문은 서유린이 글을 짓고 이병모가 글씨를 썼으며, 조윤정이 비의 제목을 새겼다. 원래의 자리는 성주초등학교 교정이었는데, 학교 운동장을 넓히면서…","a":"쌍충사적비","c":"시도유형문화유산","r":"경상북도","s":"성주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640354.jpg"},{"q":"제주도 민가의 일반적 형태를 지닌 초가집이며 벽은 검은 돌로 쌓았다. 지붕은 선이 완만하고 매끈한 유선형이며 지붕이 날아가지 않도록 새(띠)를 바둑판처럼 얽어 놓았다. 제주도의 자연환경과 생활양식을 연구하는데 좋은 자료가 되고 있다.","a":"송종선가옥","c":"시도민속문화유산","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659217.jpg"},{"q":"\"○○○ 가옥은 창평면 소재지의 남쪽부근의 넓은 들을 바라보면 자리하고 있다. 넓고 잘 다듬어진 마을 안 길을 가다 집으로 향한 좁은 골목으로 10여m 지나면 5칸의 곡간채가 나오는데 맨 좌측 끝 1칸을 대문으로 하였다. 동입서출이라고 동쪽으로 난 대문을 들어서면 벽돌 담장을 쌓아 대문에서 안채가 들어다 보이지 않게 하였다. 시선차단용 담장을 지나면 넓은 안마당을 두고 사방을 안채, 사랑채, 삼칸채, 문간(곡간)채가 마당을 에워싼 ㅁ자형식으로 둘러싸여 있다. 가옥의 구성은 정면 6칸, 측면 1칸, 전후좌우퇴의 규모를 갖춘 아주 격식 있는 안채와 문간채, 사랑채, 곡간…","a":"담양고재환가옥","c":"시도민속문화유산","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658409.jpg"},{"q":"○○○는 1973년에 세운 건물로 공자를 중심으로 주자와 안자의 영정을 모시고 있는 사당이다. 앞면 3칸·옆면 1칸의 규모로, 지붕은 옆면에서 볼 때 사람 인(人)자 모양을 한 맞배지붕이다. 원래 대평면 하촌리에 있던 것을 남강댐 공사로 1995년 지금 있는 자리에 옮겨 지었다.","a":"진주 도통사","c":"문화유산자료","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663956.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고, 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 고려 충렬왕 30년(1340)에 처음 지었으나, 단종 복위운동으로 고을과 함께 향교가 혁파당하여 약 200여년이 지난 숙종 9년(1683) 부(府)가 회복되면서 다시 세웠다. 이후 여러 차례 위치를 옮겨 세운 끝에 정조 14년(1790) 지금 있는 자리로 옮겨 오늘에 이르고 있다. 지금 남아 있는 건물로는 제사 공간인 대성전과 동무·서무, 교육 기능을 수행하는 강당인 명륜당, 학생들의 기숙사인 동재, 삼문 등이다. 전체적인 배치는 교육 공간인 명륜당을 앞에…","a":"순흥향교","c":"문화유산자료","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663186.jpg"},{"q":"○○○○○ 안에 있는 이방·호방·예방·병방·형방·공방 6방의 건물 중 이방청으로 조선 중기의 관청 건물이다. 조선 효종 5년(1654)에 유수 정세규가 세웠고, 정조 7년(1783)에 유수 김노진이 건물 내부를 고쳐 괘홀당이라고 불렀다. 나무로 된 1층의 기와집으로 ㄷ자형이며, 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕집이다. 여러 차례 고쳐서 옛날 관청의 모습을 잘 알 수는 없으나, 조선시대 지방의 이방청을 알 수 있는 귀중한 자료이다.","a":"강화유수부 이아","c":"시도유형문화유산","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637055.jpg"},{"q":"해학 ○○○○은 황현, 이정직과 더불어 호남 3걸로 불리는 조선말 실학자이자 항일독립투사로서 동학농민혁명에도 참여하였다. 그는 전문대학의 필요성을 강조하였으며 모든 국민이 의무적으로 학문을 배워야 한다고 주장하였다. 1904년 통감부 설치에 따른 국제적 외교활동으로 구국운동을 전개하고자 1905년 미국 포츠머스에서 열리는 강화회의에 나아가 일본의 침략저의를 규탄하려 했으나 뜻을 이루지 못하였다. 1906년에는 장지연, 윤효정 등과 함께 대한자강회를 조직하여 교육자로써 민중계몽에 힘썼으며 민족의 주체의식을 고취하려는 뜻으로 1909년 단학회 창립을 추진하기도 하였으나…","a":"해학이기선생생가","c":"시도기념물","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653818.jpg"},{"q":"두암마을의 민가 옆에 자리하고 있는 탑으로, 주위에서 고려시대의 기와조각이 발견되어 이곳이 당시의 옛 절터임을 알게 되었다. 탑은 전체의 무게를 받치는 기단(基壇)을 2층으로 쌓고, 그 위로 3층의 탑신(塔身)을 올린 모습으로, 꼭대기의 머리장식을 제외하고는 대체로 본모습을 잘 간직하고 있다. 아래층 기단에는 각 면마다 3개씩의 안상(眼象)을 움푹 들어가게 새겼고, 위층 기단에는 4면의 모서리와 가운데에 기둥모양의 조각을 두었다. 탑신부의 1층 몸돌에는 한쪽면에 문짝모양을 새겼는데 그 안에 자물쇠도 표현해 놓았다. 지붕돌은 밑면에 3단씩의 받침을 두었으며, 처마는 수…","a":"옥천 두암리 삼층석탑","c":"시도유형문화유산","r":"충청북도","s":"옥천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638579.jpg"},{"q":"○○○란 한 인물의 옛 자취를 밝혀 후세에 알리고자 세우는 비로, 이 비는 포은 ○○○ 선생의 효행을 기리고 있다. ○○○ 선생은 고려 후기의 문신이자 학자이며 삼은(三隱)의 한사람이다. 공민왕 5년(1355) 부친상을 당하여 묘 곁에서 3년상을 치르고, 그후 공민왕 14년(1365) 모친상까지 당하여 역시 3년상을 지내였다. 이토록 지극하였던 그의 효성이 조정에 보고 되자, 출생지인 이곳 우항리 마을에 비를 세워두도록 하였다. 비는 반듯하고 널찍한 사각받침돌 위에 비몸을 세운 모습이다. 앞면에는 효행을 행한 마을이라는 뜻의 ‘효자리(孝子里)’라는 글귀를 세로로 큼직…","a":"포은정몽주유허비","c":"시도유형문화유산","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640853.jpg"},{"q":"임진왜란 때 의병장으로 활약한 ○○○ 장군을 기리기 위해 그의 군대가 주둔하였던 옛 성루 터에 세운 비이다. 고루(古壘)란 과거에 전투를 벌였던 ‘작은 성루〔城壘〕’를 말한다. 이재(李縡)가 지은 비문에 “안성군 남쪽 15리쯤에 있는 목촌(木村) 마을의 옆에는 우뚝 솟은 산이 있는데 (중략) 사람들이 서로 전하기를 옛날 ○○○ 장군의 군대가 진을 치던 작은 성루라고 한다”는 내용이 전한다. ○○○은 임진왜란이 일어나자 부친 홍자수(洪自修), 형 4명과 함께 의병을 모아 많은 승리를 거두었다. 그 공로를 인정받아 수원판관(水原判官)을 제수받았고 아울러 기호양도(畿湖兩道…","a":"홍계남장군고루비","c":"시도유형문화유산","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637449.jpg"},{"q":"조선 전기의 문신인 ○○○ 선생의 묘 앞에 자리하고 있는 비이다. 국당 ○○○ 선생은 어려서부터 학문으로 이름이 높아 고려 우왕 13년(1386) 13세에 진사가 되었고, 17세인 공양왕 2년(1390)에 생원이 되었다. 이색의 추천으로 여흥부·춘천부의 교수로 벼슬을 시작하여 세종 5년(1423) 창평현감을 역임하였다. 조선 세종 7년(1424)에는 상을 당하여 3년간 묘곁을 지켰는데 그에 대한 표창으로 정려각이 세워지기도 하였다. 세조의 왕위찬탈에 반대하는 단종복위운동에 가담하였는데, 이후 공주 동학사 숙모전 초혼각에 생육신과 함께 배향되었다. 비는 네모진 받침돌…","a":"영동 박흥생 묘비","c":"시도기념물","r":"충청북도","s":"영동군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650216.jpg"},{"q":"경상북도 청도군 운문면 ○○○의 동쪽에 있는 약수로 이름난 ○○○에 모셔져 있는 ○○○○○이다. 재질은 흔히 옥돌이라 부르는 것으로 경주 일원에서 흔히 볼 수 있는 흰 돌이다. 불상에 금칠을 다시 할 때 복장유물(復藏遺物)이 발견되었는데, 강희 20년(숙종 7년, 1681)에 만들어졌다는 기록이 나왔다. 조각 양식상으로 보아도 조선 후기 작품임이 분명하다. 이 시기의 불상 중 돌로 만든 불상은 그 예가 많지 않으므로 당시의 불상 연구에 중요한 자료가 된다.","a":"운문사내원암석조아미타불좌상","c":"문화유산자료","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663178.jpg"},{"q":"○○○○○ 1916년 2월 24일 시행된 조선총독부령 제7호에 의한 조선총독부 지방관에 따라 전라남도 ○○○○○으로 설립되어 1917년 5월 17일 개칭한 한센병(노르웨이 의사 한센이 1873년 처음 나균을 발견하여 한센병이라 함) 진료를 위한 의료시설이다.","a":"고흥소록도자혜의원본관","c":"문화유산자료","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662270.jpg"},{"q":"이 유물은 광산 김씨인 후조당 김부필(1577∼1644)이 나라에서 시호를 내릴 때 받은 교지와 「퇴계유묵」, 『향병일기』, 『전가보첩』 등 4종 6점이다. 김부필은 퇴계 이황의 문인으로, 학문이 뛰어났던 인물이다. 그가 죽은 후 순조 2년(1802)에 오위도총부도총관에 증직되었고, ‘문순(文純)’이란 시호를 받았다. 그 밖에 광산 김씨의 유물로 문집, 서책 등 수백 점이 숭원각에 보호, 관리되고 있다.","a":"후조당유물","c":"시도유형문화유산","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640357.jpg"},{"q":"○○○에 보존되어 있는 그림으로, 석가가 영취산에서 설법하는 모습을 그린 ○○○○○이다. 이 ○○○○○는 면 바탕에 채색하여 그려진 것으로, 화면은 중앙에 석가여래상이 연꽃무늬 대좌 위에 결가부좌하고, 그 전면 좌우측에는 문수·보현보살이 안쪽을 향한 모습으로 연꽃무늬 대좌 위에 반가좌하고 있으며, 그 위쪽으로 사천왕상과 관음·세지보살, 그리고 아난·가섭상을 비롯한 제자상이 본존을 에워싸고 있다. 본존의 육신부는 황색을 바르고 먹선의 하묘선 위에 붉은색 선으로 윤곽선을 처리하였다. 머리 부분은 입자가 거친 군청안료를 바르고 윤곽선은 녹청으로 융기되게 표현하였다. 눈썹·…","a":"마하사 영산회상도","c":"문화유산자료","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659360.jpg"},{"q":"조선 영조 26년(1750)경에 유정원(1702∼1761)이 지어 학문을 연마하고 후학을 가르치던 정자이다. 지금은 그 후손들이 선생의 덕행을 기리며 자손들을 가르치는 곳으로 쓰고 있다. 유정원은 영조 때의 문신으로 홍문관수찬·사간원교리 등을 거쳐 대사간에 이르렀다. 영조의 총애와 채제공의 추천으로 장헌세자에게 강의하기도 하였다. 한편 지방관으로 있을 때에는 백성들에게 선정을 베풀어 정약용의『목민심서』에서 그 치적을 다루기도 하였다.『역해참고』등 많은 책을 남겼다. 앞면 3칸·옆면 2칸의 규모이며, 지붕의 옆면이 여덟 팔(八)자 모양인 팔작지붕집이다.","a":"안동삼산정","c":"시도유형문화유산","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640604.jpg"},{"q":"경상북도 경주시 황성동에 있는 신라 제26대 진평왕(579∼632)대의 충신이었던 김후직의 묘이다. 진평왕 2년(580)에 지금의 국방부 장관에 해당하는 병부령을 지냈으며, 진평왕이 사냥만을 즐기고 나라일을 돌보지 않아 중지할 것을 충고하였으나 듣지 않았다. 병이 들어 죽게 되었을 때 세 아들에게 유언을 하여 왕이 사냥 다니는 길목에 묻게 해 죽은 뒤에라도 왕을 깨우쳐 주겠다고 했다. 왕이 이 말을 듣고 크게 뉘우치고 다시는 사냥을 하지 않았다고 하여 충신으로 불려온 것이다. 묘는 흙으로 높게 쌓은 원형봉토분이다. 묘 앞에는 숙종 36년(1710)에 경주의 남지훈이…","a":"경주간묘","c":"시도기념물","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654437.jpg"},{"q":"전북특별자치도 무주군 안성면 공정리에 위치한 이 묘소는 일제와 싸우다 숨을 거둔 의병장 신명선과 그의 부하들이 묻힌 곳이다. 1907년 일본의 강압으로 정미7조약이 체결되어 우리의 군대가 해산당하게 되자 일본의 침략에 울분을 참지 못한 시위보병(侍衛步兵)을 중심으로 전국적인 항일항쟁이 벌어졌다. 시위대 출신 장교 신명선은 전북특별자치도 무주의 덕유산을 거점으로 150여명의 의병을 모집하여 무주·진안·장수 등지에서 일본군과 싸우면서 많은 업적을 세웠다. 1908년 4월 계속된 접전으로 피로가 겹친 의병들이 덕유산의 칠연계곡에서 휴식을 취하고 있던 중 잠복하고 있던 일본…","a":"칠연의총","c":"시도기념물","r":"전북특별자치도","s":"무주군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2020051113545600.jpg"},{"q":"이곳은 함안 조씨 문중에서 1917년 세운 재각으로 집안의 대소사를 의논하거나 제사를 지낼 때뿐만 아니라 마을의 노인들이 모이는 장소로 이용하고 있다. 앞면 4칸·옆면 2칸 규모의 건물로 2층 기단 위에 세워 마당보다 높다. 건물 중앙에 있는 대청마루는 사람이 모일 때 문을 위로 들어 올려 넓은 공간을 마련할 수 있게 꾸몄다. 지붕은 옆에서 보면 여덟 팔(八)자 모양의 팔작지붕이며, 건물 주위에는 각종 나무와 정원석, 연못이 있다. 나무를 다듬은 수법과 서로 짜 맞춘 기법이 매우 우수하며 전형적인 재실의 모습을 보여주는 건물로 관리와 보존이 양호하여 옛 모습을 그대로…","a":"영류재","c":"문화유산자료","r":"전남광주통합특별시","s":"곡성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662155.jpg"},{"q":"지정 대사본인 문수사판은 한국 선종사에 있어서 사상적 이념을 제공한 불교문헌으로 평가되고 있고, 국내에서 ○○○에만 유일하게 소장되어 있는 매우 희귀한 선종문헌의 일종이다.","a":"고양 원각사 달마대사관심론","c":"시도유형문화유산","r":"경기도","s":"고양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637812.jpg"},{"q":"강원특별자치도 원주시 소초면 ○○○ 탑고개의 커다란 암벽에 얕게 선으로 새겼다. 얼굴과 상체, 팔목 등은 총탄 자국으로 훼손되었으나 전체적으로 상태가 양호한 편이다. 정면에서 오른쪽으로 45도 정도 돌려 앉아 있는 옆모습을 새긴 ○○○이다. 신체 각 부분의 비례가 비교적 잘 맞고 통통한 편이다. 얼굴은 비교적 원만하고, 목 뒤로 내려진 머리카락은 어깨에 닿을 듯하다. 상체에 걸친 옷은 3∼4가닥의 선으로 왼쪽 어깨에서 오른쪽 허리로 흐르고 있고, 하체의 옷도 몇 가닥의 선으로만 간략히 표현하고 있다. 양 손은 어깨까지 올려 꽃으로 짐작되는 공양물을 바치고 있는데, 손…","a":"원주평장리마애공양보살상","c":"시도유형문화유산","r":"강원특별자치도","s":"원주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638163.jpg"},{"q":"대전광역시 동구 삼괴동 닭재 위의 북쪽 봉우리를 감싸고 있는 산성으로, 성의 둘레는 220m이다. 성벽은 대부분 허물어져 있으나 남동쪽의 성벽 일부분은 원래의 모습을 유지하고 있다. 밑에서 1.8m까지의 성벽은 안으로 약간씩 오므리며 쌓다가 그 위 1.5m 정도의 성벽은 거의 수직으로 쌓았다. 이곳에서 백제의 것으로 보여지는 토기 조각과 기와 조각 등이 발견되어 건물이 있었음을 짐작할 수 있다. 성안에는 남쪽 성벽 부분에 폭 6∼8m의 평평한 대지가 마련되어 있으며, 북쪽에는 장대로 보이는 시설이 있다. 남쪽벽과 북쪽벽에는 성문터가 보인다. ○○○○은 충청남도 금산군…","a":"계현산성","c":"시도기념물","r":"대전광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645808.jpg"},{"q":"이 성은 ○○○ 8부 능선을 따라 축조된 테뫼성으로서 소가야시대에 쌓은 성(城)이라고 전해지고 있다. 지리적으로 ○○○은 ○○평야의 동쪽에 위치하면서 서쪽을 제외한 동남북 3면이 바다에 둘러 쌓여 있고, 특히 북쪽으로는 임진왜란때 전적지로 유명한 당항포만이 자리할 정도로 남해안을 관망할 수 있는 요충지이다. 성은 자연 암벽사이에 산돌을 이용하여 외벽을 받쳐쌓은 내락수법을 취하고 내벽쪽은 평평한 성내의 도로처럼 평지와 연결되어 있으며, 성벽자체는 곡선을 이룬다. 임진왜란때 화살의 방패로 사용하기 위해서 철마 수십리를 만들어 성내에 세워 두었으며, 왜적이 침입하면서 운반…","a":"고성 철마산성","c":"문화유산자료","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664030.jpg"},{"q":"우석목·무석목·벅수머리 등으로 불리우는 이 석상은 제주목·정의현· 대정현의 성문 입구에 세워졌던 것이나, 현재는 제주도민속자연사박물관· 제주대학·제주시청·제주국제공항· 삼성혈·관덕정 등에 산재하여 있으며 제주시내에 21기, 성읍에 12기, 대정의 인성·안성·보성에 12기 도합 45기가 있다. 석상의 형태는 대체로 벙거지형 모자, 부리부리한 왕방울 눈, 큼지막한 주먹코, 꼭다문 입술 두손은 배위 아래로 위엄있게 얹은 모습을 하고 있다. ○○○○의 크기는 평균 신장이 제주 187Cm, 성읍 141Cm, 대정 134Cm 이며 제작 연대는 영조 30년(1754) 경으로 추정…","a":"돌하르방","c":"시도민속문화유산","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659168.jpg"},{"q":"운강 박시묵의 동생인 박기묵(1830∼1911)이 광무 3년(1899) 합천군수로 있을 때 세운 집이다. 박기묵이 죽은 뒤에 박시묵의 손자 소유였다가 조카인 박재수(1894∼1973)의 소유가 되었다. 이 집은 박재수의 자(字)를 따라 ‘○○○○’이라고 부른다. 대문을 들어서면 오른쪽으로 사랑채가 있고 사랑채 오른쪽에 중문이 있다. 중문 안쪽 정면으로 안채가 보이고 그 좌우에 헛간채와 별당채가 있다. 각 건물은 모두 一자형 건물이며 안마당을 중심으로 전체적으로는 ㅁ자형을 이루고 있어, 영남 평지에 지은 가옥의 대표적인 구조를 보이고 있다.","a":"청도 도일고택","c":"시도민속문화유산","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658983.jpg"},{"q":"이 불화는 북극보전에 산신도, 독성도와 함께 봉안되어 있는 ○○○로서 1886년 4월 판전의 후불탱화(비로자나불화), 산신도와 함께 조성되어 판전에 봉안되었다가 1942년 북극보전으로 이안된 것이다. 치성광여래는 흰 소가 끄는 마차 위 연화대좌 위에 결가부좌하고 있다. 둥근 얼굴에 육계가 뾰족하며, 오른손은 가슴부근으로 들어 올려 손가락을 마주 잡고 왼손은 무릎 위에 놓아 금륜(金輪)을 들고 있다. 소가 끄는 마차에 앉아있는 치성광여래의 도상은 힌두교에서 태양이 백우거(白牛車)를 타고 우주를 1회 돌면 1년이 된다는 설에서 유래한 것으로 중국과 한국 등에서는 일찍부터…","a":"봉은사 칠성도","c":"시도유형문화유산","r":"서울특별시","s":"강남구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636421.jpg"},{"q":"『○○○○』은 그 크기가 세로 33cm, 가로 22cm이며 전후의 표지를 포함하여 39장으로 구성되어 있다. 표지에는 3行에 걸쳐 '옹정원년구월○○○○', '건륭이십사년삼월○○○○', '건륭이십사년십이월객성등록(乾隆二十四年十二月客星謄錄)'이 묵서(墨書)되어 있다. 이 등록은 조선시대의 천문학자들이 실제 관측활동을 통하여 얻은 사실을 구체적으로 기록한 희귀한 자료라는 점과 관상감에 행해지는 측후의 과정 및 참여인원의 규모 등을 알 수 있는 희귀한 자료라는 점에서 한국의 과학사, 특히 천문학사의 연구에 귀중한 자료이므로 서울시 유형문화유산으로 지정한다.","a":"성변등록","c":"시도유형문화유산","r":"서울특별시","s":"서대문구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2593394.jpg"},{"q":"대전광역시 유성구 안산동과 충청남도 공주시 반포면 사이에 있는 해발 226m의 고조산 정상에 쌓은 산성이다. 산봉우리를 둘러싸고 있는 형태로 둘레는 약 600∼800m이며, 성벽 안쪽에 교통호가 일부 남아 있다. 지형을 따라서 쌓아 3층의 계단 모양으로 만들어 3중의 산성처럼 보이는데 백제 때 만들어진 산성에서 흔히 볼 수 있는 형태이다. 현재는 성벽이 조금 남아 있는데, 안쪽 성벽은 높이 1.1m, 바깥쪽 성벽은 높이 6.3m이다. 성안의 가운데에는 둥글게 쌓은 곳이 있는데 창고터로 여겨지며, 북쪽으로 통로가 나있다. 지리적으로 성에서 대전∼조치원간 도로가 잘 보이…","a":"안산동산성","c":"시도기념물","r":"대전광역시","s":"유성구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645799.jpg"},{"q":"○○○ 씨가 소장한 전적은 모두 필사원본(筆寫原本)으로서 조선 후기 및 한말의 정치·경제·사회·법제사 및 재지사족(在地士族)들의 범절과 서예사 연구에 중요한 자료이며, 특히 『훈령(訓令)』은 1895년부터 1901년까지 경상도관찰사가 선산에 하달한 훈령을 비롯하여 탁지부(度支部, 재정담당 중앙부서)와 내무부의 훈령과 칙령 등을 연월순으로 등록, 정리한 것으로 근대 행정사 연구에 귀중한 자료로 평가된다. 그외 고문서는 종류가 다양하며, 각기 일정한 문화유산적, 사료적 가치를 지니고 있으며, 보존상태도 양호하고, 특히 점연문기(粘連文記)와 봉수(烽燧) 관련 문서는 사료적…","a":"선산노진환소장전적","c":"시도유형문화유산","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641101.jpg"},{"q":"○○○ 천왕문 앞에 자리한 ○○○ 일선선사(1533∼1609)의 사리탑이다. 일선선사는 조선 중기의 승려로 서산대사의 제자이며 전북지역내의 불교 보급에 큰 영향을 미쳤다. 탑은 연꽃을 두른 원형의 받침돌 위로 길쭉한 종모양의 탑신을 올린 간략한 형태이다. 탑신 표면에는 아무런 장식도 없고 다만 맨 끝부분을 마치 팽이처럼 뾰족하게 조각하여 마무리하였다. 탑신의 아래에 ‘○○○ 일선탑(靜觀堂 一禪塔)’이라는 탑이름이 있고, 바닥돌 윗면에 ‘만력 37년건(萬曆三十七年建)’이라 적혀 있어, 조선 광해군 원년(1609)에 세운 것임을 알게 되었다.","a":"백련사 정관당 부도","c":"시도유형문화유산","r":"전북특별자치도","s":"무주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639523.jpg"},{"q":"조선 초기의 문신이며 학자인 괴애(乖崖) ○○○ 선생의 ○○이다. 세종 23년(1441)에 문과에 급제하여 세종의 특명으로 집현전 학사가 되어『치평요람』을 편찬하였으며, 그 후『의방유취』편찬에도 참여하였다. 세조 15년(1466)에는 판중추부사에 올랐으며, 성종 2년(1471)에는 좌리공신 4등으로 영산부원군에 봉해졌다. 선생은 학문과 문장에 뛰어나 서거정, 성삼문 등 당대의 학자들과 함께 이름을 떨쳤으며,『사서오경』의 토를 만들고,『명황계감』을 번역하는 등 번역과 간행사업에 많은 업적을 이루었다. 현재 묘역에는 아랫부분에 둘레석을 두른 봉분을 중심으로 앞에는 묘비·…","a":"영동 김수온 묘소","c":"시도기념물","r":"충청북도","s":"영동군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650038.jpg"},{"q":"목포지역은 예부터 내륙과 해상을 연결하는 군사상의 요충지였는데, 목포진은 조선시대 수군의 진영으로 목포영, 목포대라고 부른다. 조선 왕조 때 각 도의 여러 진에 붙은 종 4품의 무관인 만호가 배치되었다고 해서 만호영, 만호진, 만호청이라고 부르기도 한다. 여러 기록을 통해서 볼 때 조선 세종 15년(1433)에 목포병선을 황원(현재 해남)으로 옮기고, 세종 21년(1439)에 현재의 자리에 목포 만호진을 설치하였으며, 개항과 함께 고종 21년(1895)에 폐진된 것으로 보인다. 현재 목포 만호진의 성이나 유적은 거의 남아있지 않다. 원래 위치는 대략 현재의 목포시 만…","a":"목포진지","c":"문화유산자료","r":"전남광주통합특별시","s":"목포시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662089.jpg"},{"q":"목이 길고 무게중심이 아래에 있는 전형적인 19세기 백자 병이다. 구연부(口緣部)의 끝이 작고 둥글게 마무리되어있고 목이 곧고 일정하며 몸체 아랫부분이 넓게 퍼져 풍만한 양감과 안정감을 보여주고 있다. 푸른빛을 머금은 유약(釉藥)과 태토(胎土)가 상품갑번(上品甲燔)에 속한다고 판단된다. 이 ○○○○는 분원기(分院期)의 자기로서는 드물게 세필(細筆)로써 성새(城塞)와 산수(山水)를 표현하고 있는데 강상(江上)의 전경(全景)을 다양한 소재를 가지고 표현한 점이 특징적이다. 표면에는 깔끔한 백유(白釉)가 전면 시유(施釉)되어 있으며 청화(靑畵)의 발색(發色)도 선명하다.…","a":"청화백자성새산수문병","c":"시도유형문화유산","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2590215.png"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 법곡동에 있었으나 임진왜란 때 소실되었고 그 뒤 광해군 2년(1610)에 지금 있는 자리로 옮겨 세웠다. 전체적인 구조는 전학후묘의 전형적인 형태로 앞쪽에는 교육 공간을, 뒤쪽에는 제사 공간을 두었다. 입구에는 하마비·홍살문이 있고 외삼문을 지나면 정면에 교육 공간인 명륜당과 기숙사인 동재가 있다. 명륜당 뒤쪽 내삼문을 지나면 정면에 제사 공간인 대성전이 있다. 명륜당은 앞면 5칸·옆면 2칸의 규모이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 화려한 팔…","a":"온양향교","c":"시도기념물","r":"충청남도","s":"아산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652900.jpg"},{"q":"○○○에 모셔져 있는 철로 만든 여래좌상으로 높이 1.03m, 무릎 너비 0.8이다. 머리에는 작은 소라 모양의 머리칼을 붙여 놓았으며, 그 위로 상투 모양의 머리묶음이 낮게 표현되었다. 4각형에 가까운 얼굴은 눈이 작은 편이며 귀는 어깨까지 길게 내려오고 있다. 옷은 왼쪽 어깨를 감싸고 있으며 옷깃이 왼쪽 어깨에서 수직으로 내려오고, 왼쪽 겨드랑이 부분에 매듭이 보인다. 옷주름은 매듭에서 오른쪽 허리를 향하여 비스듬하게 표현되었다. 손모양은 오른손을 어깨높이로 들어 엄지와 중지를 맞대고 있고, 왼손은 무릎 위에 굽혀들어 손바닥을 위로 하여 역시 엄지와 중지를 맞대고…","a":"대복사철불좌상","c":"시도유형문화유산","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639390.jpg"},{"q":"이 정자는 구휼(救恤)사업 및 육영(育英)사업과 독립운동가(獨立運動家)의 지원(支援)을 펼친 현장(現場事業處)로서 수봉 이규인(秀峯 李圭寅)(1859～1936) 선생이 1924년 서당(書堂)인 비해당(匪懈堂)과 약국(藥局)인 보인재(輔仁齋)를 갖춘 2층으로 건립하였으나 1953년 현재와 같이 단층으로 개수되었다. 선생은 사립(私立)의 경주고등보통학교(慶州高等普通學校)를 설립하여 구국(救國)의 인재(人材)를 양성하려 하였으나 끝내 조선총독부(朝鮮總督府)에 수탈(收奪)되어 경주공립중학교(慶州公立中學校)로 개교되고 말았다. 그러나 광복(光復) 후 선생의 유지(遺志)대로 사…","a":"수봉정","c":"시도기념물","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654567.jpg"},{"q":"경상남도 ○○시 장목면에 있는 이 성은 동쪽을 제외한 3면이 산으로 둘러싸인 계곡에 돌로 쌓은 성이다. 성 밖에는 민가가 있고 안은 경작지로 사용하는 등 주변 형태를 쉽게 파악할 수 있다. 문터에는 성문을 보호하기 위해 쌓은 작은 성이 북쪽과 남쪽에 있는데, 남쪽은 그런대로 남아 있으나 북쪽은 겨우 흔적만 남아 있다. 원래 외포 바닷가에 성을 만들었는데 이곳으로 옮겼다고 하며 『신증동국여지승람』○○조에는 율포부라 불렀다고 한다. 『○○군지』에 보면 숙종 14년(1688) 통제사 이세현이 글을 써 올려 이곳에 성을 만들고 무종 9품의 권관을 두어 방어케 하였다고 한다.…","a":"거제 구율포진성(1998)","c":"시도기념물","r":"경상남도","s":"거제시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656608.jpg"},{"q":"자라올이라 불리는 오촌 마을 동쪽 야산지대와 무동산 남쪽 산등선과 서쪽 산줄기에 밀집된 무덤들이다. 1978년 행해진 발굴조사에 의하면 삼국시대의 것으로 확인된 무덤이 총 211에 이르렀으나 거의 파괴되었다. 봉토는 없으나 지표에서 50∼80㎝ 내외의 땅속으로 들어가면 무덤의 뚜껑돌(개석상면)이 확인된다. 돌방(석실)은 서남쪽으로 향해있으며, 널방(현실)과 널길(연도)는 완전한 모습을 갖추고 있다.","a":"초촌리고분군","c":"시도기념물","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653484.jpg"},{"q":"○○○○○은 극락전 앞에 자리하고 있으며, 그 높이는 2.5m이다. 원래 대웅전 앞에 있었으나, 1973년 현재의 위치로 옮겨 세웠다. 석탑의 하층 기단은 여러 장의 판석을 이용하여 결구하고 사방에 안상을 조각하였다. 그 상부에는 4매의 판석으로 구성하여 상층기단을 올렸다. 기단의 면석에는 2개의 우주(隅柱)와 1개의 탱주(撑柱)가 새겨져 있다. 탑신석과 옥개석은 각각 하나의 석재로 구성되어 있다. 탑신석에는 양 우주가 정연하게 새겨져 있으며, 상층으로 갈수록 정연한 체감비를 느낄 수 있다. 옥개석의 하면에는 각형 4단의 옥개받침이 있으며, 상면에는 3단의 받침을 새…","a":"석남사삼층석탑","c":"시도유형문화유산","r":"울산광역시","s":"울주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637254.jpg"},{"q":"경상남도 ○○시 장목면 해안에 있는 구영마을 남쪽 야산 기슭에 평면 원추형태로 쌓은 성이며, 성벽의 안팎에는 경작지와 민가가 자리잡고 있다. ○○도의 가장 북쪽으로 진해, 웅천 등 육지와 가장 인접하며 주변에 영등왜성, 구율포성 등 성곽 유적이 많이 분포하고 있다. 지금 성벽은 대부분 훼손되고 기단부만 남아 있는 상태지만 구조와 쌓은 수법은 어느 정도 확인이 가능하다. 남북 양쪽에 반원형으로 된 옹성(성문을 보호하기 위하여 성문 밖으로 쌓은 작은 성)을 쌓았는데 그 출입문이 한쪽 옆에 있다. 성의 바깥벽은 큰 돌로 쌓고 안쪽 벽은 돌을 지면에 겹쳐 쌓은 뒤 크고 작은…","a":"거제 구영등성","c":"시도기념물","r":"경상남도","s":"거제시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656596.jpg"},{"q":"이 책판은 고려 충선왕과 공민왕 양대에 걸쳐 고관을 지낸 익재 이제현(1287∼1367)의 문집을 새긴 목판이다. 이 책판은 사간본으로 숙종 19년(1693)에 간행되었으며, 147매이다. 이제현 선생은 원나라의 만권당에서 조맹부 등과 교류하며 고려에 신학문과 사상을 소개하고, 성리학을 전파, 발전시키는데 중요한 역할을 하였다. 저서로 『국사』,『역옹패설』 등을 남겼다. 『익재집』은 여러 차례에 걸쳐 간행되었다. 초간본은 공민왕 12년(1363), 재간본은 세종 14년(1432), 세번째로 선조 33년(1600)에 간행되었다. 하지만 이것들은 지금까지 전해지지 않는다…","a":"익재집책판","c":"시도유형문화유산","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640757.jpg"},{"q":"○○○는 통일신라 후기의 대학자인 최치원 선생이 세상을 피해 지리산에 들어가기 전 낚시를 즐기던 곳이라 전하고 있다. 바위에 ‘○○○치원서(靑龍臺致遠書)’라는 글자를 새겨 놓았는데, 글씨체로 보아 최치원의 친필로 여겨진다. 최근 후손들에 의해 이를 기리는 ○○○비(靑龍臺碑)가 건립되었다. 당시에는 이곳에 밀물과 썰물이 드나들었다고 하나, 지금은 뭍(육지)으로 변하였다.","a":"창원 청룡대 각석","c":"시도기념물","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656374.jpg"},{"q":"○○○○는 사찰 입구에 설치하는 것으로, 절에 행사나 의식이 있을 때면 당이라는 깃발을 달아 두는데, 이 당을 꽂아두는 길다란 장대를 당간이라 하고, 당간의 양쪽에 서서 이를 지탱시켜주는 두 돌기둥을 ○○○○라 한다. 드물게 당간이 있으나 대부분 두 기둥만 남아있다. 이 ○○○○는 마을 입구의 민가 뒷돌담에 서 있다. 남아있는 상태가 그리 좋지 않아서 한쪽 기둥은 잘린 채 떨어져 있고, 다른 한쪽도 파손이 심하다. 기둥의 받침대는 여러 개의 돌로 조립되어 있으며, 옆면에 연꽃무늬를 새겨 놓았다. 마주보는 면에는 아래위 두 곳에 당간을 고정시키기 위한 홈을 파놓았다.…","a":"공주상신리당간지주","c":"시도유형문화유산","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639157.jpg"},{"q":"○○○ 대웅전 앞에 서있는 탑으로, 2층 기단(基壇) 위에 4층의 탑신(塔身)을 올린 모습이다. 기단은 아래·위층이 거의 비슷한 높이인데 보통 아래층 기단이 낮고 위층 기단이 높은 일반적인 탑들과는 형태를 달리하고 있다. 탑신의 1층 몸돌은 면마다 불상을 조각하였다. 지붕돌은 몸돌에 비해 큰 편으로 네 귀퉁이가 위로 들려 있다. 꼭대기에는 머리장식의 일부가 놓여 있다. 통일신라 헌안왕 3년(859) 부처님의 진신사리를 모시기 위해 도선국사가 세운 탑이다. 기단에 비해 탑신이 가늘어 가냘픈 감을 주며, 탑신의 몸돌에 비해 지붕돌이 커서 불안정해 보인다. 전하는 말에 따…","a":"청암사다층석탑","c":"문화유산자료","r":"경상북도","s":"김천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662631.jpg"},{"q":"해촌 남극만 선생이 조선 영조 31년(1755) 세운 집으로, 고종 15년(1878) 고쳐 지어 오늘에 이르고 있다. 왼쪽 3칸에 중간문과 아랫방을 배치하였고, 오른쪽에는 1칸 규모의 작은 사랑방을 두었으며 그 뒤쪽으로는 큰 사랑방을 놓았다. 작은 사랑방의 앞면과 오른쪽면으로는 각 1칸 반 규모의 사랑마루를 꾸며 놓았다.","a":"영덕 괴시동 해촌고택","c":"시도민속문화유산","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658969.jpg"},{"q":"○○○○은 용운마을의 동남쪽에 위치하는데 여기에서 동남쪽으로 내려오는 줄기는 다시 37.5m의 작은 동산을 형성하고 남서쪽으로 내려오다 다시 높아져 정상을 형성하고 있는데 여기에 1호분이 있고 남서쪽 아래로 2m 정도의 간격을 두고 2호분이 있다. 따라서 2기의 고분은 구릉성 산줄기의 정상과 남서쪽 능선상에 위치하고 있어서 주변지역이 잘 조망된다. 1호분은 구릉의 정상부에 위치하고 있는데, 분정에는 2.2×0.8m의 장방형 구덩이가 있다. 분구의 평면형태는 원형이며 규모는 직경 15m, 너비 1.8m이다. 2호분은 구릉의 남서쪽에 있는 고분으로 분구가 거의 삭평되어…","a":"해남방산리독수리봉고분군","c":"문화유산자료","r":"전남광주통합특별시","s":"해남군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2019052110004700.JPG"},{"q":"1910년도에 초창된 다포팔작식 목조건물인데 망우당 곽재우 장군과 17장령의 증직명과 관향 등이 적힌 명판을 부착한 ○○○으로서 어느 한 곳에도 쇠못을 사용하지 않은 우리나라 전통 목조건물의 건축양식으로 지어졌으며, 조선후기 건립된 다포팔작양식으로 극락세계를 염원하는 상여모양을 본뜬 건물이다.","a":"의령 충의각","c":"문화유산자료","r":"경상남도","s":"의령군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666725.jpg"},{"q":"창녕 조씨 재실인 모선재의 비각안에 모셔둔 비이다. 조선 중종 때의 문신인 조치우 선생의 부인에게 내린 비로서, 임금이 하사한 것이라하여 ‘○○○○’라 불리운다. 비는 비몸과 머릿돌을 한돌고 다듬어 세워 놓았다. 조치우는 대구부사를 지낸이로, 청렴결백하고 공이 뛰어나 청백리에 올랐다. 부인과 함께 옥비를 하사받았는데 그의 비는 경북 영천군에 보존되어 있다.","a":"창원 어사옥비","c":"문화유산자료","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664230.jpg"},{"q":"○○○는 지었을 당시의 정확한 기록은 알 수 없고, 고려 선종 6년(1088)에 의천이 다시 지었다고 한다. ○○○의 본래 이름은 장육전으로 통일신라 경문왕 원년(861)에 다시 지었으나 임진왜란 때 소실되어 현종 1년(1660)에 복원하였고, 다시 영조 36년(1760)에 고쳐 세워 오늘에 이르고 있다. 경내 가장 구석진 곳에 있는 ○○○은 앞면 1칸·옆면 1칸 규모의 작은 전각이다. 지붕은 옆에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 꾸몄다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 기둥 위와 기둥 사이에도 있는 다포 양식으로 규모는 작으나 화려한 멋을…","a":"선암사각황전","c":"문화유산자료","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662169.jpg"},{"q":"조선 헌종(재위 1834-1849)이 진주 하씨 집안 대대로 충효가 지극한 것을 칭찬하고자, 학행과 효성이 지극한 하준호에게 ‘운초재’라는 호를 짓고 목판에 새겨 내려주면서 세운 건물이다. ○○○은 임금이 직접 글씨를 써서 내려준 건물이라는 뜻이다. 왕의 글씨가 담긴 목판뿐만 아니라, 당시 영의정이었던 전병국이 쓴 『운초재』서문과 신응조가 쓴 『○○○명병기』를 목판에 새겨 함께 보존하고 있다.","a":"장포리어필각","c":"문화유산자료","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661760.jpg"},{"q":"○○○○○는 건립연대가 정조 14년(1790)으로 확인되는 바 시기상으로 보아 200년 이상이 되었고, 형태면에서도 18세기 후기에 많이 보이는 비석형태를 보여주고 있다. 특히 옥개석 양측면에 조각되어 있는 쌍조(雙鳥)의 모습과 옥개석 앞뒤 밑부분에 2단씩 조각되어 있는 연목(椽木, 서까래) 형식은 목조가옥이 지붕을 연상케 해 주어 독특한 감이 있다. 이 비석의 비문 내용으로 보아서 ○○○○의 유래와 배향인물 19명의 내력을 기록하고 있다. 비문의 경우 친자인 이복원(李福源)은 후일 정조 때 우상(右相)과 좌상(左相)을 역임한 인물로 학행이 있었고, 글쓴이 조윤형(曺…","a":"창녕 물계서원 원정비","c":"문화유산자료","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665286.jpg"},{"q":"이곳은 A.D 42년 낙동강을 중심으로 일어난 여섯 가야(伽倻) 중 하나인 ○○○○ 태조의 무덤이라고 전해오고 있다. ○○○○는 낙동강 일대인 함창, 문경, 가은 지방을 영역으로 하여 세워진 나라로,『삼국유사』의 5가야조와『삼국사기』의 고령군조에 그 이름이 보이고 있다. 조선 선조 25년(1592) 당시 경상도 관찰사 김수와 함창 현감 이국필 등이 묘 앞에 묻혀 있던 묘비를 발견하여 ○○○○임을 확인했다고도 전해오고 있다. 그 후 조선 숙종 38년(1712) 왕명으로 묘비와 석양(石羊) 등의 석물을 마련한 후 후손들에 의해 여러 차례 묘역이 정비되어 오늘에 이르렀다.","a":"전고령가야왕릉","c":"시도기념물","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654431.jpg"},{"q":"이 영정은 ○○○○○선사의 좌안7분면 바닥가부좌상으로, 돗자리위에 방석을 깔고 왼손엔 목리문이 그려진 주장자를 쥐고, 오른손은 염주를 가볍게 쥐고 앉아 있다. 화면은 주색의 연속당초화문이 그려진 상단벽면과 돗자리의 이단구도로 이루어져 있다. 장삼과 가사의 의습선 주변으로는 가볍게 농담을 주어 음영을 자연스럽게 표현하고 있다. 화면 향좌측에 ‘○○○○○대선사진(喚應堂敏悅大禪師眞)’의 화제가 있으며, 화면 크기는 가로 75.2cm, 세로 121.0cm이다.","a":"환응당 민열 진영","c":"시도유형문화유산","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001643025.JPG"},{"q":"함양 ○○○ 삼성각에 봉안되어 있었던 이 山神幀은 현재 사측에서 별도 보관 중이다. 絹의 틈이 넓은 명주를 바탕재료로 하여 액자 형태로 제작되어 있는 이 탱화의 화면에는 산신이 호랑이 등에 타고 앉아있는 모습을 그려져 있으며, 뒷면에는 朱書된 全身舍利寶篋多羅尼가 있고, 다시 그 아래쪽에는 墨書된 銘文이 附記되어 있다. 그리고 이 ○○○은 조성 당시에 화면을 액자틀에서 조금 비스듬히 구획하였던 것이 후대로 오면서 틀의 뒤틀림과 함께 화면이 향좌측으로 조금 더 비틀어져 있기도 하다. 또한 제작된 지 오랜 세월의 경과와 관리소홀로 인하여 화면 하단 호랑이 부분과 상단 향우…","a":"함양영각사산신탱","c":"문화유산자료","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666499.jpg"},{"q":"보백당 김계행(1431∼1517)이 말년에 독서와 사색을 위해 지은 정자이다. 김계행은 조선 전기의 청렴결백한 관리로 뽑혔던 분으로, ‘내 집에 보물이 있다면 오직 맑고 깨끗함 뿐이다.’라는 가르침을 남겼다. 규모는 앞면 3칸·옆면 2칸이며, 앞면을 마루 형식으로 개방하여 자연경관을 감상할 수 있도록 하였다. 양쪽에는 온돌방을 두어 학문의 공간으로 활용하였다. 16세기 초에 지은 이 정자는 자연과 조화를 이루는 아름다움을 보여주고 있으며, 특히 그 아래 떨어지는 폭포는 장관을 이룬다. 정자 아래 바위에는 ‘보백당○○○천석(寶白堂晩休亭泉石)’이란 큰 글씨를 새겨 놓았다…","a":"만휴정","c":"문화유산자료","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662748.jpg"},{"q":"○○○는 횃불과 연기를 이용하여 급한 소식을 전하던 옛날의 통신수단을 말한다. 높은 산에 올라가서 불을 피워 낮에는 연기로 밤에는 불빛으로 신호를 보냈다. 남산 ○○○는 조선 태조 3년(1394)에 도읍을 한양으로 옮긴 뒤 설치하여, 갑오경장 다음해까지 약 500년간 사용되어 왔다. 남산의 옛 이름을 따서 ○○○○○라 하기도 하고, 서울에 있다하여 경○○○라 부르기도 하였다. 평상시에는 1개, 적이 나타나면 2개, 적이 경계에 접근하면 3개, 경계를 침범하면 4개, 경계에서 아군과 전투를 벌이면 5개의 불을 올리도록 하였다. 남산 ○○○는 전국의 봉수가 도달하게 되는…","a":"목멱산봉수대터","c":"시도기념물","r":"서울특별시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1644792.jpg"},{"q":"의성 김씨로 처음 이곳에 터전을 잡아 살기 시작한 김근(1579∼1656) 선생의 위패를 모시고 있는 사당이다. 5대에 걸쳐 양양, 진성, 안망 등지를 옮겨다니던 생활을 청산하고, 광해군 7년(1615) 그의 나이 37세 때 터를 잡아 후손들이 이곳에 정착하게 되었다. 선생은 인조 20년(1642) 진사시에 합격한 뒤 벼슬을 단념하고 학문에만 전념하였다. 그를 가리켜 정현광 선생은 ‘유림노성(儒林老成)’이라 칭찬하였다. 그 뒤 후손인 김굉이 주도하여 정조 15년(1791)부터 4년에 걸친 공사 끝에 사당 건물을 비롯하여 동재·서재와 강당을 20여칸 규모로 마련하였다고…","a":"구암정사","c":"시도기념물","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654555.jpg"},{"q":"○○○에 있는 옛집으로 곱은자 모양의 안채와 一자 모양의 곡간채 및 문간채로 구성되어 있다. 안채 뒤에 사랑채가 있었지만 지금은 흔적만 있으며, 건넌방이 사랑채의 기능을 대신하고 있다. 부엌 앞에는 고방을 두어 식료품을 저장하는데, 부엌과 고방 사이에는 판자벽을 둘렀다. 이러한 기법은 오래된 집에서만 볼 수 있는 양식이다. 문간채 주위에는 담장을 둘러 바깥마당과 구분하고, 대문간에도 담을 설치하여 밖에서 집안을 들여다보지 못하도록 하였다. 특히 안채와 곡간채 사이에도 담장을 둘러 사랑채 역할을 하고 있는 건넌방의 독립성과 아늑한 분위기를 조성한 점이 특이하다.","a":"제천 지곡리 고가","c":"시도유형문화유산","r":"충청북도","s":"제천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638525.jpg"},{"q":"<○○○○○>은 고종 21년 11월 18일 조선과 독일 사이에 수교된 전문 13조의 ○○○○문으로 조덕수호○○○○, 부속통상장정, 세칙, 세칙장정, 선후속약의 한문 필사본 1책 32장, 영문 필사본 1책 45장, 독어 필사본 1책 45장으로 이루어져 있다. 이 책은 고종 21년(1884년) 8월 17일 창덕궁에서 조선과 ○○○ 즉 독일 사이에 이루어진 수교내용을 담은 문서로, 양국간에 우호적인 입장에서 서로 왕래하며 통상하자는 것이다. 그 수단으로 서로의 신분을 보장하고, 재산을 보호하며 총영사관과 부영사제를 설치하여 통상구역 안에 주차(관리가 공무로 다른 나라에 머…","a":"대조선국ㆍ대덕국 통상조약(한문, 영문, 독문)","c":"시도유형문화유산","r":"서울특별시","s":"서초구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2587966.jpg"},{"q":"조선시대 만들어진 높이 111㎝, 입 지름 84㎝의 종이다. 종은 정조 7년(1783)에 제작된 것으로 소리울림을 도와주는 음통은 없으며, 종을 매다는 고리는 2마리의 용으로 되어 있다. 몸체 가운데에 4개의 유곽이 독립적으로 배치되어 있고, 유곽 사이의 빈 공간에는 보살상이 새겨 있다. 문양의 조각기법이 조잡하고 표면은 거친 편이나, 조선시대 ○○ 연구에 중요한 자료가 된다.","a":"창원 성주사 동종","c":"문화유산자료","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664572.jpg"},{"q":"○○○○은 300여년 전 김굉필의 후손들이 세운 것으로, 그 뒤 묘각이나 서당으로 사용하였다. 조선 고종 3년(1866)에는 김굉필의 둘째 아들 언상공을 비롯한 4명의 위패를 모시고 서원으로 지었으나, 고종 5년(1868) 흥선대원군의 서원철폐령으로 폐쇄되었다. 지금 있는 정당은 1916년에 규모를 넓게 수리한 것이다. 경내에는 정당을 비롯하여 사당, 동재, 서재, 문루, 관리사 등이 있다.","a":"창녕 구니서당","c":"문화유산자료","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664470.jpg"},{"q":"목판본으로 된 5침 선장본이다. 표지 서명은 『법어(法語)』로 되어 있으나, 원책명은『몽산화상법어약록』이다. 이 책은 부처님의 말씀이나 가르침을 적어놓은 것으로, 승려들의 수행서이다. 원(元)의 고승(高僧) 몽산(蒙山) 덕이(德異)의 법어를 고려때 보제존자(普齊尊者)가 초록(抄錄)하고 혜각존자(慧覺尊者)가 12결(訣)로 한역하였다. 조선조 덕종의 비인 인수대비(1437~1504)는 불교에 조예가 깊어 1471년(성종 2)에 명(明)에 가서 불경을 구입하게 하고, 1472년(성종 3)에는 세조와 예종, 의경왕의 명복을 빌기 위해 『묘법연화경』 등 29종 2,815부의…","a":"중편현수법수","c":"시도유형문화유산","r":"경상남도","s":"사천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001643208.JPG"},{"q":"○○○은 언제 지었는지 정확한 기록이 없으나, ○○○ 양돈(1461∼1512)의 호로 미루어 그가 생존시에 지은 것으로 추정한다. 양돈은 성종 9년(1498) 사마시에 합격하였으나 무오사화로 봉현리에 낙향하였다. 그의 문장과 덕행은 뛰어나 당시 모범이 되었고, 남효온의 추천으로 조정에서 벼슬을 내렸으나 이를 거부하고 조용히 세상을 살았다. 원래 정자는 삼계면 후천리 광제 마을에 있었으나, 고종 9년(1872)에 지금 있는 자리로 옮겨 지었다. ○○○은 앞면 3칸·옆면 2칸 규모이며, 정자 한 가운데에 온돌방이 하나 있는 점이 특징이다. 계단식 축대 위에 정자가 있으며…","a":"광제정","c":"문화유산자료","r":"전북특별자치도","s":"임실군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661763.jpg"},{"q":"요지는 자기나 기와, 그릇들을 만들어 굽던 가마터를 말한다. ○○○ 사기마을과 마을 뒷산에 4개의 가마터가 있는데, 이중 1개는 통일신라시대의 것이며, 나머지 3개는 분청사기와 백자를 굽던 조선시대의 것이다. 임진왜란 때 일본인들이 이곳의 가마를 파괴하고 도공들을 납치해 갔다고 전해진다. 이곳에서 출토되는 그릇의 종류는 대접, 접시, 사발, 병, 항아리, 장군, 잔 등 다양하며, 주로 생활용 그릇들을 굽던 곳으로 보인다. 도자기를 만드는 바탕흙인 태토는 회색인데 모래 같은 불순물들이 많이 섞여 있으며, 거칠고 어두운 회청색을 띤 유약을 두껍게 칠하였다. 특히 주목되는…","a":"하동 백련리 도요지","c":"시도기념물","r":"경상남도","s":"하동군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654816.jpg"},{"q":"강원특별자치도 원주시 흥업면 ○○○ 연세대학교 원주캠퍼스 앞의 저수지 가운데 있는 거북섬 꼭대기에 세워져 있다. 원래 저수지의 상류 논둑에 위치하였으나 수몰로 인해 1956년 현위치로 옮겼다고 한다. 전체를 하나의 돌로 조각하였는데, 발목 아랫부분은 땅에 묻혀 있다. 두 볼이 통통한 사각형의 얼굴에는 코와 입이 작게 표현되어 있고 약간 가운데로 몰려 있다. 귀에는 귀걸이가 장식되어 있고, 목에는 3줄의 삼도(三道)가 그어져 있다. 보발(寶髮)은 끝이 약간 잘려 나갔는데, 정수리 부분의 윗면이 판판하고 그 중앙에 구멍이 있는 점으로 보아 원래 보관(寶冠)이 있던 것으로…","a":"원주매지리석조보살입상","c":"시도유형문화유산","r":"강원특별자치도","s":"원주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638169.jpg"},{"q":"* 특이 사항 -kbs 정문 (남) : 왼손을 가슴위에 올려놓고 있다. -kbs 정문 (북) : 왼손을 가슴위에 올려놓고 있다. 기단은 원래 없었으나 후에 만들어 세웠다.","a":"돌하르방","c":"시도민속문화유산","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659153.jpg"},{"q":"이 ○○은 임진왜란 때 이순신 휘하에 있으면서 여러 해전에서 많은 전공을 세워 전후에 선무원종공신에 책록된 이응표(1555~1611)와 그 후손의 전적 및 ○○이다. 『선무원종공신녹권』은 병자호란 이전의 간본으로 여기에 수록된 공신은 임진왜란의 양상을 연구하는 데 중요한 자료이다. 또한 이응표 부자의 교지 및 유서, 호구단자 등의 고문서는 해당 시대의 사회경제적 이면을 이해하는 데 중요한 자료이다.","a":"포항 합천이씨 전서공파 소장 유물","c":"시도유형문화유산","r":"경상북도","s":"포항시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641213.jpg"},{"q":"조선 중종 38년(1543)에 당시 전라도 관찰사였던 규암 송인수가 왕명을 받들어 지지당 송흠을 위하여 관수정 건너편에 지은 정자이다. 병자호란과 화재를 당하여 폐허가 되었다가 철종 7년(1856)에 송인수의 10대손인 송겸수가 영광군수로 부임하여 고쳐 지었다. 건물은 앞면 2칸·옆면 2칸 규모로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 꾸몄다. 바닥에 마루를 깔아 대청으로만 구성되어 있으며 사방을 낮은 평난간을 돌렸는데, 땅의 위치가 높아 누마루의 높이가 상대적으로 낮다. ○○○은 용암천 위의 경치가 아름다운 경승지에 자리잡고 있다.","a":"장성 기영정","c":"문화유산자료","r":"전남광주통합특별시","s":"장성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662037.jpg"},{"q":"조선 중종(재위 1506∼1544) 때 학자이자 서화가인 학포 양팽손의 서재였으나 지금 있는 건물은 당시의 건물이 아니고 1920년대에 후손들이 지은 것이다. 양팽손(1488∼1545)은 조선 중기 문신으로 중종 11년(1516) 과거에 급제한 후 정언, 전랑, 수찬, 교리 등의 직을 역임하였다. 중종 14년(1519) 기묘사화로 관직을 잃은 뒤 고향으로 내려와 1521년 ○○○을 짓고 제자들을 가르치며 시와 그림으로 하루를 보냈다. 글과 그림에 능하였으며 저서로는 『학포유집』 2책이 전하고 있다. 1994년 ○○○을 보수하였고, 1995년에 외삼문을 원래대로 지었다…","a":"학포당","c":"시도기념물","r":"전남광주통합특별시","s":"화순군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654243.jpg"},{"q":"제주도의 고인돌은 한반도와는 달리 청동기시대가 아닌 탐라시대에 만들어진 거석문화유산으로 북방식․남방식․개석식(무지석식)으로 구분된다. 이 ○○○는 남방식고인돌 형식을 취하고 있으며, 장축 방향은 북서쪽이다. 상석 아래 지석은 작은 괴석이나 할석으로 6매가 상석 주변을 돌아가면서 고여 있고, 남동쪽은 이중으로 고여 있어, 매장시설은 지하에 두었던 것으로 추정된다. 뚜껑돌의 장축 242cm, 단축 185cm, 두께 60cm이며, 축조 시기는 탐라국시대 로 추정된다.","a":"하모리지석묘","c":"시도기념물","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657733.jpg"},{"q":"규모가 다소 작고 지대석과 기단부의 면석 및 답신석 등이 결실되어 있으나 남아있는 석탑부재들이 도드락다듬으로 치석되었으며, 운모와 장석이 자연스럽게 마모되어 있는 조성 당시의 것이고 특히 노반 및 복발이 온전하게 잘 남아 있어 고려 말에 조성된 석탑의 좋은 자료이다.","a":"김해 영구암 삼층석탑","c":"문화유산자료","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666584.jpg"},{"q":"조선 정조 19년(1795)에 왕이 내린 불교식 가사(歌辭)로, 손수지어 용주사에 내린 게송이다. 원래의 명칭은 『어제화산용주사봉불기복게』인데, 화산의 용주사에 부처를 모시고 복을 기원하는 글이라는 뜻이다. '기복게'는 서문과 본문으로 이루어져 있다. 서문에는 정조사 용주사를 건립하게 된 배경과 삼업(三業) 공양을 바치고 복전(福田, 부모가 양육한 은혜)에 보답하기 위해 게송을 지었음을 밝혔다. 이어지는 게송은 오언절구 형식으로 총 10수 이다. 용주사에는 ‘기복게’ 필사본과 목판 9매가 전한다. 필사본 ‘기복게’는 2책인데, 종이로 장황한 것과 비단으로 장황한 것이…","a":"전적수사본","c":"시도유형문화유산","r":"경기도","s":"화성시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637360.jpg"},{"q":"향교는 지방에 설립한 국립교육기관으로서，성현의 위패를 모시고 제사를 지내는 기능과 학생을 교육하는 강학 기능을 동시에 담당하였다. ○○○○는 조선 태조 7년(1398)에 처음 지었으나 임진왜란 때 불타 없어졌다．선조 32년(1599)에 달성공원 근처에 다시 세웠다가 선조 38년(1605) 교동으로 옮겼고，1932년 지금 있는 자리로 옮겨 세운 것이다. 지금 남아 있는 건물로는 ○○○·명륜당·동재·서재·문묘·삼문 등이 있다. ○○○○로 들어서면 교육 공간인 명륜당과 학생들이 숙식하는 동재·서재가 있으며，내삼문을 열고 뒤채로 들어서면 제사 공간인 ○○○이 나타난다. ○○…","a":"대구향교대성전","c":"문화유산자료","r":"대구광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659447.jpg"},{"q":"손님이 묵고 가기 위한 숙소로 1922년 은진 송씨 문중에서 지었다. 원래는 현재 위치에서 남서쪽으로 1㎞ 정도 떨어진 유전리에 세웠으나, 1985년 ○○댐 건설로 지금 있는 자리에 옮겨 지었다. 건물은 앞면 4칸·옆면 3칸 규모의 2층 기와집으로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 누각에는 둥근기둥(두리기둥)을 사용하였으며, 사방으로 난간을 설치하였다. 마루 중앙에는 앞면 2칸·옆면 1칸 규모의 온돌방이 있다.","a":"합천 사의정","c":"문화유산자료","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664056.jpg"},{"q":"○○○의 효행에 대해서는 『모재실기(慕齋實記)』와 「상서문(上書文)」에 잘 나타나 있다. 더구나 정려기를 지은 단계(端磎) 김인섭(金麟燮)은 성재(性齋) 허전(許傳)의 문인(門人)으로 문과(文科)에 급제하여 사간원(司諫院)의 헌납(獻納)을 지냈던 인물이며, 효자 ○○○과 같은 지역의 동시대 인물이므로 그가 지은 정려기는 신필(信筆)이라 하기에 손색이 없다. 그리고 정려(旌閭)가 되기까지의 과정 및 그 이후의 세역(稅役) 면제(免除) 관련 사항까지 알 수 있는 다섯 점의 고문서가 갖추어져 있으므로 문화유산로서 가치가 있다.","a":"정용균 효행문서 및 정려비","c":"문화유산자료","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665084.jpg"},{"q":"통례원 봉례를 지낸 황전이 세종 11년(1429)에 학문을 연마하고 지방 유생들을 가르치기 위해 세운 건물이다. 그 후 영주지역 창원 황씨를 중심으로 사림들이 영조 11년(1735)에 사당으로 다시 지었으며 현재의 건물은 정조 2년(1778)레 고쳐 지은 것이다. 앞면 3칸·옆면 1칸 규모이며 지붕은 옆면에서 볼 때 사람 인(人)자 모양을 한 맞배지붕의 단아한 건물이다. 가운데 마루가 있고 양 옆에 온돌방을 배치하였다.","a":"첨모당","c":"문화유산자료","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663129.jpg"},{"q":"고흥 ○○○ 산성은 고흥군 남양면 ○○○와 중산리 일대에 있는 해발 162m의 산 정상부를 감싸고 있는 산성으로 동서 양쪽의 바다를 조망할 수 있는 위치이다. 이 지역 일대는 백제시대에 조조례현(助助禮縣)이 있었던 곳이다. 조조례현은 통일신라 경덕왕대에 이르러 충렬현(忠烈縣)이 되었다가 다시 고려시대에 이르러 남양현(南陽縣)으로 이름이 바뀌었다. ○○○ 산성은 돌을 쌓아 만든 산성이며, 총 둘레는 534m이고, 너비는 4m내외이다. 산성의 평면형태는 부정형으로 남북이 동서에 비해 길며, 성벽은 동벽과 북벽 일부가 잘 남아 있다. 성 안은 북서쪽에서 남동쪽으로 완만하게…","a":"고흥남양리산성","c":"시도기념물","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2020052414105500.JPG"},{"q":"경기도 양주 장흥면 삼하리 ○○○ 계곡의 자연 암반 9곳에 새겨진 글씨이다. 새겨진 여러 글씨 중에 쓴 사람을 추정할 수 있는 것으로 세로 약 50cm길이로 ‘夢齋(몽재)’라는 행서체 대자 명문이 있는데, 그 말미에 ‘秋史(추사)’라는 글씨가 새겨져 있어 조선 후기의 유명한 문인 서예가 추사 김정희(金正喜, 1786∼1856)의 필적임을 추정할 수 있다. 또한 이곳에는 추사의 글씨 외에도 미수선생이 지팡이를 놓았던 장소라는 뜻인 ‘眉叟先生杖履之所(미수선생장리지소)’라 쓴 것과 그 주변에 이시선(李時善), 임술(壬戌), ○○○ 등 미수풍의 글씨가 있어서 미수 허목(許穆…","a":"노고산독재동추사필적암각문","c":"시도기념물","r":"경기도","s":"양주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646359.jpg"},{"q":"성현들에게 제사지내고 지방민의 교육을 위해 세웠던 국립교육기관으로 고려 인종 5년(1127) 세웠다. 그 뒤 여러 차례 옮기고 복원하였는데, 지금 있는 위치는 영조 7년(1731) 유수 유척기가 옮긴 것이다. 남아있는 건물로는 제사공간인 대성전과 동무·서무, 교육공간인 명륜당을 비롯해 여러 부속 건물이 있다. 조선시대에는 국가로부터 토지·노비·책 등을 지원받아 제사와 교육의 기능을 담당했으나, 교육기능은 사라지고 지금은 제사의 기능만 남아있다.","a":"강화향교","c":"시도유형문화유산","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637088.jpg"},{"q":"계룡산 내에 봉우리처럼 우뚝 솟아있는 자연바위로, 사람의 손에 의해 만들어진 것이 아닌 자연 그대로의 탑이다. 탑이란 부처의 사리를 모셔두는 곳을 일컫는 것으로, 이 탑에는 다음과 같은 전설이 전해 내려오고 있다. 석가모니가 열반한 후 인도의 아육왕은 구시나가라국에 있는 사리탑에서 많은 양의 사리를 발견하여 이를 시방세계(十方世界:열곳의 방향에 있는 중생의 세계로, 동·서·남·북·동북·동남·서남·서북·상(上)·하(下)에 있는 무한한 세계를 가리킴)에 나누어 주었다. 그 때 4천왕(四天王:불교의 법을 지키는 무리로, 동·서·남·북 네곳을 지키고 있음) 가운데 북쪽을 담…","a":"천진보탑","c":"문화유산자료","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660991.jpg"},{"q":"원래는 조선 중기인 명종 1년(1546)에 옥계서당으로 세워졌던 건물이다. 이것을 순조 4년(1804)에 고성 남씨의 수일파 문중에서 후손들에게 학문을 전수할 목적으로 지금의 위치에 옮겨 짓고 그 이름도 ○○○로 바뀌었다. 앞면 2칸·옆면 2칸의 규모로 지붕은 옆면이 여덟 팔(八)자 모양인 팔작지붕이다. 앞면 2칸은 우물마루를 깔아 누마루를 만들고 뒷면 2칸은 온돌방을 만들었다. ○○○○○는 앞면과 옆면의 칸수를 같게 하고 4면에는 난간을 돌리고, 누마루를 만들어 놓은 것 등 여러 가지 면에서 조선시대 사대부들이 즐겨 이용하던 누각과 정자건축의 특징을 가지고 있다.","a":"영동 화수루","c":"시도유형문화유산","r":"충청북도","s":"영동군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638651.jpg"},{"q":"조선 정조(재위 1776∼1800))는 아버지인 사도세자의 묘를 양주 배봉산에서 수원의 화산 아래로 옮기면서 기존의 수원읍을 현재의 팔달산 아래로 옮겨 새 도시를 조성하였다. 새로 이주한 주민들의 안정을 위해 성곽을 쌓을 것을 계획하고 수원의 이름을 화성으로 바꾸었다. 정조는 새 도시 경영을 위한 경제적 기반 확보와 백성들의 생활안정을 목적으로 둔전(각 궁과 관아에 딸렸던 밭)을 설치하였다. 또한 농사를 위한 관개 용수와 제방 쌓는 일, 상권에 대한 보호, 나무를 심는 식수사업 등 갖가지 정책적인 배려를 베풀었다. 정조 21년(1797)에 세운 ○○○는 사도세자의 능…","a":"만년제","c":"시도기념물","r":"경기도","s":"화성시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2019070418061800.png"},{"q":"조선 순조 1년(1801)에 있었던 천주교 박해 때부터 지금까지 천주교 신자들이 많이 찾는 천주교의 성지이다. ‘배론’이라는 이름은 이곳의 지형이 마치 배 밑바닥과 같은 모양이라해서 붙여진 것이다. 유적으로는 조선 후기 천주교도 황사영이 머무르며 ‘백서’를 썼던 토굴과 성 요셉 신학교, 최양업 신부의 묘가 있다. 1801년 천주교에 대한 박해가 일어나자 황사영은 이 토굴에서 교회의 재건과 신앙의 자유를 얻기 위해 중국 베이징에 있는 주교에게 보낼 글을 썼으나 뜻을 이루지는 못하였다. 성 요셉 신학교는 한국에서 처음으로 세워진 신학교로 성직자를 양성하는 곳이었다. 조선…","a":"제천 배론성지","c":"시도기념물","r":"충청북도","s":"제천시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650769.jpg"},{"q":"이명발이 은거하던 모고산 입구에 후손인 이학이 세운 것으로, 강학과 풍류를 즐기던 곳이다. 이명발은 문종 때 승지였던 이승길의 아들로, 성균관에서 공부하던 중 단종폐위에 충격을 받고 이곳으로 내려와 지냈다. 건물은 조선 중종 15년(1520)에 지었는데 처음에는 절벽 위에 있던 것을 비바람으로 퇴락하여 현종 10년(1670) 자손인 명선이 지금 있는 자리로 옮겼다. 앞면 4칸·옆면 2칸 규모이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕으로 꾸몄다.","a":"모고재","c":"문화유산자료","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662856.jpg"},{"q":"조선 정조 12년(1788)에 농수재 최광익(聾睡齋 崔光翊:1731~1795)이 둘째 아들인 최승우(崔昇羽:1770~1841)를 위해 지었으나 그 형인 최성우(崔成羽:1762~1802)와 집을 바꾸었다고 전한다. 북애라는 명칭은 건너편에 위치한 구미 쌍암고택(국가민속문화유산)에서 이 집을 바라볼 때 북쪽 언덕에 있다하여 지어진 이름이다. 一자형 사랑채와 중문간채, ㄷ자형 안채가 남향으로 배치되었는데, 쌍암고가와 같은 형식이다. 원래는 대문간채와 사당도 있었다고 하나 현재는 남아있지 않다. 사랑채는 앞면 4칸·옆면 2칸으로 서쪽에는 2칸의 사랑방을 두고, 동쪽에는 대청…","a":"해평동북애고택","c":"시도민속문화유산","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658597.jpg"},{"q":"이 영정은 ○○○○○선사의 좌안7분면 전신교의가부좌상으로, 전체 구도는 서운문이 시문된 푸른색 상단과 돗자리로 반분된 이단구도 형식이다. 선사는 다리가 없고 팔걸이만 있는 의자에 앉아 왼손으로는 금색의 용머리가 화려하게 장식된 불자를 들고, 오른손은 무릎위에 얹고 있다. 이 작품은 교의가부좌상에서 바닥가부좌상으로 넘어가는 과도기적 형식을 보여준다. 화면 향좌측엔 주지묵서의 ‘부종수교겸팔도총섭○○○○○대화상지○○’의 화제가 있고 뒤편으론 배면묵서가 있다. 이로서 1881년 화공 관허당 의관이 조성하였음을 알 수 있다. 통도사 부도전에 남아있는 이 ○○선사의 탑비는 우운…","a":"낙운당 지일 진영","c":"시도유형문화유산","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001643038.JPG"},{"q":"흥법사는 『고려사』에 기록된 내용으로 보아 신라 때 세워진 것을 알 수 있으며, 임진왜란 때 없어진 것으로 추측된다. 이곳에는 염거화상탑(국보), 진공대사탑 및 석관(보물)이 있었는데, 1931년 일본인들에 의해 강제로 반출되었다가 지금은 국립중앙박물관에서 보관하고 있다. 현재는 ○○○○삼층석탑(보물), 진공대사탑비(보물)만이 남아있다.","a":"흥법사지","c":"문화유산자료","r":"강원특별자치도","s":"원주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660412.jpg"},{"q":"○○○란 어떤 건물이 있던 터에 세워두는 비로, 그 건물에 얽힌 사연을 담고 있다. 조선 광해군 때의 왕실종친이었던 구천군 이수는 기울어가는 나라의 종묘사직을 구하고자 당시 권력을 휘두르던 이이첨을 탄핵하였다가 이곳 순천지역으로 유배되었다. 손수 정자를 지어 ‘○○○’이라 이름짓고 항상 북쪽(서울)을 바라보며 나라와 임금의 안위를 걱정하였다. 그 후 이 정자는 없어지고, 정조 5년(1781) 이수의 6세손인 순천부사 이동엽이 그 옛 터에 정각을 다시 지어 ‘망북각’이라는 현판을 달아놓았으며, 순조 때 전라좌도수군절도사였던 6대손 이동선이 ○○○에 얽힌 조상의 충절을…","a":"순천망북정유지비","c":"문화유산자료","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661902.jpg"},{"q":"1805년(純祖 5) 건립한 ○○○○○는 비각을 건립하여 보관하고 있다. 비는 조선시대 일반적인 형태인 팔각지붕형 갓석과 비신, 비대석으로 되어 있다. 비문은 金祖淳이 썼으며, 글씨는 申緯가 썼고, 篆字는 徐邁修가 썼다. 신위는 조선시대 4대 명필가였으며, 서매수는 당시 좌의정이었다. 비의 규모는 비신의 높이 228cm, 폭 106cm, 두께 39cm이다. ○○시 서면 방동리 821-1번지내에 위치하고 있는 ○○○○○는「신○○○ 묘역」(강원특별자치도 기념물, 1967.6.17 지정)과 인접하여 있으며 주변의 금산리에는「○○ 한백록 묘역 및 정문」(강원특별자치도 문화유…","a":"춘천 장절공 신숭겸 신도비","c":"시도유형문화유산","r":"강원특별자치도","s":"춘천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638337.jpg"},{"q":"○○○란 조선 고종 때 병인양요와 신미양요를 승리로 이끈 흥선대원군이 서양세력의 침략을 온 국민에게 경고하고자 서울 및 전국 각지의 도로변에 세우도록 한 비로, 이 비도 그 중의 하나이다. 전국에서 유일하게 바위에 비문을 새겨 놓았으며, 비문에는 “서양 오랑캐가 침략하는데 싸우지 않으면 화해할 수 밖에 없으나 화해를 주장하는 것은 나라를 파는 것이니 자손만대에 경고하노라”라는 강한 경고 문구가 적혀있다. 고종 8년(1871) 전국에 동시에 세운 것으로, 고종 19년(1882) 임오군란이 일어나고 대원군이 러시아 공사관으로 납치된 후 세계 여러 나라들과의 교류가 이루어…","a":"구미 척화비","c":"문화유산자료","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662382.jpg"},{"q":"지석묘는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 홍성군 구항면·은하면에 분포하고 있는 이 고인돌은 탁자식으로 모두 4기이다. 구항면 태봉리에 있는 고인돌은 4개의 받침돌 중 1개가 빠져 나간 상태이고, 나머지 3개는 약간 무너졌으나 비교적 양호한 편이다. 그 위에 올려 놓은 덮개돌은 길이…","a":"홍성지석묘","c":"시도기념물","r":"충청남도","s":"홍성군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652003.jpg"},{"q":"○○○○○는 발굴조사를 통해 고려시대 건물지를 비롯하여 조선시대 건물지와 월산대군과 인수왕비 등 왕실 후원자가 새겨진 명문기와가 확인되었다. 조선 전기 왕실을 기반으로 한 ① 사찰중창의 배경, ② 사찰 조영의 계획, ③ 조성과정 등을 밝힐 수 있는 역사적 가치가 있다. ○○○○는 세차례 조사를 통하여 건물지 10동과 부석시설, 석축시설 등이 확인되었다. 특히 조선시대 초기 월산대군과 관련된 유물의 출토와 관련 기록은 왕실과 관련된 중요한 자료이다. 발굴(시굴)조사는 세차례에 걸쳐 실시하였는데, 1차는 사지의 윗 부분, 2차와 3차는 사지의 아랫 부분을 대상으로 하였다…","a":"영암 월산사지","c":"문화유산자료","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018101715540600.JPG"},{"q":"함평 이씨 재실로 묘를 수호하고 제사를 지내기 위한 곳이다. 원래는 광해군 때 이선지가 모친의 산소 아래 임시 거처로 집을 짓고 묘를 돌보며 살던 곳인데, 후손들이 숙종 때 재실로 새롭게 지은 것이다. 현재 건물은 1897년에 낡은 것을 고친 것이다.","a":"밀양 의첨재","c":"문화유산자료","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664137.jpg"},{"q":"○○○은 봉황산과 제봉산 사이에 아늑하게 자리잡은 오동촌 입구에 있다. 물이 방울처럼 솟아오른다 하여 ○○○ 또는 방울 시암 즉 영천(鈴泉)이라는 이름을 얻었는데 이 샘에 얽힌 이야기가 많이 전해온다. 동네 공동 우물인 이 샘은 500여 년 전 용이 승천한 늪이였다고 한다. 옛 기록을 살펴 보면 이 샘이 영험하여 가뭄이 들면 이 샘에 기우제를 지냈고 물 색깔의 붉기도 하고 뜬물 같이 희기도 하여 이것으로서 세상일을 예측해 주기도 했다고 한다. 동학농민운동과 한국전쟁, 천재지변 등이 일어날 때에는 황토물이 나오고 대풍년 같이 나라에 좋은 일이 있을 때에는 흰물이 나왔다…","a":"장성 영천리 방울샘","c":"시도기념물","r":"전남광주통합특별시","s":"장성군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2020121609240600.JPG"},{"q":"우옹 이희안(1504∼1559)과 임진왜란 때 공을 세운 전치원, 이대기의 학문과 덕행을 추모하기 위해 세운 서원이다. 이희안은 조선 중기의 학자로 김안국의 문인이다. 몇 차례 관직에 나갔으나 사직하고, 조식과 사귀며 학문을 닦았다. ○○○○은 명종 19년(1564)에 처음 지었다. 이후 고종 6년(1869) 흥선대원군의 서원철폐령으로 폐쇄되었다가 그 뒤에 복원하였다. 이 서원은 왼편과 오른편에 동재·서재가 있었다고 전하나, 현재는 서당과 대문간채만 남아 있다. 서당은 앞면 5칸·옆면 1칸 규모이며, 앞뒤로 퇴칸이 있다. 왼쪽부터 방·마루 2칸·방 2칸으로 구성되어…","a":"합천 청계서원","c":"문화유산자료","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664151.jpg"},{"q":"현 소유자의 10대조가 세운 집으로 안채와 사랑채로 구분되는 ㅁ자형 평면을 가진 집이다. 집을 지을 당시에 현재 사랑채로 사용되는 건물을 먼저 짓고 그 뒤에 안채를 지은 것으로 보인다. 안채는 앞면 5칸·옆면 2칸 규모이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다. 넓은 마루를 중심으로 양 옆에 방과 부엌을 배치하였다. 사랑채는 가운데 방 3칸을 배치하고 앞면에 툇마루를 놓았다. 툇마루 양 옆으로는 부엌과 창고를 마련하였다. 창고는 공간을 넓게 확보하기 위하여 앞으로 내밀고 앞면은 누마루 형태로 건물을 높였으며 방 앞쪽으로 툇마루를 놓았다. 가…","a":"양양조규승가옥","c":"문화유산자료","r":"강원특별자치도","s":"양양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660483.jpg"},{"q":"경상남도 진해시 안골동에 있는 이 성은 동망산 정상 위에 만들어졌다. 성의 둘레는 594m이며, 성벽의 높이는 4∼7m 정도이다. 임진왜란 때 왜군이 쌓은 왜성으로 협반안치, 가등가명, 구귀가룡 등이 쌓아서 1년씩 교대로 수비한 일본 수군의 본거지이다. 해전에서 거듭 타격을 입고 일본으로부터 보급이 원활하지 못하자, 우리의 수군을 막기 위한 최후의 기지로 삼기 위해 쌓은 것으로 보인다. 산의 지형을 3등분으로 나누어 부분적으로 정상을 평평하게 깎은 뒤 본성, 제1외곽, 제2외곽을 나누어서 따로 돌로 쌓고, 외곽으로 각 부분을 연결하였는데, 외곽의 일부는 흙으로 쌓았다…","a":"창원 안골왜성","c":"문화유산자료","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664601.jpg"},{"q":"진산부원군 ○○은 1398년 1차 왕자의 난에 이방원을 도와 정사공신이 되고, 1400년 2차 왕자의 난에 이방원을 도와 태종으로 등극시킨 좌명공신이다. 진산부원군묘당은 ○○군 병곡면 도천리 도천마을에 있으며 외삼문인 대문간채와 내삼문, 사당, 그리고 맞배지붕으로 되어있는 문충세가 안채와 아랫채로 구성되어 있으며, 사당은 모로 단청에다가 벽면에는 벽화를 그려 넣었다.","a":"함양 하륜 부조묘","c":"문화유산자료","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2623297.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다 ○○○○의 세워진 시기는 알 수 없으나『김해읍지』에 의하면 옛 김해부 동쪽 다전동에 있었던 것으로 보인다. 그 후 향교가 있던 산이 무너져 숙종 14년(1688)에 지금의 위치로 옮겼다. 전체적인 배치는 공부하는 곳인 명륜당이 앞에 있고 제사지내는 곳인 대성전과 동·서무가 뒤에 있는 전학후묘의 형태로, 일반 향교의 배치와 비슷하다. 정문인 풍화루는 누형식의 건물이 아닌 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕으로 된 1층 건물로 지어져 특이하다. 조선시대에는 국가로부터 토…","a":"김해향교","c":"시도유형문화유산","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641896.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 전형적인 향교 건축으로 조선 세종 15년(1433)에 처음 지었다고 전하나 그 뒤 불타 없어졌다．광해군 3년(1611)에 대성전만 다시 지었고, 인조 25년(1647) ○○○를 세운 것으로 보인다. 현재 남아있는 건물로는 대성전와 명륜당, ○○○, 동재, 서재, 외삼문 등이다. 외삼문 밖에 자리하고 있는 ○○○○○는 앞면 3칸·옆면 2칸 규모의 2층 누각이다. 지붕은 옆에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 되어 있다. 2층 바닥의 높이는 약 1.7m…","a":"화순향교만화루","c":"문화유산자료","r":"전남광주통합특별시","s":"화순군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661992.jpg"},{"q":"조선 인조 14년(1636) 병자호란이 일어났을 때 나라를 구하기 위해 목숨을 바쳐 싸우다 죽은 ○○○와 그의 충성스런 노비 억부의 충절을 기리기 위해 세운 비이다. ○○○는 광해군 10년(1618) 무과에 급제하여 남포현감을 지낸 분으로 병자호란 때 이천의 쌍령전투에서 그의 노비인 억부와 함께 전사하였는데, 시체를 찾지 못하여 옷과 관으로 제사를 지냈다. 정조 7년(1783) 왕의 명을 받아 세워 놓은 비로, 비문은 우승지 이정규가 짓고 정충필이 글씨를 썼다.","a":"손종로정충비각","c":"문화유산자료","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662983.jpg"},{"q":"임진왜란 때 밀양 박씨 문중의 14명이 의병운동을 일으켜 왜적과 싸웠던 일들을 기록하여 새긴 목판이다. 206매로 구성되어 있으며, 1매에 20행 18자로 이루어져 있다. 책의 간행에 있어 기초로 삼은 것은 정조 18년(1794) 혹은 21년(1797)에 간행된『충효록』이나, 후손 박정상이 지은『박씨충효록』이다. 하지만 이들 자료는 모두 임진왜란 당시의 기록이 아니라 200여년이 지난 후의 사실이라 그 자료적 가치에 한계를 지니고 있다. 기존의 사료에서는 알려지지 않은 임진왜란 당시의 지역전투상황과 전쟁극복에 대한 구체적인 상황이 서술되어 있어 역사적으로 시사해 주는…","a":"십사의사록판목","c":"문화유산자료","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662587.jpg"}]);